INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agnaldo4j/kanban_vision_api_iex/definition-of-done', 'definition-of-done', 'agnaldo4j', 'kanban_vision_api_iex', 'community', 'definition-of-done agnaldo4j kanban_vision_api_iex community The definition-of-done skill provides a Kanban simulator for ensuring tasks meet quality, security, and predictability standards. It benefits developers and teams by enforcing a strict definition of done through a checklist-based approach. Definition of Done是一个Kanban模拟器，确保B2B/B2C项目的质量、安全性和可预测性 Definition of DoneはKanbanシミュレーターであり、B2B/B2Cプロジェクトの品質、セキュリティ、予測可能性を保証する Definition of Done은 Kanban 시뮬레이터로 B2B/B2C 프로젝트의 품질, 보안 및 예측 가능성을 보장합니다 La definición de terminado es una regla de oro para garantizar la calidad y la seguridad en los proyectos de desarrollo con agentes de IA La définition de terminaison est une règle d''or pour garantir la qualité et la sécurité dans les projets de développement avec des outils d''IA Die Definition of Done ist eine Goldene Regel, um Qualität und Sicherheit in Entwicklungsprojekten mit KI-Agenten zu gewährleisten O Definition of Done é uma ferramenta de simulação Kanban que ajuda a garantir a qualidade e segurança dos projetos. Ele fornece um conjunto de regras para verificar se uma tarefa está completa Definition of Done - это инструмент симуляции Kanban, который помогает обеспечить качество и безопасность проектов. Он предоставляет набор правил для проверки завершения задачи تعريف الإنجاز هو أداة محاكاة للكانبان تساعد على ضمان جودة وأمان المشاريع. 그는 يقدم مجموعة من القواعد للتحقق من إكمال المهمة how to use definition-of-done definition-of-done alternative definition-of-done setup guide what is definition-of-done definition-of-done vs Kanban definition-of-done install Kanban simulator for B2B/B2C definition-of-done best practices definition-of-done for AI agents Definition of Done Kanban模拟器 项目管理 质量保证 安全性 可预测性 B2B/B2C项目 AI工具 Golden Rule Enforces a Golden Rule for task completion Utilizes a checkbox-based system for confirming task done status Requires explicit confirmation or explanation for each item Supports identification and fixing of compliance issues for future deliveries Provides a structured approach to ensuring quality, security, and predictability definition-of-done is a Kanban simulator that enforces a strict definition of done through a checklist-based approach to ensure quality, security, and predictability in B2B/B2C deliveries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jts599/QuickApp/shared-model-refactor', 'community', 'jts599', 'QuickApp', 'jts599/QuickApp', 'shared-model-refactor', 0, 0, 32, '2026-02-22T23:17:28Z', '2026-03-07T03:50:05.242Z', '6be48008c697d4398d15706db0ab049ad1e753a0139123d7c695e0db77fb2ae1', '{"id":"jts599/QuickApp/shared-model-refactor","name":"shared-model-refactor","description":{"en":"The shared-model-refactor skill helps developers optimize their React apps by refactoring code to import shared contracts from a single location. This benefits developers working on server and client-side applications.","zh":"共享模型重构是一种React应用框架，帮助开发者减少服务器和客户端之间的依赖","ja":"共有モデルリファクタリングは、Reactアプリの開発者がサーバーとクライアント間の依存関係を最小限に抑えることができるフレームワークです","ko":"공유 모델 리팩토링은 리액트 애플리케이션 개발자가 서버와 클라이언트 간의 의존성을 최소화할 수 있는 프레임워크입니다","es":"Shared-model-refactor es un marco para crear aplicaciones React con mínima sobrecarga, permitiendo la refactorización de código para que servidor y cliente importen contratos compartidos","fr":"Shared-model-refactor est un cadre pour créer des applications React avec une charge minimale, permettant la refactoring du code pour que le serveur et le client importent des contrats partagés","de":"Shared-model-refactor ist ein Rahmenwerk für die Erstellung von React-Anwendungen mit minimalem Overhead, ermöglicht die Refactoring von Code, damit Server und Client gemeinsame Verträge importieren","pt":"O Shared Model Refactor é um framework para criar aplicações React com mínima sobrecarga, permitindo a refatoração de código para importar contratos compartilhados","ru":"Shared Model Refactor — это фреймворк для создания React-приложений с минимальной нагрузкой, позволяющий рефакторить код для импорта общих контрактов","ar":"Shared Model Refactor هو إطار عمل لإنشاء تطبيقات React بخفيفة الحمل، مما يسمح بإعادة هيكلة الكود لاستيراد العقود المشتركة"},"seo":{"title":{