INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KatTate/Katalyst-Lexicon/bmad-validate-prd', 'bmad-validate-prd', 'KatTate', 'Katalyst-Lexicon', 'community', 'bmad-validate-prd KatTate Katalyst-Lexicon community The bmad-validate-prd skill activates the BMAD PRD Validation workflow, reviewing existing PRDs against BMAD standards. It benefits developers by providing a comprehensive quality assessment. BMAD Validate PRD是用于验证PRD的工作流，通过_comprehensive quality assessment来提高PRD质量 BMAD Validate PRDはPRDを検証するワークフローであり、包括的な品質評価を通じてPRDの品質を高めます BMAD Validate PRD는 PRD를 검증하는 워크플로우로, 포괄적인 품질 평가를 통해 PRD 품질을 높입니다 El skill bmad-validate-prd activa el flujo de trabajo de validación de PRD de BMAD, que revisa un PRD existente contra los estándares de BMAD Le skill bmad-validate-prd active le flux de travail de validation de PRD de BMAD, qui examine un PRD existant contre les normes de BMAD Das Skill bmad-validate-prd aktiviert den Workflow für die Validierung von PRD von BMAD, der einen bestehenden PRD gegen die BMAD-Standards überprüft O bmad-validate-prd é uma ferramenta que valida o PRD contra os padrões BMAD, utilizando uma arquitetura de steps e configuração em YAML. bmad-validate-prd - это инструмент, который проверяет PRD на соответствие стандартам BMAD, используя шаговую архитектуру и конфигурацию в YAML. بمد-تأكيد-prd هو أداة لتحقق من وثائق PRD مقابل معايير BMAD، مستخدمًا هيكل الخطوات وتكوين YAML how to use bmad-validate-prd bmad-validate-prd setup guide bmad-validate-prd alternative bmad-validate-prd vs BMAD standards what is bmad-validate-prd bmad-validate-prd install PRD validation workflow BMAD PRD validation comprehensive quality assessment BMAD Validate PRD AI工具 PRD验证 工作流设置 质量评估 配置加载 步骤文件架构 PRD文件验证 Loads and follows the workflow directly from _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md Uses step-file architecture with steps in steps-v/ directory Configuration loading from _bmad/bmm/config.yaml Reviews existing PRDs against BMAD standards through comprehensive quality assessment Triggers the BMAD PRD validation workflow for quality assessment bmad-validate-prd is a skill that activates the BMAD PRD Validation workflow, using a step-file architecture and configuration loading from config.yaml');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xenitV1/claude-code-maestro/frontend-design', 'community', 'xenitV1', 'claude-code-maestro', 'xenitV1/claude-code-maestro', 'frontend-design', 0, 0, 32, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:58.064Z', 'ef15ad0461b726c97cea0e1b005664f191dc9d06ca155765eb6ca602898e1922', '{"id":"xenitV1/claude-code-maestro/frontend-design","name":"frontend-design","description":{"en":"Frontend-design helps developers create user-friendly interfaces by minimizing cognitive load and making interactions intuitive. It benefits developers and users alike by providing a philosophy for designing simple and natural interactions.","zh":"前端设计系统致力于减少认知负荷，实现交互的直观性，尊重人类心理、行为模式和认知局限性。","ja":"フロントエンド設計システムは、認知負荷を減らし、インタラクションの直感性を実現し、人間の心理、行動パターン、認知の限界を尊重します。","ko":"프론트엔드 디자인 시스템은 인지 부하를 줄이고 상호작용의 직관성을 구현하며 인간의 심리, 행동 패턴, 인지 제한을尊重합니다.","es":"El diseño frontend se centra en minimizar la carga cognitiva y hacer que las interacciones sean intuitivas. Nuestro enfoque se basa en el respeto a la psicología humana y los patrones de comportamiento","fr":"La conception frontend vise à minimiser la charge cognitive et à rendre les interactions intuitives. Notre approche repose sur le respect de la psychologie humaine et des modèles de comportement","de":"Das Frontend-Design konzentriert sich auf die Minimierung der kognitiven Belastung und die Schaffung intuitiver Interaktionen. Unser Ansatz basiert auf dem Respekt für die menschliche Psychologie und die Verhaltensmuster","pt":"O frontend design visa minimizar a carga cognitiva e tornar as interações intuitivas, respeitando a psicologia humana e os padrões comportamentais","ru":"Фронтенд дизайн направлен на минимизацию когнитивной нагрузки и создание интуитивного взаимодействия, уважая человеческую психологию и поведенческие паттерны","ar":"يهدف تصميم الواجهة الأمامية إلى تقليل التحميل المعرفي وجعل التفاعل بديهياً، مع احترام النفسية البشرية والأنماط السلوكية"},"seo":{"title":{"en":"Frontend-design: Invisible Design Setup Guide | AI Agent ...","zh":"前端设计系统搭建指南","ja":"フロントエンド設計システムのベストプラクティス","ko":"프론트엔드 디자인 시스템 구축 가이드","es":"Guía de Diseño Frontend: Principios y Mejores Prácticas p...","fr":"Guide de Conception Frontend pour les Outils d''Intelligen...","de":"Frontend-Design-Leitfaden: Grundlagen und Best Practices ...","pt":"Guia de Frontend Design: Princípios de Interação Intuitiva","ru":"Руководство по Фронтенд Дизайну: ИИ Агенты для Интуитивно...","ar":"دليل تصميم الواجهة الأمامية: مبادئ التفاعل البصري"},"description":{"en":"Discover how to create intuitive interfaces with frontend-design. Learn how to minimize cognitive load and make interactions effortless. Get started now!","zh":"了解前端设计系统的核心原则和哲学，实现无缝的用户体验，AIエージェント","ja":"フロントエンド設計システムの基本原則と哲学を学び、無限のユーザーエクスペリエンスを実現する、AIエージェント","ko":"프론트엔드 디자인 시스템의 핵심 원칙과 철학을 이해하고 무결점의 사용자 경험을 구현하는 방법, AI 도구","es":"Aprende a diseñar interfaces de usuario intuitivas con nuestra guía de diseño frontend para AI Agentes. Descubre los principios y mejores prácticas para mini...","fr":"Découvrez les principes et les meilleures pratiques de conception frontend pour les outils d''intelligence artificielle. Créez des interfaces utilisateur intu...","de":"Erfahren Sie, wie Sie mit unserem Frontend-Design-Leitfaden benutzerfreundliche Schnittstellen für KI-Tools erstellen. Lernen Sie die Grundlagen und Best Pra...","pt":"Aprenda sobre os princípios de frontend design que minimizam a carga cognitiva e tornam as interações intuitivas, com exemplos práticos de implementação","ru":"Изучите принципы фронтенд дизайна, которые минимизируют когнитивную нагрузку и делают взаимодействие интуитивным, с помощью ИИ Агентов","ar":"تعرف على مبادئ تصميم الواجهة الأمامية التي تقلل من التحميل المعرفي وتجعل التفاعل بديهياً، مع أمثلة عملية للتطبيق"},"definition":{"en":"Frontend-design is a philosophy and core principle for creating intuitive and invisible design that respects human psychology and cognitive limitations.","zh":"前端设计系统是一种设计哲学，旨在减少认知负荷，实现交互的直观性","ja":"フロントエンド設計システムは、認知負荷を減らし、インタラクションの直感性を実現するための設計哲学です","ko":"프론트엔드 디자인 시스템은 인지 부하를 줄이고 상호작용의 직관성을 구현하는 디자인 철학입니다","es":"El diseño frontend es un enfoque que se centra en la creación de interfaces de usuario intuitivas y naturales, respetando la psicología humana y los patrones de comportamiento","fr":"La conception frontend est une approche qui vise à créer des interfaces utilisateur intuitives et naturelles, en respectant la psychologie humaine et les modèles de comportement","de":"Das Frontend-Design ist ein Ansatz, der sich auf die Erstellung benutzerfreundlicher und natürlicher Schnittstellen konzentriert, unter Berücksichtigung der menschlichen Psychologie und der Verhaltensmuster","pt":"Frontend design é uma abordagem de design que visa criar interfaces intuitivas e fáceis de usar, minimizando a carga cognitiva do usuário","ru":"Фронтенд дизайн - это подход к дизайну, направленный на создание интуитивных и простых в использовании интерфейсов, минимизирующих когнитивную нагрузку пользователя","ar":"تصميم الواجهة الأمامية هو نهج تصميم يهدف إلى создание واجهات بديهية وسهلة الاستخدام، مع تقليل التحميل المعرفي للمستخدم"},"features":{"en":["Minimizes cognitive load to make interactions intuitive","Respects human psychology and behavioral patterns in design decisions","Follows the core principle that good design is invisible","Aligns design with how humans naturally think and behave","Supports effortless and natural user interactions","Reduces complexity for users by bearing it in the design process"],"zh":["基于人类心理和行为模式的设计","减少认知负荷，实现交互的直观性","尊重认知局限性，设计简单易用界面","实现无缝的用户体验","使用React和其他前端技术实现设计"],"ja":["人間の心理と行動パターンに基づいた設計","認知負荷を減らし、インタラクションの直感性を実現","認知の限界を尊重し、シンプルで使いやすいインターフェイスを設計","無限のユーザーエクスペリエンスを実現","Reactやその他のフロントエンド技術を使用して設計を実現"],"ko":["인간의 심리와 행동 패턴을 기반으로 한 디자인","인지 부하를 줄이고 상호작용의 직관성을 구현","인지 제한을尊重하고 심플하고 사용하기 쉬운 인터페이스를 디자인","무결점의 사용자 경험을 구현","React와 다른 프론트엔드 기술을 사용하여 디자인을 구현"],"es":["Diseño de interfaces de usuario minimalistas y intuitivas","Aplicación de principios de psicología humana y patrones de comportamiento","Enfoque en la minimización de la carga cognitiva","Creación de experiencias de usuario naturales y eficientes","Integración con tecnologías frontend como React y JavaScript"],"fr":["Conception d''interfaces utilisateur minimalistes et intuitives","Application des principes de psychologie humaine et des modèles de comportement","Focus sur la minimisation de la charge cognitive","Création d''expériences utilisateur naturelles et efficientes","Intégration avec des technologies frontend comme React et JavaScript"],"de":["Erstellung von benutzerfreundlichen und minimalistischen Schnittstellen","Anwendung von Prinzipien der menschlichen Psychologie und Verhaltensmustern","Fokus auf die Minimierung der kognitiven Belastung","Schaffung von natürlichen und effizienten Benutzererfahrungen","Integration mit Frontend-Technologien wie React und JavaScript"],"pt":["Minimização da carga cognitiva","Criação de interações intuitivas","Respeito à psicologia humana e padrões comportamentais","Design invisível e natural","Alignamento com a forma como os humanos pensam e se comportam"],"ru":["Минимизация когнитивной нагрузки","Создание интуитивного взаимодействия","Уважение человеческой психологии и поведенческих паттернов","Невидимый и естественный дизайн","Соответствие тому, как люди думают и ведут себя"],"ar":["تقليل التحميل المعرفي","إنشاء تفاعل بديهي","احترام النفسية البشرية والأنماط السلوكية","تصميم غير مرئي وطبيعي","التوافق مع كيفية تفكير البشر وسلوكياتهم"]},"keywords":{"en":["how to use frontend-design","what is frontend-design","frontend-design philosophy","invisible design principles","frontend-design vs material design","frontend-design setup guide","frontend-design for AI agents","cognitive load minimization techniques","intuitive interface design patterns"],"zh":["前端设计系统","AIエージェント","用户体验","认知负荷","交互设计","React","前端开发","设计哲学"],"ja":["フロントエンド設計システム","AIエージェント","ユーザーエクスペリエンス","認知負荷","インタラクション設計","React","フロントエンド開発","設計哲学"],"ko":["프론트엔드 디자인 시스템","AI 도구","사용자 경험","인지 부하","상호작용 디자인","React","프론트엔드 개발","디자인 철학"],"es":["diseño frontend","ai agentes","interfaces de usuario","psicología humana","patrones de comportamiento","react","javascript","desarrollo web","experiencias de usuario"],"fr":["conception frontend","outils d''intelligence artificielle","interfaces utilisateur","psychologie humaine","modèles de comportement","react","javascript","développement web","expériences utilisateur"],"de":["frontend-design","ki-tools","benutzerfreundliche schnittstellen","menschliche psychologie","verhaltensmuster","react","javascript","webentwicklung","benutzererfahrungen"],"pt":["frontend design","design de interface","experiência do usuário","carga cognitiva","interações intuitivas","psicologia humana","padrões comportamentais"],"ru":["фронтенд дизайн","дизайн интерфейса","опыт пользователя","когнитивная нагрузка","интуитивное взаимодействие","человеческая психология","поведенческие паттерны","ИИ Агенты"],"ar":["تصميم الواجهة الأمامية","تصميم الواجهة","تجربة المستخدم","التحميل المعرفي","التفاعل البديهي","النفسية البشرية","الأنماط السلوكية","أدوات الذكاء الاصطناعي"]}},"owner":"xenitV1","repo":"claude-code-maestro","repoPath":"xenitV1/claude-code-maestro","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"frontend-design","description":"Elite Tier Web UI standards, including pixel-perfect retro aesthetics, immersive layouts, and UX psychology protocols.","bodyPreview":"<domain_overview>\n# Frontend Design System\n\n> **Philosophy:** Minimize cognitive load and make interactions intuitive. Every design decision should respect human psychology, behavioral patterns, and cognitive limitations. The designer bears complexity so the user experiences simplicity.\n> **Core Principle:** Good design is invisible - users should accomplish their goals without noticing the design itself. Design should feel effortless and natural, aligning with how humans naturally think and beh","body":"<domain_overview>\n# Frontend Design System\n\n> **Philosophy:** Minimize cognitive load and make interactions intuitive. Every design decision should respect human psychology, behavioral patterns, and cognitive limitations. The designer bears complexity so the user experiences simplicity.\n> **Core Principle:** Good design is invisible - users should accomplish their goals without noticing the design itself. Design should feel effortless and natural, aligning with how humans naturally think and behave.\n\n## ⚠️ Core Protocols & Standards\n**ANTI-AI AESTHETIC MANDATE (CRITICAL):** Never use generic aesthetics that give the impression of being AI-generated. This includes overused font families (Inter, Roboto, Arial, system fonts), cliché color schemes (especially purple gradients on white backgrounds), predictable layouts, and repetitive component patterns.\n**ABSOLUTELY FORBIDDEN:** The \"Cyberpunk\" aesthetic is strictly prohibited. Do NOT use neon glows, matrix rain, glitch effects, or \"high-tech\" dark modes unless explicitly requested for a specific context. This cliché is the hallmark of lazy AI generation.\nSpecifically avoid template-driven designs that lack context-specific character. This skill aims to create distinctive, original, and production-level frontends. Realize functional, high-fidelity code by paying extraordinary attention to aesthetic details and creative decisions.\n\n**CRITICAL PROTOCOL:** The detailed rules are stored in separate reference files. You **MUST** use the `Read` tool to load these files into your context **BEFORE** starting any design work. Do not assume you know the contents.\n\n- **[frontend_reference.md](frontend_reference.md)**: Contains Technical Standards, Aesthetic Signatures, and Creative Protocols.\n- **[animation_reference.md](animation_reference.md)**: Contains 2025 Motion Standards, Physics-based animation rules, and Micro-interactions.\n- **[css_art_reference.md](css_art_reference.md)**: **FOR VISUAL OBJECTS.** Use this when asked to \"draw\" or \"create\" complex items (Swords, Logos, Icons) using code. Defines Geometric Composition & LCH Materials.\n- **[security-protocols.md](security-protocols.md)**: Contains critical Frontend Security rules.\n\n## 🎬 Core Animation Principles\n> **Motion Mandate:** Animation must be **Physics-Based** (Springs), **Continuous** (No Teleportation), and **Meaningful** (Storytelling).\n\n- **Continuity:** State changes must morph, not cut (View Transitions).\n- **Weight:** Objects must feel like they have mass (Use Spring Animations).\n- **Focus:** Animation guides attention; it does not distract.\n- **Narrative:** Every motion tells a story about where an element came from and where it is going.\n*(See `animation_reference.md` for the full 12-Principle Framework)*\n\n## 🔗 Related & Required Skills\nWhen executing Frontend tasks, you **MUST** integrate these complementary skills to ensure architectural integrity:\n\n| Skill | Purpose in Frontend Context |\n|-------|-----------------------------|\n| **`brainstorming`** | **MANDATORY PRE-REQUISITE.** Before ANY design work, use this to interrogate the user''s vague instructions and crystallize the \"Screenplay/Narrative\" defined in `frontend_reference.md`. |\n| **`clean-code`** | **MANDATORY.** Ensures component modularity, cleaner hooks/state logic, and security compliance. Prevents \"spaghetti UI code\". |\n| **`tdd-mastery`** | **MANDATORY.** \"Iron Law\" applies to components too. Use for visual regression tests and logic verification before coding UI. |\n| **`optimization-mastery`** | Use for Performance Audits (Lighthouse, Core Web Vitals), reducing bundle size, and optimizing re-renders. |\n| **`backend-design`** | Consult this when defining API data shapes, error handling states, and ensuring type safety across the network boundary. |\n| **`planning-mastery`** | Use this to break down complex UI implementations into \"Atomic\" deliverables (Atoms -> Molecules -> Organisms). |\n\n## 🛠️ Automation Scripts\nUse the following script to audit your implementation:\n- **`scripts/js/ux-audit.js`**: Run this to perform a heuristic analysis of the UI for consistency, accessibility (contrast/spacing), and compliance with the design tokens.\n  - *Usage:* `node scripts/js/ux-audit.js`\n</domain_overview>"},"lastSynced":"2026-03-08T02:00:58.064Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing intuitive interaction design and minimal cognitive load","zh":"适合需要直观交互设计和最小认知负担的UI焦点Agent","ja":"UIに焦点を当てたエージェントが直感的なインタラクション設計と最小限の認知負荷を必要とする場合に最適","ko":"사용자 인터페이스에 중점을 둔 에이전트가 직관적인 상호 작용 설계와 최소한의 인지 부담을 필요로 할 때 적합","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan un diseño de interacción intuitivo y una carga cognitiva mínima","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant une conception d''interaction intuitive et une charge cognitive minimale","de":"Perfekt für benutzeroberflächenorientierte Agenten, die ein intuitives Interaktionsdesign und eine minimale kognitive Belastung benötigen","pt":"Perfeito para Agentes focados em UI que necessitam de design de interação intuitivo e carga cognitiva mínima","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходим интуитивный дизайн взаимодействия и минимальная когнитивная нагрузка","ar":"مثالي لعميل يركز على واجهة المستخدم التي تحتاج إلى تصميم تفاعل直ي وحد أدنى من التحميل المعرفي"},"recommendation":{"en":"Empowers agents to create user-friendly interfaces by leveraging human psychology, behavioral patterns, and cognitive limitations, utilizing design philosophies that prioritize simplicity and natural interactions, and implementing core principles like invisible design through HTML, CSS, and JavaScript","zh":"通过利用人类心理学、行为模式和认知局限性，优先考虑简单性和自然交互的设计哲学，并通过HTML、CSS和JavaScript实现核心原则，如隐形设计，从而使代理能够创建用户友好的界面","ja":"人間の心理学、行動パターン、認知の限界を利用し、シンプルさと自然なインタラクションを優先するデザイン哲学を採用し、HTML、CSS、JavaScriptを通じてインビジブルデザインなどの核心原則を実装することで、エージェントがユーザーに優しいインターフェースを作成できるようにする","ko":"인간의 심리학, 행동 패턴, 인지 제한을 활용하고, 단순성과 자연스러운 상호 작용을 우선하는 디자인 철학을 채택하고, HTML, CSS, JavaScript를 통해 무형 디자인과 같은 핵심 원칙을 구현함으로써 에이전트가 사용자에게 친숙한 인터페이스를 만들 수 있도록 함","es":"Habilita a los agentes a crear interfaces de usuario amigables aprovechando la psicología humana, los patrones de comportamiento y las limitaciones cognitivas, utilizando filosofías de diseño que priorizan la simplicidad y las interacciones naturales, e implementando principios básicos como el diseño invisible a través de HTML, CSS y JavaScript","fr":"Permet aux agents de créer des interfaces utilisateur conviviales en exploitant la psychologie humaine, les modèles de comportement et les limitations cognitives, en utilisant des philosophies de conception qui donnent la priorité à la simplicité et aux interactions naturelles, et en mettant en œuvre des principes de base tels que la conception invisible via HTML, CSS et JavaScript","de":"Ermächtigt Agenten, benutzerfreundliche Schnittstellen zu erstellen, indem sie die menschliche Psychologie, Verhaltensmuster und kognitive Einschränkungen nutzen, Designphilosophien anwenden, die Einfachheit und natürliche Interaktionen priorisieren, und grundlegende Prinzipien wie unsichtbares Design mithilfe von HTML, CSS und JavaScript implementieren","pt":"Habilita os agentes a criarem interfaces de usuário amigáveis aproveitando a psicologia humana, padrões de comportamento e limitações cognitivas, utilizando filosofias de design que priorizam a simplicidade e as interações naturais, e implementando princípios básicos como design invisível por meio de HTML, CSS e JavaScript","ru":"Наделяет агентов возможностью создавать пользовательские интерфейсы, используя психологию человека, поведенческие модели и когнитивные ограничения, применяя дизайнерские философии, отдающие приоритет простоте и естественным взаимодействиям, и реализуя основные принципы, такие как невидимый дизайн посредством HTML, CSS и JavaScript","ar":"تمكّن العميل من إنشاء واجهات مستخدم متوافقة بالاستفادة من علم النفس البشري وأنماط السلوك والقيود المعرفية، وبتطبيق فلسفات التصميم التي تعطي الأولوية للبساطة والتفاعلات الطبيعية، وتنفيذ المبادئ الأساسية مثل تصميم غير مرئي من خلال HTML و CSS و JavaScript"},"useCases":{"en":["Designing intuitive navigation systems","Creating minimalistic and simple user interfaces","Optimizing web page layouts for effortless user experience"],"zh":["设计直观的导航系统","创建极简和简单的用户界面","优化网页布局以实现无缝的用户体验"],"ja":["直感的なナビゲーションシステムの設計","極めてシンプルで単純なユーザーインターフェースの作成","ウェブページのレイアウトを最適化して無駄のないユーザーエクスペリエンスを実現"],"ko":["직관적인 내비게이션 시스템 설계","최소한하고 단순한 사용자 인터페이스 생성","웹 페이지 레이아웃 최적화하여 무결점의 사용자 경험 구현"],"es":["Diseñar sistemas de navegación intuitivos","Crear interfaces de usuario minimalistas y simples","Optimizar diseños de página web para una experiencia de usuario sin esfuerzo"],"fr":["Concevoir des systèmes de navigation intuitifs","Créer des interfaces utilisateur minimalistes et simples","Optimiser les mises en page de page Web pour une expérience utilisateur sans effort"],"de":["Intuitive Navigationsysteme entwerfen","Minimalistische und einfache Benutzeroberflächen erstellen","Webseitengestaltungen für eine mühelose Benutzererfahrung optimieren"],"pt":["Projetar sistemas de navegação intuitivos","Criar interfaces de usuário minimalistas e simples","Otimizar layouts de páginas da web para experiência de usuário sem esforço"],"ru":["Проектирование интуитивных систем навигации","Создание минималистичных и простых пользовательских интерфейсов","Оптимизация макетов веб-страниц для беспроблемного пользовательского опыта"],"ar":["تصميم أنظمة ملاحة直ية","إنشاء واجهات مستخدم بسيطة وmínimalista","تحسين تخطيطات صفحات الويب لتجربة مستخدم بدون جهد"]},"limitations":{"en":["Requires understanding of human-centered design principles","Dependent on developer''s knowledge of frontend development frameworks and libraries"],"zh":["需要了解以人为本的设计原则","依赖于开发者的前端开发框架和库的知识"],"ja":["人間中心のデザイン原則の理解が必要","フロントエンド開発フレームワークやライブラリの知識に依存する"],"ko":["사용자 중심의 디자인 원칙에 대한 이해가 필요","프론트엔드 개발 프레임워크 및 라이브러리에 대한 지식에 의존"],"es":["Requiere comprensión de los principios de diseño centrado en el ser humano","Depende del conocimiento del desarrollador sobre frameworks y bibliotecas de desarrollo frontend"],"fr":["Nécessite une compréhension des principes de conception centrés sur l''humain","Dépend de la connaissance du développeur sur les frameworks et bibliothèques de développement frontend"],"de":["Erfordert das Verständnis von menschzentrierten Designprinzipien","Hängt vom Wissen des Entwicklers über Frontend-Entwicklungsframeworks und -Bibliotheken ab"],"pt":["Exige compreensão de princípios de design centrados no ser humano","Dependente do conhecimento do desenvolvedor sobre frameworks e bibliotecas de desenvolvimento frontend"],"ru":["Требует понимания принципов дизайна, ориентированного на человека","Зависит от знаний разработчика о фреймворках и библиотеках frontend-разработки"],"ar":["يتطلب فهم مبادئ التصميم المرتكز على الإنسان","يعتمد على معرفة المطور إطار العمل ومكتبات تطوير الواجهة الأمامية"]},"version":4},"contentHash":"ef15ad0461b726c97cea0e1b005664f191dc9d06ca155765eb6ca602898e1922","qualityScore":32}');
DELETE FROM skills_fts WHERE id = 'xenitV1/claude-code-maestro/frontend-design';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xenitV1/claude-code-maestro/frontend-design', 'frontend-design', 'xenitV1', 'claude-code-maestro', 'community', 'frontend-design xenitV1 claude-code-maestro community Frontend-design helps developers create user-friendly interfaces by minimizing cognitive load and making interactions intuitive. It benefits developers and users alike by providing a philosophy for designing simple and natural interactions. 前端设计系统致力于减少认知负荷，实现交互的直观性，尊重人类心理、行为模式和认知局限性。 フロントエンド設計システムは、認知負荷を減らし、インタラクションの直感性を実現し、人間の心理、行動パターン、認知の限界を尊重します。 프론트엔드 디자인 시스템은 인지 부하를 줄이고 상호작용의 직관성을 구현하며 인간의 심리, 행동 패턴, 인지 제한을尊重합니다. El diseño frontend se centra en minimizar la carga cognitiva y hacer que las interacciones sean intuitivas. Nuestro enfoque se basa en el respeto a la psicología humana y los patrones de comportamiento La conception frontend vise à minimiser la charge cognitive et à rendre les interactions intuitives. Notre approche repose sur le respect de la psychologie humaine et des modèles de comportement Das Frontend-Design konzentriert sich auf die Minimierung der kognitiven Belastung und die Schaffung intuitiver Interaktionen. Unser Ansatz basiert auf dem Respekt für die menschliche Psychologie und die Verhaltensmuster O frontend design visa minimizar a carga cognitiva e tornar as interações intuitivas, respeitando a psicologia humana e os padrões comportamentais Фронтенд дизайн направлен на минимизацию когнитивной нагрузки и создание интуитивного взаимодействия, уважая человеческую психологию и поведенческие паттерны يهدف تصميم الواجهة الأمامية إلى تقليل التحميل المعرفي وجعل التفاعل بديهياً، مع احترام النفسية البشرية والأنماط السلوكية how to use frontend-design what is frontend-design frontend-design philosophy invisible design principles frontend-design vs material design frontend-design setup guide frontend-design for AI agents cognitive load minimization techniques intuitive interface design patterns 前端设计系统 AIエージェント 用户体验 认知负荷 交互设计 React 前端开发 设计哲学 Minimizes cognitive load to make interactions intuitive Respects human psychology and behavioral patterns in design decisions Follows the core principle that good design is invisible Aligns design with how humans naturally think and behave Supports effortless and natural user interactions Reduces complexity for users by bearing it in the design process Frontend-design is a philosophy and core principle for creating intuitive and invisible design that respects human psychology and cognitive limitations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tachyon-zcash/ragu/book-review', 'community', 'tachyon-zcash', 'ragu', 'tachyon-zcash/ragu', 'book-review', 0, 0, 32, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:13.689Z', '8cde8111f9ce64927a0c539ae1115d2cc2bb1949fb16a47a97b5d59be82aeae9', '{"id":"tachyon-zcash/ragu/book-review","name":"book-review","description":{"en":"The book-review skill utilizes Rust language for proof-carrying data, benefiting developers by streamlining code review processes through git diff analysis and custom review policies.","zh":"Book Review是一个Rust语言的证明携带数据框架，用于代码审查和书籍章节审查","ja":"Book ReviewはRust言語のProof-Carrying Dataフレームワークであり、コードレビューと書籍章のレビューに使用される","ko":"Book Review는 Rust 언어의 증명 携帯 데이터 프레임워크로서 코드 리뷰와 책 장을 리뷰하는 데 사용된다","es":"book-review es un marco de datos de comprobación de Rust que revisa partes de un libro según $ARGUMENTS. Utiliza políticas de revisión de libros del proyecto para garantizar la calidad.","fr":"book-review est un cadre de données de vérification Rust qui examine des parties d''un livre selon $ARGUMENTS. Il utilise les politiques de révision de livres du projet pour assurer la qualité.","de":"book-review ist ein Rust-Proof-Carrying-Data-Framework, das Teile eines Buches nach $ARGUMENTS überprüft. Es verwendet die Buch-Review-Richtlinien des Projekts, um die Qualität zu gewährleisten.","pt":"A ferramenta de revisão de livros com Rust é uma solução inovadora para revisar e melhorar a qualidade do código. Ela utiliza o framework de prova de dados de Rust para garantir a integridade dos dados.","ru":"ИИ Агент для обзора книг с помощью Rust является инновационным решением для проверки и улучшения качества кода. Он использует фреймворк доказательства данных Rust для обеспечения целостности данных.","ar":"أداة استعراض الكتب مع لغة الرست هي حل مبتكر لمراجعة وتحسين جودة الكود. إنها تستخدم إطار العمل لبرهنة البيانات من الرست لضمان سلامة البيانات."},"seo":{"title":{"en":"book-review: Rust Language Proof-Carrying Data Framework ...","zh":"Book Review Setup Guide - Rust语言证明携带数据框架","ja":"Book Review ベストプラクティス - Rust言語のProof-Carrying Dataフレームワーク","ko":"Book Review 설정 가이드 - Rust 언어 증명 携帯 데이터 프레임워크","es":"Guía de Configuración de book-review para Desarrolladores","fr":"Guide d''Installation de book-review pour les Développeurs","de":"Einrichtungs-Leitfaden für book-review-Entwickler","pt":"Guia de Configuração do Ferramenta de Revisão de Livros c...","ru":"Настройка ИИ Агента для Обзора Книг с помощью Rust","ar":"دليل إعداد أداة استعراض الكتب مع لغة الرست"},"description":{"en":"Discover how to utilize book-review for efficient code review. Learn to interpret $ARGUMENTS and leverage git diff for uncommitted changes analysis.","zh":"使用Book Review AI Agent进行Rust语言项目的代码审查和书籍章节审查，提高代码质量和开发效率","ja":"Book Review AIエージェントを使用してRust言語プロジェクトのコードレビューと書籍章のレビューを実行し、コード品質と開発効率を向上させる","ko":"Book Review AI 에이전트를 사용하여 Rust 언어 프로젝트의 코드 리뷰와 책 장을 리뷰하여 코드 품질과 개발 효율을 향상시키는 방법","es":"Aprende a configurar book-review para revisar partes de un libro especificado por $ARGUMENTS, utilizando políticas de revisión de libros del proyecto","fr":"Découvrez comment configurer book-review pour examiner une partie d''un livre spécifiée par $ARGUMENTS, en utilisant les politiques de révision de livres du p...","de":"Erfahren Sie, wie Sie book-review einrichten, um Teile eines Buches zu überprüfen, die durch $ARGUMENTS angegeben sind, unter Verwendung der Buch-Review-Rich...","pt":"Aprenda a configurar a ferramenta de revisão de livros com Rust e melhore sua produtividade com recursos avançados de revisão de código","ru":"Узнайте, как настроить ИИ Агента для обзора книг с помощью Rust и повысьте свою производительность с помощью продвинутых функций проверки кода","ar":"تعلم كيفية إعداد أداة استعراض الكتب مع لغة الرست وتحسين إنتاجيتك باستخدام ميزات متقدمة لمراجعة الكود"},"definition":{"en":"book-review is a Rust language proof-carrying data framework designed to facilitate efficient code review by interpreting user arguments and applying project-specific review policies.","zh":"Book Review是一种用于Rust语言项目的代码审查和书籍章节审查的AI工具","ja":"Book ReviewはRust言語プロジェクトのコードレビューと書籍章のレビューに使用されるAIエージェントの一種","ko":"Book Review는 Rust 언어 프로젝트의 코드 리뷰와 책 장을 리뷰하는 데 사용되는 AI 에이전트의 일종","es":"book-review es un agente de AI que utiliza Rust para revisar partes de un libro según $ARGUMENTS, siguiendo las políticas de revisión de libros del proyecto","fr":"book-review est un agent IA qui utilise Rust pour examiner des parties d''un livre selon $ARGUMENTS, en suivant les politiques de révision de livres du projet","de":"book-review ist ein KI-Agent, der Rust verwendet, um Teile eines Buches nach $ARGUMENTS zu überprüfen, unter Einhaltung der Buch-Review-Richtlinien des Projekts","pt":"A ferramenta de revisão de livros com Rust é um sistema que utiliza o framework de prova de dados de Rust para revisar e melhorar a qualidade do código","ru":"ИИ Агент для обзора книг с помощью Rust является системой, которая использует фреймворк доказательства данных Rust для проверки и улучшения качества кода","ar":"أداة استعراض الكتب مع لغة الرست هي نظام يستخدم إطار العمل لبرهنة البيانات من الرست لمراجعة وتحسين جودة الكود"},"features":{"en":["Interprets $ARGUMENTS for flexible review options","Utilizes git diff -- book/src/ for uncommitted changes analysis","Supports review of specific file paths and line ranges (e.g., foo.md:10-20)","Automates review of whole chapters based on file path input","Leverages project''s book review policies for consistent evaluation"],"zh":["支持Rust语言项目的代码审查","能够审查书籍章节和代码变更","使用git diff命令审查未提交的变更","支持文件路径和行号指定的审查"],"ja":["Rust言語プロジェクトのコードレビューをサポート","書籍章とコードの変更をレビューできる","git diffコマンドを使用して未コミットの変更をレビュー","ファイルパスと行番号を指定してレビューできる"],"ko":["Rust 언어 프로젝트의 코드 리뷰를 지원","책 장과 코드의 변경을 리뷰할 수 있다","git diff 명령을 사용하여 커밋되지 않은 변경을 리뷰","파일 경로와 행 번호를 지정하여 리뷰할 수 있다"],"es":["Revisión de partes de un libro según $ARGUMENTS","Uso de políticas de revisión de libros del proyecto","Compatibilidad con Rust","Soporte para revisión de archivos y líneas específicas","Integración con git diff para revisar cambios no comprometidos"],"fr":["Examen de parties d''un livre selon $ARGUMENTS","Utilisation des politiques de révision de livres du projet","Compatibilité avec Rust","Prise en charge de la révision de fichiers et de lignes spécifiques","Intégration avec git diff pour examiner les modifications non validées"],"de":["Überprüfung von Teilen eines Buches nach $ARGUMENTS","Verwendung der Buch-Review-Richtlinien des Projekts","Kompatibilität mit Rust","Unterstützung für die Überprüfung von Dateien und spezifischen Zeilen","Integration mit git diff zur Überprüfung von nicht committeten Änderungen"],"pt":["Revisão de código com base em políticas de revisão de livros","Suporte a revisão de capítulos inteiros com base em caminhos de arquivos","Integração com Git para revisar alterações não commitadas","Suporte a revisão de linhas específicas em arquivos","Utilização do framework de prova de dados de Rust para garantir a integridade dos dados"],"ru":["Проверка кода на основе политики обзора книг","Поддержка проверки целых глав на основе путей файлов","Интеграция с Git для проверки незафиксированных изменений","Поддержка проверки определенных строк в файлах","Использование фреймворка доказательства данных Rust для обеспечения целостности данных"],"ar":["مراجعة الكود على أساس سياسات استعراض الكتب","دعم مراجعة الفصول الكاملة على أساس مسارات الملفات","التكامل مع Git لمراجعة التغييرات غير الملتزمة","دعم مراجعة السطور المحددة في الملفات","استخدام إطار العمل لبرهنة البيانات من الرست لضمان سلامة البيانات"]},"keywords":{"en":["how to use book-review","book-review setup guide","Rust language proof-carrying data","git diff for code review","book-review alternative","book-review vs git review","install book-review","book-review for developers","book-review tutorial"],"zh":["Rust语言","代码审查","书籍章节审查","AI工具","Proof-Carrying Data","git diff","代码质量","开发效率"],"ja":["Rust言語","コードレビュー","書籍章のレビュー","AIエージェント","Proof-Carrying Data","git diff","コード品質","開発効率"],"ko":["Rust 언어","코드 리뷰","책 장 리뷰","AI 에이전트","Proof-Carrying Data","git diff","코드 품질","개발 효율"],"es":["book-review","Rust","revisión de libros","políticas de revisión","git diff","desarrollo de software","herramientas de desarrollo","agentes de AI","Herramientas de revisión de código"],"fr":["book-review","Rust","révision de livres","politiques de révision","git diff","développement de logiciels","outils de développement","agents IA","Outils de révision de code"],"de":["book-review","Rust","Buch-Review","Review-Richtlinien","git diff","Software-Entwicklung","Entwicklertools","KI-Agents","Code-Review-Tools"],"pt":["ferramenta de revisão de livros","Rust","revisão de código","políticas de revisão de livros","Git","prova de dados","desenvolvimento de software","qualidade de código"],"ru":["ИИ Агент для обзора книг","Rust","проверка кода","политики обзора книг","Git","доказательство данных","разработка программного обеспечения","качество кода"],"ar":["أداة استعراض الكتب","لغة الرست","مراجعة الكود","سياسات استعراض الكتب","جيت","برهنة البيانات","تطوير البرمجيات","جودة الكود"]}},"owner":"tachyon-zcash","repo":"ragu","repoPath":"tachyon-zcash/ragu","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"book-review","description":"Review any part of the book using parallel specialist agents","bodyPreview":"# Book Review\n\nReview part of the book specified by `$ARGUMENTS`, using the project''s book\nreview policies.\n\n## Step 1: Figure Out What to Review\n\nThe user''s `$ARGUMENTS` could be anything. Interpret them:\n\n| Arguments | What to do |\n|-----------|-----------|\n| *(empty)* | Run `git diff -- book/src/` and `git diff --cached -- book/src/`. Review the uncommitted changes. If no changes, say so and stop. |\n| A file path | Read that file. Review the whole chapter. |\n| A file path with lines (`foo.md:","body":"# Book Review\n\nReview part of the book specified by `$ARGUMENTS`, using the project''s book\nreview policies.\n\n## Step 1: Figure Out What to Review\n\nThe user''s `$ARGUMENTS` could be anything. Interpret them:\n\n| Arguments | What to do |\n|-----------|-----------|\n| *(empty)* | Run `git diff -- book/src/` and `git diff --cached -- book/src/`. Review the uncommitted changes. If no changes, say so and stop. |\n| A file path | Read that file. Review the whole chapter. |\n| A file path with lines (`foo.md:50-80`) | Read that file. Focus the review on those lines (but read the full file for context). |\n| Multiple file paths | Read all of them. Review each, and also look for consistency across them. |\n| A section heading or topic name | Use Grep/Glob to find where that topic is discussed in `book/src/`. Read those sections. Review them. |\n| A conceptual description (\"how we explain X\", \"the transition between Y and Z\") | Search the book to find the relevant passages. Read them with surrounding context. Review them as a unit. |\n| A mix of the above | Handle each part, then review the union. |\n\nIf you''re unsure what the user means, ask before launching reviewers.\n\n## Step 2: Discover and Launch Reviewers\n\n1. Use Glob to find all `.claude/book-review/*.md` files.\n2. Read `.claude/book-review/standards.md` (master standards shared by all\n   reviewers).\n3. For EACH policy file **except `standards.md`**, launch a `general-purpose`\n   Task agent (use model `sonnet`). Give each agent a prompt constructed from\n   this template — adapt it based on what you''re reviewing:\n\n   > You are reviewing part of \"The Ragu Book,\" a technical book about a\n   > recursive proof system (proof-carrying data framework).\n   >\n   > Read these files:\n   > - `.claude/book-review/standards.md` (master standards that always apply)\n   > - `.claude/book-review/{focus}.md` (your specific review policy)\n   >\n   > **What to review:** {describe the specific content — file paths, line\n   > ranges, the topic, whatever the user specified. If reviewing a diff,\n   > include the diff text and list the full file paths for context.}\n   >\n   > {If the scope is a diff or a narrow range, add: \"Focus on the specified\n   > content. Flag issues in surrounding text ONLY if the specified content\n   > introduced an inconsistency with it.\"}\n   >\n   > {If the scope spans multiple files or a concept, add: \"Pay attention to\n   > consistency across the passages. Flag contradictions, redundancies, or\n   > gaps in the explanation as it spans these locations.\"}\n   >\n   > If the policy references other files (like `book/macros.txt` or\n   > `book/src/appendix/terminology.md`), read those too.\n   >\n   > For each finding:\n   > - **Location**: file path and quoted text (or line number)\n   > - **Issue**: what''s wrong, specifically\n   > - **Suggestion**: a concrete rewrite, not just \"improve this\"\n   > - **Severity**: `must-fix` (clearly wrong/confusing) or `suggestion`\n   >\n   > Stay within your policy''s scope. Be specific. If you find no real issues,\n   > say so — don''t manufacture problems.\n   >\n   > **Tool usage rules:**\n   > - Use the Grep tool for searching file contents — do NOT run `grep` or `rg`\n   >   as a Bash command.\n   > - Use the Read tool to read files — do NOT use `cat`, `head`, or `tail`.\n   > - Use the Glob tool to find files — do NOT use `find` or `ls`.\n   > - When you do use Bash, the command must be a clean shell command with NO\n   >   comment lines (`#`) prepended. Put your reasoning in the `description`\n   >   parameter, not in the command itself.\n\n   Additionally, read `book/FIXME.md` and extract the `###`-level headings\n   under `## Deferred Issues`. Include them in each reviewer''s prompt as a\n   bullet list with the instruction:\n   > The following issues are already tracked and deferred. Do NOT raise\n   > findings that duplicate or overlap with these items. If your finding\n   > is essentially the same issue, omit it.\n   >\n   > {bullet list of ### headings from book/FIXME.md}\n   >\n   > However, if while reviewing you notice that a deferred issue appears to\n   > have been **resolved** by existing content or is now easily resolvable\n   > given changes in the surrounding text, mention it as a separate\n   > observation (not a finding). Format:\n   > - **Resolvable FIXME**: \"{FIXME heading}\" — {brief explanation of why\n   >   it appears resolved or how to resolve it now}\n\n   Launch ALL agents in parallel (multiple Task calls in one message).\n\n## Step 3: Run Automated Link Checks\n\nIn parallel with the reviewer agents (launched in Step 2), run the automated\nQA scripts to detect broken links and dead pages:\n\n1. Run `python3 qa/book/broken_links.py` — finds broken internal links and\n   invalid anchors (requires `mdbook` to be installed).\n2. Run `python3 qa/book/dead_pages.py` — finds markdown files not listed in\n   `SUMMARY.md`.\n3. Run `python3 qa/book/line_width.py` — finds lines exceeding the\n   80-character width limit (excludes code blocks, math blocks, and other\n   exempt content).\n\nIf either script fails to run (e.g., `mdbook` is not installed), note the\nfailure in your output but do not block the review. Include any findings from\nthese scripts alongside the reviewer agents'' results in the synthesis step.\n\n## Step 4: Synthesize\n\nOnce all agents return, organize findings by location (earliest in the book\nfirst). If multiple reviewers flagged overlapping concerns, merge them. Present:\n\n- **Must-fix** issues first\n- **Suggestions** second\n- For each finding, note which reviewer(s) identified it\n\nIf the review scope was cross-file or conceptual, add a short section at the end\nabout cross-cutting observations (consistency, narrative coherence, etc.).\n\nBefore presenting findings, read `book/FIXME.md` and remove any finding that\nsubstantially overlaps with an already-deferred issue (match against the `###`\nheadings). If you remove findings this way, do not mention them at all.\n\nIf any reviewer flagged a resolvable FIXME, collect them in a **Potentially\nResolvable FIXMEs** section after the main findings. The user can then use\n`/book-fixme` to address them.\n\n## Step 5: Validate Proposed Changes\n\nAfter synthesizing findings, but before presenting them to the user:\n\n1. Collect all proposed changes (the \"suggestion\" field from each finding) into\n   a single numbered list — the **proposed plan**.\n2. For EACH policy file (same set as Step 2 — every `.claude/book-review/*.md`\n   except `standards.md`), launch a `general-purpose` Task agent (model\n   `sonnet`) with this prompt:\n\n   > You are validating a set of proposed book edits against review policies.\n   >\n   > Read these files:\n   > - `.claude/book-review/standards.md` (master standards)\n   > - `.claude/book-review/{focus}.md` (your policy)\n   >\n   > Here is the proposed plan of changes:\n   > {numbered list of proposed changes with locations and suggested rewrites}\n   >\n   > For each proposed change, check whether applying it would **introduce** a\n   > violation of any rule in your policy or the master standards. Only flag\n   > real conflicts — do not restate rules that are already satisfied.\n   >\n   > For each conflict found:\n   > - **Change #**: which proposed change\n   > - **Rule violated**: quote the relevant policy text\n   > - **Conflict**: explain specifically how the suggestion violates the rule\n   > - **Resolution**: suggest how to fix the suggestion to comply\n   >\n   > **Tool usage rules:**\n   > - Use the Grep tool for searching file contents — do NOT run `grep` or `rg`\n   >   as a Bash command.\n   > - Use the Read tool to read files — do NOT use `cat`, `head`, or `tail`.\n   > - Use the Glob tool to find files — do NOT use `find` or `ls`.\n   > - When you do use Bash, the command must be a clean shell command with NO\n   >   comment lines (`#`) prepended. Put your reasoning in the `description`\n   >   parameter, not in the command itself.\n   >\n   > If no proposed changes conflict with your policy, say so.\n\n   Launch ALL agents in parallel.\n\n3. Merge validation feedback into the findings. For each conflict:\n   - If the validator provides a compliant alternative, replace the original\n     suggestion with the corrected version.\n   - If the conflict has no clear resolution, annotate the finding with the\n     conflict so the user can decide during triage.\n\n4. If any suggestions were corrected, briefly note it in the synthesis output\n   (e.g., \"Grammar validator caught that suggestion #3 would violate the\n   lowercase-technical-terms rule; corrected.\").\n\n## Step 6: Triage\n\nAfter presenting findings, use AskUserQuestion to let the user decide the\ndisposition of each finding (or group of closely related findings). For each,\noffer:\n\n- **Fix** — apply the suggested fix now\n- **Skip** — drop this finding; do not record it anywhere\n- **Defer** — record this finding in `book/FIXME.md` for future attention\n\nIf there are many findings, you may batch them into logical groups and ask\nabout each group rather than each individual finding.\n\n## Step 7: Apply Fixes\n\nFor each finding the user chose to **fix**:\n\n1. Read the target file to get the current content.\n2. Apply the suggested change using the Edit tool. If the finding is a group\n   (e.g., \"add slugs to these 15 headings\"), apply all changes in the group.\n3. After applying all fixes, run any relevant QA scripts to verify the changes\n   don''t introduce new issues:\n   - If formatting changes were made: `python3 qa/book/line_width.py`\n   - If links or headings were changed: `python3 qa/book/broken_links.py`\n4. Briefly report what was changed and any QA results.\n\n## Step 8: Record Deferred Issues\n\nFor each finding the user chose to **defer**:\n\n1. Read `book/FIXME.md`.\n2. Check whether a substantially similar issue is already listed. First scan\n   the `###` headings for a potential match; if a heading looks similar, read\n   the paragraph beneath it to confirm it describes the same issue. Only skip\n   if both the heading and description match — do not treat a heading match\n   alone as a duplicate.\n3. If the issue is new, append it as a new `###`-level subsection under\n   `## Deferred Issues`, following the existing format: a short descriptive\n   heading, then a concise paragraph explaining the issue and its location.\n4. Write the updated file.\n\nAfter recording, confirm what was deferred and remind the user they can use\n`/book-refine` to turn feedback into policy improvements.\n"},"lastSynced":"2026-03-08T02:01:13.689Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents leveraging Rust for streamlined git diff analysis and custom review policies.","zh":"适用于利用Rust进行流线化git diff分析和自定义审查策略的代码审查代理。","ja":"Rustを使用したストリームライン化されたgit diff分析とカスタムのレビュー ポリシーを利用するコード レビュー エージェントに最適です。","ko":"Rust를 사용하여 스트림 라인화된 git diff 분석 및 사용자 정의 리뷰 정책을 사용하는 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que utilizan Rust para análisis de git diff simplificado y políticas de revisión personalizadas.","fr":"Idéal pour les agents de révision de code utilisant Rust pour une analyse de git diff simplifiée et des politiques de révision personnalisées.","de":"Ideal für Code-Review-Agents, die Rust für eine gestreamte git diff-Analyse und benutzerdefinierte Überprüfungsrichtlinien verwenden.","pt":"Ideal para Agentes de Revisão de Código que utilizam Rust para análise de git diff otimizada e políticas de revisão personalizadas.","ru":"Идеально для Агентов проверки кода, использующих Rust для оптимизированного анализа git diff и пользовательских политик проверки.","ar":"مثالي لعميل مراجعة الكود الذي يستخدم روست لتحليل git diff المتدفق وسياسات المراجعة المخصصة."},"recommendation":{"en":"Empowers agents to review book chapters using git diff analysis and custom policies, enabling efficient proof-carrying data with Rust, and supporting file paths with line specifications for precise review control.","zh":"赋予代理人使用git diff分析和自定义策略审查书籍章节的能力，实现使用Rust进行高效的证明数据传递，并支持带有行规范的文件路径以实现精确的审查控制。","ja":"エージェントがgit diff分析とカスタム ポリシーを使用して書籍の章をレビューする能力を与え、Rustを使用して効率的な証明データの転送を実現し、行仕様を含むファイル パスをサポートして、正確なレビュー制御を実現します。","ko":"에이전트가 git diff 분석 및 사용자 정의 정책을 사용하여 책 장을 리뷰할 수 있는 기능을 부여하여 Rust를 사용하여 효율적인 증명 데이터 전송을 가능하게 하며, 행 사양을 포함하는 파일 경로를 지원하여 정밀한 리뷰 제어를 가능하게 합니다.","es":"Habilita a los agentes a revisar capítulos de libros utilizando análisis de git diff y políticas personalizadas, permitiendo datos de prueba eficientes con Rust y admitiendo rutas de archivo con especificaciones de línea para un control de revisión preciso.","fr":"Permet aux agents de réviser des chapitres de livres en utilisant l''analyse de git diff et des politiques personnalisées, permettant ainsi des données de preuve efficaces avec Rust et prenant en charge les chemins de fichiers avec des spécifications de ligne pour un contrôle de révision précis.","de":"Ermächtigt Agenten, Buchkapitel mithilfe von git diff-Analyse und benutzerdefinierter Richtlinien zu überprüfen, wodurch effiziente Trägerdaten mit Rust ermöglicht werden und Dateipfade mit Zeilenspezifikationen für eine präzise Überprüfungskontrolle unterstützt werden.","pt":"Habilita os agentes a revisar capítulos de livros usando análise de git diff e políticas personalizadas, permitindo dados de comprovação eficientes com Rust e suportando caminhos de arquivos com especificações de linha para controle de revisão preciso.","ru":"Наделяет агентов возможностью просматривать главы книг с помощью анализа git diff и пользовательских политик, обеспечивая эффективную передачу данных с помощью Rust и поддержку путей к файлам с указанием строки для точного контроля проверки.","ar":"يسمح للوكلاء بمراجعة فصول الكتب باستخدام تحليل git diff وسياسات مخصصة، وتمكين بيانات الحمل الكفء مع روست ودعم مسارات الملفات مع مواصفات السطر للسيطرة الدقيقة على المراجعة."},"useCases":{"en":["Reviewing uncommitted book chapter changes","Analyzing specific file paths for code quality","Enforcing custom review policies with git diff"],"zh":["审查未提交的书籍章节更改","分析特定文件路径以检查代码质量","使用git diff实施自定义审查策略"],"ja":["コミットされていない書籍の章の変更をレビューする","コード品質を確認するために特定のファイル パスを分析する","git diffを使用してカスタムのレビュー ポリシーを適用する"],"ko":["커밋되지 않은 책 장의 변경 사항을 리뷰하는 것","코드 품질을 확인하기 위해 특정 파일 경로를 분석하는 것","git diff를 사용하여 사용자 정의 리뷰 정책을 적용하는 것"],"es":["Revisar cambios de capítulos de libros no confirmados","Analizar rutas de archivo específicas para la calidad del código","Hacer cumplir políticas de revisión personalizadas con git diff"],"fr":["Réviser les modifications de chapitres de livres non validés","Analyser des chemins de fichiers spécifiques pour la qualité du code","Faire respecter les politiques de révision personnalisées avec git diff"],"de":["Überprüfen von nicht committeten Buchkapiteländerungen","Analysieren spezifischer Dateipfade für die Codequalität","Durchsetzen benutzerdefinierter Überprüfungsrichtlinien mit git diff"],"pt":["Revisar alterações de capítulos de livros não comprometidas","Analisar caminhos de arquivos específicos para qualidade de código","Impor políticas de revisão personalizadas com git diff"],"ru":["Просмотр незафиксированных изменений глав книги","Анализ конкретных путей файлов для качества кода","Применение пользовательских политик проверки с помощью git diff"],"ar":["مراجعة تغييرات فصول الكتاب غير الملتزمة","تحليل مسارات الملفات المحددة لجودة الكود","تنفيذ سياسات مراجعة مخصصة مع git diff"]},"limitations":{"en":["Requires Rust language support","Limited to git-based version control systems","Needs custom review policies configured"],"zh":["需要Rust语言支持","仅限于基于git的版本控制系统","需要配置自定义审查策略"],"ja":["Rust言語のサポートが必要","gitベースのバージョン管理システムのみ","カスタムのレビュー ポリシーの設定が必要"],"ko":["Rust 언어 지원이 필요함","git 기반 버전 관리 시스템에만 제한됨","사용자 정의 리뷰 정책을 구성해야 함"],"es":["Requiere soporte de lenguaje Rust","Limitado a sistemas de control de versiones basados en git","Requiere políticas de revisión personalizadas configuradas"],"fr":["Nécessite un support de langage Rust","Limité aux systèmes de contrôle de version basés sur git","Nécessite des politiques de révision personnalisées configurées"],"de":["Benötigt Rust-Sprachunterstützung","Begrenzt auf git-basierte Versionskontrollsysteme","Benötigt benutzerdefinierte Überprüfungsrichtlinien, die konfiguriert sind"],"pt":["Exige suporte à linguagem Rust","Limitado a sistemas de controle de versão baseados em git","Necessita de políticas de revisão personalizadas configuradas"],"ru":["Требует поддержки языка Rust","Ограничен системами контроля версий на основе git","Требует настроенных пользовательских политик проверки"],"ar":["يتطلب دعم اللغة روست","محدود بنظم تحكم الإصدارات المستندة إلى جيت","يحتاج إلى سياسات مراجعة مخصصة مضبوطة"]},"version":4},"contentHash":"8cde8111f9ce64927a0c539ae1115d2cc2bb1949fb16a47a97b5d59be82aeae9","qualityScore":32}');
DELETE FROM skills_fts WHERE id = 'tachyon-zcash/ragu/book-review';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tachyon-zcash/ragu/book-review', 'book-review', 'tachyon-zcash', 'ragu', 'community', 'book-review tachyon-zcash ragu community The book-review skill utilizes Rust language for proof-carrying data, benefiting developers by streamlining code review processes through git diff analysis and custom review policies. Book Review是一个Rust语言的证明携带数据框架，用于代码审查和书籍章节审查 Book ReviewはRust言語のProof-Carrying Dataフレームワークであり、コードレビューと書籍章のレビューに使用される Book Review는 Rust 언어의 증명 携帯 데이터 프레임워크로서 코드 리뷰와 책 장을 리뷰하는 데 사용된다 book-review es un marco de datos de comprobación de Rust que revisa partes de un libro según $ARGUMENTS. Utiliza políticas de revisión de libros del proyecto para garantizar la calidad. book-review est un cadre de données de vérification Rust qui examine des parties d''un livre selon $ARGUMENTS. Il utilise les politiques de révision de livres du projet pour assurer la qualité. book-review ist ein Rust-Proof-Carrying-Data-Framework, das Teile eines Buches nach $ARGUMENTS überprüft. Es verwendet die Buch-Review-Richtlinien des Projekts, um die Qualität zu gewährleisten. A ferramenta de revisão de livros com Rust é uma solução inovadora para revisar e melhorar a qualidade do código. Ela utiliza o framework de prova de dados de Rust para garantir a integridade dos dados. ИИ Агент для обзора книг с помощью Rust является инновационным решением для проверки и улучшения качества кода. Он использует фреймворк доказательства данных Rust для обеспечения целостности данных. أداة استعراض الكتب مع لغة الرست هي حل مبتكر لمراجعة وتحسين جودة الكود. إنها تستخدم إطار العمل لبرهنة البيانات من الرست لضمان سلامة البيانات. how to use book-review book-review setup guide Rust language proof-carrying data git diff for code review book-review alternative book-review vs git review install book-review book-review for developers book-review tutorial Rust语言 代码审查 书籍章节审查 AI工具 Proof-Carrying Data git diff 代码质量 开发效率 Interprets $ARGUMENTS for flexible review options Utilizes git diff -- book/src/ for uncommitted changes analysis Supports review of specific file paths and line ranges (e.g., foo.md:10-20) Automates review of whole chapters based on file path input Leverages project''s book review policies for consistent evaluation book-review is a Rust language proof-carrying data framework designed to facilitate efficient code review by interpreting user arguments and applying project-specific review policies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CANTAGESTUDIO/CosmicAtlasPacker/hook-development', 'community', 'CANTAGESTUDIO', 'CosmicAtlasPacker', 'CANTAGESTUDIO/CosmicAtlasPacker', 'hook-development', 0, 0, 32, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:24.862Z', '100b96f059481c5377f6f1c7ebd2955c3a9a817af1ab213103a7d49c473c1bee', '{"id":"CANTAGESTUDIO/CosmicAtlasPacker/hook-development","name":"hook-development","description":{"en":"hook-development is a Flutter Desktop texture atlas editor for game development, allowing developers to automate tasks and validate operations using event-driven automation scripts. It benefits game developers and designers working with Flutter.","zh":"Hook 开发是一种事件驱动的自动化脚本，用于扩展 Claude Code 插件。它支持 Prompt-Based Hooks 和 Command Hooks。","ja":"Hook 開発は、Claude Code プラグインを拡張するためのイベント駆動型自動化スクリプトです。Prompt-Based Hooks と Command Hooks をサポートしています。","ko":"Hook 개발은 Claude Code 플러그인을 확장하기 위한 이벤트驱동 자동화 스크립트입니다. Prompt-Based Hooks 및 Command Hooks를 지원합니다.","es":"Hook-development es una tecnología que permite la automatización de operaciones en Claude Code mediante scripts de eventos. Utilice hook-development para validar operaciones y integrar herramientas externas en flujos de trabajo","fr":"Le développement de hook est une technologie qui permet l''automatisation des opérations dans Claude Code à l''aide de scripts d''événements. Utilisez le développement de hook pour valider les opérations et intégrer des outils externes dans les flux de travail","de":"Hook-development ist eine Technologie, die die Automatisierung von Operationen in Claude Code mithilfe von Ereignisskripten ermöglicht. Nutzen Sie hook-development, um Operationen zu validieren und externe Tools in Workflows zu integrieren","pt":"O Hook-Development é uma ferramenta de automação de eventos para desenvolvimento de jogos, permitindo a criação de hooks personalizados para