INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CANTAGESTUDIO/CosmicAtlasPacker/hook-development', 'hook-development', 'CANTAGESTUDIO', 'CosmicAtlasPacker', 'community', 'hook-development CANTAGESTUDIO CosmicAtlasPacker community hook-development is a Flutter Desktop texture atlas editor for game development, allowing developers to automate tasks and validate operations using event-driven automation scripts. It benefits game developers and designers working with Flutter. Hook 开发是一种事件驱动的自动化脚本，用于扩展 Claude Code 插件。它支持 Prompt-Based Hooks 和 Command Hooks。 Hook 開発は、Claude Code プラグインを拡張するためのイベント駆動型自動化スクリプトです。Prompt-Based Hooks と Command Hooks をサポートしています。 Hook 개발은 Claude Code 플러그인을 확장하기 위한 이벤트驱동 자동화 스크립트입니다. Prompt-Based Hooks 및 Command Hooks를 지원합니다. Hook-development es una tecnología que permite la automatización de operaciones en Claude Code mediante scripts de eventos. Utilice hook-development para validar operaciones y integrar herramientas externas en flujos de trabajo Le développement de hook est une technologie qui permet l''automatisation des opérations dans Claude Code à l''aide de scripts d''événements. Utilisez le développement de hook pour valider les opérations et intégrer des outils externes dans les flux de travail Hook-development ist eine Technologie, die die Automatisierung von Operationen in Claude Code mithilfe von Ereignisskripten ermöglicht. Nutzen Sie hook-development, um Operationen zu validieren und externe Tools in Workflows zu integrieren O Hook-Development é uma ferramenta de automação de eventos para desenvolvimento de jogos, permitindo a criação de hooks personalizados para validação de operações e integração de ferramentas externas Hook-Development - это инструмент автоматизации событий для разработки игр, позволяющий создавать пользовательские хуки для проверки операций и интеграции внешних инструментов для ИИ Агентов Hook-Development هي أداة لتutomatización الأحداث لتطوير الألعاب، تمكن من إنشاء hooks مخصصة للتحقق من العمليات وتكامل الأدوات الخارجية لآلات الذكاء الاصطناعي how to use hook-development hook-development setup guide hook-development alternative hook-development vs Claude Code what is hook-development hook-development install hook-development for game development Flutter Desktop texture atlas editor event-driven automation scripts Hook 开发 Flutter 桌面游戏开发 事件驱动自动化脚本 Claude Code 插件 Prompt-Based Hooks Command Hooks LLM 驱动的决策 Bash 命令 游戏开发工作流 Supports Prompt-Based Hooks for context-aware validation using LLM-driven decision making Executes Command Hooks for deterministic checks using bash commands Integrates with Claude Code events for automated workflows Enables validation of operations and enforcement of policies Adds context to workflows and integrates external tools hook-development is an event-driven automation script editor for Flutter Desktop texture atlas editing, enabling context-aware validation and integration with external tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Daisuke134/anicca.ai/google-calendar-automation', 'community', 'Daisuke134', 'anicca.ai', 'Daisuke134/anicca.ai', 'google-calendar-automation', 0, 0, 32, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:44.016Z', '9d9cca2dfeb40c59100fb1f856667178da3da4e31eab6e371c8db53776d5b553', '{"id":"Daisuke134/anicca.ai/google-calendar-automation","name":"google-calendar-automation","description":{"en":"The google-calendar-automation skill automates Google Calendar workflows, including event creation and scheduling, for AI agents. It benefits developers by streamlining calendar management via Composio''s Google Calendar toolkit.","zh":"Google 日历自动化通过 Rube MCP 实现事件创建、安排和管理。需要 Rube MCP 连接和 Google 日历工具包","ja":"Google カレンダー自動化は Rube MCP を使用してイベント作成、スケジューリング、管理を実現します。Rube MCP 接続と Google カレンダー ツールキットが必要です","ko":"구글 캘린더 자동화는 Rube MCP를 이용하여 이벤트 생성, 스케줄링, 관리를 구현합니다. Rube MCP 연결과 구글 캘린더 툴킷이 필요합니다","es":"La automatización de Google Calendar con Rube MCP permite la creación de eventos, la programación y la gestión de asistentes. Conozca cómo configurarla.","fr":"L''automatisation de Google Calendar avec Rube MCP permet la création d''événements, la planification et la gestion des participants. Découvrez comment la configurer.","de":"Die Automatisierung von Google-Kalender mit Rube MCP ermöglicht die Erstellung von Ereignissen, die Planung und die Verwaltung von Teilnehmern. Erfahren Sie, wie Sie sie einrichten.","pt":"Automatize fluxos de trabalho do Google Calendar com o Rube MCP e a ferramenta do Google Calendar, incluindo criação de eventos e gerenciamento de participantes","ru":"Автоматизируйте рабочие процессы Google Календаря с помощью Rube MCP и инструментария Google Календаря, включая создание событий и управление участниками","ar":"التلقين عمليات جوجل كالندر باستخدام Rube MCP وأداة جوجل كالندر، بما في ذلك إنشاء الأحداث وإدارة المشاركين"},"seo":{"title":{"en":"google-calendar-automation: Setup Guide for AI Agents","zh":"Google 日历自动化 Setup Guide - 通过 Rube MCP 实现高效管理","ja":"Google カレンダー自動化ベストプラクティス - AIエージェントによる効率化","ko":"구글 캘린더 자동화 설정 가이드 - Rube MCP를 이용한 스마트 관리","es":"Automatización de Google Calendar: Guía de Configuración ...","fr":"Automatisation de Google Calendar : Guide de Configuratio...","de":"Google-Kalender-Automatisierung: Einrichtungsanleitung mi...","pt":"Guia de Configuração do Google Calendar Automation","ru":"Настройка Автоматизации Google Календаря через ИИ Агенты","ar":"دليل إعداد تطبيق تلقائي لجوجل كالندر"},"description":{"en":"Unlock proactive nudges for self-care with google-calendar-automation. Learn how to connect Rube MCP and automate Google Calendar workflows today!","zh":"通过 Rube MCP 和 Google 日历工具包，实现事件创建、安排、可用性检查、出席者管理和日历浏览的自动化","ja":"Rube MCP と Google カレンダー ツールキットを使用して、イベント作成、スケジューリング、可用性チェック、出席者管理、カレンダー閲覧を自動化します","ko":"Rube MCP와 구글 캘린더 툴킷을 사용하여 이벤트 생성, 스케줄링, 가용성 확인, 참석자 관리, 캘린더 브라우징을 자동화합니다","es":"Automatice flujos de trabajo de Google Calendar con Rube MCP. Conozca los prerequisitos y la configuración para crear eventos, programar y gestionar asistentes.","fr":"Automatisez les flux de travail de Google Calendar avec Rube MCP. Découvrez les prérequis et la configuration pour créer des événements, planifier et gérer l...","de":"Automatisieren Sie Google-Kalender-Workflows mit Rube MCP. Erfahren Sie mehr über die Voraussetzungen und die Einrichtung für die Erstellung von Ereignissen,...","pt":"Aprenda a automatizar fluxos de trabalho do Google Calendar com o Rube MCP e a ferramenta do Google Calendar","ru":"Автоматизируйте рабочие процессы Google Календаря с помощью Rube MCP и инструментария Google Календаря","ar":"تعلم كيفية تلقين عمليات جوجل كالندر باستخدام Rube MCP وأداة جوجل كالندر"},"definition":{"en":"google-calendar-automation is a skill that automates Google Calendar workflows through Composio''s toolkit, enabling event creation, scheduling, and attendee management.","zh":"Google 日历自动化是通过 Rube MCP 和 Google 日历工具包实现的自动化功能","ja":"Google カレンダー自動化は Rube MCP と Google カレンダー ツールキットを使用した自動化機能です","ko":"구글 캘린더 자동화는 Rube MCP와 구글 캘린더 툴킷을 사용한 자동화 기능입니다","es":"La automatización de Google Calendar es una herramienta que utiliza Rube MCP para automatizar flujos de trabajo de calendario.","fr":"L''automatisation de Google Calendar est un outil qui utilise Rube MCP pour automatiser les flux de travail de calendrier.","de":"Die Automatisierung von Google-Kalender ist ein Tool, das Rube MCP verwendet, um Kalender-Workflows zu automatisieren.","pt":"O Google Calendar Automation é uma ferramenta que permite automatizar fluxos de trabalho do Google Calendar","ru":"Автоматизация Google Календаря - это инструмент, который позволяет автоматизировать рабочие процессы Google Календаря","ar":"تطبيق تلقائي لجوجل كالندر هو أداة تمكنك من تلقين عمليات جوجل كالندر"},"features":{"en":["Automates Google Calendar workflows via Composio''s Google Calendar toolkit","Supports event creation, scheduling, availability checks, and attendee management","Requires Rube MCP connection and active Google Calendar connection via RUBE_MANAGE_CONNECTIONS","Utilizes RUBE_SEARCH_TOOLS for current tool schemas","Enables calendar browsing through the googlecalendar toolkit"],"zh":["事件创建自动化","安排和可用性检查","出席者管理","日历浏览","Rube MCP 连接"],"ja":["イベント作成自動化","スケジューリングと可用性チェック","出席者管理","カレンダー閲覧","Rube MCP 接続"],"ko":["이벤트 생성 자동화","스케줄링과 가용성 확인","참석자 관리","캘린더 브라우징","Rube MCP 연결"],"es":["Creación de eventos de Google Calendar","Programación y gestión de asistentes","Verificación de disponibilidad","Navegación por calendarios","Integración con Rube MCP"],"fr":["Création d''événements Google Calendar","Planification et gestion des participants","Vérification de la disponibilité","Navigation dans les calendriers","Intégration avec Rube MCP"],"de":["Erstellung von Google-Kalender-Ereignissen","Planung und Verwaltung von Teilnehmern","Verfügbarkeitsprüfung","Navigation in Kalendern","Integration mit Rube MCP"],"pt":["Criação de eventos","Gerenciamento de participantes","Verificação de disponibilidade","Navegação pelo calendário","Integração com o Rube MCP","Uso da ferramenta do Google Calendar"],"ru":["Создание событий","Управление участниками","Проверка доступности","Навигация по календарю","Интеграция с Rube MCP","Использование инструментария Google Календаря"],"ar":["إنشاء الأحداث","إدارة المشاركين","التحقق من التوفر","ملاحة الجدول الزمني","التكامل مع Rube MCP","استخدام أداة جوجل كالندر"]},"keywords":{"en":["how to use google-calendar-automation","google-calendar-automation setup guide","Rube MCP connection for google-calendar-automation","google-calendar-automation vs calendar automation tools","google-calendar-automation install for AI agents","automating Google Calendar workflows with Composio''s toolkit"],"zh":["Google 日历自动化","Rube MCP","Google 日历工具包","事件创建自动化","安排和可用性检查","出席者管理","日历浏览","AIエージェント"],"ja":["Google カレンダー自動化","Rube MCP","Google カレンダー ツールキット","イベント作成自動化","スケジューリングと可用性チェック","出席者管理","カレンダー閲覧","AIエージェント"],"ko":["구글 캘린더 자동화","Rube MCP","구글 캘린더 툴킷","이벤트 생성 자동화","스케줄링과 가용성 확인","참석자 관리","캘린더 브라우징","AI 에이전트"],"es":["automatización de google calendar","rube mcp","creación de eventos","gestión de asistentes","verificación de disponibilidad","navegación por calendarios","integración con rube mcp","herramientas de automatización de calendario"],"fr":["automatisation de google calendar","rube mcp","création d''événements","gestion des participants","vérification de la disponibilité","navigation dans les calendriers","intégration avec rube mcp","outils d''automatisation de calendrier"],"de":["google-kalender-automatisierung","rube mcp","erstellung von ereignissen","verwaltung von teilnehmern","verfügbarkeitsprüfung","navigation in kalendern","integration mit rube mcp","werkzeuge für kalenderautomatisierung"],"pt":["google calendar automation","rube mcp","ferramenta do google calendar","automação de fluxos de trabalho","criação de eventos","gerenciamento de participantes","integração com rube mcp"],"ru":["автоматизация google календаря","rube mcp","инструментарий google календаря","автоматизация рабочих процессов","создание событий","управление участниками","интеграция с rube mcp"],"ar":["تطبيق تلقائي لجوجل كالندر","rube mcp","أداة جوجل كالندر","التلقين عمليات جوجل كالندر","إنشاء الأحداث","إدارة المشاركين","التكامل مع rube mcp"]}},"owner":"Daisuke134","repo":"anicca.ai","repoPath":"Daisuke134/anicca.ai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.314Z","topics":[],"category":"community","skillMd":{"name":"google-calendar-automation","description":"Automate Google Calendar events, scheduling, availability checks, and attendee management via Rube MCP (Composio). Create events, find free slots, manage attendees, and list calendars programmatically.","bodyPreview":"# Google Calendar Automation via Rube MCP\n\nAutomate Google Calendar workflows including event creation, scheduling, availability checks, attendee management, and calendar browsing through Composio''s Google Calendar toolkit.\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Google Calendar connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `","body":"# Google Calendar Automation via Rube MCP\n\nAutomate Google Calendar workflows including event creation, scheduling, availability checks, attendee management, and calendar browsing through Composio''s Google Calendar toolkit.\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Google Calendar connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `https://rube.app/mcp` as an MCP server in your client configuration. No API keys needed — just add the endpoint and it works.\n\n\n1. Verify Rube MCP is available by confirming `RUBE_SEARCH_TOOLS` responds\n2. Call `RUBE_MANAGE_CONNECTIONS` with toolkit `googlecalendar`\n3. If connection is not ACTIVE, follow the returned auth link to complete Google OAuth\n4. Confirm connection status shows ACTIVE before running any workflows\n\n## Core Workflows\n\n### 1. Create and Manage Events\n\n**When to use**: User wants to create, update, or delete calendar events\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Identify target calendar ID [Prerequisite]\n2. `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` - Get current time with proper timezone [Optional]\n3. `GOOGLECALENDAR_FIND_FREE_SLOTS` - Check availability before booking [Optional]\n4. `GOOGLECALENDAR_CREATE_EVENT` - Create the event [Required]\n5. `GOOGLECALENDAR_PATCH_EVENT` - Update specific fields of an existing event [Alternative]\n6. `GOOGLECALENDAR_UPDATE_EVENT` - Full replacement update of an event [Alternative]\n7. `GOOGLECALENDAR_DELETE_EVENT` - Delete an event [Optional]\n\n**Key parameters**:\n- `calendar_id`: Use ''primary'' for main calendar, or specific calendar ID\n- `start_datetime`: ISO 8601 format ''YYYY-MM-DDTHH:MM:SS'' (NOT natural language)\n- `timezone`: IANA timezone name (e.g., ''America/New_York'', NOT ''EST'' or ''PST'')\n- `event_duration_hour`: Hours (0+)\n- `event_duration_minutes`: Minutes (0-59 only; NEVER use 60+)\n- `summary`: Event title\n- `attendees`: Array of email addresses (NOT names)\n- `location`: Free-form text for event location\n\n**Pitfalls**:\n- `start_datetime` must be ISO 8601; natural language like ''tomorrow'' is rejected\n- `event_duration_minutes` max is 59; use `event_duration_hour=1` instead of `event_duration_minutes=60`\n- `timezone` must be IANA identifier; abbreviations like ''EST'', ''PST'' are NOT valid\n- `attendees` only accepts email addresses, not names; resolve names first\n- Google Meet link creation defaults to true; may fail on personal Gmail accounts (graceful fallback)\n- Organizer is auto-added as attendee unless `exclude_organizer=true`\n\n### 2. List and Search Events\n\n**When to use**: User wants to find or browse events on their calendar\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Get available calendars [Prerequisite]\n2. `GOOGLECALENDAR_FIND_EVENT` - Search by title/keyword with time bounds [Required]\n3. `GOOGLECALENDAR_EVENTS_LIST` - List events in a time range [Alternative]\n4. `GOOGLECALENDAR_EVENTS_INSTANCES` - List instances of a recurring event [Optional]\n\n**Key parameters**:\n- `query` / `q`: Free-text search (matches summary, description, location, attendees)\n- `timeMin`: Lower bound (RFC3339 with timezone offset, e.g., ''2024-01-01T00:00:00-08:00'')\n- `timeMax`: Upper bound (RFC3339 with timezone offset)\n- `singleEvents`: true to expand recurring events into instances\n- `orderBy`: ''startTime'' (requires singleEvents=true) or ''updated''\n- `maxResults`: Results per page (max 2500)\n\n**Pitfalls**:\n- **Timezone warning**: UTC timestamps (ending in ''Z'') don''t align with local dates; use local timezone offsets instead\n- Example: ''2026-01-19T00:00:00Z'' covers 2026-01-18 4pm to 2026-01-19 4pm in PST\n- Omitting `timeMin`/`timeMax` scans the full calendar and can be slow\n- `pageToken` in response means more results; paginate until absent\n- `orderBy=''startTime''` requires `singleEvents=true`\n\n### 3. Manage Attendees and Invitations\n\n**When to use**: User wants to add, remove, or update event attendees\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_FIND_EVENT` or `GOOGLECALENDAR_EVENTS_LIST` - Find the event [Prerequisite]\n2. `GOOGLECALENDAR_PATCH_EVENT` - Add attendees (replaces entire attendees list) [Required]\n3. `GOOGLECALENDAR_REMOVE_ATTENDEE` - Remove a specific attendee by email [Required]\n\n**Key parameters**:\n- `event_id`: Unique event identifier (opaque string, NOT the event title)\n- `attendees`: Full list of attendee emails (PATCH replaces entire list)\n- `attendee_email`: Email to remove\n- `send_updates`: ''all'', ''externalOnly'', or ''none''\n\n**Pitfalls**:\n- `event_id` is a technical identifier, NOT the event title; always search first to get the ID\n- `PATCH_EVENT` attendees field replaces the entire list; include existing attendees to avoid removing them\n- Attendee names cannot be resolved; always use email addresses\n- Use `GMAIL_SEARCH_PEOPLE` to resolve names to emails before managing attendees\n\n### 4. Check Availability and Free/Busy Status\n\n**When to use**: User wants to find available time slots or check busy periods\n\n**Tool sequence**:\n1. `GOOGLECALENDAR_LIST_CALENDARS` - Identify calendars to check [Prerequisite]\n2. `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` - Get current time with timezone [Optional]\n3. `GOOGLECALENDAR_FIND_FREE_SLOTS` - Find free intervals across calendars [Required]\n4. `GOOGLECALENDAR_FREE_BUSY_QUERY` - Get raw busy periods for computing gaps [Fallback]\n5. `GOOGLECALENDAR_CREATE_EVENT` - Book a confirmed slot [Required]\n\n**Key parameters**:\n- `items`: List of calendar IDs to check (e.g., [''primary''])\n- `time_min`/`time_max`: Query interval (defaults to current day if omitted)\n- `timezone`: IANA timezone for interpreting naive timestamps\n- `calendarExpansionMax`: Max calendars (1-50)\n- `groupExpansionMax`: Max members per group (1-100)\n\n**Pitfalls**:\n- Maximum span ~90 days per Google Calendar freeBusy API limit\n- Very long ranges or inaccessible calendars yield empty/invalid results\n- Only calendars with at least freeBusyReader access are visible\n- Free slots responses may normalize to UTC (''Z''); check offsets\n- `GOOGLECALENDAR_FREE_BUSY_QUERY` requires RFC3339 timestamps with timezone\n\n## Common Patterns\n\n### ID Resolution\n- **Calendar name -> calendar_id**: `GOOGLECALENDAR_LIST_CALENDARS` to enumerate all calendars\n- **Event title -> event_id**: `GOOGLECALENDAR_FIND_EVENT` or `GOOGLECALENDAR_EVENTS_LIST`\n- **Attendee name -> email**: `GMAIL_SEARCH_PEOPLE`\n\n### Timezone Handling\n- Always use IANA timezone identifiers (e.g., ''America/Los_Angeles'')\n- Use `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` to get current time in user''s timezone\n- When querying events for a local date, use timestamps with local offset, NOT UTC\n- Example: ''2026-01-19T00:00:00-08:00'' for PST, NOT ''2026-01-19T00:00:00Z''\n\n### Pagination\n- `GOOGLECALENDAR_EVENTS_LIST` returns `nextPageToken`; iterate until absent\n- `GOOGLECALENDAR_LIST_CALENDARS` also paginates; use `page_token`\n\n## Known Pitfalls\n\n- **Natural language dates**: NOT supported; all dates must be ISO 8601 or RFC3339\n- **Timezone mismatch**: UTC timestamps don''t align with local dates for filtering\n- **Duration limits**: `event_duration_minutes` max 59; use hours for longer durations\n- **IANA timezones only**: ''EST'', ''PST'', etc. are NOT valid; use ''America/New_York''\n- **Event IDs are opaque**: Always search to get event_id; never guess or construct\n- **Attendees as emails**: Names cannot be used; resolve with GMAIL_SEARCH_PEOPLE\n- **PATCH replaces attendees**: Include all desired attendees in the array, not just new ones\n- **Conference limitations**: Google Meet may fail on personal accounts (graceful fallback)\n- **Rate limits**: High-volume searches can trigger 403/429; throttle between calls\n\n## Quick Reference\n\n| Task | Tool Slug | Key Params |\n|------|-----------|------------|\n| List calendars | `GOOGLECALENDAR_LIST_CALENDARS` | `max_results` |\n| Create event | `GOOGLECALENDAR_CREATE_EVENT` | `start_datetime`, `timezone`, `summary` |\n| Update event | `GOOGLECALENDAR_PATCH_EVENT` | `calendar_id`, `event_id`, fields to update |\n| Delete event | `GOOGLECALENDAR_DELETE_EVENT` | `calendar_id`, `event_id` |\n| Search events | `GOOGLECALENDAR_FIND_EVENT` | `query`, `timeMin`, `timeMax` |\n| List events | `GOOGLECALENDAR_EVENTS_LIST` | `calendarId`, `timeMin`, `timeMax` |\n| Recurring instances | `GOOGLECALENDAR_EVENTS_INSTANCES` | `calendarId`, `eventId` |\n| Find free slots | `GOOGLECALENDAR_FIND_FREE_SLOTS` | `items`, `time_min`, `time_max`, `timezone` |\n| Free/busy query | `GOOGLECALENDAR_FREE_BUSY_QUERY` | `timeMin`, `timeMax`, `items` |\n| Remove attendee | `GOOGLECALENDAR_REMOVE_ATTENDEE` | `event_id`, `attendee_email` |\n| Get current time | `GOOGLECALENDAR_GET_CURRENT_DATE_TIME` | `timezone` |\n| Get calendar | `GOOGLECALENDAR_GET_CALENDAR` | `calendar_id` |\n"},"lastSynced":"2026-03-08T02:02:44.016Z","agentAnalysis":{"suitability":{"en":"Perfect for Schedule Management Agents needing automated Google Calendar workflow integration.","zh":"适合需要自动化Google Calendar工作流集成的日程管理代理。","ja":"Google Calendarのワークフロー自動化の統合が必要なスケジュール管理エージェントに適しています。","ko":"Google Calendar 워크플로 자동화 통합이 필요한 스케줄 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de gestión de horarios que necesitan integración de flujo de trabajo automatizada de Google Calendar.","fr":"Parfait pour les agents de gestion de planning nécessitant une intégration de workflow Google Calendar automatisée.","de":"Perfekt für Schedule-Management-Agents, die eine automatisierte Google-Kalender-Workflow-Integration benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Agendamento que precisam de integração de fluxo de trabalho automatizada do Google Calendar.","ru":"Идеально для агентов управления расписанием, которым необходима автоматизированная интеграция рабочего процесса Google Calendar.","ar":"مثالي لعمليات إدارة الجدول الزمني التي تحتاج إلى دمج تلقائي في سير عمل جوجل كالندر."},"recommendation":{"en":"Empowers agents to automate event creation, scheduling, availability checks, attendee management, and calendar browsing through Composio''s Google Calendar toolkit, utilizing Rube MCP and the googlecalendar connection.","zh":"通过Composio的Google Calendar工具包、利用Rube MCP和googlecalendar连接，赋予代理自动创建事件、安排、可用性检查、出席者管理和日历浏览的能力。","ja":"ComposioのGoogle Calendarツールキットを使用し、Rube MCPとgooglecalendar接続を利用して、エージェントにイベントの作成、スケジューリング、可用性の確認、出席者管理、カレンダーの閲覧を自動化する能力を付与します。","ko":"Composio의 Google Calendar 툴킷을 사용하여 Rube MCP와 googlecalendar 연결을 활용하여 에이전트가 이벤트 생성, 스케줄링, 가용성 확인, 참석자 관리 및 캘린더閲覧을 자동화하는 기능을 부여합니다.","es":"Habilita a los agentes a automatizar la creación de eventos, programación, verificación de disponibilidad, gestión de asistentes y navegación por calendario a través de la herramienta de Google Calendar de Composio, utilizando Rube MCP y la conexión googlecalendar.","fr":"Permet aux agents d''automatiser la création d''événements, la planification, les vérifications de disponibilité, la gestion des participants et la navigation dans le calendrier via l''outil Google Calendar de Composio, en utilisant Rube MCP et la connexion googlecalendar.","de":"Ermächtigt die Agenten, die Erstellung von Ereignissen, die Planung, die Verfügbarkeitsprüfung, das Teilnehmermanagement und die Kalenderbrowsing durch das Google-Kalender-Toolkit von Composio zu automatisieren, unter Verwendung von Rube MCP und der googlecalendar-Verbindung.","pt":"Permite que os agentes automatem a criação de eventos, agendamento, verificação de disponibilidade, gerenciamento de participantes e navegação pelo calendário por meio da ferramenta de calendário do Google da Composio, utilizando Rube MCP e a conexão googlecalendar.","ru":"Позволяет агентам автоматизировать создание событий, планирование, проверку доступности, управление участниками и просмотр календаря с помощью инструмента календаря Google от Composio, используя Rube MCP и соединение googlecalendar.","ar":"يمكن للعميل تفويض الوكلاء لتحقيق أتمتة إنشاء الحدث وتحديد الموعد والتحقق من التوفر وإدارة الحضور والمتصفح عبر أداة جوجل كالندر من كومبوسيو، باستخدام Rube MCP و الاتصال googlecalendar."},"useCases":{"en":["Automating event scheduling with attendee management","Generating calendar availability checks for meeting planning","Browsing and managing Google Calendar events programmatically"],"zh":["使用出席者管理自动化事件调度","为会议规划生成日历可用性检查","程序化地浏览和管理Google Calendar事件"],"ja":["出席者管理を使用してイベントスケジューリングを自動化する","会議計画のためのカレンダーの可用性チェックを生成する","プログラムによってGoogle Calendarのイベントを閲覧して管理する"],"ko":["참석자 관리를 사용하여 이벤트 스케줄링을 자동화하는 것","회의 계획을 위한 캘린더 가용성 확인을 생성하는 것","프로그램적으로 Google Calendar의 이벤트를閲覧하고 관리하는 것"],"es":["Automatización de la programación de eventos con gestión de asistentes","Generación de controles de disponibilidad de calendario para la planificación de reuniones","Navegación y gestión de eventos de Google Calendar de forma programática"],"fr":["Automatisation de la planification d''événements avec gestion des participants","Génération de vérifications de disponibilité de calendrier pour la planification de réunions","Navigation et gestion d''événements Google Calendar de manière programmatique"],"de":["Automatisierung der Ereignisplanung mit Teilnehmermanagement","Erzeugung von Kalender-Verfügbarkeitsprüfungen für die Besprechungsplanung","Navigieren und Verwalten von Google-Kalender-Ereignissen programmgesteuert"],"pt":["Automatizar o agendamento de eventos com gerenciamento de participantes","Gerar verificações de disponibilidade do calendário para planejamento de reuniões","Navegar e gerenciar eventos do Google Calendar programaticamente"],"ru":["Автоматизировать планирование событий с управлением участниками","Генерировать проверки доступности календаря для планирования встреч","Просматривать и управлять событиями Google Calendar программно"],"ar":["أتمتة جدولة الأحداث مع إدارة الحضور","генерировать تحقق من توفر التقويم لتحديد اجتماعات","استعراض وإدارة أحداث جوجل كالندر بالبرمجة"]},"limitations":{"en":["Requires Rube MCP connection with RUBE_SEARCH_TOOLS available","Active Google Calendar connection via RUBE_MANAGE_CONNECTIONS with toolkit googlecalendar","Python environment with Composio''s Google Calendar toolkit"],"zh":["需要具有RUBE_SEARCH_TOOLS的Rube MCP连接","需要通过RUBE_MANAGE_CONNECTIONS具有活跃的Google Calendar连接和工具包googlecalendar","需要具有Composio的Google Calendar工具包的Python环境"],"ja":["RUBE_SEARCH_TOOLSを使用したRube MCP接続が必要","RUBE_MANAGE_CONNECTIONSを使用してアクティブなGoogle Calendar接続とツールキットgooglecalendarが必要","ComposioのGoogle Calendarツールキットを使用したPython環境が必要"],"ko":["RUBE_SEARCH_TOOLS를 사용하는 Rube MCP 연결이 필요합니다.","RUBE_MANAGE_CONNECTIONS를 사용하여 활성화된 Google Calendar 연결 및 툴킷 googlecalendar가 필요합니다.","Composio의 Google Calendar 툴킷을 사용하는 Python 환경이 필요합니다."],"es":["Requiere conexión Rube MCP con RUBE_SEARCH_TOOLS disponible","Conexión activa de Google Calendar a través de RUBE_MANAGE_CONNECTIONS con la herramienta googlecalendar","Entorno de Python con la herramienta de Google Calendar de Composio"],"fr":["Nécessite une connexion Rube MCP avec RUBE_SEARCH_TOOLS disponible","Connexion active Google Calendar via RUBE_MANAGE_CONNECTIONS avec l''outil googlecalendar","Environnement Python avec l''outil Google Calendar de Composio"],"de":["Benötigt Rube-MCP-Verbindung mit verfügbarer RUBE_SEARCH_TOOLS","Aktive Google-Kalender-Verbindung über RUBE_MANAGE_CONNECTIONS mit dem googlecalendar-Toolkit","Python-Umgebung mit dem Google-Kalender-Toolkit von Composio"],"pt":["Requer conexão Rube MCP com RUBE_SEARCH_TOOLS disponível","Conexão ativa do Google Calendar via RUBE_MANAGE_CONNECTIONS com a ferramenta googlecalendar","Ambiente Python com a ferramenta de calendário do Google da Composio"],"ru":["Требуется соединение Rube MCP с доступным RUBE_SEARCH_TOOLS","Активное соединение Google Calendar через RUBE_MANAGE_CONNECTIONS с инструментом googlecalendar","Среда Python с инструментом календаря Google от Composio"],"ar":["يتطلب اتصال Rube MCP مع RUBE_SEARCH_TOOLS متاح","اتصال نشط لجوجل كالندر عبر RUBE_MANAGE_CONNECTIONS مع أداة googlecalendar","بيئة بايثون مع أداة جوجل كالندر من كومبوسيو"]},"version":4},"contentHash":"9d9cca2dfeb40c59100fb1f856667178da3da4e31eab6e371c8db53776d5b553","qualityScore":32}');
