INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Daisuke134/anicca.ai/google-calendar-automation', 'google-calendar-automation', 'Daisuke134', 'anicca.ai', 'community', 'google-calendar-automation Daisuke134 anicca.ai community The google-calendar-automation skill automates Google Calendar workflows, including event creation and scheduling, for AI agents. It benefits developers by streamlining calendar management via Composio''s Google Calendar toolkit. Google 日历自动化通过 Rube MCP 实现事件创建、安排和管理。需要 Rube MCP 连接和 Google 日历工具包 Google カレンダー自動化は Rube MCP を使用してイベント作成、スケジューリング、管理を実現します。Rube MCP 接続と Google カレンダー ツールキットが必要です 구글 캘린더 자동화는 Rube MCP를 이용하여 이벤트 생성, 스케줄링, 관리를 구현합니다. Rube MCP 연결과 구글 캘린더 툴킷이 필요합니다 La automatización de Google Calendar con Rube MCP permite la creación de eventos, la programación y la gestión de asistentes. Conozca cómo configurarla. L''automatisation de Google Calendar avec Rube MCP permet la création d''événements, la planification et la gestion des participants. Découvrez comment la configurer. Die Automatisierung von Google-Kalender mit Rube MCP ermöglicht die Erstellung von Ereignissen, die Planung und die Verwaltung von Teilnehmern. Erfahren Sie, wie Sie sie einrichten. Automatize fluxos de trabalho do Google Calendar com o Rube MCP e a ferramenta do Google Calendar, incluindo criação de eventos e gerenciamento de participantes Автоматизируйте рабочие процессы Google Календаря с помощью Rube MCP и инструментария Google Календаря, включая создание событий и управление участниками التلقين عمليات جوجل كالندر باستخدام Rube MCP وأداة جوجل كالندر، بما في ذلك إنشاء الأحداث وإدارة المشاركين how to use google-calendar-automation google-calendar-automation setup guide Rube MCP connection for google-calendar-automation google-calendar-automation vs calendar automation tools google-calendar-automation install for AI agents automating Google Calendar workflows with Composio''s toolkit Google 日历自动化 Rube MCP Google 日历工具包 事件创建自动化 安排和可用性检查 出席者管理 日历浏览 AIエージェント Automates Google Calendar workflows via Composio''s Google Calendar toolkit Supports event creation, scheduling, availability checks, and attendee management Requires Rube MCP connection and active Google Calendar connection via RUBE_MANAGE_CONNECTIONS Utilizes RUBE_SEARCH_TOOLS for current tool schemas Enables calendar browsing through the googlecalendar toolkit google-calendar-automation is a skill that automates Google Calendar workflows through Composio''s toolkit, enabling event creation, scheduling, and attendee management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raivitor/config-codex/openai-docs', 'community', 'raivitor', 'config-codex', 'raivitor/config-codex', 'openai-docs', 0, 0, 32, '2026-03-08T01:57:15.322Z', '2026-03-08T02:02:59.278Z', '100099568ce8887ccd961aad2aa824a6d6054d4e5e697625815cc6e1b30d54a7', '{"id":"raivitor/config-codex/openai-docs","name":"openai-docs","description":{"en":"The openai-docs skill provides current guidance from OpenAI developer docs using the developers.openai.com MCP server, benefiting developers who need accurate information. It prioritizes MCP tools over web search for OpenAI-related questions.","zh":"OpenAI 文档技能提供了快速访问 OpenAI 开发者文档的能力，帮助开发者找到相关文档页面","ja":"OpenAI ドキュメント スキルは、OpenAI 開発者ドキュメントへの迅速なアクセスを提供し、開発者が関連するドキュメント ページを見つけるのに役立ちます","ko":"OpenAI 문서 스킬은 OpenAI 개발자 문서에 빠르게 액세스할 수 있는 기능을 제공하여 개발자가 관련 문서 페이지를 찾을 수 있도록 도와줍니다","es":"OpenAI Docs proporciona orientación actualizada y autorizada desde los documentos de desarrolladores de OpenAI. Utiliza los herramientas MCP para encontrar respuestas precisas.","fr":"OpenAI Docs fournit des conseils actualisés et autorisés à partir de la documentation des développeurs d''OpenAI. Utilisez les outils MCP pour trouver des réponses précises.","de":"OpenAI Docs bietet aktuelle und autorisierte Anleitungen aus der OpenAI-Entwicklerdokumentation. Verwenden Sie die MCP-Tools, um genaue Antworten zu finden.","pt":"O OpenAI Docs fornece orientação autorizada e atualizada sobre desenvolvimento de IA usando o servidor MCP da developers.openai.com.","ru":"OpenAI Документы предоставляют актуальную информацию об ИИ разработке с использованием сервера MCP с developers.openai.com.","ar":"توفر وثائق OpenAI إرشادات موثوقة وحديثة حول تطوير الذكاء الاصطناعي باستخدام خادم MCP من developers.openai.com."},"seo":{"title":{"en":"openai-docs: MCP Server Integration Guide | AI Agent Skill","zh":"OpenAI 文档集成指南","ja":"OpenAI ドキュメント検索設定ガイド","ko":"OpenAI 문서 통합 설정 가이드","es":"Guía de configuración de OpenAI Docs para desarrolladores","fr":"Guide de démarrage rapide pour OpenAI Docs","de":"OpenAI Docs Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do OpenAI Docs","ru":"Настройка OpenAI Документов: ИИ Агенты","ar":"دليل إعداد وثائق OpenAI"},"description":{"en":"Unlock authoritative OpenAI guidance with openai-docs. Discover how to prioritize developer docs MCP tools and fall back to web search when needed. Get start...","zh":"使用 OpenAI 文档技能，快速找到相关文档页面，并获取最新的开发者指导","ja":"OpenAI ドキュメント スキルを使用して、関連するドキュメント ページをすばやく見つけて、最新の開発者向けガイダンスを取得します","ko":"OpenAI 문서 스킬을 사용하여 관련 문서 페이지를 빠르게 찾고 최신 개발자 가이드를 얻으세요","es":"Accede a la documentación oficial de OpenAI con nuestra guía de OpenAI Docs. Aprende a utilizar los herramientas MCP para encontrar respuestas precisas.","fr":"Découvrez les documents officiels d''OpenAI avec notre guide OpenAI Docs. Apprenez à utiliser les outils MCP pour trouver des réponses précises.","de":"Greifen Sie auf die offizielle OpenAI-Dokumentation zu mit unserem OpenAI Docs-Leitfaden. Erfahren Sie, wie Sie die MCP-Tools verwenden, um genaue Antworten ...","pt":"Aprenda a configurar o OpenAI Docs para obter orientação autorizada e atualizada sobre desenvolvimento de IA","ru":"Узнайте, как настроить OpenAI Документы для получения актуальной информации об ИИ разработке","ar":"تعرف على كيفية إعداد وثائق OpenAI للاستفادة من الإرشادات الموثوقة والأحدث حول تطوير الذكاء الاصطناعي"},"definition":{"en":"openai-docs is a skill that offers authoritative and current guidance from OpenAI developer documentation using the MCP server.","zh":"OpenAI 文档技能是一种 AI 工具，用于提供 OpenAI 开发者文档的搜索和获取功能","ja":"OpenAI ドキュメント スキルは、OpenAI 開発者ドキュメントの検索と取得機能を提供する AI エージェントです","ko":"OpenAI 문서 스킬은 OpenAI 개발자 문서의 검색 및 가져오기 기능을 제공하는 AI 에이전트입니다","es":"OpenAI Docs es un conjunto de herramientas que proporcionan documentación oficial de OpenAI para desarrolladores.","fr":"OpenAI Docs est un ensemble d''outils qui fournissent la documentation officielle d''OpenAI pour les développeurs.","de":"OpenAI Docs ist eine Sammlung von Tools, die die offizielle OpenAI-Dokumentation für Entwickler bereitstellen.","pt":"O OpenAI Docs é uma ferramenta de documentação que fornece orientação autorizada sobre desenvolvimento de IA","ru":"OpenAI Документы - это инструмент документации, предоставляющий актуальную информацию об ИИ разработке","ar":"وثائق OpenAI هي أداة توثيق تقدم إرشادات موثوقة حول تطوير الذكاء الاصطناعي"},"features":{"en":["Utilizes `mcp__openaiDeveloperDocs__search_openai_docs` to find relevant doc pages","Employs `mcp__openaiDeveloperDocs__fetch_openai_doc` to pull exact sections","Prioritizes developer docs MCP tools over web search for OpenAI-related queries","Falls back to web search when the MCP server returns no meaningful results","Integrates with the developers.openai.com MCP server for accurate information","Supports quick start functionality for efficient documentation retrieval"],"zh":["使用 mcp__openaiDeveloperDocs__search_openai_docs 快速搜索相关文档页面","使用 mcp__openaiDeveloperDocs__fetch_openai_doc 获取确切的文档节","优先使用开发者文档 MCP 工具","支持 web.search 回退机制"],"ja":["mcp__openaiDeveloperDocs__search_openai_docs を使用して関連するドキュメント ページをすばやく検索","mcp__openaiDeveloperDocs__fetch_openai_doc を使用して正確なドキュメント セクションを取得","開発者ドキュメント MCP ツールを優先する","web.search 回帰メカニズムをサポート"],"ko":["mcp__openaiDeveloperDocs__search_openai_docs 를 사용하여 관련 문서 페이지를 빠르게 검색","mcp__openaiDeveloperDocs__fetch_openai_doc 를 사용하여 정확한 문서 섹션을 가져옵니다","개발자 문서 MCP 툴을 우선 사용","web.search 후퇴 메커니즘 지원"],"es":["Búsqueda de documentación oficial de OpenAI con mcp__openaiDeveloperDocs__search_openai_docs","Recuperación de secciones exactas de documentación con mcp__openaiDeveloperDocs__fetch_openai_doc","Priorización de los resultados de los herramientas MCP sobre la búsqueda web","Compatibilidad con el servidor MCP para desarrolladores","Acceso a la documentación más actualizada de OpenAI","Uso de los herramientas MCP para encontrar respuestas precisas"],"fr":["Recherche de documentation officielle d''OpenAI avec mcp__openaiDeveloperDocs__search_openai_docs","Récupération de sections exactes de documentation avec mcp__openaiDeveloperDocs__fetch_openai_doc","Priorisation des résultats des outils MCP sur la recherche web","Compatibilité avec le serveur MCP pour les développeurs","Accès à la documentation la plus à jour d''OpenAI","Utilisation des outils MCP pour trouver des réponses précises"],"de":["Suche nach offizieller OpenAI-Dokumentation mit mcp__openaiDeveloperDocs__search_openai_docs","Abruf exakter Dokumentationsabschnitte mit mcp__openaiDeveloperDocs__fetch_openai_doc","Priorisierung der Ergebnisse der MCP-Tools gegenüber der Web-Suche","Kompatibilität mit dem MCP-Server für Entwickler","Zugriff auf die aktuellste OpenAI-Dokumentation","Verwendung der MCP-Tools, um genaue Antworten zu finden"],"pt":["Pesquisa de documentos do OpenAI usando o MCP","Recuperação de seções exatas de documentos do OpenAI","Priorização do servidor MCP sobre a pesquisa na web","Suporte ao desenvolvimento de IA com documentos atualizados"],"ru":["Поиск документов OpenAI с использованием MCP","Получение точных разделов документов OpenAI","Приоритет сервера MCP над веб-поиском","Поддержка ИИ разработки с актуальными документами"],"ar":["بحث وثائق OpenAI باستخدام MCP","استرجاع أقسام دقيقة من وثائق OpenAI","أولوية خادم MCP على البحث على الويب","دعم تطوير الذكاء الاصطناعي مع وثائق حديثة"]},"keywords":{"en":["how to use openai-docs","openai-docs MCP server integration","openai-docs alternative","openai-docs setup guide","what is openai-docs","openai-docs vs web search","openai-docs install","openai-docs documentation retrieval"],"zh":["OpenAI 文档","AI 文档搜索","开发者文档","MCP 工具","web.search","OpenAI 开发者指南"],"ja":["OpenAI ドキュメント","AI ドキュメント検索","開発者ドキュメント","MCP ツール","web.search","OpenAI 開発者ガイド"],"ko":["OpenAI 문서","AI 문서 검색","개발자 문서","MCP 툴","web.search","OpenAI 개발자 가이드"],"es":["OpenAI Docs","documentación de OpenAI","herramientas MCP","desarrolladores de OpenAI","guias de configuración de OpenAI","búsqueda de documentación de OpenAI","recuperación de secciones de documentación","priorización de resultados de MCP","servidor MCP para desarrolladores","documentación actualizada de OpenAI"],"fr":["OpenAI Docs","documentation d''OpenAI","outils MCP","développeurs d''OpenAI","guides de configuration d''OpenAI","recherche de documentation d''OpenAI","récupération de sections de documentation","priorisation des résultats de MCP","serveur MCP pour les développeurs","documentation à jour d''OpenAI"],"de":["OpenAI Docs","OpenAI-Dokumentation","MCP-Tools","OpenAI-Entwickler","OpenAI-Konfigurationsleitfäden","Suche nach OpenAI-Dokumentation","Abruf von Dokumentationsabschnitten","Priorisierung der MCP-Ergebnisse","MCP-Server für Entwickler","aktuelle OpenAI-Dokumentation"],"pt":["OpenAI Docs","desenvolvimento de IA","MCP servidor","documentação de IA","ferramentas de desenvolvimento de IA","Guia de configuração do OpenAI","orientação autorizada sobre IA"],"ru":["OpenAI Документы","ИИ разработка","MCP сервер","документация ИИ","инструменты ИИ разработки","Настройка OpenAI Документов","актуальная информация об ИИ"],"ar":["وثائق OpenAI","تطوير الذكاء الاصطناعي","خادم MCP","توثيق الذكاء الاصطناعي","أدوات تطوير الذكاء الاصطناعي","دليل إعداد وثائق OpenAI","إرشادات موثوقة حول الذكاء الاصطناعي"]}},"owner":"raivitor","repo":"config-codex","repoPath":"raivitor/config-codex","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.322Z","topics":[],"category":"community","skillMd":{"name":"openai-docs","description":"Use when the user asks how to build with OpenAI products or APIs and needs up-to-date official documentation with citations (for example: Codex, Responses API, Chat Completions, Apps SDK, Agents SDK, Realtime, model capabilities or limits); prioritize OpenAI docs MCP tools and restrict any fallback browsing to official OpenAI domains.","bodyPreview":"# OpenAI Docs\n\nProvide authoritative, current guidance from OpenAI developer docs using the developers.openai.com MCP server. Always prioritize the developer docs MCP tools over web.run for OpenAI-related questions. Only if the MCP server is installed and returns no meaningful results should you fall back to web search.\n\n## Quick start\n\n- Use `mcp__openaiDeveloperDocs__search_openai_docs` to find the most relevant doc pages.\n- Use `mcp__openaiDeveloperDocs__fetch_openai_doc` to pull exact sectio","body":"# OpenAI Docs\n\nProvide authoritative, current guidance from OpenAI developer docs using the developers.openai.com MCP server. Always prioritize the developer docs MCP tools over web.run for OpenAI-related questions. Only if the MCP server is installed and returns no meaningful results should you fall back to web search.\n\n## Quick start\n\n- Use `mcp__openaiDeveloperDocs__search_openai_docs` to find the most relevant doc pages.\n- Use `mcp__openaiDeveloperDocs__fetch_openai_doc` to pull exact sections and quote/paraphrase accurately.\n- Use `mcp__openaiDeveloperDocs__list_openai_docs` only when you need to browse or discover pages without a clear query.\n\n## OpenAI product snapshots\n\n1. Apps SDK: Build ChatGPT apps by providing a web component UI and an MCP server that exposes your app''s tools to ChatGPT.\n2. Responses API: A unified endpoint designed for stateful, multimodal, tool-using interactions in agentic workflows.\n3. Chat Completions API: Generate a model response from a list of messages comprising a conversation.\n4. Codex: OpenAI''s coding agent for software development that can write, understand, review, and debug code.\n5. gpt-oss: Open-weight OpenAI reasoning models (gpt-oss-120b and gpt-oss-20b) released under the Apache 2.0 license.\n6. Realtime API: Build low-latency, multimodal experiences including natural speech-to-speech conversations.\n7. Agents SDK: A toolkit for building agentic apps where a model can use tools and context, hand off to other agents, stream partial results, and keep a full trace.\n\n## If MCP server is missing\n\nIf MCP tools fail or no OpenAI docs resources are available:\n\n1. Run the install command yourself: `codex mcp add openaiDeveloperDocs --url https://developers.openai.com/mcp`\n2. If it fails due to permissions/sandboxing, immediately retry the same command with escalated permissions and include a 1-sentence justification for approval. Do not ask the user to run it yet.\n3. Only if the escalated attempt fails, ask the user to run the install command.\n4. Ask the user to restart Codex.\n5. Re-run the doc search/fetch after restart.\n\n## Workflow\n\n1. Clarify the product scope (Codex, OpenAI API, or ChatGPT Apps SDK) and the task.\n2. Search docs with a precise query.\n3. Fetch the best page and the specific section needed (use `anchor` when possible).\n4. Answer with concise guidance and cite the doc source.\n5. Provide code snippets only when the docs support them.\n\n## Quality rules\n\n- Treat OpenAI docs as the source of truth; avoid speculation.\n- Keep quotes short and within policy limits; prefer paraphrase with citations.\n- If multiple pages differ, call out the difference and cite both.\n- If docs do not cover the user’s need, say so and offer next steps.\n\n## Tooling notes\n\n- Always use MCP doc tools before any web search for OpenAI-related questions.\n- If the MCP server is installed but returns no meaningful results, then use web search as a fallback.\n- When falling back to web search, restrict to official OpenAI domains (developers.openai.com, platform.openai.com) and cite sources.\n"},"lastSynced":"2026-03-08T02:02:59.278Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing authoritative OpenAI developer documentation and guidance from the developers.openai.com MCP server","zh":"非常适合需要权威的OpenAI开发者文档和developers.openai.com MCP服务器指导的AI代理","ja":"OpenAI開発者ドキュメントとdevelopers.openai.comのMCPサーバーのガイダンスが必要なAIエージェントに最適","ko":"developers.openai.com MCP서버의 가이드와 권위적인 OpenAI 개발자 문서가 필요한 AI 에이전트에게 적합","es":"Perfecto para agentes de IA que necesitan documentación y orientación autorizada de los desarrolladores de OpenAI y guías del servidor MCP de developers.openai.com","fr":"Parfait pour les agents IA ayant besoin de documentation et de conseils autorisés des développeurs OpenAI et de guides du serveur MCP de developers.openai.com","de":"Perfekt für KI-Agents, die autorisierte OpenAI-Entwicklerdokumentation und Anleitung von den Entwicklern.openai.com MCP-Servern benötigen","pt":"Perfeito para Agente de IA que precisa de documentação autorizada de desenvolvedor OpenAI e orientação do servidor MCP developers.openai.com","ru":"Идеально для агентов ИИ, которым требуется авторитетная документация для разработчиков OpenAI и руководство сервера MCP developers.openai.com","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى توثيق مطور OpenAI موثوق به وتوجيه من خادم MCP developers.openai.com"},"recommendation":{"en":"Empowers agents to provide accurate and current OpenAI-related information by prioritizing MCP tools over web search, utilizing protocols like MCP server queries and leveraging developer docs for enhanced knowledge retrieval","zh":"通过优先使用MCP工具而不是网络搜索，使用诸如MCP服务器查询等协议，并利用开发者文档来增强知识检索，使得代理能够提供准确和最新的OpenAI相关信息","ja":"MCPツールを優先してWeb検索を使わず、MCPサーバー問い合わせなどのプロトコルを使用し、開発者ドキュメントを活用して知識の取得を強化することで、エージェントが正確で最新のOpenAI関連情報を提供できるようにする","ko":"MCP 도구를 우선하여 웹 검색을 사용하지 않고, MCP 서버 쿼리와 같은 프로토콜을 사용하며, 개발자 문서를 활용하여 지식 검색을 강화함으로써 에이전트가 정확하고 최신의 OpenAI 관련 정보를 제공할 수 있도록 함","es":"Habilita a los agentes a proporcionar información precisa y actualizada relacionada con OpenAI, priorizando las herramientas MCP sobre la búsqueda web, utilizando protocolos como consultas de servidor MCP y aprovechando la documentación de desarrolladores para una recuperación de conocimientos mejorada","fr":"Permet aux agents de fournir des informations précises et à jour sur OpenAI, en donnant la priorité aux outils MCP par rapport à la recherche sur le Web, en utilisant des protocoles tels que les requêtes de serveur MCP et en exploitant la documentation des développeurs pour une récupération de connaissances améliorée","de":"Ermächtigt die Agenten, genaue und aktuelle OpenAI-bezogene Informationen bereitzustellen, indem MCP-Tools gegenüber der Websuche priorisiert werden, Protokolle wie MCP-Serverabfragen genutzt und Entwicklerdokumentation für eine verbesserte Wissensrückgewinnung ausgenutzt werden","pt":"Habilita agentes a fornecer informações precisas e atuais relacionadas à OpenAI, priorizando ferramentas MCP sobre pesquisa na web, utilizando protocolos como consultas de servidor MCP e aproveitando documentação de desenvolvedor para recuperação de conhecimento aprimorada","ru":"Позволяет агентам предоставлять точную и актуальную информацию, связанную с OpenAI, отдаючи приоритет инструментам MCP над поиском в Интернете, используя протоколы, такие как запросы сервера MCP, и используя документацию разработчика для улучшения извлечения знаний","ar":"تمكين العملاء من تقديم معلومات دقيقة وحديثة تتعلق ب OpenAI من خلال تحديد الأولوية لأدوات MCP على البحث على الويب، واستخدام بروتوكولات مثل استفسارات خادم MCP وتعزيز توثيق المطور لاسترجاع المعرفة"},"useCases":{"en":["Searching OpenAI developer docs using mcp__openaiDeveloperDocs__search_openai_docs","Fetching exact sections of OpenAI documentation with mcp__openaiDeveloperDocs__fetch_openai_doc","Resolving OpenAI-related queries with authoritative guidance"],"zh":["使用mcp__openaiDeveloperDocs__search_openai_docs搜索OpenAI开发者文档","使用mcp__openaiDeveloperDocs__fetch_openai_doc获取OpenAI文档的确切部分","使用mcp__openaiDeveloperDocs__resolve_openai_queries解决OpenAI相关查询"],"ja":["mcp__openaiDeveloperDocs__search_openai_docsを使用してOpenAI開発者ドキュメントを検索する","mcp__openaiDeveloperDocs__fetch_openai_docを使用してOpenAIドキュメントの正確な部分を取得する","mcp__openaiDeveloperDocs__resolve_openai_queriesを使用してOpenAI関連のクエリを解決する"],"ko":["mcp__openaiDeveloperDocs__search_openai_docs를 사용하여 OpenAI 개발자 문서를 검색","mcp__openaiDeveloperDocs__fetch_openai_doc를 사용하여 OpenAI 문서의 정확한 부분을 가져옴","mcp__openaiDeveloperDocs__resolve_openai_queries를 사용하여 OpenAI 관련 쿼리를 해결"],"es":["Buscar documentación de desarrolladores de OpenAI con mcp__openaiDeveloperDocs__search_openai_docs","Recuperar secciones exactas de la documentación de OpenAI con mcp__openaiDeveloperDocs__fetch_openai_doc","Resolver consultas relacionadas con OpenAI con orientación autorizada"],"fr":["Rechercher la documentation des développeurs OpenAI avec mcp__openaiDeveloperDocs__search_openai_docs","Récupérer des sections exactes de la documentation OpenAI avec mcp__openaiDeveloperDocs__fetch_openai_doc","Résoudre des requêtes liées à OpenAI avec des conseils autorisés"],"de":["OpenAI-Entwicklerdokumentation mit mcp__openaiDeveloperDocs__search_openai_docs durchsuchen","Genauere Abschnitte der OpenAI-Dokumentation mit mcp__openaiDeveloperDocs__fetch_openai_doc abrufen","OpenAI-bezogene Anfragen mit autorisierter Anleitung lösen"],"pt":["Pesquisando documentação de desenvolvedor OpenAI usando mcp__openaiDeveloperDocs__search_openai_docs","Buscando seções exatas da documentação OpenAI com mcp__openaiDeveloperDocs__fetch_openai_doc","Resolvendo consultas relacionadas à OpenAI com orientação autorizada"],"ru":["Поиск документации разработчика OpenAI с помощью mcp__openaiDeveloperDocs__search_openai_docs","Получение точных разделов документации OpenAI с помощью mcp__openaiDeveloperDocs__fetch_openai_doc","Решение запросов, связанных с OpenAI, с помощью авторитетного руководства"],"ar":["بحث توثيق مطور OpenAI باستخدام mcp__openaiDeveloperDocs__search_openai_docs","استرجاع أقسام دقيقة من توثيق OpenAI باستخدام mcp__openaiDeveloperDocs__fetch_openai_doc","حل استفسارات متعلقة ب OpenAI مع توجيه موثوق به"]},"limitations":{"en":["Requires MCP server installation","Dependent on developers.openai.com MCP server availability and response"],"zh":["需要MCP服务器安装","依赖于developers.openai.com MCP服务器的可用性和响应"],"ja":["MCPサーバーのインストールが必要","developers.openai.comのMCPサーバーの可用性とレスポンスに依存"],"ko":["MCP 서버 설치가 필요","developers.openai.com의 MCP 서버 가용성 및 응답에 의존"],"es":["Requiere instalación del servidor MCP","Dependiente de la disponibilidad y respuesta del servidor MCP de developers.openai.com"],"fr":["Nécessite l''installation du serveur MCP","Dépend de la disponibilité et de la réponse du serveur MCP de developers.openai.com"],"de":["Benötigt die Installation des MCP-Servers","Abhängig von der Verfügbarkeit und Antwort des MCP-Servers von developers.openai.com"],"pt":["Requer instalação do servidor MCP","Dependente da disponibilidade e resposta do servidor MCP developers.openai.com"],"ru":["Требуется установка сервера MCP","Зависит от доступности и ответа сервера MCP developers.openai.com"],"ar":["يتطلب تثبيت خادم MCP","يعتمد على توافر واستجابة خادم MCP developers.openai.com"]},"version":4},"contentHash":"100099568ce8887ccd961aad2aa824a6d6054d4e5e697625815cc6e1b30d54a7","qualityScore":32}');
