INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rakheen-dama/b2b-strawman/ideate', 'ideate', 'rakheen-dama', 'b2b-strawman', 'community', 'ideate rakheen-dama b2b-strawman community ideate is a conversational strategy skill for product strategists, focusing on practice-management and client-services SaaS. It helps businesses optimize billable utilization, client lifetime value, and project profitability. Ideate 技术是产品策略和客户服务 SaaS 的重要组成部分，能够帮助企业提高业务效率和客户满意度 Ideate は、製品戦略とクライアントサービス SaaS の重要な要素であり、ビジネスの効率化と顧客満足度の向上を支援します Ideate 기술은 제품 전략 및 클라이언트 서비스 SaaS의 중요한 구성 요소로, 비즈니스의 효율성을 높이고 고객 만족도를 향상시킬 수 있습니다 Ideate es una habilidad de estrategia conversacional para SaaS que ayuda a mejorar la gestión de proyectos y servicios Ideate est une compétence de stratégie conversationnelle pour les outils de SaaS qui améliore la gestion de projets et de services Ideate ist eine Fähigkeit der Konversationstrategie für SaaS-Tools, die die Projekt- und Dienstleistungsverwaltung verbessert O ideate é uma habilidade de estratégia conversacional para SaaS de gestão de práticas e serviços de cliente, incluindo ferramentas como Harvest e Teamwork Идеате - это навык разговорной стратегии для SaaS управления практикой и клиентскими услугами, включая инструменты như Harvest и Teamwork ideate هو مهارة استراتيجية محادثات لبرامج السaaS لإدارة الممارسات وخدمات العملاء، بما في ذلك أدوات مثل Harvest و Teamwork how to use ideate what is ideate ideate alternative ideate vs Accelo ideate setup guide ideate install product ideation strategy practice-management SaaS client-services SaaS billable utilization optimization Ideate 技术 产品策略 客户服务 SaaS AI 技术 billable utilization client lifetime value project profitability resource planning SaaS 优化 Understands billable utilization and client lifetime value metrics Optimizes project profitability and resource planning Familiar with operational rhythms of agencies, consultancies, and professional services firms Knowledgeable about tools like Harvest, Teamwork, Accelo, Scoro, and Productive.io Provides expertise in practice-management and client-services SaaS Analyzes business metrics like project profitability and resource planning ideate is a product ideation skill that provides expertise in practice-management and client-services SaaS, including tools like Harvest, Teamwork, and Accelo.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chongdashu/phaserjs-tinyswords/phaser-gamedev', 'community', 'chongdashu', 'phaserjs-tinyswords', 'chongdashu/phaserjs-tinyswords', 'phaser-gamedev', 0, 0, 32, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.112Z', '02a7564a8233ac5579ee59aa7bb53ab39e9dc316028a92774d2e26403a0492d1', '{"id":"chongdashu/phaserjs-tinyswords/phaser-gamedev","name":"phaser-gamedev","description":{"en":"phaser-gamedev enables developers to build dynamic 2D browser games using Phaser 3''s scene-based architecture and physics systems, ideal for creating interactive and immersive gaming experiences.","zh":"Phaser游戏开发使用场景和物理系统来构建快速、精致的2D浏览器游戏。游戏开发的动态系统和实体交互是核心","ja":"Phaserゲーム開発はシーンと物理システムを使用して高速で洗練された2Dブラウザゲームを構築します。ゲーム開発のダイナミックシステムとエンティティの相互作用が重要","ko":"Phaser 게임 개발은 씬과 물리 시스템을 사용하여 빠르고 정교한 2D 브라우저 게임을 구축합니다. 게임 개발의 동적 시스템과 엔티티 상호 작용이 핵심입니다","es":"Phaser Game Development es una herramienta para crear juegos 2D en el navegador con una arquitectura basada en escenas y sistemas de física","fr":"Phaser Game Development est un outil pour créer des jeux 2D dans le navigateur avec une architecture basée sur les scènes et des systèmes de physique","de":"Phaser Game Development ist ein Tool zum Erstellen von 2D-Browser-Spielen mit einer szenebasierten Architektur und Physiksystemen","pt":"Phaser GameDev é uma ferramenta para criar jogos 2D rápidos e polidos com Phaser 3","ru":"Phaser GameDev — это инструмент для создания быстрых и отполированных 2D-игр с помощью Phaser 3","ar":"Phaser GameDev هو أداة لإنشاء ألعاب 2D سريعة وملونة باستخدام Phaser 3"},"seo":{"title":{"en":"phaser-gamedev: 2D Browser Game Development Setup Guide |...","zh":"Phaser游戏开发设置指南 - 使用场景和物理系统","ja":"Phaserゲーム開発ベストプラクティス - シーンと物理システムの活用","ko":"Phaser 게임 개발 설정 가이드 - 씬과 물리 시스템을 활용하여","es":"Guía de configuración de Phaser Game Development","fr":"Guide de démarrage de Phaser Game Development","de":"Einrichtungsleitfaden für Phaser Game Development","pt":"Guia de Configuração Phaser GameDev: Desenvolvimento de J...","ru":"ИИ Агенты для Phaser GameDev: Руководство по Настройке","ar":"دليل Phaser GameDev: تطوير ألعاب 2D باستخدام أدوات الذكاء..."},"description":{"en":"Unlock the power of Phaser 3''s scene-based architecture and physics systems. Get started with phaser-gamedev and build fast, polished 2D browser games today!","zh":"学习使用Phaser 3的场景和物理系统来构建快速、精致的2D浏览器游戏。了解游戏开发的动态系统和实体交互","ja":"Phaser 3のシーンと物理システムを使用して高速で洗練された2Dブラウザゲームを構築する方法を学びましょう。ゲーム開発のダイナミックシステムとエンティティの相互作用について","ko":"Phaser 3의 씬과 물리 시스템을 사용하여 빠르고 정교한 2D 브라우저 게임을 구축하는 방법을 배우세요. 게임 개발의 동적 시스템과 엔티티 상호 작용에 대해 알아보세요","es":"Aprende a crear juegos 2D en el navegador con Phaser 3 y su arquitectura basada en escenas","fr":"Découvrez comment créer des jeux 2D dans le navigateur avec Phaser 3 et son architecture basée sur les scènes","de":"Erfahren Sie, wie Sie 2D-Browser-Spiele mit Phaser 3 und seiner szenebasierten Architektur erstellen","pt":"Aprenda a criar jogos 2D rápidos e polidos com Phaser 3 e sua arquitetura baseada em cenas e sistemas de física","ru":"Создавайте быстрые и отполированные 2D-игры для браузера с помощью Phaser 3 и его сценарного архитектуры и физических систем","ar":"تعلم كيفية إنشاء ألعاب 2D سريعة وملونة باستخدام Phaser 3 وعمارة المشهد ونظام الفيزياء"},"definition":{"en":"phaser-gamedev is a skill for building fast, polished 2D browser games using Phaser 3''s scene-based architecture and physics systems, focusing on dynamic systems and entity interactions.","zh":"Phaser游戏开发是一种使用场景和物理系统来构建快速、精致的2D浏览器游戏的方法","ja":"Phaserゲーム開発はシーンと物理システムを使用して高速で洗練された2Dブラウザゲームを構築する方法","ko":"Phaser 게임 개발은 씬과 물리 시스템을 사용하여 빠르고 정교한 2D 브라우저 게임을 구축하는 방법","es":"Phaser Game Development es un framework para crear juegos 2D en el navegador","fr":"Phaser Game Development est un framework pour créer des jeux 2D dans le navigateur","de":"Phaser Game Development ist ein Framework zum Erstellen von 2D-Browser-Spielen","pt":"Phaser GameDev é uma ferramenta de desenvolvimento de jogos 2D que utiliza a arquitetura baseada em cenas e sistemas de física do Phaser 3","ru":"Phaser GameDev — это инструмент разработки 2D-игр, использующий сценарную архитектуру и физические системы Phaser 3","ar":"Phaser GameDev هو أداة تطوير ألعاب 2D تستخدم عمارة المشهد ونظام الفيزياء في Phaser 3"},"features":{"en":["Builds games using Phaser 3''s scene-based architecture","Utilizes physics systems for realistic entity interactions","Supports multiple scenes, including Boot, Menu, Game, Pause, and GameOver","Manages state persistence for seamless gameplay","Enables creation of core entities and their interactions"],"zh":["使用Phaser 3的场景来构建游戏","物理系统来模拟游戏世界","实体交互和状态管理","动态系统来驱动游戏逻辑","快速、精致的2D游戏渲染"],"ja":["Phaser 3のシーンを使用してゲームを構築","物理システムを使用してゲーム世界をシミュレート","エンティティの相互作用と状態管理","ダイナミックシステムを使用してゲームロジックを駆動","高速で洗練された2Dゲームレンダリング"],"ko":["Phaser 3의 씬을 사용하여 게임을 구축","물리 시스템을 사용하여 게임 세계를 시뮬레이션","엔티티 상호 작용과 상태 관리","동적 시스템을 사용하여 게임 로직을 구동","빠르고 정교한 2D 게임 렌더링"],"es":["Arquitectura basada en escenas","Sistemas de física integrados","Creación de juegos 2D en el navegador","Soporte para entidades y estado persistente","Diseño de juegos como sistemas dinámicos"],"fr":["Architecture basée sur les scènes","Systèmes de physique intégrés","Création de jeux 2D dans le navigateur","Prise en charge des entités et de l''état persistant","Conception de jeux comme systèmes dynamiques"],"de":["Szenebasierte Architektur","Integrierte Physiksysteme","Erstellung von 2D-Browser-Spielen","Unterstützung für Entitäten und persistierenden Zustand","Spielentwurf als dynamische Systeme"],"pt":["Arquitetura baseada em cenas do Phaser 3","Sistemas de física para simulações realistas","Desenvolvimento de jogos 2D rápidos e polidos","Criação de entidades e interações dinâmicas","Gerenciamento de estado e persistência de dados"],"ru":["Сценарная архитектура Phaser 3","Физические системы для реалистичных симуляций","Создание быстрых и отполированных 2D-игр","Создание сущностей и динамических взаимодействий","Управление состоянием и сохранение данных"],"ar":["عمارة المشهد في Phaser 3","نظام الفيزياء ل симуляции الواقعية","إنشاء ألعاب 2D سريعة وملونة","إنشاء الكيانات والتفاعلات الديناميكية","إدارة الحالة و保存 البيانات"]},"keywords":{"en":["how to use phaser-gamedev","phaser-gamedev tutorial","phaser-gamedev alternative","phaser-gamedev vs pixi.js","phaser-gamedev install","phaser-gamedev setup guide","2d browser game development","phaser 3 game development"],"zh":["Phaser游戏开发","2D浏览器游戏","场景和物理系统","游戏开发动态系统","实体交互","状态管理","Phaser 3","游戏开发框架"],"ja":["Phaserゲーム開発","2Dブラウザゲーム","シーンと物理システム","ゲーム開発ダイナミックシステム","エンティティの相互作用","状態管理","Phaser 3","ゲーム開発フレームワーク"],"ko":["Phaser 게임 개발","2D 브라우저 게임","씬과 물리 시스템","게임 개발 동적 시스템","엔티티 상호 작용","상태 관리","Phaser 3","게임 개발 프레임워크"],"es":["Phaser Game Development","juegos 2D en el navegador","arquitectura basada en escenas","sistemas de física","entidades y estado persistente","diseño de juegos","herramientas de desarrollo de juegos","framework de juegos 2D"],"fr":["Phaser Game Development","jeux 2D dans le navigateur","architecture basée sur les scènes","systèmes de physique","entités et état persistant","conception de jeux","outils de développement de jeux","framework de jeux 2D"],"de":["Phaser Game Development","2D-Browser-Spiele","szenebasierte Architektur","Physiksysteme","Entitäten und persistierender Zustand","Spielentwurf","Entwicklungstools für Spiele","Framework für 2D-Spiele"],"pt":["Phaser GameDev","desenvolvimento de jogos 2D","arquitetura baseada em cenas","sistemas de física","jogos rápidos e polidos","entidades e interações dinâmicas","gerenciamento de estado","Phaser 3"],"ru":["Phaser GameDev","создание 2D-игр","сценарная архитектура","физические системы","быстрые и отполированные 2D-игры","сущности и динамические взаимодействия","управление состоянием","Phaser 3"],"ar":["Phaser GameDev","تطوير ألعاب 2D","عمارة المشهد","نظام الفيزياء","ألعاب 2D سريعة وملونة","الكيانات والتفاعلات الديناميكية","إدارة الحالة","Phaser 3"]}},"owner":"chongdashu","repo":"phaserjs-tinyswords","repoPath":"chongdashu/phaserjs-tinyswords","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"phaser-gamedev","description":"Build 2D browser games with Phaser 3 (JS/TS): scenes (Boot/Menu/Game/UI), sprites/animations, input, Arcade/Matter physics, tilemaps (Tiled), asset loading, and performance patterns. Use for prompts like Phaser scene, Arcade physics, tilemap, Phaser 3 game architecture.","bodyPreview":"# Phaser Game Development\n\nBuild fast, polished 2D browser games using Phaser 3’s scene-based architecture and physics systems.\n\n## Philosophy: Games as Living Systems\n\nGames are not static UIs—they are **dynamic systems** where entities interact, state evolves, and player input drives everything.\n\n**Before building, ask**:\n- What **scenes** does this game need? (Boot, Menu, Game, Pause, GameOver, UI overlay)\n- What are the **core entities** and how do they interact?\n- What **state** must persis","body":"# Phaser Game Development\n\nBuild fast, polished 2D browser games using Phaser 3’s scene-based architecture and physics systems.\n\n## Philosophy: Games as Living Systems\n\nGames are not static UIs—they are **dynamic systems** where entities interact, state evolves, and player input drives everything.\n\n**Before building, ask**:\n- What **scenes** does this game need? (Boot, Menu, Game, Pause, GameOver, UI overlay)\n- What are the **core entities** and how do they interact?\n- What **state** must persist across scenes (and what must not)?\n- What **physics** model fits? (Arcade for speed, Matter for realism)\n- What **input methods** will players use? (keyboard/gamepad/touch)\n\n**Core principles**:\n1. **Scene-first architecture**: Organize code around scene lifecycle and transitions.\n2. **Composition over inheritance**: Build entities from sprite/body/controllers, not deep class trees.\n3. **Physics-aware design**: Choose collision model early; don’t retrofit physics late.\n4. **Asset pipeline discipline**: Preload everything; reference by keys; keep loading deterministic.\n5. **Frame-rate independence**: Use `delta` for motion and timers; avoid frame counting.\n\n## Workflow: Build the Spine First\n\n- Define the minimal playable loop (movement + win/lose + restart) before content/polish.\n- Decide scene graph and transitions (including UI overlay scene if needed).\n- Choose physics system early:\n  - **Arcade** for most games (platformers/top-down/shooters).\n  - **Matter** for realistic collision/constraints/ragdolls.\n  - **None** for non-physics scenes (menus, VN, card games).\n- Implement a reliable asset-loading path (Boot scene), then scale out content.\n- Add debug toggles/profiling early so performance doesn’t become a late surprise.\n\n## Use References (Progressive Disclosure)\n\n- `references/core-patterns.md`: config, scene lifecycle, objects, input, animations, asset loading, project structure.\n- `references/arcade-physics.md`: Arcade physics deep dive (including pooling patterns).\n- `references/tilemaps.md`: Tiled tilemap workflows, collision setup, object layers.\n- `references/performance.md`: optimization strategies (pooling, batching, culling, camera, texture atlases).\n- `references/spritesheets-nineslice.md`: spritesheet loading (spacing/margin), nine-slice UI panels, asset inspection protocol.\n\n## Anti-Patterns to Avoid\n\n❌ **Global state soup**: Storing game state on `window` or module globals  \nWhy bad: scene transitions become fragile; debugging becomes chaotic  \nBetter: scene data, registries, or a dedicated state manager\n\n❌ **Loading in `create()`**: Loading assets in `create()` instead of `preload()`  \nWhy bad: assets may not be ready when referenced  \nBetter: load in `preload()`; use a Boot scene for all assets\n\n❌ **Frame-dependent logic**: Using frame count instead of `delta`  \nWhy bad: game speed varies with frame rate  \nBetter: scale by `(delta / 1000)` for consistent movement/timers\n\n❌ **Physics overkill**: Using Matter for simple platformer collisions  \nWhy bad: unnecessary complexity + perf cost  \nBetter: Arcade covers most 2D collision needs\n\n❌ **Monolithic scenes**: One giant scene with all game logic  \nWhy bad: hard to extend; UI/menus/pause become hacks  \nBetter: separate gameplay vs UI overlay vs menus\n\n❌ **Magic numbers everywhere**: Hardcoded tuning values scattered in code  \nWhy bad: balancing becomes painful; changes cause regressions  \nBetter: config objects/constants and centralized tuning\n\n❌ **No pooling for spammy objects**: Creating/destroying bullets/particles constantly\nWhy bad: GC spikes → stutters\nBetter: object pooling with groups + `setActive(false)` / `setVisible(false)`\n\n❌ **Assuming spritesheet frame dimensions**: Using guessed frame sizes without verifying source asset\nWhy bad: wrong dimensions cause silent frame corruption; off-by-pixels compounds into broken visuals\nBetter: open asset file, measure frames, calculate with spacing/margin, verify math adds up\n\n❌ **Ignoring spritesheet spacing**: Not specifying `spacing` for gapped spritesheets\nWhy bad: frames shift progressively; later frames read wrong pixel regions\nBetter: check source asset for gaps between frames; use `spacing: N` in loader config\n\n❌ **Hardcoding nine-slice colors**: Using single background color for all UI panel variants\nWhy bad: transparent frame edges reveal wrong color for different asset color schemes\nBetter: per-asset background color config; sample from center frame (frame 4)\n\n❌ **Nine-slice with padded frames**: Treating the full frame as the slice region when the art is centered/padded inside each tile\nWhy bad: edge tiles contribute interior fill, showing up as opaque “side bars” inside the panel\nBetter: trim tiles to their effective content bounds (alpha bbox) and composite/cache a texture; add ~1px overlap + disable smoothing to avoid seams\n\n❌ **Scaling discontinuous UI art**: Scaling a cropped banner/ribbon row that contains internal transparent gaps\nWhy bad: the transparent gutters scale too, making the UI look “broken” or segmented\nBetter: slice into left/center/right (or similar), stretch only the center, and stitch into a cached texture at the target size\n\n## Variation Guidance\n\nOutputs should vary based on:\n- **Genre** (platformer vs top-down vs shmup changes physics/input/camera)\n- **Target platform** (mobile touch, desktop keyboard, gamepad support)\n- **Art style** (pixel art scaling vs HD smoothing; atlas usage)\n- **Performance envelope** (many sprites → pooling/culling; few sprites → simpler code)\n- **Team size / complexity** (prototype vs production architecture)\n\nAvoid converging on:\n- One “default” resolution and scale mode\n- Always defaulting to Arcade (or always defaulting to Matter)\n- Copy-pasting boilerplate without adapting to the game’s needs\n\n## Remember\n\nPhaser gives powerful primitives—scenes, sprites, physics, input—but **architecture is your responsibility**.\n\nThink in systems: define the scenes, define the entities, define their interactions—then implement.\n\n**Codex is capable of building complete, polished Phaser games. These guidelines illuminate the path—they don''t fence it.**\n"},"lastSynced":"2026-03-08T02:04:29.112Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing dynamic 2D browser game creation capabilities with Phaser 3''s scene-based architecture and physics systems.","zh":"非常适合需要动态2D浏览器游戏创建能力的游戏开发代理，具有Phaser 3的场景基于架构和物理系统。","ja":"Phaser 3のシーンベースのアーキテクチャと物理システムを使用した動的2Dブラウザゲーム作成機能が必要なゲーム開発エージェントに最適です。","ko":"Phaser 3의 장면 기반 아키텍처와 물리 시스템을 사용하여 동적 2D 브라우저 게임을 생성할 수 있는 기능이 필요한 게임 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de juegos que necesitan capacidades de creación de juegos de navegador 2D dinámicos con la arquitectura basada en escenas de Phaser 3 y sistemas de física.","fr":"Parfait pour les agents de développement de jeux ayant besoin de capacités de création de jeux de navigateur 2D dynamiques avec l''architecture basée sur les scènes de Phaser 3 et les systèmes de physique.","de":"Perfekt für Game-Development-Agents, die dynamische 2D-Browser-Spiele mit der szenebasierten Architektur von Phaser 3 und Physiksystemen erstellen müssen.","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que necessitam de capacidades de criação de jogos de navegador 2D dinâmicos com a arquitetura baseada em cenas do Phaser 3 e sistemas de física.","ru":"Идеально подходит для агентов по разработке игр, которым необходимы динамические возможности создания 2D-игр для браузера с использованием сценарной архитектуры Phaser 3 и систем физики.","ar":"مثالي للوكلاء الذين يحتاجون إلى إمكانيات إنشاء ألعاب 2D متطورة في المتصفح باستخدام Phaser 3''s scene-based architecture و أنظمة الفيزياء."},"recommendation":{"en":"Empowers agents to build fast, polished 2D browser games using Phaser 3''s scene-based architecture, physics systems, and core entities interaction, enabling the creation of interactive and immersive gaming experiences with dynamic systems and state evolution.","zh":"赋予代理使用Phaser 3的场景基于架构、物理系统和核心实体交互来构建快速、精致的2D浏览器游戏的能力，实现动态系统和状态演化的交互式和沉浸式游戏体验。","ja":"Phaser 3のシーンベースのアーキテクチャ、物理システム、コアエンティティの相互作用を使用して、高速で磨きをかけた2Dブラウザゲームを構築するエージェントを可能にし、ダイナミックシステムと状態の進化を使用したインタラクティブで没入感のあるゲーム体験を作成します。","ko":"Phaser 3의 장면 기반 아키텍처, 물리 시스템 및 핵심 엔티티 상호 작용을 사용하여 빠르고 정교한 2D 브라우저 게임을 구축할 수 있는 에이전트를赋予하고, 동적 시스템 및 상태 진화와 같은 상호 작용형 및 몰입형 게임 경험을 구현할 수 있습니다.","es":"Permite a los agentes crear juegos de navegador 2D rápidos y pulidos utilizando la arquitectura basada en escenas de Phaser 3, sistemas de física y la interacción de entidades básicas, lo que permite la creación de experiencias de juego interactivas e inmersivas con sistemas dinámicos y evolución de estado.","fr":"Permet aux agents de créer des jeux de navigateur 2D rapides et polissés en utilisant l''architecture basée sur les scènes de Phaser 3, les systèmes de physique et l''interaction des entités de base, permettant ainsi la création d''expériences de jeu interactives et immersives avec des systèmes dynamiques et une évolution d''état.","de":"Ermöglicht es Agenten, schnelle und polierte 2D-Browser-Spiele mit der szenebasierten Architektur von Phaser 3, Physiksystemen und der Interaktion von Kernentitäten zu erstellen, wodurch die Erstellung interaktiver und immersiver Spiel-Erfahrungen mit dynamischen Systemen und Zustandsevolution ermöglicht wird.","pt":"Habilita os agentes a construir jogos de navegador 2D rápidos e polidos usando a arquitetura baseada em cenas do Phaser 3, sistemas de física e interação de entidades principais, permitindo a criação de experiências de jogo interativas e imersivas com sistemas dinâmicos e evolução de estado.","ru":"Наделяет агентов возможностью создавать быстрые и отполированные 2D-игры для браузера, используя сценарную архитектуру Phaser 3, системы физики и взаимодействие основных сущностей, что позволяет создавать интерактивные и иммерсивные игровые trải nghiệm с динамическими системами и эволюцией состояния.","ar":"يمنح الوكلاء القدرة على بناء ألعاب متصفح سريعة ومحسنة باستخدام Phaser 3''s scene-based architecture و أنظمة الفيزياء و تفاعل الكائنات الأساسية، مما يسمح بإنشاء تجارب ألعاب تفاعلية و غامرة مع أنظمة ديناميكية وتطور الحالة."},"useCases":{"en":["Building dynamic 2D browser games with Phaser 3''s scene-based architecture","Creating interactive and immersive gaming experiences with physics systems","Designing core entities and their interactions for engaging game play","Developing games with persistent state and player input-driven dynamics"],"zh":["使用Phaser 3的场景基于架构构建动态2D浏览器游戏","使用物理系统创建交互式和沉浸式游戏体验","设计核心实体及其交互以实现吸引人的游戏体验","开发具有持久状态和玩家输入驱动动态的游戏"],"ja":["Phaser 3のシーンベースのアーキテクチャを使用した動的2Dブラウザゲームの構築","物理システムを使用したインタラクティブで没入感のあるゲーム体験の作成","コアエンティティとその相互作用を設計して、魅力的で没入感のあるゲーム体験を実現する","永続的な状態とプレイヤーの入力によって駆動されるダイナミクスを持つゲームの開発"],"ko":["Phaser 3의 장면 기반 아키텍처를 사용하여 동적 2D 브라우저 게임을 구축한다","물리 시스템을 사용하여 상호 작용형 및 몰입형 게임 경험을 생성한다","핵심 엔티티 및 상호 작용을 설계하여 매력적인 게임 플레이를 구현한다","지속적인 상태 및 플레이어 입력에 의한 동적을 가진 게임을 개발한다"],"es":["Creación de juegos de navegador 2D dinámicos con la arquitectura basada en escenas de Phaser 3","Creación de experiencias de juego interactivas e inmersivas con sistemas de física","Diseño de entidades básicas y sus interacciones para un juego atractivo","Desarrollo de juegos con estado persistente y dinámicas impulsadas por la entrada del jugador"],"fr":["Création de jeux de navigateur 2D dynamiques avec l''architecture basée sur les scènes de Phaser 3","Création d''expériences de jeu interactives et immersives avec des systèmes de physique","Conception d''entités de base et de leurs interactions pour un gameplay engageant","Développement de jeux avec un état persistant et des dynamiques impulsées par l''entrée du joueur"],"de":["Erstellung von dynamischen 2D-Browser-Spielen mit der szenebasierten Architektur von Phaser 3","Erstellung interaktiver und immersiver Spiel-Erfahrungen mit Physiksystemen","Entwurf von Kernentitäten und deren Interaktionen für ein unterhaltsames Gameplay","Entwicklung von Spielen mit persistierendem Zustand und spielereingabegetriebenen Dynamiken"],"pt":["Construção de jogos de navegador 2D dinâmicos com a arquitetura baseada em cenas do Phaser 3","Criação de experiências de jogo interativas e imersivas com sistemas de física","Desenho de entidades principais e suas interações para um jogo atraente","Desenvolvimento de jogos com estado persistente e dinâmica impulsionada pela entrada do jogador"],"ru":["Создание динамических 2D-игр для браузера с использованием сценарной архитектуры Phaser 3","Создание интерактивных и иммерсивных игровых trải nghiệm с системами физики","Проектирование основных сущностей и их взаимодействия для увлекательной игры","Разработка игр с сохраненным состоянием и динамикой, управляемой вводом игрока"],"ar":["بناء ألعاب 2D متطورة في المتصفح باستخدام Phaser 3''s scene-based architecture","إنشاء تجارب ألعاب تفاعلية و غامرة مع أنظمة الفيزياء","تصميم الكائنات الأساسية وتفاعلاتها لتشغيل لعبة جذابة","تطوير ألعاب مع حالة مستدامة وديناميكية مدفوعة بالمدخلات الخاصة باللاعب"]},"limitations":{"en":["Requires knowledge of Phaser 3''s scene-based architecture and physics systems","Limited to 2D browser game development","Needs understanding of dynamic systems, state evolution, and player input-driven game design"],"zh":["需要了解Phaser 3的场景基于架构和物理系统","仅限于2D浏览器游戏开发","需要了解动态系统、状态演化和玩家输入驱动的游戏设计"],"ja":["Phaser 3のシーンベースのアーキテクチャと物理システムの知識が必要","2Dブラウザゲームの開発に限定される","ダイナミックシステム、状態の進化、プレイヤーの入力によって駆動されるゲームデザインの理解が必要"],"ko":["Phaser 3의 장면 기반 아키텍처와 물리 시스템에 대한 지식이 필요합니다","2D 브라우저 게임 개발에만 제한됩니다","동적 시스템, 상태 진화 및 플레이어 입력에 의한 게임 디자인에 대한 이해가 필요합니다"],"es":["Requiere conocimiento de la arquitectura basada en escenas de Phaser 3 y sistemas de física","Limitado al desarrollo de juegos de navegador 2D","Necesita comprensión de sistemas dinámicos, evolución de estado y diseño de juego impulsado por la entrada del jugador"],"fr":["Nécessite une connaissance de l''architecture basée sur les scènes de Phaser 3 et des systèmes de physique","Limité au développement de jeux de navigateur 2D","Nécessite une compréhension des systèmes dynamiques, de l''évolution d''état et de la conception de jeu impulsée par l''entrée du joueur"],"de":["Benötigt Kenntnisse der szenebasierten Architektur von Phaser 3 und Physiksystemen","Begrenzt auf die Entwicklung von 2D-Browser-Spielen","Benötigt Verständnis für dynamische Systeme, Zustandsevolution und spielereingabegetriebenes Spieldesign"],"pt":["Requer conhecimento da arquitetura baseada em cenas do Phaser 3 e sistemas de física","Limitado ao desenvolvimento de jogos de navegador 2D","Necessita de compreensão de sistemas dinâmicos, evolução de estado e design de jogo impulsionado pela entrada do jogador"],"ru":["Требует знания сценарной архитектуры Phaser 3 и систем физики","Ограничен разработкой 2D-игр для браузера","Требует понимания динамических систем, эволюции состояния и дизайна игры, управляемого вводом игрока"],"ar":["يتطلب معرفة Phaser 3''s scene-based architecture و أنظمة الفيزياء","محدود بتطوير ألعاب متصفح 2D","يحتاج إلى فهم الأنظمة الديناميكية وتطور الحالة وتصميم اللعبة المدفوعة بالمدخلات الخاصة باللاعب"]},"version":4},"contentHash":"02a7564a8233ac5579ee59aa7bb53ab39e9dc316028a92774d2e26403a0492d1","qualityScore":32}');
