INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chongdashu/phaserjs-tinyswords/phaser-gamedev', 'phaser-gamedev', 'chongdashu', 'phaserjs-tinyswords', 'community', 'phaser-gamedev chongdashu phaserjs-tinyswords community phaser-gamedev enables developers to build dynamic 2D browser games using Phaser 3''s scene-based architecture and physics systems, ideal for creating interactive and immersive gaming experiences. Phaser游戏开发使用场景和物理系统来构建快速、精致的2D浏览器游戏。游戏开发的动态系统和实体交互是核心 Phaserゲーム開発はシーンと物理システムを使用して高速で洗練された2Dブラウザゲームを構築します。ゲーム開発のダイナミックシステムとエンティティの相互作用が重要 Phaser 게임 개발은 씬과 물리 시스템을 사용하여 빠르고 정교한 2D 브라우저 게임을 구축합니다. 게임 개발의 동적 시스템과 엔티티 상호 작용이 핵심입니다 Phaser Game Development es una herramienta para crear juegos 2D en el navegador con una arquitectura basada en escenas y sistemas de física Phaser Game Development est un outil pour créer des jeux 2D dans le navigateur avec une architecture basée sur les scènes et des systèmes de physique Phaser Game Development ist ein Tool zum Erstellen von 2D-Browser-Spielen mit einer szenebasierten Architektur und Physiksystemen Phaser GameDev é uma ferramenta para criar jogos 2D rápidos e polidos com Phaser 3 Phaser GameDev — это инструмент для создания быстрых и отполированных 2D-игр с помощью Phaser 3 Phaser GameDev هو أداة لإنشاء ألعاب 2D سريعة وملونة باستخدام Phaser 3 how to use phaser-gamedev phaser-gamedev tutorial phaser-gamedev alternative phaser-gamedev vs pixi.js phaser-gamedev install phaser-gamedev setup guide 2d browser game development phaser 3 game development Phaser游戏开发 2D浏览器游戏 场景和物理系统 游戏开发动态系统 实体交互 状态管理 Phaser 3 游戏开发框架 Builds games using Phaser 3''s scene-based architecture Utilizes physics systems for realistic entity interactions Supports multiple scenes, including Boot, Menu, Game, Pause, and GameOver Manages state persistence for seamless gameplay Enables creation of core entities and their interactions phaser-gamedev is a skill for building fast, polished 2D browser games using Phaser 3''s scene-based architecture and physics systems, focusing on dynamic systems and entity interactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aztr0nutzs/XENGENiX/gameplay-integrator', 'community', 'aztr0nutzs', 'XENGENiX', 'aztr0nutzs/XENGENiX', 'gameplay-integrator', 0, 0, 32, '2026-03-08T01:57:15.395Z', '2026-03-08T02:06:19.518Z', 'cff1263ec6aabe2ce1391c0198ebc84b68736bb3dac1eeb29b8f882ef1caa429', '{"id":"aztr0nutzs/XENGENiX/gameplay-integrator","name":"gameplay-integrator","description":{"en":"The gameplay-integrator skill integrates or refactors gameplay modes while preserving state, assets, performance, and build stability, benefiting game developers and designers.","zh":"游戏集成器是一种强大的工具，用于集成或重构游戏模式，支持WebView、JS桥接和原生UI","ja":"ゲームプレイ統合ツールは、ゲームモードを統合またはリファクタリングするための強力なツールです。WebView、JSブリッジ、ネイティブUIをサポート","ko":"게임플레이 통합은 게임 모드를 통합하거나 리팩토링하기 위한 강력한 도구입니다. WebView, JS 브릿지, 네이티브 UI를 지원","es":"Gameplay-integrator es una herramienta para integrar o refactorizar modos de juego sin romper los modos existentes, preservando el estado y los activos.","fr":"Gameplay-integrator est un outil pour intégrer ou refactoriser les modes de jeu sans casser les modes existants, en préservant l''état et les ressources.","de":"Gameplay-integrator ist ein Tool zum Integrieren oder Refaktorisieren von Spielmodi, ohne bestehende Modi zu brechen, während der Zustand und die Ressourcen erhalten bleiben.","pt":"O Gameplay Integrator é uma ferramenta que permite integrar ou refatorar modos de jogo sem afetar modos existentes, preservando o estado e os ativos.","ru":"ИИ Агент Gameplay Integrator позволяет интегрировать или рефакторить режимы игры без нарушения существующих режимов, сохраняя состояние и активы.","ar":"Gameplay Integrator هو أداة تمكنك من دمج أو إعادة هيكلة أنماط اللعب دون التأثير على الأنماط الحالية مع الحفاظ على الحالة والموارد."},"seo":{"title":{"en":"gameplay-integrator: Seamless Mode Integration Setup Guid...","zh":"游戏集成器 Setup Guide - 使用WebView和JS桥接","ja":"ゲームプレイ統合ツールベストプラクティス - WebViewとJSブリッジ","ko":"게임플레이 통합 가이드 - WebView와 JS 브릿지","es":"Guía de Configuración de gameplay-integrator para Desarro...","fr":"Guide d''Intégration de gameplay-integrator pour les Dével...","de":"Einrichtungsleitfaden für gameplay-integrator für Entwickler","pt":"Guia de Configuração do Gameplay Integrator para Desenvol...","ru":"Настройка ИИ Агента Gameplay Integrator: Лучшие Практики","ar":"دليل إعداد Gameplay Integrator لتنمية التطبيقات"},"description":{"en":"Discover how to integrate gameplay modes without breaking existing ones. Learn how to preserve state, assets, and performance with our gameplay-integrator guide","zh":"了解游戏集成器的工作原理，使用WebView、JS桥接和原生UI来集成或重构游戏模式","ja":"ゲームプレイ統合ツールの仕組みを解説。WebView、JSブリッジ、ネイティブUIを使用してゲームモードを統合またはリファクタリング","ko":"게임플레이 통합의 원리를 알아보세요. WebView, JS 브릿지, 네이티브 UI를 사용하여 게임 모드를 통합하거나 리팩토링","es":"Aprende a integrar o refactorizar modos de juego con gameplay-integrator, preservando el estado y los activos, y mejorando el rendimiento y la estabilidad de...","fr":"Découvrez comment intégrer ou refactoriser les modes de jeu avec gameplay-integrator, en préservant l''état et les ressources, et en améliorant les performanc...","de":"Erfahren Sie, wie Sie Spielmodi mit gameplay-integrator integrieren oder neu strukturieren, während Sie den Zustand und die Ressourcen erhalten und die Leist...","pt":"Aprenda a integrar modos de jogo sem quebrar modos existentes, preservando o estado, ativos, desempenho e estabilidade de compilação com o Gameplay Integrator","ru":"Интегрируйте режимы игры без нарушения существующих режимов, сохраняя состояние, активы, производительность и стабильность сборки с помощью ИИ Агента Gamepla...","ar":"تعلم كيفية دمج أنماط اللعب دون كسر الأنماط الحالية مع الحفاظ على الحالة والموارد والأداء واستقرار البناء باستخدام Gameplay Integrator"},"definition":{"en":"gameplay-integrator is a skill that enables the integration or refactoring of gameplay modes without compromising existing modes or performance","zh":"游戏集成器是一种AI工具，用于集成或重构游戏模式","ja":"ゲームプレイ統合ツールは、ゲームモードを統合またはリファクタリングするためのAIエージェント","ko":"게임플레이 통합은 게임 모드를 통합하거나 리팩토링하기 위한 AI 도구","es":"Gameplay-integrator es una herramienta de desarrollo que permite integrar o refactorizar modos de juego.","fr":"Gameplay-integrator est un outil de développement qui permet d''intégrer ou de refactoriser les modes de jeu.","de":"Gameplay-integrator ist ein Entwicklungstool, das die Integration oder Neustrukturierung von Spielmodi ermöglicht.","pt":"O que é Gameplay Integrator? É uma ferramenta que integra modos de jogo sem quebrar modos existentes.","ru":"Что такое ИИ Агент Gameplay Integrator? Это инструмент, который интегрирует режимы игры без нарушения существующих режимов.","ar":"ما هو Gameplay Integrator? هو أداة تدمج أنماط اللعب دون كسر الأنماط الحالية."},"features":{"en":["Inspects app architecture via MainActivity.java to determine UI type","Supports WebView-based UI with HTML/CSS/JS and JS bridge","Allows for native UI components in hybrid architectures","Preserves state, assets, and performance during mode integration","Ensures build stability through careful refactoring"],"zh":["支持WebView和JS桥接","原生UI支持","游戏模式集成和重构","保留状态、资产、性能和构建稳定性","支持HTML/CSS/JS和原生代码"],"ja":["WebViewとJSブリッジをサポート","ネイティブUIをサポート","ゲームモードの統合とリファクタリング","状態、資産、パフォーマンス、ビルド安定性を保持","HTML/CSS/JSとネイティブコードをサポート"],"ko":["WebView와 JS 브릿지를 지원","네이티브 UI를 지원","게임 모드의 통합과 리팩토링","상태, 자산, 성능, 빌드 안정성을 유지","HTML/CSS/JS와 네이티브 코드를 지원"],"es":["Integración de modos de juego con WebView/HTML, UI nativa Compose o híbrida","Inspección de la arquitectura en `app/src/main/java/com/xenogenics/app/MainActivity.java`","Uso de rutas de WebView y puente de JS para conectar pantallas","Mejora de la estabilidad y el rendimiento de la compilación"],"fr":["Intégration de modes de jeu avec WebView/HTML, UI native Compose ou hybride","Inspection de l''architecture en `app/src/main/java/com/xenogenics/app/MainActivity.java`","Utilisation de routes de WebView et de pont de JS pour connecter les écrans","Amélioration de la stabilité et des performances de la construction"],"de":["Integration von Spielmodi mit WebView/HTML, nativer UI Compose oder Hybrid","Inspektion der Architektur in `app/src/main/java/com/xenogenics/app/MainActivity.java`","Verwendung von WebView-Routen und JS-Brücke zum Verbinden von Bildschirmen","Verbesserung der Stabilität und Leistung der Build"],"pt":["Integração de modos de jogo sem afetar modos existentes","Preservação do estado e dos ativos","Suporte a WebView, native Compose e hybrid","Uso de JavaScript e JS bridge para wiring","Manutenção da performance e estabilidade de compilação"],"ru":["Интеграция режимов игры без нарушения существующих режимов","Сохранение состояния и активов","Поддержка WebView, native Compose и hybrid","Использование JavaScript и JS bridge для подключения","Поддержание производительности и стабильности сборки"],"ar":["دمج أنماط اللعب دون التأثير على الأنماط الحالية","الحفاظ على الحالة والموارد","دعم WebView و native Compose و hybrid","استخدام JavaScript و JS bridge للربط","الحفاظ على الأداء واستقرار البناء"]},"keywords":{"en":["how to use gameplay-integrator","gameplay-integrator setup guide","gameplay-integrator vs alternative solutions","what is gameplay-integrator","gameplay-integrator install","integrating gameplay modes with gameplay-integrator"],"zh":["游戏集成器","AI工具","游戏模式集成","WebView","JS桥接","原生UI","游戏开发","游戏引擎","游戏框架"],"ja":["ゲームプレイ統合ツール","AIエージェント","ゲームモード統合","WebView","JSブリッジ","ネイティブUI","ゲーム開発","ゲームエンジン","ゲームフレームワーク"],"ko":["게임플레이 통합","AI 도구","게임 모드 통합","WebView","JS 브릿지","네이티브 UI","게임 개발","게임 엔진","게임 프레임워크"],"es":["gameplay-integrator","integración de modos de juego","desarrollo de juegos","herramientas de desarrollo","WebView","UI Compose","JS bridge","estabilidad de la compilación"],"fr":["gameplay-integrator","intégration de modes de jeu","développement de jeux","outils de développement","WebView","UI Compose","pont de JS","stabilité de la construction"],"de":["gameplay-integrator","Integration von Spielmodi","Spielentwicklung","Entwicklungstools","WebView","UI Compose","JS-Brücke","Build-Stabilität"],"pt":["gameplay integrator","desenvolvimento de jogos","integração de modos de jogo","preservação de estado","WebView","native Compose","hybrid","JavaScript","JS bridge"],"ru":["ИИ Агент Gameplay Integrator","разработка игр","интеграция режимов игры","сохранение состояния","WebView","native Compose","hybrid","JavaScript","ИИ Агенты"],"ar":["Gameplay Integrator","تطوير الألعاب","دمج أنماط اللعب","الحفاظ على الحالة","WebView","native Compose","hybrid","JavaScript","أدوات الذكاء الاصطناعي"]}},"owner":"aztr0nutzs","repo":"XENGENiX","repoPath":"aztr0nutzs/XENGENiX","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.395Z","topics":[],"category":"community","skillMd":{"name":"gameplay-integrator","description":"Integrate new or updated gameplay modes into the existing game app end-to-end, including lobby registration, navigation wiring, state persistence, assets, gameplay rules, performance guardrails, and verification. Use when adding a mini-game/mode, refactoring gameplay logic, wiring assets, or ensuring state/controls remain stable across flows.","bodyPreview":"# Gameplay Integrator\n\n## Overview\nIntegrate or refactor gameplay modes without breaking existing modes, while preserving state, assets, performance, and build stability.\n\n## Workflow Decision Tree\n- Architecture gate (must happen first): inspect `app/src/main/java/com/xenogenics/app/MainActivity.java` and determine whether UI is WebView/HTML, native Compose, or hybrid.\n- If WebView-based, default to shipping screens as HTML/CSS/JS and wiring via WebView routes + JS bridge. Only add native UI wh","body":"# Gameplay Integrator\n\n## Overview\nIntegrate or refactor gameplay modes without breaking existing modes, while preserving state, assets, performance, and build stability.\n\n## Workflow Decision Tree\n- Architecture gate (must happen first): inspect `app/src/main/java/com/xenogenics/app/MainActivity.java` and determine whether UI is WebView/HTML, native Compose, or hybrid.\n- If WebView-based, default to shipping screens as HTML/CSS/JS and wiring via WebView routes + JS bridge. Only add native UI when explicitly requested.\n- If the request touches UI or navigation, locate existing lobby and routing patterns before adding new ones.\n- If the project lacks the requested architecture (e.g., Compose, NavGraph, ViewModel), stop and ask how to proceed.\n- If tests are missing, add minimal pure logic tests for gameplay rules.\n\n## Workflow\n\n### 1) Intake and Constraints\n- Parse the request for: mode name, flow entry points, rules, assets, settings to preserve, and performance limits.\n- Confirm constraints in `references/project-standards.md`.\n\n### 2) Locate Integration Points\n- Identify the lobby entry, mode registry, navigation wiring, and state persistence layer.\n- Follow patterns in `references/integration-patterns.md`.\n\n### 3) Gameplay and State\n- Implement or refactor game logic: win/lose, turns, input, pause/resume, game-over flows.\n- Persist and restore: selected character/piece set, difficulty/level, audio/vibration, accessibility settings.\n- Never change persistence keys unless explicitly requested.\n\n### 4) Assets and Resource Mapping\n- Map visuals and audio to real assets; add them via the existing pipeline.\n- Keep assets optimized and in correct directories; avoid mystery files.\n\n### 5) Performance and Stability\n- Avoid heavy work on the main thread.\n- Limit recomposition triggers and mutable state in UI.\n- Prevent unbounded coroutines, loops, or particle effects.\n- Add low-end device guardrails when the project supports them.\n\n### 6) Verification\n- Run the project build/tests (prefer `./gradlew :app:assembleDebug`).\n- If no tests exist, add minimal unit tests for game rules and key transitions.\n- Fix failures and rerun until green.\n\n### 7) Output\n- Provide a concise change log with file paths and a checklist:\n  - Integrated into lobby\n  - Navigation wiring\n  - State persistence\n  - Assets\n  - Performance guardrails\n  - Verification\n\n## Guardrails\n- Do not delete existing modes or routes.\n- Do not change `applicationId` or package names.\n- Only modify files required for the request.\n- No placeholders, TODOs, or dead controls.\n- All visible UI actions must be wired to real logic.\n\n## References\n- `references/project-standards.md`\n- `references/repo-scan.md`\n- `references/integration-patterns.md`\n- `references/asset-pipeline.md`\n- `references/performance-policies.md`\n- `references/test-requirements.md`\n\n## Golden Path Pointers\n- Entry point: `app/src/main/java/com/xenogenics/app/MainActivity.java`\n- Web UI: `app/src/main/assets/www/index.html`, `app/src/main/assets/www/script.js`, `app/src/main/assets/www/style.css`\n"},"lastSynced":"2026-03-08T02:06:19.518Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing seamless gameplay mode integration while preserving state, assets, performance, and build stability.","zh":"非常适合需要无缝游戏模式集成同时保留状态、资产、性能和构建稳定的游戏开发代理。","ja":"ゲーム開発エージェントがシームレスなゲームプレイモード統合を必要とする場合に最適で、状態、資産、パフォーマンス、ビルドの安定性を保ちます。","ko":"무결점한 게임 플레이 모드 통합을 필요로 하는 게임 개발 에이전트에게 적합하며, 상태, 자산, 성능 및 빌드 안정성을 유지합니다.","es":"Perfecto para agentes de desarrollo de juegos que necesitan una integración de modo de juego sin problemas mientras se preserva el estado, los activos, el rendimiento y la estabilidad de la compilación.","fr":"Parfait pour les agents de développement de jeux ayant besoin d''une intégration de mode de jeu transparente tout en préservant l''état, les ressources, les performances et la stabilité de la construction.","de":"Perfekt für Game-Development-Agents, die eine nahtlose Integration des Spielmodus benötigen, während Zustand, Assets, Leistung und Build-Stabilität erhalten bleiben.","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que necessitam de integração de modo de jogo sem interrupção, preservando estado, ativos, desempenho e estabilidade de compilação.","ru":"Идеально подходит для агентов разработки игр, которым требуется бесшовная интеграция режима игры, сохраняющая состояние, активы, производительность и стабильность сборки.","ar":"مثالي لعمليات تطوير الألعاب التي تحتاج إلى دمج نمط لعب متواصل مع الحفاظ على الحالة والموارد والأداء واستقرار البناء."},"recommendation":{"en":"Empowers agents to refactor gameplay modes without breaking existing modes, leveraging architecture gates, WebView routes, and JS bridges to ensure stable and performant builds, while supporting hybrid, native Compose, or WebView/HTML UI architectures.","zh":"赋予代理人重构游戏模式的能力，而不破坏现有的模式，利用架构门、WebView 路由和 JS 桥来确保稳定和高效的构建，同时支持混合、原生 Compose 或 WebView/HTML UI 架构。","ja":"エージェントが既存のモードを破壊せずにゲームプレイモードをリファクタリングできるようにし、アーキテクチャゲート、WebView ルート、JS ブリッジを利用して安定したビルドとパフォーマンスを確保し、ハイブリッド、ネイティブ Compose、または WebView/HTML UI アーキテクチャをサポートします。","ko":"에이전트가 기존 모드를 손상하지 않고 게임 플레이 모드를 리팩토링할 수 있도록 하며, 아키텍처 게이트, WebView 경로 및 JS 브릿지를 사용하여 안정적이고 효율적인 빌드를 보장하며, 하이브리드, 네이티브 Compose 또는 WebView/HTML UI 아키텍처를 지원합니다.","es":"Habilita a los agentes a refactorizar los modos de juego sin romper los modos existentes, aprovechando las puertas de arquitectura, las rutas de WebView y los puentes de JS para garantizar compilaciones estables y con un buen rendimiento, mientras admite arquitecturas de UI híbridas, nativas Compose o WebView/HTML.","fr":"Permet aux agents de refactoriser les modes de jeu sans casser les modes existants, en exploitant les portes d''architecture, les routes de WebView et les ponts de JS pour assurer des constructions stables et performantes, tout en supportant des architectures d''UI hybrides, natives Compose ou WebView/HTML.","de":"Ermächtigt Agenten, Gameplay-Modi ohne Brechen bestehender Modi zu refaktorisieren, indem Architektur-Tore, WebView-Routen und JS-Brücken genutzt werden, um stabile und performante Builds sicherzustellen, während hybride, native Compose- oder WebView/HTML-UI-Architekturen unterstützt werden.","pt":"Habilita os agentes a reestruturar os modos de jogo sem quebrar os modos existentes, aproveitando os gateways de arquitetura, rotas do WebView e pontes do JS para garantir compilações estáveis e de alto desempenho, ao mesmo tempo em que suporta arquiteturas de UI híbridas, nativas Compose ou WebView/HTML.","ru":"Позволяет агентам перерабатывать режимы игры без нарушения существующих режимов, используя архитектурные ворота, маршруты WebView и мосты JS для обеспечения стабильных и производительных сборок, а также поддержки гибридных, родных Compose или архитектур WebView/HTML.","ar":"تمكّن الوكلاء من إعادة هيكلة أنماط اللعب بدون كسر الأنماط الحالية، وتستفيد من بوابات الهندسة المعمارية وطرق عرض الويب وجسور JS لضمان بناء مستقر وعالي الأداء، مع دعم هندسة واجهة المستخدم الهجينة أو الأصلية أو عرض الويب/HTML."},"useCases":{"en":["Integrating new gameplay modes without disrupting existing functionality","Refactoring gameplay modes to improve performance and build stability","Inspecting and determining UI architecture for optimal gameplay integration"],"zh":["将新的游戏模式集成到现有的功能中而不中断","重构游戏模式以提高性能和构建稳定性","检查和确定 UI 架构以实现最佳的游戏集成"],"ja":["既存の機能を中断せずに新しいゲームプレイモードを統合する","パフォーマンスとビルドの安定性を向上させるためにゲームプレイモードをリファクタリングする","最適なゲーム統合を実現するために UI アーキテクチャを検査および決定する"],"ko":["기존 기능을 중단하지 않고 새로운 게임 플레이 모드를 통합하는 것","성능과 빌드 안정성을 향상시키기 위해 게임 플레이 모드를 리팩토링하는 것","최적의 게임 통합을 위해 UI 아키텍처를 검사 및 결정하는 것"],"es":["Integrar nuevos modos de juego sin interrumpir la funcionalidad existente","Refactorizar modos de juego para mejorar el rendimiento y la estabilidad de la compilación","Inspeccionar y determinar la arquitectura de la UI para una integración de juego óptima"],"fr":["Intégrer de nouveaux modes de jeu sans perturber la fonctionnalité existante","Refactoriser les modes de jeu pour améliorer les performances et la stabilité de la construction","Inspecter et déterminer l''architecture de l''UI pour une intégration de jeu optimale"],"de":["Neue Spielmodi integrieren, ohne die bestehende Funktionalität zu stören","Spielmodi refaktorisieren, um die Leistung und die Build-Stabilität zu verbessern","Die UI-Architektur untersuchen und bestimmen, um eine optimale Spielintegration zu ermöglichen"],"pt":["Integrar novos modos de jogo sem interromper a funcionalidade existente","Reestruturar modos de jogo para melhorar o desempenho e a estabilidade da compilação","Inspecionar e determinar a arquitetura da UI para integração de jogo ideal"],"ru":["Интегрировать новые режимы игры без нарушения существующей функциональности","Перерабатывать режимы игры для улучшения производительности и стабильности сборки","Осматривать и определять архитектуру UI для оптимальной интеграции игры"],"ar":["دمج أنماط لعب جديدة بدون تعطيل الوظائف الحالية","إعادة هيكلة أنماط اللعب لتحسين الأداء واستقرار البناء","فحص وتحديد هندسة واجهة المستخدم لتحقيق تكامل اللعب الأمثل"]},"limitations":{"en":["Requires inspection of app architecture, specifically MainActivity.java","Limited to supporting WebView/HTML, native Compose, or hybrid UI architectures"],"zh":["需要检查应用程序架构，特别是 MainActivity.java","仅限支持 WebView/HTML、原生 Compose 或混合 UI 架构"],"ja":["アプリケーションのアーキテクチャ、特に MainActivity.java を検査する必要がある","WebView/HTML、ネイティブ Compose、またはハイブリッド UI アーキテクチャのみをサポートする"],"ko":["애플리케이션 아키텍처, 특히 MainActivity.java를 검사해야 함","WebView/HTML, 네이티브 Compose 또는 하이브리드 UI 아키텍처만 지원"],"es":["Requiere la inspección de la arquitectura de la aplicación, específicamente MainActivity.java","Limitado a admitir arquitecturas de UI WebView/HTML, nativas Compose o híbridas"],"fr":["Nécessite l''inspection de l''architecture de l''application, en particulier MainActivity.java","Limité à supporter des architectures d''UI WebView/HTML, natives Compose ou hybrides"],"de":["Erfordert die Untersuchung der App-Architektur, insbesondere MainActivity.java","Begrenzt auf die Unterstützung von WebView/HTML-, nativen Compose- oder Hybrid-UI-Architekturen"],"pt":["Requer inspeção da arquitetura do aplicativo, especificamente MainActivity.java","Limitado a suportar arquiteturas de UI WebView/HTML, nativas Compose ou híbridas"],"ru":["Требует осмотра архитектуры приложения, в частности MainActivity.java","Ограничен поддержкой архитектур UI WebView/HTML, родных Compose или гибридных"],"ar":["يتطلب فحص هندسة التطبيق، تحديدا MainActivity.java","محدود بالدعم للهندسة القائمة على عرض الويب/HTML أو الأصلية أو الهجينة"]},"version":4},"contentHash":"cff1263ec6aabe2ce1391c0198ebc84b68736bb3dac1eeb29b8f882ef1caa429","qualityScore":32}');
