INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pliniou/loto-generator/agent-domain', 'agent-domain', 'pliniou', 'loto-generator', 'community', 'agent-domain pliniou loto-generator community The agent-domain skill ensures the core business logic and rules of an application remain portable, testable, and stable. It benefits developers by keeping the domain layer pure Kotlin. AIエージェント域专家负责Kotlin核心业务逻辑，确保域层的纯净和可移植性。了解关键技术细节和最佳实践 AIエージェントのドメイン層はKotlinで構築され、Androidフレームワークから独立しています。ドメイン層の役割と技術要件を理解しましょう AI 에이전트 도메인 전문가는 Kotlin 핵심 비즈니스 로직을 책임지며, 도메인 계층의 순수성과 이식성을 보장합니다. 주요 기술 세부 정보와 최선의实践을 확인하세요 El agent-domain se enfoca en la capa de dominio, donde se toman las decisiones críticas de negocio y se realizan cálculos y validaciones en Kotlin. L''agent-domain se concentre sur la couche de domaine, où les décisions métier critiques sont prises et les calculs et validations sont effectués en Kotlin. Das agent-domain konzentriert sich auf die Domänen-Schicht, in der kritische Geschäftsentscheidungen getroffen und Berechnungen und Validierungen in Kotlin durchgeführt werden. O Agent-Domain é responsável pela lógica de negócios e regras da aplicação, garantindo uma camada de domínio pura e portátil ИИ Агент-Domain отвечает за бизнес-логику и правила приложения, обеспечивая чистый и портативный слой домена وظيفة Agent-Domain هي التحكم في منطق الأعمال وقواعد التطبيق، مما يضمن слой مجال نقي وقابل للنقل how to use agent-domain what is agent-domain agent-domain alternative agent-domain vs Android frameworks agent-domain install agent-domain setup guide pure Kotlin development portable application development testable domain logic AIエージェント Kotlin 核心业务逻辑 解耦Android框架 可移植代码 纯Kotlin域层 AI工具 ドメイン層開発 Ensures domain layer remains pure Kotlin Detaches domain logic from Android frameworks and UI concerns Supports portable and testable application development Enforces stable core business logic and rules Allows for entity definitions and business logic utilities without dependencies Keeps use case classes independent of Android frameworks agent-domain is a skill that focuses on the domain layer of an application, responsible for core business logic and rules, ensuring portability, testability, and stability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Acadbek/personal-site/emilkowal-animations', 'community', 'Acadbek', 'personal-site', 'Acadbek/personal-site', 'emilkowal-animations', 0, 0, 32, '2026-03-08T01:57:15.469Z', '2026-03-08T02:09:32.046Z', '52f80219ebfd09c38c933a632bbda5e44b60877fdd65aa75311a37b9549b9bcf', '{"id":"Acadbek/personal-site/emilkowal-animations","name":"emilkowal-animations","description":{"en":"emilkowal-animations provides a comprehensive guide for web interface animations, benefiting React developers and designers. It offers 43 rules across 7 categories for implementing animations and interactions.","zh":"Emil Kowalski 动画最佳实践指南，用于 React 组件和 Web 界面，包含 43 条规则和 7 个类别","ja":"Emil Kowalski アニメーション ベストプラクティス ガイド、React コンポーネントと Web インターフェイス向け、43 のルールと 7 つのカテゴリを含む","ko":"Emil Kowalski 애니메이션 가이드, React 컴포넌트 및 웹 인터페이스용, 43개의 규칙 및 7개의 카테고리 포함","es":"emilkowal-animations es una guía completa para animaciones web basada en las enseñanzas de Emil Kowalski, con 43 reglas en 7 categorías","fr":"emilkowal-animations est un guide complet pour les animations web basé sur les enseignements d''Emil Kowalski, avec 43 règles dans 7 catégories","de":"emilkowal-animations ist ein umfassender Leitfaden für Webanimationen basierend auf den Lehren von Emil Kowalski, mit 43 Regeln in 7 Kategorien","pt":"O emilkowal-animations é um guia abrangente de animações para interfaces web baseado nas lições de Emil Kowalski e bibliotecas open-source.","ru":"ИИ Агент emilkowal-animations представляет собой комплексное руководство по анимациям для веб-интерфейсов, основанное на учении Эмиля Ковальски и открытых библиотеках.","ar":"와جھ emilkowal-animations هو دليـل شامـل للرسوم المتحركة لأشعة الويب dựa على تعاليم إميل كووالسكي والمكتبات المفتوحة المصدر."},"seo":{"title":{"en":"emilkowal-animations: Best Practices for Web Interface An...","zh":"Emil Kowalski 动画最佳实践指南 - AIエージェント","ja":"Emil Kowalski アニメーション ベストプラクティス - AIエージェント","ko":"Emil Kowalski 애니메이션 가이드 - AI 에이전트","es":"Guía de configuración de emilkowal-animations para interf...","fr":"Guide de mise en place d''emilkowal-animations pour les in...","de":"Einrichtungsleitfaden für emilkowal-animations in Webinte...","pt":"Guia de Animações emilkowal-animations: Melhores Práticas...","ru":"ИИ Агент emilkowal-animations: Настройка и Лучшие Практик...","ar":"إميل كووالسكي-الرسوم المتحركة: دليل أفضل الممارسات لأشعة ..."},"description":{"en":"Unlock expert-approved animation techniques with emilkowal-animations. Discover 43 rules for React, easing curves, and gesture-based interactions. Get starte...","zh":"学习 Emil Kowalski 的动画最佳实践，用于 React 组件和 Web 界面，提高用户体验","ja":"Emil Kowalski のアニメーションベストプラクティスを学び、React コンポーネントと Web インターフェイスのユーザーエクスペリエンスを向上させます","ko":"Emil Kowalski 의 애니메이션 가이드를 알아보고 React 컴포넌트 및 웹 인터페이스 사용자 경험을 향상시키세요","es":"Aprende a implementar animaciones web con emilkowal-animations, siguiendo las mejores prácticas de Emil Kowalski y utilizando bibliotecas de código abierto c...","fr":"Découvrez comment mettre en œuvre des animations web avec emilkowal-animations, en suivant les meilleures pratiques d''Emil Kowalski et en utilisant des bibli...","de":"Erfahren Sie, wie Sie Webanimationen mit emilkowal-animations implementieren, indem Sie die Best Practices von Emil Kowalski und Open-Source-Bibliotheken wie...","pt":"Aprenda a implementar animações emilkowal-animations em React com as melhores práticas e bibliotecas open-source como Sonner e Vaul","ru":"Изучите лучшие практики анимаций emilkowal-animations для веб-интерфейсов с React и открытыми библиотеками Sonner и Vaul","ar":"تعلم كيفية تنفيذ الرسوم المتحركة emilkowal-animations في React مع أفضل الممارسات والمكتبات المفتوحة المصدر مثل Sonner و Vaul"},"definition":{"en":"emilkowal-animations is a set of best practices for web interface animations, based on Emil Kowalski''s teachings and open-source libraries like Sonner and Vaul.","zh":"Emil Kowalski 动画最佳实践是指用于 Web 界面和 React 组件的动画设计和实现的指南","ja":"Emil Kowalski アニメーション ベストプラクティスとは、Web インターフェイスと React コンポーネント向けのアニメーションデザインと実装のガイドです","ko":"Emil Kowalski 애니메이션 가이드는 웹 인터페이스 및 React 컴포넌트를 위한 애니메이션 디자인 및 구현 지침입니다","es":"emilkowal-animations es un conjunto de reglas y mejores prácticas para crear animaciones web de alta calidad","fr":"emilkowal-animations est un ensemble de règles et de meilleures pratiques pour créer des animations web de haute qualité","de":"emilkowal-animations ist eine Sammlung von Regeln und Best Practices für die Erstellung von hochwertigen Webanimationen","pt":"O emilkowal-animations é um conjunto de regras e diretrizes para animações web baseado no trabalho de Emil Kowalski.","ru":"ИИ Агент emilkowal-animations - это набор правил и руководств для веб-анимаций, основанный на работе Эмиля Ковальски.","ar":"إميل كووالسكي-الرسوم المتحركة هو مجموعة من القواعد والإرشادات للرسوم المتحركة على الويب dựa على عمل إميل كووالسكي."},"features":{"en":["Provides 43 animation rules across 7 categories, prioritized by impact","Covers adding animations to React components","Offers guidance on choosing easing curves and timing values","Supports implementing gesture-based interactions like swipe and drag","Includes resources from Emil Kowalski''s animations.dev course"],"zh":["包含 43 条动画规则","7 个动画类别","用于 React 组件的动画最佳实践","基于 Sonner 和 Vaul 的开源库","包含 gesture-based 交互的实现"],"ja":["43 のアニメーションルールを含む","7 つのアニメーションカテゴリ","React コンポーネント向けのアニメーション ベストプラクティス","Sonner と Vaul のオープンソース ライブラリに基づく","ジェスチャーベースのインタラクションの実装を含む"],"ko":["43개의 애니메이션 규칙 포함","7개의 애니메이션 카테고리","React 컴포넌트를 위한 애니메이션 가이드","Sonner 및 Vaul의 오픈소스 라이브러리에 기반","제스처 기반 상호작용 구현 포함"],"es":["43 reglas para animaciones web en 7 categorías","Implementación de bibliotecas de código abierto como Sonner y Vaul","Guía para agregar animaciones a componentes React","Selección de curvas de suavización y valores de temporización","Implementación de interacciones basadas en gestos como deslizar y arrastrar"],"fr":["43 règles pour les animations web dans 7 catégories","Mise en œuvre de bibliothèques open-source comme Sonner et Vaul","Guide pour ajouter des animations à des composants React","Sélection de courbes de lissage et de valeurs de temporisation","Mise en œuvre d''interactions basées sur des gestes comme glisser et faire glisser"],"de":["43 Regeln für Webanimationen in 7 Kategorien","Implementierung von Open-Source-Bibliotheken wie Sonner und Vaul","Leitfaden für das Hinzufügen von Animationen zu React-Komponenten","Auswahl von Lissierungscurven und Zeitwert","Implementierung von gestenbasierten Interaktionen wie Wischen und Ziehen"],"pt":["43 regras para animações web","7 categorias de animações","Integração com React e bibliotecas open-source como Sonner e Vaul","Easing curves e timing values personalizáveis","Suporte a interações baseadas em gestos como swipe e drag","Implementação de notificações toast"],"ru":["43 правила для веб-анимаций","7 категорий анимаций","Интеграция с React и открытыми библиотеками seperti Sonner и Vaul","Настраиваемые easing curves и timing values","Поддержка жестовых взаимодействий как swipe и drag","Реализация уведомлений toast"],"ar":["43 قاعده للرسوم المتحركة على الويب","7 فئات من الرسوم المتحركة","التكامل مع React والمكتبات المفتوحة المصدر مثل Sonner و Vaul","منحنيات و قيم توقيت قابلة للتعديل","دعم التفاعلات القائمة على الإشارات مثل السحب و السحب","تنفيذ إشعارات Toast"]},"keywords":{"en":["emilkowal-animations tutorial","web interface animation best practices","React animation techniques","emilkowal-animations vs Greensock","how to use emilkowal-animations","emilkowal-animations setup guide","gesture-based interaction design","easing curves for web animations","emilkowal-animations alternative","animations.dev course review"],"zh":["Emil Kowalski 动画","React 动画","Web 界面动画","动画最佳实践","AIエージェント","动画设计","React 组件动画"],"ja":["Emil Kowalski アニメーション","React アニメーション","Web インターフェイス アニメーション","アニメーション ベストプラクティス","AIエージェント","アニメーションデザイン","React コンポーネント アニメーション"],"ko":["Emil Kowalski 애니메이션","React 애니메이션","웹 인터페이스 애니메이션","애니메이션 가이드","AI 에이전트","애니메이션 디자인","React 컴포넌트 애니메이션"],"es":["emilkowal-animations","animaciones web","mejores prácticas","bibliotecas de código abierto","React","curvas de suavización","valores de temporización","interacciones basadas en gestos"],"fr":["emilkowal-animations","animations web","meilleures pratiques","bibliothèques open-source","React","courbes de lissage","valeurs de temporisation","interactions basées sur des gestes"],"de":["emilkowal-animations","Webanimationen","Best Practices","Open-Source-Bibliotheken","React","Lissierungscurven","Zeitwerte","gestenbasierte Interaktionen"],"pt":["emilkowal-animations","animações web","React","Sonner","Vaul","easing curves","timing values","interações baseadas em gestos","notificações toast","melhores práticas de animações"],"ru":["ИИ Агент emilkowal-animations","веб-анимации","React","Sonner","Vaul","настраиваемые easing curves","настраиваемые timing values","жестовые взаимодействия","уведомления toast","лучшие практики анимаций"],"ar":["إميل كووالسكي-الرسوم المتحركة","الرسوم المتحركة على الويب","React","Sonner","Vaul","منحنيات و قيم توقيت قابلة للتعديل","التفاعلات القائمة على الإشارات","إشعارات Toast","أفضل الممارسات للرسوم المتحركة"]}},"owner":"Acadbek","repo":"personal-site","repoPath":"Acadbek/personal-site","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.469Z","topics":[],"category":"community","skillMd":{"name":"emilkowal-animations","description":"Emil Kowalskis animation best practices for web interfaces. Use when writing, reviewing, or implementing animations in React, CSS, or Framer Motion. Triggers on tasks involving transitions, easing, gestures, toasts, drawers, or motion.","bodyPreview":"# Emil Kowalski Animation Best Practices\n\nComprehensive animation guide for web interfaces based on Emil Kowalski''s teachings, open-source libraries (Sonner, Vaul), and his [animations.dev](https://animations.dev) course. Contains 43 rules across 7 categories, prioritized by impact.\n\n## When to Apply\n\nReference these guidelines when:\n- Adding animations to React components\n- Choosing easing curves or timing values\n- Implementing gesture-based interactions (swipe, drag)\n- Building toast notificat","body":"# Emil Kowalski Animation Best Practices\n\nComprehensive animation guide for web interfaces based on Emil Kowalski''s teachings, open-source libraries (Sonner, Vaul), and his [animations.dev](https://animations.dev) course. Contains 43 rules across 7 categories, prioritized by impact.\n\n## When to Apply\n\nReference these guidelines when:\n- Adding animations to React components\n- Choosing easing curves or timing values\n- Implementing gesture-based interactions (swipe, drag)\n- Building toast notifications or drawer components\n- Optimizing animation performance\n- Ensuring animation accessibility\n\n## Rule Categories by Priority\n\n| Priority | Category | Impact | Prefix |\n|----------|----------|--------|--------|\n| 1 | Easing Selection | CRITICAL | `ease-` |\n| 2 | Timing & Duration | CRITICAL | `timing-` |\n| 3 | Property Selection | HIGH | `props-` |\n| 4 | Transform Techniques | HIGH | `transform-` |\n| 5 | Interaction Patterns | MEDIUM-HIGH | `interact-` |\n| 6 | Strategic Animation | MEDIUM | `strategy-` |\n| 7 | Accessibility & Polish | MEDIUM | `polish-` |\n\n## Quick Reference\n\n### 1. Easing Selection (CRITICAL)\n\n- [`ease-out-default`](references/ease-out-default.md) - Use ease-out as your default easing\n- [`ease-custom-curves`](references/ease-custom-curves.md) - Use custom cubic-bezier over built-in CSS\n- [`ease-in-out-onscreen`](references/ease-in-out-onscreen.md) - Use ease-in-out for on-screen movement\n- [`ease-spring-natural`](references/ease-spring-natural.md) - Use spring animations for natural motion\n- [`ease-ios-drawer`](references/ease-ios-drawer.md) - Use iOS-style easing for drawer components\n- [`ease-context-matters`](references/ease-context-matters.md) - Match easing to animation context\n\n### 2. Timing & Duration (CRITICAL)\n\n- [`timing-300ms-max`](references/timing-300ms-max.md) - Keep UI animations under 300ms\n- [`timing-faster-better`](references/timing-faster-better.md) - Faster animations improve perceived performance\n- [`timing-asymmetric`](references/timing-asymmetric.md) - Use asymmetric timing for press and release\n- [`timing-tooltip-delay`](references/timing-tooltip-delay.md) - Delay initial tooltips, instant subsequent ones\n- [`timing-drawer-500ms`](references/timing-drawer-500ms.md) - Use 500ms duration for drawer animations\n\n### 3. Property Selection (HIGH)\n\n- [`props-transform-opacity`](references/props-transform-opacity.md) - Animate only transform and opacity\n- [`props-hardware-accelerated`](references/props-hardware-accelerated.md) - Use hardware-accelerated animations when main thread is busy\n- [`props-will-change`](references/props-will-change.md) - Use will-change to prevent 1px shift\n- [`props-avoid-css-variables`](references/props-avoid-css-variables.md) - Avoid CSS variables for drag animations\n- [`props-clip-path-performant`](references/props-clip-path-performant.md) - Use clip-path for layout-free reveals\n\n### 4. Transform Techniques (HIGH)\n\n- [`transform-scale-097`](references/transform-scale-097.md) - Scale buttons to 0.97 on press\n- [`transform-never-scale-zero`](references/transform-never-scale-zero.md) - Never animate from scale(0)\n- [`transform-percentage-translate`](references/transform-percentage-translate.md) - Use percentage values for translateY\n- [`transform-origin-aware`](references/transform-origin-aware.md) - Make animations origin-aware\n- [`transform-scale-children`](references/transform-scale-children.md) - Scale transforms affect children\n- [`transform-3d-preserve`](references/transform-3d-preserve.md) - Use preserve-3d for 3D transform effects\n\n### 5. Interaction Patterns (MEDIUM-HIGH)\n\n- [`interact-interruptible`](references/interact-interruptible.md) - Make animations interruptible\n- [`interact-momentum-dismiss`](references/interact-momentum-dismiss.md) - Use momentum-based dismissal\n- [`interact-damping`](references/interact-damping.md) - Damp drag at boundaries\n- [`interact-scroll-drag-conflict`](references/interact-scroll-drag-conflict.md) - Resolve scroll and drag conflicts\n- [`interact-snap-points`](references/interact-snap-points.md) - Implement velocity-aware snap points\n- [`interact-friction-upward`](references/interact-friction-upward.md) - Allow upward drag with friction\n- [`interact-pointer-capture`](references/interact-pointer-capture.md) - Use pointer capture for drag operations\n\n### 6. Strategic Animation (MEDIUM)\n\n- [`strategy-keyboard-no-animate`](references/strategy-keyboard-no-animate.md) - Never animate keyboard-initiated actions\n- [`strategy-frequency-matters`](references/strategy-frequency-matters.md) - Consider interaction frequency before animating\n- [`strategy-purpose-required`](references/strategy-purpose-required.md) - Every animation must have a purpose\n- [`strategy-feedback-immediate`](references/strategy-feedback-immediate.md) - Provide immediate feedback on all actions\n- [`strategy-marketing-exception`](references/strategy-marketing-exception.md) - Marketing sites are the exception\n\n### 7. Accessibility & Polish (MEDIUM)\n\n- [`polish-reduced-motion`](references/polish-reduced-motion.md) - Respect prefers-reduced-motion\n- [`polish-opacity-fallback`](references/polish-opacity-fallback.md) - Use opacity as reduced motion fallback\n- [`polish-framer-hook`](references/polish-framer-hook.md) - Use useReducedMotion hook in Framer Motion\n- [`polish-dont-remove-all`](references/polish-dont-remove-all.md) - Don''t remove all animation for reduced motion\n- [`polish-blur-bridge`](references/polish-blur-bridge.md) - Use blur to bridge animation states\n- [`polish-clip-path-tabs`](references/polish-clip-path-tabs.md) - Use clip-path for tab transitions\n- [`polish-toast-stacking`](references/polish-toast-stacking.md) - Implement toast stacking with scale and offset\n- [`polish-scroll-reveal`](references/polish-scroll-reveal.md) - Trigger scroll animations at appropriate threshold\n- [`polish-hover-gap-fill`](references/polish-hover-gap-fill.md) - Fill gaps between hoverable elements\n- [`polish-stagger-children`](references/polish-stagger-children.md) - Stagger child animations for orchestration\n\n## Key Values Reference\n\n| Value | Usage |\n|-------|-------|\n| `cubic-bezier(0.32, 0.72, 0, 1)` | iOS-style drawer/sheet animation |\n| `scale(0.97)` | Button press feedback |\n| `scale(0.95)` | Minimum enter scale (never scale(0)) |\n| `200ms ease-out` | Standard UI transition |\n| `300ms` | Maximum duration for UI animations |\n| `500ms` | Drawer animation duration |\n| `0.11 px/ms` | Velocity threshold for momentum dismiss |\n| `100px` | Scroll-reveal viewport threshold |\n| `14px` | Toast stack offset |\n\n## Reference Files\n\n| File | Description |\n|------|-------------|\n| [references/_sections.md](references/_sections.md) | Category definitions and ordering |\n| [assets/templates/_template.md](assets/templates/_template.md) | Template for new rules |\n| [metadata.json](metadata.json) | Version and reference information |\n"},"lastSynced":"2026-03-08T02:09:32.046Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents and React developers needing comprehensive web interface animation guidance","zh":"非常适合前端代理和React开发者，需要全面的Web界面动画指导","ja":"フロントエンドエージェントとReact開発者に最適で、包括的なWebインターフェースアニメーションガイダンスを必要とする場合","ko":"프론트엔드 에이전트와 React 개발자에게 완벽하며, 포괄적인 웹 인터페이스 애니메이션 가이드가 필요함","es":"Perfecto para agentes de frontend y desarrolladores de React que necesitan una guía completa sobre animaciones de interfaz web","fr":"Parfait pour les agents de frontend et les développeurs React qui ont besoin d''un guide complet sur les animations d''interface web","de":"Perfekt für Frontend-Agenten und React-Entwickler, die eine umfassende Anleitung zu Webinterface-Animationen benötigen","pt":"Perfeito para Agentes Frontend e desenvolvedores React que precisam de orientações abrangentes sobre animação de interface web","ru":"Идеально подходит для агентов Frontend и разработчиков React, которым необходимы всесторонние рекомендации по анимации веб-интерфейса","ar":"مثالي لعميل الواجهة الأمامية ومطوري React الذين يحتاجون إلى إرشادات شاملة حول رسوم متحركة واجهة الويب"},"recommendation":{"en":"Empowers agents to implement animations and interactions using 43 rules across 7 categories, leveraging open-source libraries like Sonner and Vaul, and prioritizing impact for seamless user experiences with React components and gesture-based interactions like swipe and drag","zh":"使代理能够使用7个类别的43条规则实现动画和交互，利用Sonner和Vaul等开源库，并优先考虑影响，以实现React组件和基于手势的交互（如滑动和拖动）的无缝用户体验","ja":"SonnerやVaulなどのオープンソースライブラリを活用し、7つのカテゴリーにわたる43のルールを使用してアニメーションとインタラクションを実装する能力をエージェントに付与し、Reactコンポーネントやスワイプやドラッグなどのジェスチャーベースのインタラクションによるシームレスなユーザー体験への影響を優先します","ko":"Sonner 및 Vaul과 같은 오픈소스 라이브러리를 활용하고, 영향을 우선시하여 React 컴포넌트 및 스와이프 및 드래그와 같은 제스처 기반 상호작용으로 원활한 사용자 경험을 제공하기 위해 7개 범주의 43개 규칙을 사용하여 애니메이션 및 상호작용을 구현할 수 있도록 에이전트를 강화함","es":"Habilita a los agentes a implementar animaciones e interacciones utilizando 43 reglas en 7 categorías, aprovechando bibliotecas de código abierto como Sonner y Vaul, y priorizando el impacto para experiencias de usuario fluidas con componentes de React y interacciones basadas en gestos como deslizar y arrastrar","fr":"Permet aux agents de mettre en œuvre des animations et des interactions en utilisant 43 règles dans 7 catégories, en exploitant des bibliothèques open-source comme Sonner et Vaul, et en donnant la priorité à l''impact pour des expériences utilisateur fluides avec des composants React et des interactions basées sur les gestes comme le défilement et le glisser-déposer","de":"Ermächtigt Agenten, Animationen und Interaktionen mithilfe von 43 Regeln in 7 Kategorien umzusetzen, indem es Open-Source-Bibliotheken wie Sonner und Vaul nutzt und den Impact für nahtlose Benutzererfahrungen mit React-Komponenten und gestenbasierten Interaktionen wie Wischen und Ziehen priorisiert","pt":"Habilita os agentes a implementar animações e interações usando 43 regras em 7 categorias, aproveitando bibliotecas de código aberto como Sonner e Vaul, e priorizando o impacto para experiências de usuário sem interrupções com componentes React e interações baseadas em gestos como swipe e drag","ru":"Наделяет агентов возможностью реализовывать анимации и взаимодействия, используя 43 правила в 7 категориях, используя открытое программное обеспечение, такое как Sonner и Vaul, и отдаёт приоритет воздействию для бесперебойного пользовательского опыта с компонентами React и жестовыми взаимодействиями, такими как свайп и перетаскивание","ar":"يسمح للوكيل بتنفيذ الرسوم المتحركة والتفاعلات باستخدام 43 قاعدة في 7 فئات، واستغلال المكتبات مفتوحة المصدر مثل Sonner و Vaul، وتوجيه الأولوية للتأثير لتجارب المستخدم دون انقطاع مع مكونات React والتفاعلات القائمة على الإشارة مثل سويب وسحب"},"useCases":{"en":["Implementing animations for React components","Choosing optimal easing curves and timing values","Building interactive toast notifications","Developing gesture-based interactions"],"zh":["React组件的动画实现","选择最佳缓动曲线和计时值","构建交互式Toast通知","开发基于手势的交互"],"ja":["Reactコンポーネントのアニメーション実装","最適なイージングカーブとタイミング値の選択","インタラクティブなトースト通知の構築","ジェスチャーベースのインタラクションの開発"],"ko":["React 컴포넌트 애니메이션 구현","최적의 이징 곡선 및 타이밍 값 선택","대화형 토스트 알림 구축","제스처 기반 상호작용 개발"],"es":["Implementar animaciones para componentes de React","Elegir curvas de suavización y valores de temporización óptimos","Crear notificaciones interactivas de toast","Desarrollar interacciones basadas en gestos"],"fr":["Mettre en œuvre des animations pour les composants React","Choisir des courbes de lissage et des valeurs de temporisation optimales","Créer des notifications de toast interactives","Développer des interactions basées sur les gestes"],"de":["Animationen für React-Komponenten implementieren","Optimale Ausgleichskurven und Zeitwerte auswählen","Interaktive Toast-Benachrichtigungen erstellen","Gestenbasierte Interaktionen entwickeln"],"pt":["Implementar animações para componentes React","Escolher curvas de aceleração e valores de tempo óptimos","Construir notificações interativas de toast","Desenvolver interações baseadas em gestos"],"ru":["Реализация анимаций для компонентов React","Выбор оптимальных кривых ускорения и значений времени","Создание интерактивных уведомлений toast","Разработка жестовых взаимодействий"],"ar":["تنفيذ الرسوم المتحركة لمكونات React","اختيار منحنيات التسارع والقيم الزمنية المثالية","بناء إشعارات تفاعلية من نوع toast","تطوير التفاعلات القائمة على الإشارة"]},"limitations":{"en":["Specific to React development","Requires knowledge of web interface animation principles"],"zh":["特定于React开发","需要了解Web界面动画原理"],"ja":["React開発に特化","Webインターフェースアニメーションの原則に関する知識が必要"],"ko":["React 개발에 특화됨","웹 인터페이스 애니메이션 원리에 대한 지식 필요"],"es":["Específico para el desarrollo de React","Requiere conocimiento de los principios de animación de interfaz web"],"fr":["Spécifique au développement React","Nécessite des connaissances sur les principes d''animation d''interface web"],"de":["Spezifisch für die React-Entwicklung","Benötigt Kenntnisse über die Prinzipien der Webinterface-Animation"],"pt":["Específico para desenvolvimento React","Requer conhecimento de princípios de animação de interface web"],"ru":["Конкретно для разработки React","Требует знания принципов анимации веб-интерфейса"],"ar":["محدد لتطوير React","يتطلب معرفة مبادئ رسوم متحركة واجهة الويب"]},"version":4},"contentHash":"52f80219ebfd09c38c933a632bbda5e44b60877fdd65aa75311a37b9549b9bcf","qualityScore":32}');
