INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Acadbek/personal-site/emilkowal-animations', 'emilkowal-animations', 'Acadbek', 'personal-site', 'community', 'emilkowal-animations Acadbek personal-site community emilkowal-animations provides a comprehensive guide for web interface animations, benefiting React developers and designers. It offers 43 rules across 7 categories for implementing animations and interactions. Emil Kowalski 动画最佳实践指南，用于 React 组件和 Web 界面，包含 43 条规则和 7 个类别 Emil Kowalski アニメーション ベストプラクティス ガイド、React コンポーネントと Web インターフェイス向け、43 のルールと 7 つのカテゴリを含む Emil Kowalski 애니메이션 가이드, React 컴포넌트 및 웹 인터페이스용, 43개의 규칙 및 7개의 카테고리 포함 emilkowal-animations es una guía completa para animaciones web basada en las enseñanzas de Emil Kowalski, con 43 reglas en 7 categorías emilkowal-animations est un guide complet pour les animations web basé sur les enseignements d''Emil Kowalski, avec 43 règles dans 7 catégories emilkowal-animations ist ein umfassender Leitfaden für Webanimationen basierend auf den Lehren von Emil Kowalski, mit 43 Regeln in 7 Kategorien O emilkowal-animations é um guia abrangente de animações para interfaces web baseado nas lições de Emil Kowalski e bibliotecas open-source. ИИ Агент emilkowal-animations представляет собой комплексное руководство по анимациям для веб-интерфейсов, основанное на учении Эмиля Ковальски и открытых библиотеках. 와جھ emilkowal-animations هو دليـل شامـل للرسوم المتحركة لأشعة الويب dựa على تعاليم إميل كووالسكي والمكتبات المفتوحة المصدر. emilkowal-animations tutorial web interface animation best practices React animation techniques emilkowal-animations vs Greensock how to use emilkowal-animations emilkowal-animations setup guide gesture-based interaction design easing curves for web animations emilkowal-animations alternative animations.dev course review Emil Kowalski 动画 React 动画 Web 界面动画 动画最佳实践 AIエージェント 动画设计 React 组件动画 Provides 43 animation rules across 7 categories, prioritized by impact Covers adding animations to React components Offers guidance on choosing easing curves and timing values Supports implementing gesture-based interactions like swipe and drag Includes resources from Emil Kowalski''s animations.dev course emilkowal-animations is a set of best practices for web interface animations, based on Emil Kowalski''s teachings and open-source libraries like Sonner and Vaul.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kdv1995/react-native-app/pro', 'community', 'kdv1995', 'react-native-app', 'kdv1995/react-native-app', 'pro', 0, 0, 32, '2026-03-08T01:57:15.487Z', '2026-03-08T02:10:06.228Z', 'c066cce39501c12ccc3119a41ce187ee29a7c50664a2293f5d67d5bfa0c48012', '{"id":"kdv1995/react-native-app/pro","name":"pro","description":{"en":"The pro skill enables AI agents to develop high-quality mobile UI applications using TypeScript, React Native, and Expo. It provides expertise in writing concise and technical code.","zh":"Pro AI Agent 是一个专家级的 TypeScript、React Native 和 Expo 开发工具，提供最佳的代码结构和样式","ja":"Pro AIエージェントは、TypeScript、React Native、Expo の開発に特化したエキスパートレベルのツールで、最適なコード構造とスタイルを提供します","ko":"Pro AI 에이전트는 TypeScript, React Native 및 Expo 개발에 특화된 전문가급 도구로 최적의 코드 구조 및 스타일을 제공합니다","es":"El experto en ''pro'' ofrece consejos para desarrollar aplicaciones móviles con TypeScript, React Native y Expo","fr":"L''expert en ''pro'' propose des conseils pour développer des applications mobiles avec TypeScript, React Native et Expo","de":"Der Experte für ''pro'' bietet Tipps für die Entwicklung von mobilen Anwendungen mit TypeScript, React Native und Expo","pt":"O ''pro'' é um expert em TypeScript, React Native, Expo e desenvolvimento de UI móvel, fornecendo código conciso e técnicas de programação funcionais","ru":"ИИ Агент ''pro'' - это эксперт по TypeScript, React Native, Expo и разработке мобильных интерфейсов, предоставляющий лаконичный и технический код с функциональными шаблонами программирования","ar":"الوكلاء الذكية ''pro'' هي خبير في TypeScript و React Native و Expo و تطوير واجهات المستخدم المتنقلة، وتوفر شفرة متوفرة و تقنيات برمجة وظيفية"},"seo":{"title":{"en":"pro: Expert TypeScript and React Native Development | AI ...","zh":"Pro AI Agent 设置指南：TypeScript 和 React Native 最佳实践","ja":"Pro AIエージェントの設定ガイド：TypeScript と React Native のベストプラクテ