INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kdv1995/react-native-app/pro', 'pro', 'kdv1995', 'react-native-app', 'community', 'pro kdv1995 react-native-app community The pro skill enables AI agents to develop high-quality mobile UI applications using TypeScript, React Native, and Expo. It provides expertise in writing concise and technical code. Pro AI Agent 是一个专家级的 TypeScript、React Native 和 Expo 开发工具，提供最佳的代码结构和样式 Pro AIエージェントは、TypeScript、React Native、Expo の開発に特化したエキスパートレベルのツールで、最適なコード構造とスタイルを提供します Pro AI 에이전트는 TypeScript, React Native 및 Expo 개발에 특화된 전문가급 도구로 최적의 코드 구조 및 스타일을 제공합니다 El experto en ''pro'' ofrece consejos para desarrollar aplicaciones móviles con TypeScript, React Native y Expo L''expert en ''pro'' propose des conseils pour développer des applications mobiles avec TypeScript, React Native et Expo Der Experte für ''pro'' bietet Tipps für die Entwicklung von mobilen Anwendungen mit TypeScript, React Native und Expo O ''pro'' é um expert em TypeScript, React Native, Expo e desenvolvimento de UI móvel, fornecendo código conciso e técnicas de programação funcionais ИИ Агент ''pro'' - это эксперт по TypeScript, React Native, Expo и разработке мобильных интерфейсов, предоставляющий лаконичный и технический код с функциональными шаблонами программирования الوكلاء الذكية ''pro'' هي خبير في TypeScript و React Native و Expo و تطوير واجهات المستخدم المتنقلة، وتوفر شفرة متوفرة و تقنيات برمجة وظيفية how to use pro pro vs React Native pro install guide what is pro pro alternative to Expo pro setup for mobile UI development pro and TypeScript development pro expert level development Pro AI Agent TypeScript React Native Expo 移动 UI 开发 函数式编程 声明式编程 迭代和模块化 Writes concise, technical TypeScript code with accurate examples Utilizes functional and declarative programming patterns Avoids classes in favor of modularization and iteration Employs descriptive variable names with auxiliary verbs Supports Expo and React Native for mobile UI development pro is a skill that specializes in TypeScript, React Native, Expo, and Mobile UI development, focusing on functional and declarative programming patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('coollabsio/laravel-template/inertia-vue-development', 'community', 'coollabsio', 'laravel-template', 'coollabsio/laravel-template', 'inertia-vue-development', 0, 0, 32, '2026-03-08T01:57:15.499Z', '2026-03-08T02:10:15.806Z', '78cee50a9b19af2cf597253231710b7e3fe1f43403455f968b1324e268655314', '{"id":"coollabsio/laravel-template/inertia-vue-development","name":"inertia-vue-development","description":{"en":"The inertia-vue-development skill provides a template for Laravel apps, benefiting developers working with Vue page components, forms, and client-side navigation.","zh":"Inertia Vue开发模板，用于创建或修改Vue页面组件，包括表单、客户端导航和v2功能","ja":"Inertia Vue開発のためのテンプレート、Vueページコンポーネントの作成または変更、フォーム、クライアントサイドナビゲーション、v2機能","ko":"Inertia Vue 개발을 위한 템플릿, Vue 페이지 컴포넌트의 생성 또는 수정, 폼, 클라이언트 측 탐색, v2 기능","es":"Inertia Vue Development es una plantilla para aplicaciones Laravel que permite crear componentes de página Vue con funcionalidades avanzadas","fr":"Inertia Vue Development est un modèle pour les applications Laravel qui permet de créer des composants de page Vue avec des fonctionnalités avancées","de":"Inertia Vue Development ist ein Template für Laravel-Anwendungen, das die Erstellung von Vue-Seitenkomponenten mit erweiterten Funktionen ermöglicht","pt":"Inertia Vue Development é uma ferramenta para criar aplicações Laravel com componentes de página Vue e navegação cliente","ru":"Inertia Vue Development - это инструмент для создания приложений Laravel с компонентами страниц Vue и клиентской навигацией","ar":"Inertia Vue Development هي أداة لإنشاء تطبيقات Laravel باستخدام مكونات الصفحة Vue والملاحة العميل"},"seo":{"title":{"en":"inertia-vue-development: Setup Guide for AI Agents | AI A...","zh":"Inertia Vue开发.setup指南","ja":"Inertia Vue開発ベストプラクティス - AIエージェント","ko":"Inertia Vue 개발 가이드 - AI 도구","es":"Guía de configuración de Inertia Vue Development para apl...","fr":"Guide de démarrage rapide pour Inertia Vue Development av...","de":"Setup-Leitfaden für Inertia Vue Development in Laravel-An...","pt":"Guia de Configuração para Inertia Vue Development","ru":"Настройка ИИ Агентов для Inertia Vue Development","ar":"دليل الإعداد لتقنيات Inertia Vue Development"},"description":{"en":"Unlock the full potential of Inertia Vue development with our expert guide, featuring tips on page components, forms, and client-side navigation.","zh":"Inertia Vue开发模板，用于Laravel应用，包括表单、客户端导航和v2功能","ja":"Inertia Vue開発のためのLaravelアプリテンプレート - フォーム、クライアントサイドナビゲーション、v2機能","ko":"Inertia Vue 개발을 위한 Laravel 애플리케이션 템플릿 - 폼, 클라이언트 측 탐색, v2 기능","es":"Descubre cómo implementar Inertia Vue Development en tus aplicaciones Laravel con nuestras mejores prácticas y documentación detallada","fr":"Découvrez comment mettre en œuvre Inertia Vue Development dans vos applications Laravel avec nos meilleures pratiques et documentation détaillée","de":"Erfahren Sie, wie Sie Inertia Vue Development in Ihren Laravel-Anwendungen implementieren, mit unseren Best Practices und detaillierter Dokumentation","pt":"Aprenda a criar aplicações Laravel com Inertia Vue, incluindo componentes de página, formulários e navegação cliente","ru":"Изучите создание приложений Laravel с помощью Inertia Vue, включая компоненты страниц, формы и клиентскую навигацию","ar":"تعرف على كيفية إنشاء تطبيقات Laravel باستخدام Inertia Vue، بما في ذلك مكونات الصفحة والنموذج والملاحة العميل"},"definition":{"en":"inertia-vue-development is a skill for creating and modifying Vue page components for Inertia, utilizing features like deferred props, prefetching, and polling.","zh":"Inertia Vue开发是一种用于创建Laravel应用的模板，提供表单、客户端导航和v2功能","ja":"Inertia Vue開発は、Laravelアプリケーションを作成するためのテンプレートで、フォーム、クライアントサイドナビゲーション、v2機能を提供","ko":"Inertia Vue 개발은 Laravel 애플리케이션을 생성하기 위한 템플릿으로, 폼, 클라이언트 측 탐색, v2 기능을 제공","es":"Inertia Vue Development es un conjunto de herramientas para desarrollar aplicaciones Laravel con componentes de página Vue","fr":"Inertia Vue Development est un ensemble d''outils pour développer des applications Laravel avec des composants de page Vue","de":"Inertia Vue Development ist ein Satz von Tools für die Entwicklung von Laravel-Anwendungen mit Vue-Seitenkomponenten","pt":"Inertia Vue Development é uma técnica de desenvolvimento que combina Laravel com componentes de página Vue","ru":"Inertia Vue Development - это техника разработки, сочетающая Laravel с компонентами страниц Vue","ar":"Inertia Vue Development هي تقنية تطوير تجمع بين Laravel ومكونات الصفحة Vue"},"features":{"en":["Creates and modifies Vue page components for Inertia","Works with forms in Vue using `<Form>` or `useForm`","Implements client-side navigation with `<Link>` or `router`","Utilizes v2 features like deferred props, prefetching, and polling","Builds Vue-specific features with the Inertia protocol"],"zh":["创建或修改Vue页面组件","使用表单（<Form>或useForm）","实现客户端导航（<Link>或router）","使用v2功能：deferred props、prefetching或polling","构建Vue特定的功能与Inertia协议"],"ja":["Vueページコンポーネントの作成または変更","フォーム（<Form>またはuseForm）を使用","クライアントサイドナビゲーション（<Link>またはrouter）を実装","v2機能：deferred props、prefetchingまたはpollingを使用","Vue特有の機能をInertiaプロトコルで構築"],"ko":["Vue 페이지 컴포넌트의 생성 또는 수정","폼（<Form> 또는 useForm）을 사용","클라이언트 측 탐색（<Link> 또는 router）을 구현","v2 기능：deferred props、prefetching 또는 polling을 사용","Vue 특有的 기능을 Inertia 프로토콜로 구축"],"es":["Creación de componentes de página Vue para Inertia","Trabajo con formularios en Vue utilizando `<Form>` o `useForm`","Implementación de navegación del lado cliente con `<Link>` o `router`","Uso de características de v2: props diferidos, precarga y sondeo","Construcción de características específicas de Vue con el protocolo Inertia"],"fr":["Création de composants de page Vue pour Inertia","Travail avec des formulaires dans Vue en utilisant `<Form>` ou `useForm`","Mise en œuvre de la navigation côté client avec `<Link>` ou `router`","Utilisation des fonctionnalités de v2 : props différés, préchargement et sonde","Construction de fonctionnalités spécifiques à Vue avec le protocole Inertia"],"de":["Erstellung von Vue-Seitenkomponenten für Inertia","Arbeit mit Formularen in Vue unter Verwendung von `<Form>` oder `useForm`","Implementierung der Client-Seitennavigation mit `<Link>` oder `router`","Verwendung von v2-Funktionen: verschobene Eigenschaften, Vorlädtung und Polling","Erstellung von Vue-spezifischen Funktionen mit dem Inertia-Protokoll"],"pt":["Criação de componentes de página Vue para Inertia","Trabalho com formulários em Vue usando `<Form>` ou `useForm`","Implementação de navegação cliente com `<Link>` ou `router`","Uso de recursos do v2, como props diferidos, pré-carregamento e polimento","Construção de recursos específicos do Vue com o protocolo Inertia"],"ru":["Создание компонентов страниц Vue для Inertia","Работа с формами в Vue с помощью `<Form>` или `useForm`","Реализация клиентской навигации с помощью `<Link>` или `router`","Использование функций v2, таких как отложенные свойства, предварительная загрузка и опрос","Создание функций, специфичных для Vue, с помощью протокола Inertia"],"ar":["إنشاء مكونات الصفحة Vue ل Inertia","العمل مع النماذج في Vue باستخدام `<Form>` أو `useForm`","تنفيذ الملاحة العميل باستخدام `<Link>` أو `router`","استخدام ميزات v2، مثل الخصائص المؤجلة والتحميل المسبق والاستطلاع","بناء ميزات محددة ل Vue باستخدام بروتوكول Inertia"]},"keywords":{"en":["how to use inertia-vue-development","inertia-vue-development setup guide","inertia-vue-development vs vue-router","inertia-vue-development install","what is inertia-vue-development","inertia-vue-development alternative","inertia-vue-development tutorial","inertia-vue-development documentation","inertia-vue-development best practices"],"zh":["Inertia Vue开发","Laravel应用模板","Vue页面组件","表单开发","客户端导航","v2功能","Inertia协议","AI开发工具","Vue开发最佳实践"],"ja":["Inertia Vue開発","Laravelアプリケーションテンプレート","Vueページコンポーネント","フォーム開発","クライアントサイドナビゲーション","v2機能","Inertiaプロトコル","AI開発ツール","Vue開発ベストプラクティス"],"ko":["Inertia Vue 개발","Laravel 애플리케이션 템플릿","Vue 페이지 컴포넌트","폼 개발","클라이언트 측 탐색","v2 기능","Inertia 프로토콜","AI 개발 도구","Vue 개발 가이드"],"es":["Inertia Vue Development","Laravel","Vue.js","componentes de página","formularios en Vue","navegación del lado cliente","props diferidos","precarga","sondeo","protocolo Inertia"],"fr":["Inertia Vue Development","Laravel","Vue.js","composants de page","formulaires dans Vue","navigation côté client","props différés","préchargement","sonde","protocole Inertia"],"de":["Inertia Vue Development","Laravel","Vue.js","Seitenkomponenten","Formulare in Vue","Client-Seitennavigation","verschobene Eigenschaften","Vorlädtung","Polling","Inertia-Protokoll"],"pt":["inertia vue development","laravel inertia","vue page components","formulários vue","navegação cliente vue","v2 features","protocolo inertia"],"ru":["inertia vue development","laravel(inertia","компоненты страниц vue","формы vue","клиентская навигация vue","функции v2","протокол(inertia"],"ar":["inertia vue development","laravel(inertia","مكونات الصفحة vue","نماذج vue","ملاحة العميل vue","ميزات v2","بروتوكول(inertia"]}},"owner":"coollabsio","repo":"laravel-template","repoPath":"coollabsio/laravel-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.499Z","topics":[],"category":"community","skillMd":{"name":"inertia-vue-development","description":">-","bodyPreview":"# Inertia Vue Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Creating or modifying Vue page components for Inertia\n- Working with forms in Vue (using `<Form>` or `useForm`)\n- Implementing client-side navigation with `<Link>` or `router`\n- Using v2 features: deferred props, prefetching, or polling\n- Building Vue-specific features with the Inertia protocol\n\n## Documentation\n\nUse `search-docs` for detailed Inertia v2 Vue patterns and documentation.\n\n## Basic Usage\n\n### Page Components","body":"# Inertia Vue Development\n\n## When to Apply\n\nActivate this skill when:\n\n- Creating or modifying Vue page components for Inertia\n- Working with forms in Vue (using `<Form>` or `useForm`)\n- Implementing client-side navigation with `<Link>` or `router`\n- Using v2 features: deferred props, prefetching, or polling\n- Building Vue-specific features with the Inertia protocol\n\n## Documentation\n\nUse `search-docs` for detailed Inertia v2 Vue patterns and documentation.\n\n## Basic Usage\n\n### Page Components Location\n\nVue page components should be placed in the `resources/js/pages` directory.\n\n### Page Component Structure\n\nImportant: Vue components must have a single root element.\n\n<code-snippet name=\"Basic Vue Page Component\" lang=\"vue\">\n\n<script setup>\ndefineProps({\n    users: Array\n})\n</script>\n\n<template>\n    <div>\n        <h1>Users</h1>\n        <ul>\n            <li v-for=\"user in users\" :key=\"user.id\">\n                {{ user.name }}\n            </li>\n        </ul>\n    </div>\n</template>\n\n</code-snippet>\n\n## Client-Side Navigation\n\n### Basic Link Component\n\nUse `<Link>` for client-side navigation instead of traditional `<a>` tags:\n\n<code-snippet name=\"Inertia Vue Navigation\" lang=\"vue\">\n\n<script setup>\nimport { Link } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <div>\n        <Link href=\"/\">Home</Link>\n        <Link href=\"/users\">Users</Link>\n        <Link :href=\"`/users/${user.id}`\">View User</Link>\n    </div>\n</template>\n\n</code-snippet>\n\n### Link with Method\n\n<code-snippet name=\"Link with POST Method\" lang=\"vue\">\n\n<script setup>\nimport { Link } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <Link href=\"/logout\" method=\"post\" as=\"button\">\n        Logout\n    </Link>\n</template>\n\n</code-snippet>\n\n### Prefetching\n\nPrefetch pages to improve perceived performance:\n\n<code-snippet name=\"Prefetch on Hover\" lang=\"vue\">\n\n<script setup>\nimport { Link } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <Link href=\"/users\" prefetch>\n        Users\n    </Link>\n</template>\n\n</code-snippet>\n\n### Programmatic Navigation\n\n<code-snippet name=\"Router Visit\" lang=\"vue\">\n\n<script setup>\nimport { router } from ''@inertiajs/vue3''\n\nfunction handleClick() {\n    router.visit(''/users'')\n}\n\n// Or with options\nfunction createUser() {\n    router.visit(''/users'', {\n        method: ''post'',\n        data: { name: ''John'' },\n        onSuccess: () => console.log(''Done''),\n    })\n}\n</script>\n\n<template>\n    <Link href=\"/users\">Users</Link>\n    <Link href=\"/logout\" method=\"post\" as=\"button\">Logout</Link>\n</template>\n\n</code-snippet>\n\n## Form Handling\n\n### Form Component (Recommended)\n\nThe recommended way to build forms is with the `<Form>` component:\n\n<code-snippet name=\"Form Component Example\" lang=\"vue\">\n\n<script setup>\nimport { Form } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <Form action=\"/users\" method=\"post\" #default=\"{ errors, processing, wasSuccessful }\">\n        <input type=\"text\" name=\"name\" />\n        <div v-if=\"errors.name\">{{ errors.name }}</div>\n\n        <input type=\"email\" name=\"email\" />\n        <div v-if=\"errors.email\">{{ errors.email }}</div>\n\n        <button type=\"submit\" :disabled=\"processing\">\n            {{ processing ? ''Creating...'' : ''Create User'' }}\n        </button>\n\n        <div v-if=\"wasSuccessful\">User created!</div>\n    </Form>\n</template>\n\n</code-snippet>\n\n### Form Component With All Props\n\n<code-snippet name=\"Form Component Full Example\" lang=\"vue\">\n\n<script setup>\nimport { Form } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <Form\n        action=\"/users\"\n        method=\"post\"\n        #default=\"{\n            errors,\n            hasErrors,\n            processing,\n            progress,\n            wasSuccessful,\n            recentlySuccessful,\n            setError,\n            clearErrors,\n            resetAndClearErrors,\n            defaults,\n            isDirty,\n            reset,\n            submit\n        }\"\n    >\n        <input type=\"text\" name=\"name\" :value=\"defaults.name\" />\n        <div v-if=\"errors.name\">{{ errors.name }}</div>\n\n        <button type=\"submit\" :disabled=\"processing\">\n            {{ processing ? ''Saving...'' : ''Save'' }}\n        </button>\n\n        <progress v-if=\"progress\" :value=\"progress.percentage\" max=\"100\">\n            {{ progress.percentage }}%\n        </progress>\n\n        <div v-if=\"wasSuccessful\">Saved!</div>\n    </Form>\n</template>\n\n</code-snippet>\n\n### Form Component Reset Props\n\nThe `<Form>` component supports automatic resetting:\n\n- `resetOnError` - Reset form data when the request fails\n- `resetOnSuccess` - Reset form data when the request succeeds\n- `setDefaultsOnSuccess` - Update default values on success\n\nUse the `search-docs` tool with a query of `form component resetting` for detailed guidance.\n\n<code-snippet name=\"Form with Reset Props\" lang=\"vue\">\n\n<script setup>\nimport { Form } from ''@inertiajs/vue3''\n</script>\n\n<template>\n    <Form\n        action=\"/users\"\n        method=\"post\"\n        reset-on-success\n        set-defaults-on-success\n        #default=\"{ errors, processing, wasSuccessful }\"\n    >\n        <input type=\"text\" name=\"name\" />\n        <div v-if=\"errors.name\">{{ errors.name }}</div>\n\n        <button type=\"submit\" :disabled=\"processing\">\n            Submit\n        </button>\n    </Form>\n</template>\n\n</code-snippet>\n\nForms can also be built using the `useForm` composable for more programmatic control. Use the `search-docs` tool with a query of `useForm helper` for guidance.\n\n### `useForm` Composable\n\nFor more programmatic control or to follow existing conventions, use the `useForm` composable:\n\n<code-snippet name=\"useForm Composable Example\" lang=\"vue\">\n\n<script setup>\nimport { useForm } from ''@inertiajs/vue3''\n\nconst form = useForm({\n    name: '''',\n    email: '''',\n    password: '''',\n})\n\nfunction submit() {\n    form.post(''/users'', {\n        onSuccess: () => form.reset(''password''),\n    })\n}\n</script>\n\n<template>\n    <form @submit.prevent=\"submit\">\n        <input type=\"text\" v-model=\"form.name\" />\n        <div v-if=\"form.errors.name\">{{ form.errors.name }}</div>\n\n        <input type=\"email\" v-model=\"form.email\" />\n        <div v-if=\"form.errors.email\">{{ form.errors.email }}</div>\n\n        <input type=\"password\" v-model=\"form.password\" />\n        <div v-if=\"form.errors.password\">{{ form.errors.password }}</div>\n\n        <button type=\"submit\" :disabled=\"form.processing\">\n            Create User\n        </button>\n    </form>\n</template>\n\n</code-snippet>\n\n## Inertia v2 Features\n\n### Deferred Props\n\nUse deferred props to load data after initial page render:\n\n<code-snippet name=\"Deferred Props with Empty State\" lang=\"vue\">\n\n<script setup>\ndefineProps({\n    users: Array\n})\n</script>\n\n<template>\n    <div>\n        <h1>Users</h1>\n        <div v-if=\"!users\" class=\"animate-pulse\">\n            <div class=\"h-4 bg-gray-200 rounded w-3/4 mb-2\"></div>\n            <div class=\"h-4 bg-gray-200 rounded w-1/2\"></div>\n        </div>\n        <ul v-else>\n            <li v-for=\"user in users\" :key=\"user.id\">\n                {{ user.name }}\n            </li>\n        </ul>\n    </div>\n</template>\n\n</code-snippet>\n\n### Polling\n\nAutomatically refresh data at intervals:\n\n<code-snippet name=\"Polling Example\" lang=\"vue\">\n\n<script setup>\nimport { router } from ''@inertiajs/vue3''\nimport { onMounted, onUnmounted } from ''vue''\n\ndefineProps({\n    stats: Object\n})\n\nlet interval\n\nonMounted(() => {\n    interval = setInterval(() => {\n        router.reload({ only: [''stats''] })\n    }, 5000) // Poll every 5 seconds\n})\n\nonUnmounted(() => {\n    clearInterval(interval)\n})\n</script>\n\n<template>\n    <div>\n        <h1>Dashboard</h1>\n        <div>Active Users: {{ stats.activeUsers }}</div>\n    </div>\n</template>\n\n</code-snippet>\n\n### WhenVisible (Infinite Scroll)\n\nLoad more data when user scrolls to a specific element:\n\n<code-snippet name=\"Infinite Scroll with WhenVisible\" lang=\"vue\">\n\n<script setup>\nimport { WhenVisible } from ''@inertiajs/vue3''\n\ndefineProps({\n    users: Object\n})\n</script>\n\n<template>\n    <div>\n        <div v-for=\"user in users.data\" :key=\"user.id\">\n            {{ user.name }}\n        </div>\n\n        <WhenVisible\n            v-if=\"users.next_page_url\"\n            data=\"users\"\n            :params=\"{ page: users.current_page + 1 }\"\n        >\n            <template #fallback>\n                <div>Loading more...</div>\n            </template>\n        </WhenVisible>\n    </div>\n</template>\n\n</code-snippet>\n\n## Server-Side Patterns\n\nServer-side patterns (Inertia::render, props, middleware) are covered in inertia-laravel guidelines.\n\n## Common Pitfalls\n\n- Using traditional `<a>` links instead of Inertia''s `<Link>` component (breaks SPA behavior)\n- Forgetting that Vue components must have a single root element\n- Forgetting to add loading states (skeleton screens) when using deferred props\n- Not handling the `undefined` state of deferred props before data loads\n- Using `<form>` without preventing default submission (use `<Form>` component or `@submit.prevent`)\n- Forgetting to check if `<Form>` component is available in your Inertia version"},"lastSynced":"2026-03-08T02:10:15.806Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing seamless integration of Vue page components with Laravel apps via Inertia protocol.","zh":"适合需要无缝集成Vue页面组件与Laravel应用的全栈代理，通过Inertia协议。","ja":"Inertiaプロトコルを介してVueページコンポーネントとLaravelアプリをシームレスに統合する必要があるフルスタックエージェントに適しています。","ko":"Inertia 프로토콜을 통해 Vue 페이지 컴포넌트와 Laravel 애플리케이션을 無縫的に 통합해야 하는 Full-Stack 에이전트에게 적합합니다.","es":"Perfecto para Agentes Full-Stack que necesitan una integración perfecta de componentes de página de Vue con aplicaciones de Laravel a través del protocolo Inertia.","fr":"Parfait pour les agents Full-Stack ayant besoin d''une intégration transparente des composants de page Vue avec des applications Laravel via le protocole Inertia.","de":"Perfekt für Full-Stack-Agents, die eine nahtlose Integration von Vue-Seitenkomponenten mit Laravel-Apps über das Inertia-Protokoll benötigen.","pt":"Perfeito para Agentes Full-Stack que precisam de integração perfeita de componentes de página Vue com aplicativos Laravel via protocolo Inertia.","ru":"Идеально подходит для агентов Full-Stack, которым требуется бесперебойная интеграция компонентов страниц Vue с приложениями Laravel через протокол Inertia.","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى دمج متكامل للمكونات الإضافية لصفحة Vue مع تطبيقات Laravel عبر بروتوكول Inertia."},"recommendation":{"en":"Empowers agents to build robust client-side navigations with `<Link>` or `router`, create efficient forms using `<Form>` or `useForm`, and leverage v2 features like deferred props, prefetching, or polling for enhanced user experience.","zh":"赋予代理构建强大的客户端导航，使用`<Link>`或`router`，创建高效的表单，使用`<Form>`或`useForm`，并利用v2功能，如延迟属性、预取或轮询，增强用户体验。","ja":"エージェントに、`<Link>`または`router`を使用して強力なクライアント側ナビゲーションを構築し、`<Form>`または`useForm`を使用して効率的なフォームを作成し、v2機能 such as 遅延プロパティ、プリフェッチ、またはポーリングを使用してユーザーエクスペリエンスを強化することを可能にします。","ko":"에이전트가 `<Link>` 또는 `router`를 사용하여 강력한 클라이언트 측 탐색을 구축하고, `<Form>` 또는 `useForm`를 사용하여 효율적인 양식을 생성하며, v2 기능을 사용하여 사용자 경험을 강화할 수 있습니다.","es":"Habilita a los agentes a construir navegaciones del lado del cliente robustas con `<Link>` o `router`, crear formularios eficientes utilizando `<Form>` o `useForm`, y aprovechar las características de la v2 como propiedades diferidas, precarga o sondeo para una experiencia del usuario mejorada.","fr":"Permet aux agents de créer des navigations côté client robustes avec `<Link>` ou `router`, de créer des formulaires efficaces en utilisant `<Form>` ou `useForm`, et de tirer parti des fonctionnalités de la v2 comme les propriétés différées, le préchargement ou l''interrogation pour une expérience utilisateur améliorée.","de":"Ermöglicht es Agenten, robuste Client-Seitennavigations mit `<Link>` oder `router` zu erstellen, effiziente Formulare mit `<Form>` oder `useForm` zu erstellen und die Funktionen von v2 wie aufgeschobene Eigenschaften, Vorabladung oder Polling für eine verbesserte Benutzererfahrung zu nutzen.","pt":"Habilita os agentes a construir navegações robustas do lado do cliente com `<Link>` ou `router`, criar formulários eficientes usando `<Form>` ou `useForm` e aproveitar os recursos do v2, como props adiados, pré-busca ou pesquisa para uma experiência do usuário aprimorada.","ru":"Позволяет агентам создавать надежную навигацию на стороне клиента с помощью `<Link>` или `router`, создавать эффективные формы с помощью `<Form>` или `useForm` и использовать функции v2, такие как отложенные свойства, предварительная загрузка или опрос для улучшения пользовательского опыта.","ar":"تمكن الوكلاء من بناء导航ات قوية على جانب العميل باستخدام `<Link>` أو `router`، وإنشاء استمارات كفؤة باستخدام `<Form>` أو `useForm`، وتحقيق الميزات v2 مثل الخصائص المؤجلة أو البحث المسبق أو المسح لتحسين تجربة المستخدم."},"useCases":{"en":["Creating reusable Vue page components for Inertia-powered Laravel applications","Implementing efficient client-side navigation with `<Link>` or `router` for seamless user experience","Building robust forms with `<Form>` or `useForm` for reliable data collection and validation","Utilizing Inertia v2 features for optimized performance and responsiveness"],"zh":["为Inertia驱动的Laravel应用程序创建可重用的Vue页面组件","使用`<Link>`或`router`实现高效的客户端导航，提供无缝的用户体验","使用`<Form>`或`useForm`构建强大的表单，实现可靠的数据收集和验证","利用Inertia v2功能优化性能和响应性"],"ja":["Inertia駆動のLaravelアプリケーション用の再利用可能なVueページコンポーネントを作成する","`<Link>`または`router`を使用して効率的なクライアント側ナビゲーションを実装し、シームレスなユーザーエクスペリエンスを提供する","`<Form>`または`useForm`を使用して強力なフォームを構築し、信頼性の高いデータ収集とバリデーションを実現する","Inertia v2機能を使用してパフォーマンスとレスポンス性を最適化する"],"ko":["Inertia 구동 Laravel 애플리케이션을 위한 재사용 가능한 Vue 페이지 컴포넌트 생성","`<Link>` 또는 `router`를 사용하여 효율적인 클라이언트 측 탐색을 구현하고, 무제한의 사용자 경험을 제공","`<Form>` 또는 `useForm`를 사용하여 강력한 양식을 구축하고, 신뢰할 수 있는 데이터 수집 및 검증을 실現","Inertia v2 기능을 사용하여 성능과 반응성을 최적화"],"es":["Creación de componentes de página de Vue reutilizables para aplicaciones de Laravel con Inertia","Implementación de navegación del lado del cliente eficiente con `<Link>` o `router` para una experiencia del usuario sin problemas","Construcción de formularios robustos con `<Form>` o `useForm` para una recopilación y validación de datos confiables","Uso de características de Inertia v2 para un rendimiento y una respuesta optimizados"],"fr":["Création de composants de page Vue réutilisables pour des applications Laravel avec Inertia","Mise en œuvre d''une navigation côté client efficace avec `<Link>` ou `router` pour une expérience utilisateur transparente","Conception de formulaires robustes avec `<Form>` ou `useForm` pour une collecte et une validation de données fiables","Utilisation des fonctionnalités d''Inertia v2 pour des performances et une réactivité optimisées"],"de":["Erstellung von wiederverwendbaren Vue-Seitenkomponenten für Laravel-Anwendungen mit Inertia","Implementierung einer effizienten Client-Seitennavigation mit `<Link>` oder `router` für eine nahtlose Benutzererfahrung","Erstellung von robusten Formularen mit `<Form>` oder `useForm` für eine zuverlässige Datenerfassung und -validierung","Nutzung von Inertia-v2-Funktionen für optimierte Leistung und Reaktionszeit"],"pt":["Criar componentes de página Vue reutilizáveis para aplicativos Laravel alimentados por Inertia","Implementar navegação eficiente do lado do cliente com `<Link>` ou `router` para experiência do usuário perfeita","Construir formulários robustos com `<Form>` ou `useForm` para coleta e validação de dados confiáveis","Utilizar recursos do Inertia v2 para desempenho e responsividade otimizados"],"ru":["Создание многократно используемых компонентов страниц Vue для приложений Laravel, работающих через Inertia","Реализация эффективной навигации на стороне клиента с помощью `<Link>` или `router` для бесперебойного пользовательского опыта","Создание надежных форм с помощью `<Form>` или `useForm` для надежного сбора и проверки данных","Использование функций Inertia v2 для оптимизированной производительности и отзывчивости"],"ar":["إنشاء مكونات إضافية لصفحة Vue قابلة لإعادة الاستخدام لتطبيقات Laravel مدعومة من بروتوكول Inertia","تنفيذ التنقل الفعال على جانب العميل باستخدام `<Link>` أو `router` لتجربة مستخدم سلسة","بناء استمارات قوية باستخدام `<Form>` أو `useForm` لجمع البيانات والتحقق منها بشكل موثوق","استخدام ميزات Inertia v2 لأداء واستجابة محسّنة"]},"limitations":{"en":["Requires Inertia v2 setup and understanding of Vue and Laravel ecosystem","Limited to Vue page components and Inertia protocol","Dependent on Laravel backend for full functionality"],"zh":["需要Inertia v2设置和对Vue及Laravel生态系统的理解","仅限于Vue页面组件和Inertia协议","依赖于Laravel后端才能实现全部功能"],"ja":["Inertia v2の設定とVueおよびLaravelエコシステムの理解が必要","VueページコンポーネントとInertiaプロトコルに限定される","Laravelバックエンドに依存して全機能を実現する"],"ko":["Inertia v2 설정 및 Vue 및 Laravel 생태계 이해가 필요","Vue 페이지 컴포넌트 및 Inertia 프로토콜로 제한","Laravel 백엔드에 의존하여 전체 기능을 구현"],"es":["Requiere configuración de Inertia v2 y comprensión del ecosistema de Vue y Laravel","Limitado a componentes de página de Vue y protocolo de Inertia","Dependiente del backend de Laravel para la funcionalidad completa"],"fr":["Nécessite une configuration Inertia v2 et une compréhension de l''écosystème Vue et Laravel","Limité aux composants de page Vue et au protocole Inertia","Dépendant du backend Laravel pour la fonctionnalité complète"],"de":["Benötigt Inertia-v2-Setup und Verständnis des Vue- und Laravel-Ökosystems","Begrenzt auf Vue-Seitenkomponenten und Inertia-Protokoll","Von Laravel-Backend für die volle Funktionalität abhängig"],"pt":["Requer configuração do Inertia v2 e compreensão do ecossistema Vue e Laravel","Limitado a componentes de página Vue e protocolo Inertia","Dependente do backend Laravel para funcionalidade completa"],"ru":["Требует настройки Inertia v2 и понимания экосистемы Vue и Laravel","Ограничен компонентами страниц Vue и протоколом Inertia","Зависит от бэкенда Laravel для полной функциональности"],"ar":["يتطلب إعداد Inertia v2 وفهم النظام البيئي لVue وLaravel","محدود بمكونات صفحة Vue وبروتوكول Inertia","يعتمد على الخلفية Laravel للوظيفة الكاملة"]},"version":4},"contentHash":"78cee50a9b19af2cf597253231710b7e3fe1f43403455f968b1324e268655314","qualityScore":32}');
