INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('coollabsio/laravel-template/inertia-vue-development', 'inertia-vue-development', 'coollabsio', 'laravel-template', 'community', 'inertia-vue-development coollabsio laravel-template community The inertia-vue-development skill provides a template for Laravel apps, benefiting developers working with Vue page components, forms, and client-side navigation. Inertia Vue开发模板，用于创建或修改Vue页面组件，包括表单、客户端导航和v2功能 Inertia Vue開発のためのテンプレート、Vueページコンポーネントの作成または変更、フォーム、クライアントサイドナビゲーション、v2機能 Inertia Vue 개발을 위한 템플릿, Vue 페이지 컴포넌트의 생성 또는 수정, 폼, 클라이언트 측 탐색, v2 기능 Inertia Vue Development es una plantilla para aplicaciones Laravel que permite crear componentes de página Vue con funcionalidades avanzadas Inertia Vue Development est un modèle pour les applications Laravel qui permet de créer des composants de page Vue avec des fonctionnalités avancées Inertia Vue Development ist ein Template für Laravel-Anwendungen, das die Erstellung von Vue-Seitenkomponenten mit erweiterten Funktionen ermöglicht Inertia Vue Development é uma ferramenta para criar aplicações Laravel com componentes de página Vue e navegação cliente Inertia Vue Development - это инструмент для создания приложений Laravel с компонентами страниц Vue и клиентской навигацией Inertia Vue Development هي أداة لإنشاء تطبيقات Laravel باستخدام مكونات الصفحة Vue والملاحة العميل how to use inertia-vue-development inertia-vue-development setup guide inertia-vue-development vs vue-router inertia-vue-development install what is inertia-vue-development inertia-vue-development alternative inertia-vue-development tutorial inertia-vue-development documentation inertia-vue-development best practices Inertia Vue开发 Laravel应用模板 Vue页面组件 表单开发 客户端导航 v2功能 Inertia协议 AI开发工具 Vue开发最佳实践 Creates and modifies Vue page components for Inertia Works with forms in Vue using `<Form>` or `useForm` Implements client-side navigation with `<Link>` or `router` Utilizes v2 features like deferred props, prefetching, and polling Builds Vue-specific features with the Inertia protocol inertia-vue-development is a skill for creating and modifying Vue page components for Inertia, utilizing features like deferred props, prefetching, and polling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('team-attention/code-squad/spets', 'community', 'team-attention', 'code-squad', 'team-attention/code-squad', 'spets', 0, 0, 32, '2026-03-08T01:57:15.563Z', '2026-03-08T02:11:37.300Z', 'd27436fb04f0ca1d00af3c4cd806a441eb11b2927e3466add255cb3fcccf097b', '{"id":"team-attention/code-squad/spets","name":"spets","description":{"en":"Spets is a skill that enables developers to stay in flow while building with AI by executing orchestrator commands and parsing JSON responses. It benefits AI developers and teams looking to automate their workflows.","zh":"Spets 是一个 AI 工具，允许开发者通过 JSON 解析和命令执行来构建自定义工作流","ja":"Spets は、JSON パースとコマンド実行を通じてカスタムワークフローを構築できる AI エージェントです","ko":"Spets는 JSON 파싱과 명령 실행을 통해 사용자 지정 워크플ロー 구축이 가능한 AI 도구입니다","es":"Spets es una herramienta de automatización de flujos de trabajo que utiliza comandos de orquestación y parsing de JSON para mantener el flujo de trabajo","fr":"Spets est un outil d''automatisation de flux de travail qui utilise des commandes d''orchestration et d''analyse JSON pour maintenir le flux de travail","de":"Spets ist ein Workflow-Automatisierungstool, das Orchestrierungsbefehle und JSON-Parsing verwendet, um den Arbeitsfluss aufrechtzuerhalten","pt":"O Spets é uma ferramenta de orquestração de comandos AI que ajuda a manter o fluxo de trabalho. Ele executa comandos e parseia respostas JSON.","ru":"Spets — это инструмент оркестровки команд ИИ, который помогает поддерживать рабочий процесс. Он выполняет команды и парсит ответы JSON.","ar":"Spets هو أداة لتنفيذ أوامر الإيجاد الذكي التي تساعد على الحفاظ على تدفق العمل. انها تنفذ أوامر وتحلل استجابات JSON."},"seo":{"title":{"en":"Spets: Automated AI Workflow Setup Guide | AI Agent Skill","zh":"Spets AI 工具集成指南","ja":"Spets AI エージェントの設定方法","ko":"Spets AI 도구 사용자 가이드","es":"Guía de configuración de Spets: Automatización de flujos ...","fr":"Guide de configuration de Spets : Automatisation des flux...","de":"Spets-Konfigurationsleitfaden: Automatisierung von Workfl...","pt":"Guia de Configuração Spets: Orquestração de Comandos AI","ru":"ИИ Агенты Spets: Руководство по Настройке и Оркестровке","ar":"دليل إعداد Spets: تنفيذ أوامر الإيجاد الذكي"},"description":{"en":"Unlock streamlined AI development with spets! Learn how to execute orchestrator commands, parse JSON, and integrate AI workflows seamlessly - get started today!","zh":"了解 Spets 的技术细节，掌握 JSON 解析、命令执行和决策树的使用方法","ja":"Spets の技術的な詳細を学び、JSON パース、コマンド実行、意思決定ツリーの使用方法をマスターしましょう","ko":"Spets 의 기술적 세부 사항을 배우고 JSON 파싱, 명령 실행 및 의사 결정 트리의 사용 방법을 익히세요","es":"Aprende a configurar Spets para automatizar flujos de trabajo con comandos de orquestación y parsing de JSON","fr":"Découvrez comment configurer Spets pour automatiser les flux de travail avec des commandes d''orchestration et d''analyse JSON","de":"Erfahren Sie, wie Sie Spets konfigurieren, um Workflows mit Orchestrierungsbefehlen und JSON-Parsing zu automatisieren","pt":"Aprenda a usar o Spets para manter o fluxo de trabalho enquanto constrói com IA. Veja como orquestrar comandos e parsear respostas JSON.","ru":"Узнайте, как использовать Spets для поддержания рабочего процесса при работе с ИИ. Посмотрите, как оркестровать команды и парсить ответы JSON.","ar":"تعرف على كيفية استخدام Spets للحفاظ على تدفق العمل أثناء بناء الإيجاد الذكي. انظر كيفية تنفيذ أوامر الإيجاد وتحليل استجابات JSON."},"definition":{"en":"Spets is an AI agent skill that automates workflow execution using orchestrator commands and JSON parsing, facilitating streamlined AI development.","zh":"Spets 是一个基于 JSON 的 AI 工具，用于执行命令和解析数据","ja":"Spets は JSON ベースの AI エージェントで、コマンドを実行しデータを解析します","ko":"Spets는 JSON 기반의 AI 도구로서 명령을 실행하고 데이터를 파싱합니다","es":"Spets es un agente de IA que automatiza flujos de trabajo mediante comandos de orquestación y parsing de JSON","fr":"Spets est un agent d''IA qui automatise les flux de travail à l''aide de commandes d''orchestration et d''analyse JSON","de":"Spets ist ein KI-Agent, der Workflows mittels Orchestrierungsbefehlen und JSON-Parsing automatisiert","pt":"O que é Spets? É uma ferramenta de orquestração de comandos AI que executa comandos e parseia respostas JSON.","ru":"Что такое Spets? Это инструмент оркестровки команд ИИ, который выполняет команды и парсит ответы JSON.","ar":"ما هو Spets؟ هو أداة لتنفيذ أوامر الإيجاد الذكي التي تنفذ أوامر وتحلل استجابات JSON."},"features":{"en":["Executes spets orchestrator commands via `npx spets orchestrate init`","Parses JSON responses to determine next steps","Supports conditional execution based on `type` and `checkpoint` values","Runs `onComplete` callbacks with output as JSON arguments","Handles user input and decisions through `decisions[]` array"],"zh":["支持 JSON 解析和命令执行","提供决策树功能以实现复杂逻辑","支持用户交互和输入","允许开发者自定义工作流","集成 CLI 命令以实现自动化","支持多种数据格式和协议"],"ja":["JSON パースとコマンド実行をサポート","意思決定ツリー機能を提供して複雑なロジックを実現","ユーザーインタラクションと入力をサポート","開発者がカスタムワークフローを作成できる","CLI コマンドを統合して自動化を実現","多種のデータ形式とプロトコルをサポート"],"ko":["JSON 파싱과 명령 실행을 지원","의사 결정 트리 기능을 제공하여 복잡한 논리를 구현","사용자 상호 작용과 입력을 지원","개발자가 사용자 지정 워크플ロー 생성을 허용","CLI 명령을 통합하여 자동화를 구현","다양한 데이터 형식과 프로토콜을 지원"],"es":["Ejecución de comandos de orquestación con npx spets orchestrate init","Parsing de respuestas JSON","Ejecución de comandos basados en el tipo de respuesta","Soporte para checkpoints y decisiones","Integración con herramientas de desarrollo como CLI"],"fr":["Exécution de commandes d''orchestration avec npx spets orchestrate init","Analyse de réponses JSON","Exécution de commandes basées sur le type de réponse","Prise en charge des checkpoints et des décisions","Intégration avec des outils de développement comme CLI"],"de":["Ausführung von Orchestrierungsbefehlen mit npx spets orchestrate init","Parsing von JSON-Antworten","Ausführung von Befehlen basierend auf dem Antworttyp","Unterstützung für Checkpoints und Entscheidungen","Integration mit Entwicklungstools wie CLI"],"pt":["Executa comandos Spets Orquestrador","Parseia respostas JSON","Suporta tipo ''phase'' e ''checkpoint''","Executa ações baseadas em decisões de usuário","Integração com CLI via ''npx spets orchestrate init''"],"ru":["Выполняет команды Spets Orkestrator","Парсит ответы JSON","Поддерживает тип ''phase'' и ''checkpoint''","Выполняет действия на основе решений пользователя","Интеграция с CLI через ''npx spets orchestrate init''"],"ar":["تنفيذ أوامر Spets Orkestrator","تحليل استجابات JSON","دعم نوع ''phase'' و ''checkpoint''","تنفيذ إجراءات بناءً على قرارات المستخدم","التكامل مع CLI من خلال ''npx spets orchestrate init''"]},"keywords":{"en":["how to use spets","spets setup guide","spets alternative","spets vs automation tools","spets install","spets orchestrator commands","json parsing in spets","ai workflow automation with spets"],"zh":["Spets AI 工具","JSON 解析","命令执行","决策树","自定义工作流","CLI 命令","AI 开发","自动化工具","数据解析"],"ja":["Spets AI エージェント","JSON パース","コマンド実行","意思決定ツリー","カスタムワークフロー","CLI コマンド","AI 開発","自動化ツール","データ解析"],"ko":["Spets AI 도구","JSON 파싱","명령 실행","의사 결정 트리","사용자 지정 워크플ロー","CLI 명령","AI 개발","자동화 도구","데이터 파싱"],"es":["Spets","Agentes de IA","Automatización de flujos de trabajo","Orquestación","Parsing de JSON","Desarrollo de software","Herramientas de desarrollo","CLI","Npx"],"fr":["Spets","Outils d''IA","Automatisation de flux de travail","Orchestration","Analyse JSON","Développement de logiciels","Outils de développement","CLI","Npx"],"de":["Spets","KI-Agents","Automatisierung von Workflows","Orchestrierung","JSON-Parsing","Softwareentwicklung","Entwicklungstools","CLI","Npx"],"pt":["Spets","Orquestração de Comandos AI","Parsear Respostas JSON","Desenvolvimento com IA","Ferramentas de Desenvolvimento","CLI","Npx","Comandos Spets"],"ru":["Spets","ИИ Агенты","Оркестровка Команд ИИ","Парсить Ответы JSON","Разработка с ИИ","Инструменты Разработки","CLI","Npx","Команды Spets"],"ar":["Spets","أداة الإيجاد الذكي","تنفيذ أوامر الإيجاد الذكي","تحليل استجابات JSON","التطوير بالإيجاد الذكي","أدوات التطوير","CLI","Npx","أوامر Spets"]}},"owner":"team-attention","repo":"code-squad","repoPath":"team-attention/code-squad","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.563Z","topics":[],"category":"community","skillMd":{"name":"spets","description":"SDD workflow executor - orchestrator-controlled spec-driven development. Activate when the user wants to run spets, SDD workflows, or spec-driven development tasks.","bodyPreview":"# Spets Executor\n\nYou execute spets orchestrator commands. Parse JSON, follow instructions, repeat.\n\n## Execution\n\n1. RUN `npx spets orchestrate init \"$ARGUMENTS\"`\n2. PARSE JSON response\n3. SWITCH on `type`:\n\ntype=\"phase\":\n  - EXECUTE what `prompt` says\n  - RUN `onComplete` with your output as JSON argument\n  - GOTO step 2\n\ntype=\"checkpoint\", checkpoint=\"clarify\":\n  - ASK user each question in `decisions[]`\n  - RUN `onComplete` with `[{decisionId, selectedOptionId}, ...]`\n  - GOTO step 2\n\ntype=\"","body":"# Spets Executor\n\nYou execute spets orchestrator commands. Parse JSON, follow instructions, repeat.\n\n## Execution\n\n1. RUN `npx spets orchestrate init \"$ARGUMENTS\"`\n2. PARSE JSON response\n3. SWITCH on `type`:\n\ntype=\"phase\":\n  - EXECUTE what `prompt` says\n  - RUN `onComplete` with your output as JSON argument\n  - GOTO step 2\n\ntype=\"checkpoint\", checkpoint=\"clarify\":\n  - ASK user each question in `decisions[]`\n  - RUN `onComplete` with `[{decisionId, selectedOptionId}, ...]`\n  - GOTO step 2\n\ntype=\"checkpoint\", checkpoint=\"approve\":\n  - READ `specPath`, summarize key points to user\n  - ASK user with options: Approve / Revise / Reject / Stop\n  - RUN matching `onComplete` based on user''s choice\n  - GOTO step 2\n\ntype=\"complete\" or \"error\":\n  - PRINT message\n  - STOP\n\n## Forbidden\n\nPlanning mode, task tracking tools\n\n$ARGUMENTS\ndescription: Task description for the workflow\n"},"lastSynced":"2026-03-08T02:11:37.300Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing streamlined workflow automation through JSON parsing and orchestrator command execution.","zh":"非常适合需要通过JSON解析和执行orchestrator命令来实现工作流自动化的AI代理。","ja":"JSONの解析とオーケストレーター コマンドの実行を通じてワークフロー自動化を最適化する必要があるAIエージェントに最適です。","ko":"JSON 파싱 및 오케스트레이터 명령 실행을 통해 워크플ロー 자동화를 최적화해야 하는 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan una automatización de flujo de trabajo optimizada a través del análisis de JSON y la ejecución de comandos de orquestador.","fr":"Parfait pour les agents IA nécessitant une automatisation de workflow simplifiée via l''analyse JSON et l''exécution de commandes d''orchestrateur.","de":"Perfekt für KI-Agents, die eine optimierte Workflow-Automatisierung durch JSON-Parsing und Orchester-Befehlsausführung benötigen.","pt":"Perfeito para Agentes de IA que necessitam de automação de fluxo de trabalho otimizada por meio de análise de JSON e execução de comandos de orquestrador.","ru":"Идеально для ИИ-агентов, которым требуется оптимизированная автоматизация рабочего процесса посредством парсинга JSON и выполнения команд оркестратора.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تسهيل تدفق العمل من خلال تحليل JSON وتنفيذ أوامر المدير"},"recommendation":{"en":"Empowers agents to execute spets orchestrator commands, parse JSON responses, and automate workflows using protocols like npx, while following instructions and repeating tasks as needed, utilizing JSON arguments and decision arrays.","zh":"赋予代理执行spets orchestrator命令、解析JSON响应并使用协议如npx自动化工作流的能力，同时按照指令并根据需要重复任务，利用JSON参数和决策数组。","ja":"エージェントに、spets オーケストレーター コマンドを実行し、JSON 応答を解析し、npx のようなプロトコルを使用してワークフローを自動化する機能を提供し、指示に従って必要に応じてタスクを繰り返し、JSON 引数と決定配列を利用します。","ko":"에이전트가 spets 오케스트레이터 명령을 실행하고 JSON 응답을 파싱하며 npx와 같은 프로토콜을 사용하여 워크플ロー 자동화를 수행할 수 있도록 하며, 지시를 따르고 필요한 경우 작업을 반복하며, JSON 인수와 의사결정 배열을 활용합니다.","es":"Habilita a los agentes a ejecutar comandos de orquestador personalizados, analizar respuestas JSON y automatizar flujos de trabajo utilizando protocolos como npx, siguiendo instrucciones y repitiendo tareas según sea necesario, utilizando argumentos JSON y matrices de decisión.","fr":"Permet aux agents d''exécuter des commandes d''orchestrateur personnalisées, d''analyser les réponses JSON et d''automatiser les flux de travail en utilisant des protocoles comme npx, en suivant les instructions et en répétant les tâches selon les besoins, en utilisant des arguments JSON et des tableaux de décision.","de":"Ermächtigt Agents, benutzerdefinierte Orchester-Befehle auszuführen, JSON-Antworten zu parsen und Workflows mit Protokollen wie npx zu automatisieren, indem sie Anweisungen befolgen und Aufgaben nach Bedarf wiederholen, unter Verwendung von JSON-Argumenten und Entscheidungsmatrizen.","pt":"Habilita os agentes a executar comandos de orquestrador especiais, analisar respostas JSON e automatizar fluxos de trabalho usando protocolos como npx, seguindo instruções e repetindo tarefas conforme necessário, utilizando argumentos JSON e matrizes de decisão.","ru":"Наделяет агентов возможностью выполнять специальные команды оркестратора, парсить ответы JSON и автоматизировать рабочие процессы с помощью протоколов типа npx, следуя инструкциям и повторяя задачи по мере необходимости, используя аргументы JSON и массивы решений.","ar":"تمكين الوكلاء من تنفيذ أوامر المدير الخاصة، و تحليل استجابات JSON، وتسهيل تدفق العمل باستخدام بروتوكولات مثل npx، متابعة الإرشادات وتكرار المهام حسب الحاجة، باستخدام حجة JSON ومتحولات القرار"},"useCases":{"en":["Automating AI development workflows","Parsing JSON responses for decision-making","Executing orchestrator commands with npx spets"],"zh":["自动化AI开发工作流","解析JSON响应以进行决策","使用npx spets执行orchestrator命令"],"ja":["AI開発ワークフローの自動化","JSON応答の解析による意思決定","npx spetsを使用したオーケストレーター コマンドの実行"],"ko":["AI 개발 워크플로 자동화","JSON 응답 파싱을 통한 의사결정","npx spets를 사용한 오케스트레이터 명령 실행"],"es":["Automatización de flujos de trabajo de desarrollo de IA","Análisis de respuestas JSON para la toma de decisiones","Ejecución de comandos de orquestador con npx spets"],"fr":["Automatisation des flux de travail de développement d''IA","Analyse des réponses JSON pour la prise de décision","Exécution de commandes d''orchestrateur avec npx spets"],"de":["Automatisierung von KI-Entwicklungsworkflows","Analyse von JSON-Antworten für die Entscheidungsfindung","Ausführung von Orchester-Befehlen mit npx spets"],"pt":["Automatizar fluxos de trabalho de desenvolvimento de IA","Analisar respostas JSON para tomada de decisões","Executar comandos de orquestrador com npx spets"],"ru":["Автоматизация рабочих процессов разработки ИИ","Парсинг ответов JSON для принятия решений","Выполнение команд оркестратора с помощью npx spets"],"ar":["تسهيل تدفق العمل لتطوير الذكاء الاصطناعي","تحليل استجابات JSON لاتخاذ القرارات","تنفيذ أوامر المدير مع npx spets"]},"limitations":{"en":["Requires npx spets installation","Dependent on JSON response structure","Limited to spets orchestrator commands"],"zh":["需要npx spets安装","依赖于JSON响应结构","仅限spets orchestrator命令"],"ja":["npx spetsのインストールが必要","JSON応答構造に依存している","spets オーケストレーター コマンドのみ"],"ko":["npx spets 설치가 필요함","JSON 응답 구조에 의존함","spets 오케스트레이터 명령만 해당"],"es":["Requiere la instalación de npx spets","Dependiente de la estructura de la respuesta JSON","Limitado a los comandos de orquestador spets"],"fr":["Nécessite l''installation de npx spets","Dépend de la structure de la réponse JSON","Limité aux commandes d''orchestrateur spets"],"de":["Benötigt die Installation von npx spets","Abhängig von der Struktur der JSON-Antwort","Begrenzt auf spets-Orchester-Befehle"],"pt":["Requer instalação do npx spets","Dependente da estrutura de resposta JSON","Limitado a comandos de orquestrador spets"],"ru":["Требует установки npx spets","Зависит от структуры ответа JSON","Ограничен командами оркестратора spets"],"ar":["يتطلب تثبيت npx spets","يعتمد على هيكل استجابة JSON","محدود بأوامر المدير spets"]},"version":4},"contentHash":"d27436fb04f0ca1d00af3c4cd806a441eb11b2927e3466add255cb3fcccf097b","qualityScore":32}');
