INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('team-attention/code-squad/spets', 'spets', 'team-attention', 'code-squad', 'community', 'spets team-attention code-squad community Spets is a skill that enables developers to stay in flow while building with AI by executing orchestrator commands and parsing JSON responses. It benefits AI developers and teams looking to automate their workflows. Spets 是一个 AI 工具，允许开发者通过 JSON 解析和命令执行来构建自定义工作流 Spets は、JSON パースとコマンド実行を通じてカスタムワークフローを構築できる AI エージェントです Spets는 JSON 파싱과 명령 실행을 통해 사용자 지정 워크플ロー 구축이 가능한 AI 도구입니다 Spets es una herramienta de automatización de flujos de trabajo que utiliza comandos de orquestación y parsing de JSON para mantener el flujo de trabajo Spets est un outil d''automatisation de flux de travail qui utilise des commandes d''orchestration et d''analyse JSON pour maintenir le flux de travail Spets ist ein Workflow-Automatisierungstool, das Orchestrierungsbefehle und JSON-Parsing verwendet, um den Arbeitsfluss aufrechtzuerhalten O Spets é uma ferramenta de orquestração de comandos AI que ajuda a manter o fluxo de trabalho. Ele executa comandos e parseia respostas JSON. Spets — это инструмент оркестровки команд ИИ, который помогает поддерживать рабочий процесс. Он выполняет команды и парсит ответы JSON. Spets هو أداة لتنفيذ أوامر الإيجاد الذكي التي تساعد على الحفاظ على تدفق العمل. انها تنفذ أوامر وتحلل استجابات JSON. how to use spets spets setup guide spets alternative spets vs automation tools spets install spets orchestrator commands json parsing in spets ai workflow automation with spets Spets AI 工具 JSON 解析 命令执行 决策树 自定义工作流 CLI 命令 AI 开发 自动化工具 数据解析 Executes spets orchestrator commands via `npx spets orchestrate init` Parses JSON responses to determine next steps Supports conditional execution based on `type` and `checkpoint` values Runs `onComplete` callbacks with output as JSON arguments Handles user input and decisions through `decisions[]` array Spets is an AI agent skill that automates workflow execution using orchestrator commands and JSON parsing, facilitating streamlined AI development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Amdkn/aspace_amiral/mcp_mastery', 'community', 'Amdkn', 'aspace_amiral', 'Amdkn/aspace_amiral', 'mcp_mastery', 0, 0, 32, '2026-03-08T01:57:15.568Z', '2026-03-08T02:11:43.094Z', '0eac799767ce9386ffe2fd639a439b45e2cf3e5a824cf24c3c28e5ada3e363fb', '{"id":"Amdkn/aspace_amiral/mcp_mastery","name":"mcp_mastery","description":{"en":"mcp_mastery is a skill that enables mastery of MCP servers for AI agents, allowing for efficient orchestration of A''Space OS components. It benefits developers working with autonomous agents.","zh":"MCP Mastery是A''Space OS的Cockpit de Commandement，用于orchestrer Vie、Business和Tech。它支持Filesystem、Docker和n8n等技术","ja":"MCPマスタリーはA''Space OSのCockpit de Commandementで、Vie、Business、Techをorchestrerするために使用され、Filesystem、Docker、n8nなどの技術をサポートしています","ko":"MCP Mastery는 A''Space OS의 Cockpit de Commandement로, Life OS, Business OS 및 Kernel을 오케스트레이션하기 위한 것입니다. 파일 시스템, Docker 및 n8n을 지원합니다","es":"La habilidad mcp_mastery permite a los desarrolladores dominar los servidores MCP con tecnologías como Filesystem, Docker y n8n para agents A''Space OS","fr":"La compétence mcp_mastery permet aux développeurs de maîtriser les serveurs MCP avec des technologies telles que Filesystem, Docker et n8n pour les agents A''Space OS","de":"Die Fähigkeit mcp_mastery ermöglicht es Entwicklern, MCP-Server mit Technologien wie Filesystem, Docker und n8n für A''Space-OS-Agents zu beherrschen","pt":"O mcp_mastery é uma habilidade para automação de tarefas com n8n, Docker e MCP. Configure sua infraestrutura para otimizar a produtividade","ru":"mcp_mastery - навык для автоматизации задач с n8n, Docker и MCP. Настройте свою инфраструктуру для оптимизации производительности ИИ Агентов","ar":"mcp_mastery هو مهارة لآتمتة المهام مع n8n و Docker و MCP. أعد بنيتك التحتية لتحسين الإنتاجية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"mcp_m