INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jabez007/johnny-decimal-zettelkasten/librarian-vault-manager', 'librarian-vault-manager', 'jabez007', 'johnny-decimal-zettelkasten', 'community', 'librarian-vault-manager jabez007 johnny-decimal-zettelkasten community The librarian-vault-manager skill enables Gemini CLI to manage Obsidian vaults using Johnny Decimal and Zettelkasten methodologies, assisting in knowledge development and vault maintenance for developers. Librarian Vault Manager 是一个使用 Johnny Decimal 和 Zettelkasten 方法ology 结合 AI 力量管理 Obsidian Vault 的知识管理系统 Librarian Vault Manager は、Johnny Decimal と Zettelkasten 方法ology を組み合わせて Obsidian Vault を管理する知識管理システムです Librarian Vault Manager 는 Johnny Decimal 및 Zettelkasten 방법론과 AI 를 결합하여 Obsidian Vault 를 관리하는 지식 관리 시스템입니다 Librarian Vault Manager es un sistema de conocimiento que gestiona múltiples vaults de Obsidian, combinando Johnny Decimal y Zettelkasten con agentes de biblioteca de IA para el mantenimiento Librarian Vault Manager est un système de connaissances qui gère plusieurs vaults Obsidian, combinant Johnny Decimal et Zettelkasten avec des agents de bibliothèque IA pour la maintenance Librarian Vault Manager ist ein Wissenssystem, das mehrere Obsidian-Vaults verwaltet, indem es Johnny Decimal und Zettelkasten mit IA-Bibliotheksagenten für die Wartung kombiniert O Gerenciador de Vault de Bibliotecário é um sistema de conhecimento composto que gerencia múltiplos vaults Obsidian, combinando Johnny Decimal e Zettelkasten ИИ Агент Librarian Vault Manager - это составная система знаний, которая управляет несколькими хранилищами Obsidian, сочетая Johnny Decimal и Zettelkasten مدير خزنة المكتبات هو نظام معرفي مركب يدير العديد من خزائن Obsidian، ويجمع بين Johnny Decimal و Zettelkasten how to use librarian-vault-manager librarian-vault-manager setup guide librarian-vault-manager alternative librarian-vault-manager vs other knowledge management tools librarian-vault-manager install what is librarian-vault-manager librarian-vault-manager for Obsidian vault management AI librarian agents for knowledge management Gemini CLI for librarian-vault-manager Librarian Vault Manager AI 에ージェнт 知识管理系统 Obsidian Vault Johnny Decimal Zettelkasten Gemini CLI AI 力量 结构化组织 emergent 意义 Structures Obsidian vaults using Johnny Decimal methodology Integrates Zettelkasten for emergent meaning and knowledge development Utilizes AI librarian agents for automated vault maintenance Guides users through maintenance and knowledge development tasks via Gemini CLI Prioritizes preservation of knowledge and structural integrity of the vault librarian-vault-manager is a compounding knowledge system that combines structural organization with emergent meaning, augmented by AI librarian agents for maintenance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bitsydarel/BDSkills/bd-skill-reviewing', 'community', 'bitsydarel', 'BDSkills', 'bitsydarel/BDSkills', 'bd-skill-reviewing', 0, 0, 32, '2026-03-07T12:46:33.597Z', '2026-03-07T12:58:38.739Z', 'd38f8071da82f4c0741848ca57ac76f1ad4e78b818108653a6822d28ef8e0f9c', '{"id":"bitsydarel/BDSkills/bd-skill-reviewing","name":"bd-skill-reviewing","description":{"en":"The bd-skill-reviewing skill provides a systematic framework for evaluating and improving agent skills, benefiting AI agent developers. It assesses skills against correctness, clarity, effectiveness, and maintainability.","zh":"bd-skill-reviewing提供了一套系统化的框架，用于评估和改进AI智能评估工具，涵盖正确性、清晰性、有效性和可维护性等四个维度","ja":"bd-skill-reviewingは、AIエージェントの評価と改善のためのシステム化されたフレームワークを提供し、正確性、明確性、有効性、保守性の4つの要素を網羅する","ko":"bd-skill-reviewing은 AI 에이전트의 평가 및 개선을 위한 체계적인 프레임워크를 제공하며, 정확성, 명확성, 효과성 및 유지 보수성의 4개 요소를 다룹니다","es":"El skill bd-skill-reviewing proporciona un marco sistemático para evaluar y mejorar las habilidades de los agentes de IA, considerando factores como corrección, claridad, eficacia y mantenibilidad.","fr":"Le skill bd-skill-reviewing fournit un cadre systématique pour évaluer et améliorer les compétences des agents de l''IA, en considérant des facteurs tels que la correction, la clarté, l''efficacité et la maintenabilité.","de":"Der Skill bd-skill-reviewing bietet einen systematischen Rahmen für die Bewertung und Verbesserung der Fähigkeiten von KI-Agents, unter Berücksichtigung von Faktoren wie Korrektheit, Klarheit, Effektivität und Wartbarkeit.","pt":"O bd-skill-reviewing fornece um framework sistemático para avaliar e melhorar as habilidades dos agentes de IA, considerando fatores como correção, clareza, eficácia e manutenção","ru":"Навык bd-skill-reviewing предоставляет систематический фреймворк для оценки и улучшения навыков ИИ Агентов, учитывая такие факторы, как правильность, ясность, эффективность и поддержка","ar":"يوفّر bd-skill-reviewing إطارًا منهجيًا لتقييم وتحسين مهارات أدوات الإي الأجنت، مع考虑 عوامل مثل الدقة والوضوح والفعالية والصيانة"},"seo":{"title":{"en":"bd-skill-reviewing: Review Guide for AI Agents | AI Agent...","zh":"bd-skill-reviewing 技术指南：AI智能评估工具","ja":"bd-skill-reviewing セットアップガイド：AIエージェントの評価","ko":"bd-skill-reviewing 가이드: AI 에이전트 평가 프레임워크","es":"Guía de configuración para bd-skill-reviewing: Mejora de ...","fr":"Guide de configuration pour bd-skill-reviewing : Améliora...","de":"Konfigurationsleitfaden für bd-skill-reviewing: Verbesser...","pt":"Guia de Configuração do bd-skill-reviewing para Ferrament...","ru":"Настройка навыков ИИ Агентов с помощью bd-skill-reviewing","ar":"دليل إعداد bd-skill-reviewing لأدوات الإي الأجنت"},"description":{"en":"Learn how to evaluate and improve agent skills with bd-skill-reviewing. Get started with our review workflow and criteria today!","zh":"了解bd-skill-reviewing的技术细节，包括评估标准和工作流程，优化您的AI智能评估工具","ja":"bd-skill-reviewingの評価基準とワークフローを学び、AIエージェントの評価を最適化する","ko":"bd-skill-reviewing의 기술 세부 사항을 확인하고 평가 기준 및 워크플로를 포함하여 AI 에이전트의 평가를 최적화하십시오","es":"Aprende a evaluar y mejorar las habilidades de los agentes de IA con bd-skill-reviewing. Descubre cómo seguir las mejores prácticas para un desarrollo eficaz.","fr":"Découvrez comment évaluer et améliorer les compétences des agents de l''IA avec bd-skill-reviewing. Suivez les meilleures pratiques pour un développement effi...","de":"Erfahren Sie, wie Sie die Fähigkeiten von KI-Agents mit bd-skill-reviewing bewerten und verbessern können. Entdecken Sie die besten Praktiken für eine effekt...","pt":"Aprenda a configurar e otimizar os agentes de IA com o bd-skill-reviewing, seguindo os critérios de correção, clareza, eficácia e manutenção","ru":"Узнайте, как настроить и оптимизировать ИИ Агентов с помощью bd-skill-reviewing, следуя критериям правильности, ясности, эффективности и поддержки","ar":"تعرف على كيفية إعداد وتحسين أدوات الإي الأجنت باستخدام bd-skill-reviewing، باتباع معايير الدقة والوضوح والفعالية والصيانة"},"definition":{"en":"bd-skill-reviewing is a skill that provides a systematic framework for evaluating and improving agent skills based on four dimensions: correctness, clarity, effectiveness, and maintainability.","zh":"bd-skill-reviewing是一种AI智能评估工具，用于评估和改进AI智能的质量和性能","ja":"bd-skill-reviewingは、AIエージェントの品質とパフォーマンスを評価し、改善するためのAI評価ツールです","ko":"bd-skill-reviewing은 AI 에이전트의 품질 및 성능을 평가하고 개선하기 위한 AI 평가 도구입니다","es":"El skill bd-skill-reviewing es una herramienta de evaluación y mejora de habilidades de agentes de IA que sigue cuatro dimensiones: corrección, claridad, eficacia y mantenibilidad.","fr":"Le skill bd-skill-reviewing est un outil d''évaluation et d''amélioration des compétences des agents de l''IA qui suit quatre dimensions : correction, clarté, efficacité et maintenabilité.","de":"Der Skill bd-skill-reviewing ist ein Werkzeug zur Bewertung und Verbesserung der Fähigkeiten von KI-Agents, das vier Dimensionen berücksichtigt: Korrektheit, Klarheit, Effektivität und Wartbarkeit.","pt":"O bd-skill-reviewing é um framework para avaliar e melhorar as habilidades dos agentes de IA, com base em critérios técnicos","ru":"Навык bd-skill-reviewing - это фреймворк для оценки и улучшения навыков ИИ Агентов, основанный на технических критериях","ar":"يُعرّف bd-skill-reviewing على أنه إطار لتقويم وتحسين مهارات أدوات الإي الأجنت، استنادًا إلى معايير تقنية"},"features":{"en":["Evaluates skills against four dimensions: correctness, clarity, effectiveness, and maintainability","Follows a review workflow with validate structure and evaluation steps","Assesses skills based on specification requirements and instructions","Guides well and triggers appropriately for effective skill improvement","Ensures well-organized and easy-to-update skill maintainability"],"zh":["评估标准：正确性、清晰性、有效性和可维护性","工作流程：验证结构、评估和改进","支持多维度评估","提供系统化的评估框架"],"ja":["評価基準：正確性、明確性、有効性、保守性","ワークフロー：構造の検証、評価、改善","多次元評価をサポート","システム化された評価フレームワークを提供"],"ko":["평가 기준: 정확성, 명확성, 효과성 및 유지 보수성","워크플로우: 구조 검증, 평가 및 개선","다차원 평가 지원","체계적인 평가 프레임워크 제공"],"es":["Evaluación de habilidades de agentes de IA en cuatro dimensiones: corrección, claridad, eficacia y mantenibilidad","Validación de estructura de directorios y archivos","Evalución de desencadenadores y guías de agentes de IA","Mejora de la organización y actualización de habilidades de agentes de IA","Seguimiento de las mejores prácticas para el desarrollo de habilidades de agentes de IA","Integración con herramientas de desarrollo de agentes de IA"],"fr":["Évaluation des compétences des agents de l''IA en quatre dimensions : correction, clarté, efficacité et maintenabilité","Validation de la structure de répertoires et de fichiers","Évaluation des déclencheurs et des guides des agents de l''IA","Amélioration de l''organisation et de la mise à jour des compétences des agents de l''IA","Suivi des meilleures pratiques pour le développement des compétences des agents de l''IA","Intégration avec les outils de développement des agents de l''IA"],"de":["Bewertung der Fähigkeiten von KI-Agents in vier Dimensionen: Korrektheit, Klarheit, Effektivität und Wartbarkeit","Validierung der Verzeichnis- und Dateistruktur","Bewertung von Auslösern und Anleitungen für KI-Agents","Verbesserung der Organisation und Aktualisierung von Fähigkeiten von KI-Agents","Einhalten der besten Praktiken für die Entwicklung von Fähigkeiten von KI-Agents","Integration mit Entwicklungstools für KI-Agents"],"pt":["Avaliação de habilidades com base em quatro dimensões: correção, clareza, eficácia e manutenção","Validação de estrutura de diretórios e arquivos","Avaliação de instruções claras e ações","Otimização de habilidades para melhor desempenho","Manutenção de habilidades com organização e atualizações fáceis"],"ru":["Оценка навыков на основе четырех измерений: правильности, ясности, эффективности и поддержки","Валидация структуры каталогов и файлов","Оценка ясных инструкций и действий","Оптимизация навыков для лучшей производительности","Поддержка навыков с организацией и легкими обновлениями"],"ar":["تقييم المهارات على أساس أربعة أبعاد: الدقة والوضوح والفعالية والصيانة","التحقق من هيكل الدلائل والملفات","تقييم الإرشادات الواضحة والإجراءات","تحسين المهارات لتحقيق الأداء الأمثل","صيانة المهارات بالتنظيم والتحديثات السهلة"]},"keywords":{"en":["how to use bd-skill-reviewing","bd-skill-reviewing review guide","bd-skill-reviewing alternative","bd-skill-reviewing vs other skills","bd-skill-reviewing setup guide","bd-skill-reviewing install","what is bd-skill-reviewing","bd-skill-reviewing for AI agents","improving agent skills with bd-skill-reviewing"],"zh":["AI智能评估","bd-skill-reviewing","评估标准","工作流程","AI工具","智能评估框架","AI技术"],"ja":["AIエージェント評価","bd-skill-reviewing","評価基準","ワークフロー","AIエージェント","評価フレームワーク","AI技術"],"ko":["AI 에이전트 평가","bd-skill-reviewing","평가 기준","워크플로우","AI 에이전트","평가 프레임워크","AI 기술"],"es":["bd-skill-reviewing","agentes de IA","evaluación de habilidades","mejora de habilidades","desarrollo de agentes de IA","herramientas de desarrollo de agentes de IA","evaluación de corrección","evaluación de claridad","evaluación de eficacia","evaluación de mantenibilidad"],"fr":["bd-skill-reviewing","agents de l''IA","évaluation des compétences","amélioration des compétences","développement des agents de l''IA","outils de développement des agents de l''IA","évaluation de la correction","évaluation de la clarté","évaluation de l''efficacité","évaluation de la maintenabilité"],"de":["bd-skill-reviewing","KI-Agents","Bewertung von Fähigkeiten","Verbesserung von Fähigkeiten","Entwicklung von KI-Agents","Entwicklungstools für KI-Agents","Bewertung der Korrektheit","Bewertung der Klarheit","Bewertung der Effektivität","Bewertung der Wartbarkeit"],"pt":["bd-skill-reviewing","ferramentas de IA","agentes de IA","avaliação de habilidades","otimização de habilidades","desenvolvimento de IA","tecnologias de IA","ferramentas de desenvolvimento de IA"],"ru":["bd-skill-reviewing","ИИ Агенты","инструменты ИИ","оценка навыков","оптимизация навыков","разработка ИИ","технологии ИИ","инструменты разработки ИИ"],"ar":["bd-skill-reviewing","أدوات الإي الأجنت","تقييم المهارات","تحسين المهارات","تطوير الإي","تكنولوجيا الإي","أدوات تطوير الإي","إي الأجنت"]}},"owner":"bitsydarel","repo":"BDSkills","repoPath":"bitsydarel/BDSkills","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.597Z","topics":[],"category":"community","skillMd":{"name":"bd-skill-reviewing","description":"Framework for reviewing and improving agent skills for quality, effectiveness, and compliance with the agent-skills standard. Use when auditing existing skills, providing feedback on skill PRs, improving skill descriptions, or troubleshooting underperforming skills.","bodyPreview":"# Skill Review Guide\n\nThis skill provides a systematic framework for evaluating and improving agent skills.\n\n## Review Criteria\n\nEvaluate skills against four dimensions:\n\n1. **Correctness**: Follows specification requirements\n2. **Clarity**: Instructions are unambiguous and actionable\n3. **Effectiveness**: Triggers appropriately and guides well\n4. **Maintainability**: Well-organized and easy to update\n\n## Review Workflow\n\n1. **Validate Structure**: Check directory and file organization\n2. **Eval","body":"# Skill Review Guide\n\nThis skill provides a systematic framework for evaluating and improving agent skills.\n\n## Review Criteria\n\nEvaluate skills against four dimensions:\n\n1. **Correctness**: Follows specification requirements\n2. **Clarity**: Instructions are unambiguous and actionable\n3. **Effectiveness**: Triggers appropriately and guides well\n4. **Maintainability**: Well-organized and easy to update\n\n## Review Workflow\n\n1. **Validate Structure**: Check directory and file organization\n2. **Evaluate Frontmatter**: Verify name and description compliance\n3. **Assess Content**: Review clarity, completeness, progressive disclosure\n4. **Check References**: Verify organization and linking\n5. **Test Effectiveness**: Confirm triggers and guidance work\n\nFor detailed checklist with specific checks per category, see [references/quality-checklist.md](references/quality-checklist.md).\n\n## Common Issues\n\nFor anti-patterns to identify during review (with detection methods and fixes), see [references/anti-patterns.md](references/anti-patterns.md).\n\n## Improvement Guidance\n\nFor patterns to fix common issues (with before/after examples), see [references/improvement-patterns.md](references/improvement-patterns.md).\n\n## Feedback Format\n\nFor review feedback templates and severity guidelines, see [references/feedback-template.md](references/feedback-template.md).\n\n## Anti-Patterns in Reviews\n\n- **Rubber-stamping**: Approving without thorough review\n- **Style-only focus**: Missing structural or effectiveness issues\n- **No actionable feedback**: Identifying problems without suggesting fixes\n- **Inconsistent severity**: Misclassifying critical issues as minor\n"},"lastSynced":"2026-03-07T12:58:38.739Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent Developers needing systematic skill evaluation and improvement frameworks","zh":"适合需要系统性技能评估和改进框架的AI代理开发人员","ja":"AIエージェント開発者が体系的にスキルを評価し改善するフレームワークを必要とする場合に最適","ko":"체계적인 기술 평가 및 개선 프레임워크가 필요한 AI 에이전트 개발자를 위한 최적의 선택","es":"Ideal para desarrolladores de agentes de IA que necesitan una evaluación y mejora sistemática de habilidades","fr":"Idéal pour les développeurs d''agents IA ayant besoin d''une évaluation et d''une amélioration systématiques des compétences","de":"Ideal für AI-Agent-Entwickler, die eine systematische Fähigkeitsbewertung und -verbesserung benötigen","pt":"Ideal para Desenvolvedores de Agentes de IA que precisam de uma avaliação e melhoria sistemáticas de habilidades","ru":"Идеально для разработчиков агентов ИИ, которым необходима систематическая оценка и улучшение навыков","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى تقييم وتحسين منهجي للهياكل المعرفية"},"recommendation":{"en":"Empowers agents to assess skills against correctness, clarity, effectiveness, and maintainability criteria, utilizing a structured review workflow that includes validating directory and file organization, evaluating trigger appropriateness, and ensuring maintainability through well-organized updates","zh":"赋予代理评估技能的正确性、清晰性、有效性和可维护性标准，利用结构化的审查工作流，包括验证目录和文件组织、评估触发器的适当性以及通过组织良好的更新来确保可维护性","ja":"エージェントに、ディレクトリとファイルの組織を検証し、トリガーの適切性を評価し、整理された更新を通じてメンテナンス性を確保する構造化されたレビュー・ワークフローを使用して、正確性、明確性、有効性、およびメンテナンス性の基準に対してスキルを評価する力を与えます","ko":"에이전트가 정확성, 명확성, 효과성 및 유지 보수 기준에 따라 기술을 평가할 수 있도록 하며, 디렉토리 및 파일 조직을 확인하고 트리거 적절성을 평가하며, 잘 구성된 업데이트를 통해 유지 보수를 보장하는 구조화된 검토 워크플로를 사용합니다.","es":"Habilita a los agentes a evaluar habilidades en función de criterios de corrección, claridad, eficacia y mantenibilidad, utilizando un flujo de trabajo de revisión estructurado que incluye la validación de la organización de directorios y archivos, la evaluación de la idoneidad de los desencadenantes y la garantía de mantenibilidad a través de actualizaciones bien organizadas","fr":"Permet aux agents d''évaluer les compétences en fonction de critères de correction, de clarté, d''efficacité et de maintenabilité, en utilisant un flux de travail de révision structuré qui inclut la validation de l''organisation des répertoires et des fichiers, l''évaluation de l''adéquation des déclencheurs et la garantie de la maintenabilité grâce à des mises à jour bien organisées","de":"Ermöglicht es Agenten, Fähigkeiten anhand von Korrektheits-, Klarheits-, Effektivitäts- und Wartbarkeitskriterien zu bewerten, indem sie einen strukturierten Überprüfungsworkflow verwenden, der die Überprüfung der Verzeichnis- und Dateiorganisation, die Bewertung der Auslöserangemessenheit und die Sicherstellung der Wartbarkeit durch gut organisierte Updates umfasst","pt":"Habilita os agentes a avaliar habilidades contra critérios de correção, clareza, eficácia e manutenção, utilizando um fluxo de trabalho de revisão estruturado que inclui validar a organização de diretórios e arquivos, avaliar a adequação dos gatilhos e garantir a manutenção por meio de atualizações bem organizadas","ru":"Наделяет агентов возможностью оценивать навыки по критериям правильности, ясности, эффективности и поддерживаемости, используя структурированный процесс рассмотрения, который включает проверку организации каталогов и файлов, оценку соответствия триггеров и обеспечение поддерживаемости за счет хорошо организованных обновлений","ar":"تمكين الوكلاء من تقييم المهارات ضد معايير الصحة والوضوح والفعالية والصيانة، باستخدام تدفق عمل مراجعة منظم يتضمن التحقق من تنظيم الدلائل والملفات وتقييم ملاءمة الزنادات وضمان الصيانة من خلال تحديثات منظمة جيدًا"},"useCases":{"en":["Evaluating agent skill correctness against specification requirements","Improving skill clarity through unambiguous and actionable instructions","Assessing skill effectiveness in triggering and guiding interactions"],"zh":["评估代理技能的正确性是否符合规格要求","通过明确且可操作的指令提高技能的清晰度","评估技能在触发和引导交互方面的有效性"],"ja":["エージェントのスキルが仕様の要件に合致しているかどうかを評価する","明確で実行可能な指示を通じてスキルの明確性を向上させる","スキルの有効性を、トリガーとインタラクションの誘導において評価する"],"ko":["에이전트 기술의 올바른 정도를 사양 요구 사항과 평가","명확하고 실행 가능한 지침을 통해 기술의 명확도를 향상","기술의 효율성을 트리거 및 상호 작용 가이드에 대해 평가"],"es":["Evaluación de la corrección de las habilidades del agente frente a los requisitos de especificación","Mejora de la claridad de las habilidades a través de instrucciones inequívocas y accionables","Evaluación de la eficacia de las habilidades para desencadenar y guiar interacciones"],"fr":["Évaluation de la correction des compétences de l''agent par rapport aux exigences de spécification","Amélioration de la clarté des compétences grâce à des instructions sans ambiguïté et actionnables","Évaluation de l''efficacité des compétences pour déclencher et guider les interactions"],"de":["Bewertung der Korrektheit der Agentenfähigkeiten im Vergleich zu den Spezifikationsanforderungen","Verbesserung der Klarheit der Fähigkeiten durch unmissverständliche und handhabbare Anweisungen","Bewertung der Effektivität der Fähigkeiten bei der Auslösung und Steuerung von Interaktionen"],"pt":["Avaliar a correção da habilidade do agente contra requisitos de especificação","Melhorar a clareza da habilidade por meio de instruções inequívocas e executáveis","Avaliar a eficácia da habilidade em disparar e guiar interações"],"ru":["Оценить правильность навыка агента по отношению к требованиям спецификации","Улучшить ясность навыка посредством недвусмысленных и выполнимых инструкций","Оценить эффективность навыка в триггеринге и направлении взаимодействий"],"ar":["تقييم صحة مهارة الوكيل مقابل متطلبات المواصفات","تحسين وضوح المهارة من خلال تعليمات واضحة وقابلة للتنفيذ","تقييم فعالية المهارة في تشغيل التفاعلات وتوجيهها"]},"limitations":{"en":["Requires access to skill specifications and documentation","Limited to evaluating skills against predefined criteria"],"zh":["需要访问技能规格和文档","仅限于评估技能是否符合预定义标准"],"ja":["スキル仕様とドキュメントへのアクセスが必要","スキルを事前定義された基準に対してのみ評価することができる"],"ko":["기술 사양 및 문서에 대한 액세스가 필요","기술을 사전 정의된 기준에만 평가"],"es":["Requiere acceso a las especificaciones y documentación de las habilidades","Limitado a la evaluación de habilidades frente a criterios predefinidos"],"fr":["Nécessite un accès aux spécifications et à la documentation des compétences","Limité à l''évaluation des compétences par rapport à des critères prédéfinis"],"de":["Erfordert den Zugriff auf Fähigkeitsspezifikationen und -dokumentation","Begrenzt auf die Bewertung von Fähigkeiten gegenüber vordefinierten Kriterien"],"pt":["Requer acesso a especificações e documentação de habilidades","Limitado à avaliação de habilidades contra critérios predefinidos"],"ru":["Требует доступа к спецификациям и документации навыков","Ограничен оценкой навыков по заранее определенным критериям"],"ar":["يتطلب الوصول إلى مواصفات ووثائق المهارات","محدود بتقييم المهارات ضد المعايير المحددة مسبقًا"]},"version":4},"contentHash":"d38f8071da82f4c0741848ca57ac76f1ad4e78b818108653a6822d28ef8e0f9c","qualityScore":32}');
