INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bitsydarel/BDSkills/bd-skill-reviewing', 'bd-skill-reviewing', 'bitsydarel', 'BDSkills', 'community', 'bd-skill-reviewing bitsydarel BDSkills community The bd-skill-reviewing skill provides a systematic framework for evaluating and improving agent skills, benefiting AI agent developers. It assesses skills against correctness, clarity, effectiveness, and maintainability. bd-skill-reviewing提供了一套系统化的框架，用于评估和改进AI智能评估工具，涵盖正确性、清晰性、有效性和可维护性等四个维度 bd-skill-reviewingは、AIエージェントの評価と改善のためのシステム化されたフレームワークを提供し、正確性、明確性、有効性、保守性の4つの要素を網羅する bd-skill-reviewing은 AI 에이전트의 평가 및 개선을 위한 체계적인 프레임워크를 제공하며, 정확성, 명확성, 효과성 및 유지 보수성의 4개 요소를 다룹니다 El skill bd-skill-reviewing proporciona un marco sistemático para evaluar y mejorar las habilidades de los agentes de IA, considerando factores como corrección, claridad, eficacia y mantenibilidad. Le skill bd-skill-reviewing fournit un cadre systématique pour évaluer et améliorer les compétences des agents de l''IA, en considérant des facteurs tels que la correction, la clarté, l''efficacité et la maintenabilité. Der Skill bd-skill-reviewing bietet einen systematischen Rahmen für die Bewertung und Verbesserung der Fähigkeiten von KI-Agents, unter Berücksichtigung von Faktoren wie Korrektheit, Klarheit, Effektivität und Wartbarkeit. O bd-skill-reviewing fornece um framework sistemático para avaliar e melhorar as habilidades dos agentes de IA, considerando fatores como correção, clareza, eficácia e manutenção Навык bd-skill-reviewing предоставляет систематический фреймворк для оценки и улучшения навыков ИИ Агентов, учитывая такие факторы, как правильность, ясность, эффективность и поддержка يوفّر bd-skill-reviewing إطارًا منهجيًا لتقييم وتحسين مهارات أدوات الإي الأجنت، مع考虑 عوامل مثل الدقة والوضوح والفعالية والصيانة how to use bd-skill-reviewing bd-skill-reviewing review guide bd-skill-reviewing alternative bd-skill-reviewing vs other skills bd-skill-reviewing setup guide bd-skill-reviewing install what is bd-skill-reviewing bd-skill-reviewing for AI agents improving agent skills with bd-skill-reviewing AI智能评估 bd-skill-reviewing 评估标准 工作流程 AI工具 智能评估框架 AI技术 Evaluates skills against four dimensions: correctness, clarity, effectiveness, and maintainability Follows a review workflow with validate structure and evaluation steps Assesses skills based on specification requirements and instructions Guides well and triggers appropriately for effective skill improvement Ensures well-organized and easy-to-update skill maintainability bd-skill-reviewing is a skill that provides a systematic framework for evaluating and improving agent skills based on four dimensions: correctness, clarity, effectiveness, and maintainability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aboustayyef/InfraRead/livewire-development', 'community', 'aboustayyef', 'InfraRead', 'aboustayyef/InfraRead', 'livewire-development', 52, 6, 31, '2026-02-17T11:16:52Z', '2026-03-06T06:35:31.910Z', '67f18b250f9b57e2e4b30f45f05f8ccb2f8e67a11e98b57bff9a01467dff54df', '{"id":"aboustayyef/InfraRead/livewire-development","name":"livewire-development","description":{"en":"Livewire development is a skill for creating self-hosted web feed readers and sync services using Laravel and VueJs. It benefits developers working with Livewire components.","zh":"Livewire 是一个基于 Laravel 和 VueJs 的自托管 Web Feed Reader 和 Sync Service","ja":"Livewire は、Laravel と VueJs を基盤とするセルフホステッド Web Feed Reader と Sync サービス","ko":"Livewire는 Laravel과 VueJs 기반의 셀프 호스팅 웹 피드 리더 및 동기화 서비스입니다","es":"Livewire Development es un conjunto de herramientas para crear componentes web reactivos con Laravel y VueJs","fr":"Livewire Development est un ensemble d''outils pour créer des composants web réactifs avec Laravel et VueJs","de":"Livewire Development ist eine Sammlung von Tools zur Erstellung reaktiver Webkomponenten mit Laravel und VueJs","pt":"O Livewire Development é uma ferramenta para criar componentes web interativos com Laravel e VueJs.","ru":"Livewire Development - это инструмент для создания интерактивных веб-компонентов с помощью Laravel и VueJs.","ar":"Livewire Development هو أداة لإنشاء مكونات ويب تفاعلية باستخدام Laravel و VueJs."},"seo":{"title":{"en":"Livewire Development: Laravel and VueJs Setup Guide | AI ...","zh":"Livewire 开发最佳实践","ja":"Livewire 開発ガイド","ko":"Livewire 개발 설정 가이드","es":"Guía de configuración de Livewire Development con Laravel...","fr":"Guide de mise en place de Livewire Development avec Larav...","de":"Einrichtungsleitfaden für Livewire Development mit Larave...","pt":"Guia de Configuração do Livewire Development com Laravel ...","ru":"ИИ Агенты: Руководство по Настройке Livewire Development ...","ar":"دليل إعداد Livewire Development مع Laravel و VueJs"},"description":{"en":"Unlock the full potential of Livewire development with our expert guide. Learn how to create, modify, and debug Livewire components with ease.","zh":"了解 Livewire 开发的技术细节，包括组件创建、调试和测试","ja":"Livewire 開発のテクニカルな詳細を学ぶ、コンポーネントの作成、デバッグ、テスト","ko":"Livewire 개발의 기술적인 세부 사항을 알아보세요. 컴포넌트 생성, 디버깅, 테스트 등","es":"Aprende a crear componentes Livewire con Laravel y VueJs, y a depurar problemas de reactividad y ciclo de vida","fr":"Découvrez comment créer des composants Livewire avec Laravel et VueJs, et déboguer les problèmes de réactivité et de cycle de vie","de":"Erfahren Sie, wie Sie Livewire-Komponenten mit Laravel und VueJs erstellen und Reaktivitäts- und Lebenszyklusprobleme debuggen","pt":"Aprenda a criar componentes Livewire com Laravel e VueJs, incluindo dicas de depuração e testes","ru":"Изучите, как создавать компоненты Livewire с помощью Laravel и VueJs, включая советы по отладке и тестированию","ar":"تعلم كيفية إنشاء مكونات Livewire باستخدام Laravel و VueJs، بما في ذلك نصائح حول تصحيح الأخطاء واختبارها"},"definition":{"en":"Livewire-development is a set of techniques for building reactive web applications using Laravel and VueJs, with features like component creation and debugging.","zh":"Livewire 是一个用于创建交互式 Web 应用的 Laravel 包","ja":"Livewire は、インタラクティブな Web アプリケーションを作成するための Laravel パッケージ","ko":"Livewire는 상호작용 웹 애플리케이션을 생성하기 위한 Laravel 패키지입니다","es":"Livewire Development es una técnica de desarrollo web que combina Laravel y VueJs para crear componentes reactivos","fr":"Livewire Development est une technique de développement web qui combine Laravel et VueJs pour créer des composants réactifs","de":"Livewire Development ist eine Webentwicklungstechnik, die Laravel und VueJs kombiniert, um reaktive Komponenten zu erstellen","pt":"O que é Livewire Development? É uma ferramenta para criar componentes web interativos com Laravel e VueJs.","ru":"Что такое Livewire Development? Это инструмент для создания интерактивных веб-компонентов с помощью Laravel и VueJs.","ar":"ما هو Livewire Development؟ هو أداة لإنشاء مكونات ويب تفاعلية باستخدام Laravel و VueJs."},"features":{"en":["Creates new Livewire components using `php artisan make:livewire` command","Modifies existing component state or behavior","Debugs reactivity or lifecycle issues","Writes Livewire component tests","Adds Alpine.js interactivity to components","Works with wire: directives"],"zh":["使用 Laravel 和 VueJs 构建","支持创建和修改 Livewire 组件","提供调试和测试功能","集成 Alpine.js 交互性","支持 wire: 指令"],"ja":["Laravel と VueJs を使用した構築","Livewire コンポーネントの作成と変更のサポート","デバッグとテスト機能の提供","Alpine.js のインタラクティブ性の統合","wire: ディレクティブのサポート"],"ko":["Laravel과 VueJs로 구축","Livewire 컴포넌트 생성 및 수정 지원","디버깅 및 테스트 기능 제공","Alpine.js 상호작용성 통합","wire: 지시자 지원"],"es":["Creación de componentes Livewire con Laravel","Depuración de problemas de reactividad y ciclo de vida","Uso de Alpine.js para agregar interactividad a los componentes","Trabajo con directivas wire:","Creación de componentes con php artisan make:livewire","Uso de Bulma para diseñar interfaces de usuario minimalistas"],"fr":["Création de composants Livewire avec Laravel","Débogage des problèmes de réactivité et de cycle de vie","Utilisation d''Alpine.js pour ajouter de l''interactivité aux composants","Travail avec les directives wire:","Création de composants avec php artisan make:livewire","Utilisation de Bulma pour concevoir des interfaces utilisateur minimalistes"],"de":["Erstellung von Livewire-Komponenten mit Laravel","Debuggen von Reaktivitäts- und Lebenszyklusproblemen","Verwendung von Alpine.js zur Hinzufügung von Interaktivität zu Komponenten","Arbeit mit wire:-Direktiven","Erstellung von Komponenten mit php artisan make:livewire","Verwendung von Bulma zur Gestaltung von minimalistiche Benutzeroberflächen"],"pt":["Criação de componentes Livewire com Laravel","Uso de VueJs para interfaces de usuário interativas","Depuração de reatividade e ciclo de vida dos componentes","Testes de componentes Livewire","Integração com Alpine.js para interatividade adicional","Uso de diretivas wire:"],"ru":["Создание компонентов Livewire с помощью Laravel","Использование VueJs для интерактивных пользовательских интерфейсов","Отладка реактивности и жизненного цикла компонентов","Тестирование компонентов Livewire","Интеграция с Alpine.js для дополнительной интерактивности","Использование директив wire:"],"ar":["إنشاء مكونات Livewire باستخدام Laravel","استخدام VueJs لواجهات المستخدم التفاعلية","تصحيح أخطاء التفاعل و دورة حياة المكونات","اختبار مكونات Livewire","التكامل مع Alpine.js لتحقيق تفاعلية إضافية","استخدام توجيهات wire:"]},"keywords":{"en":["how to use livewire-development","livewire-development setup guide","livewire-development alternative","livewire-development vs Laravel","livewire-development install","what is livewire-development","livewire-development tutorial","livewire-development best practices","livewire-development and VueJs"],"zh":["Livewire 开发","Laravel","VueJs","Web Feed Reader","Sync Service","AIエージェント","Livewire 组件","调试和测试"],"ja":["Livewire 開発","Laravel","VueJs","Web Feed Reader","Sync サービス","AIエージェント","Livewire コンポーネント","デバッグとテスト"],"ko":["Livewire 개발","Laravel","VueJs","웹 피드 리더","동기화 서비스","AI 에이전트","Livewire 컴포넌트","디버깅과 테스트"],"es":["Livewire Development","Laravel","VueJs","componentes reactivos","depuración de reactividad","Alpine.js","wire: directivas","php artisan make:livewire","Bulma","diseño de interfaces de usuario minimalistas"],"fr":["Livewire Development","Laravel","VueJs","composants réactifs","débogage de réactivité","Alpine.js","directives wire:","php artisan make:livewire","Bulma","conception d''interfaces utilisateur minimalistes"],"de":["Livewire Development","Laravel","VueJs","reaktive Komponenten","Debuggen von Reaktivität","Alpine.js","wire:-Direktiven","php artisan make:livewire","Bulma","Gestaltung von minimalistiche Benutzeroberflächen"],"pt":["livewire development","laravel","vuejs","componentes web interativos","depuração de reatividade","testes de componentes","alpine.js","diretivas wire:","desenvolvimento web"],"ru":["livewire development","laravel","vuejs","интерактивные веб-компоненты","отладка реактивности","тестирование компонентов","alpine.js","директивы wire:","веб-разработка"],"ar":["livewire development","laravel","vuejs","مكونات ويب تفاعلية","تصحيح أخطاء التفاعل","اختبار مكونات","alpine.js","توجيهات wire:","تطوير ويب"]}},"owner":"aboustayyef","repo":"InfraRead","repoPath":"aboustayyef/InfraRead","stars":52,"forks":6,"updatedAt":"2026-02-17T11:16:52Z","topics":["bulma","laravel","minimal","rss-reader","unread","vuejs","webapp"],"category":"community","skillMd":{"name":"livewire-development","description":">-","bodyPreview":"# Livewire Development\n\n## When to Apply\n\nActivate this skill when:\n- Creating new Livewire components\n- Modifying existing component state or behavior\n- Debugging reactivity or lifecycle issues\n- Writing Livewire component tests\n- Adding Alpine.js interactivity to components\n- Working with wire: directives\n\n## Documentation\n\nUse `search-docs` for detailed Livewire 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Components\n\nUse the `php artisan make:livewire [Posts\\CreatePost]` Artis","body":"# Livewire Development\n\n## When to Apply\n\nActivate this skill when:\n- Creating new Livewire components\n- Modifying existing component state or behavior\n- Debugging reactivity or lifecycle issues\n- Writing Livewire component tests\n- Adding Alpine.js interactivity to components\n- Working with wire: directives\n\n## Documentation\n\nUse `search-docs` for detailed Livewire 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Components\n\nUse the `php artisan make:livewire [Posts\\CreatePost]` Artisan command to create new components.\n\n### Fundamental Concepts\n\n- State should live on the server, with the UI reflecting it.\n- All Livewire requests hit the Laravel backend; they''re like regular HTTP requests. Always validate form data and run authorization checks in Livewire actions.\n\n## Livewire 3 Specifics\n\n### Key Changes From Livewire 2\n\nThese things changed in Livewire 3, but may not have been updated in this application. Verify this application''s setup to ensure you follow existing conventions.\n- Use `wire:model.live` for real-time updates, `wire:model` is now deferred by default.\n- Components now use the `App\\Livewire` namespace (not `App\\Http\\Livewire`).\n- Use `$this->dispatch()` to dispatch events (not `emit` or `dispatchBrowserEvent`).\n- Use the `components.layouts.app` view as the typical layout path (not `layouts.app`).\n\n### New Directives\n\n- `wire:show`, `wire:transition`, `wire:cloak`, `wire:offline`, `wire:target` are available for use.\n\n### Alpine Integration\n\n- Alpine is now included with Livewire; don''t manually include Alpine.js.\n- Plugins included with Alpine: persist, intersect, collapse, and focus.\n\n## Best Practices\n\n### Component Structure\n\n- Livewire components require a single root element.\n- Use `wire:loading` and `wire:dirty` for delightful loading states.\n\n### Using Keys in Loops\n\n<code-snippet name=\"Wire Key in Loops\" lang=\"blade\">\n\n@foreach ($items as $item)\n    <div wire:key=\"item-{{ $item->id }}\">\n        {{ $item->name }}\n    </div>\n@endforeach\n\n</code-snippet>\n\n### Lifecycle Hooks\n\nPrefer lifecycle hooks like `mount()`, `updatedFoo()` for initialization and reactive side effects:\n\n<code-snippet name=\"Lifecycle Hook Examples\" lang=\"php\">\n\npublic function mount(User $user) { $this->user = $user; }\npublic function updatedSearch() { $this->resetPage(); }\n\n</code-snippet>\n\n## JavaScript Hooks\n\nYou can listen for `livewire:init` to hook into Livewire initialization:\n\n<code-snippet name=\"Livewire Init Hook Example\" lang=\"js\">\n\ndocument.addEventListener(''livewire:init'', function () {\n    Livewire.hook(''request'', ({ fail }) => {\n        if (fail && fail.status === 419) {\n            alert(''Your session expired'');\n        }\n    });\n\n    Livewire.hook(''message.failed'', (message, component) => {\n        console.error(message);\n    });\n});\n\n</code-snippet>\n\n## Testing\n\n<code-snippet name=\"Example Livewire Component Test\" lang=\"php\">\n\nLivewire::test(Counter::class)\n    ->assertSet(''count'', 0)\n    ->call(''increment'')\n    ->assertSet(''count'', 1)\n    ->assertSee(1)\n    ->assertStatus(200);\n\n</code-snippet>\n\n<code-snippet name=\"Testing Livewire Component Exists on Page\" lang=\"php\">\n\n$this->get(''/posts/create'')\n    ->assertSeeLivewire(CreatePost::class);\n\n</code-snippet>\n\n## Common Pitfalls\n\n- Forgetting `wire:key` in loops causes unexpected behavior when items change\n- Using `wire:model` expecting real-time updates (use `wire:model.live` instead in v3)\n- Not validating/authorizing in Livewire actions (treat them like HTTP requests)\n- Including Alpine.js separately when it''s already bundled with Livewire 3"},"lastSynced":"2026-03-06T06:35:31.910Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing advanced Laravel and VueJs component development capabilities.","zh":"适合需要高级Laravel和VueJs组件开发能力的全栈代理。","ja":"LaravelとVueJsの高度なコンポーネント開発機能を必要とするフルスタックエージェントに最適です。","ko":"고급 Laravel 및 VueJs 컴포넌트 개발 기능이 필요한 풀스택 에이전트에게 적합합니다.","es":"Perfecto para agentes Full Stack que necesitan capacidades avanzadas de desarrollo de componentes Laravel y VueJs.","fr":"Parfait pour les agents Full Stack ayant besoin de capacités de développement avancées de composants Laravel et VueJs.","de":"Perfekt für Full-Stack-Agents, die erweiterte Laravel- und VueJs-Komponentenentwicklungsfähigkeiten benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de capacidades avançadas de desenvolvimento de componentes Laravel e VueJs.","ru":"Идеально подходит для агентов Full Stack, которым необходимы продвинутые возможности разработки компонентов Laravel и VueJs.","ar":"مثالي لوكلاء الويب الكامل الذين يحتاجون إلى قدرات متقدمة لتطوير مكونات Laravel و VueJs."},"recommendation":{"en":"Empowers agents to create self-hosted web feed readers and sync services using Livewire components, leveraging Laravel and VueJs for robust interactivity, and utilizing Alpine.js for dynamic component behavior, with features like wire: directives for seamless data synchronization.","zh":"赋予代理创建自托管网页feed读取器和同步服务的能力，利用Livewire组件，利用Laravel和VueJs实现强大的交互性，并利用Alpine.js实现动态组件行为，具有无缝数据同步的功能，如wire：指令。","ja":"エージェントがLivewireコンポーネントを使用してセルフホストされたWebフィードリーダーと同期サービスを作成できるようにし、LaravelとVueJsを使用して堅牢なインタラクティブ性を実現し、Alpine.jsを使用してダイナミックコンポーネントの動作を実現し、シームレスなデータ同期を可能にする機能を備えています。wire：ディレクティブなど。","ko":"에이전트가 Livewire 컴포넌트를 사용하여 자체 호스팅 웹 피드 리더 및 동기화 서비스를 생성할 수 있도록 하며, Laravel 및 VueJs를 사용하여 강력한 상호 작용을 제공하고, Alpine.js를 사용하여 동적 컴포넌트 동작을 제공하며, 무결점 데이터 동기화를 제공하는 기능을 제공합니다. 예를 들어 wire: 지시문","es":"Habilita a los agentes a crear lectores de fuentes web autohospedados y servicios de sincronización utilizando componentes Livewire, aprovechando Laravel y VueJs para una interactividad robusta, y utilizando Alpine.js para un comportamiento de componente dinámico, con características como directivas wire: para una sincronización de datos sin problemas.","fr":"Permet aux agents de créer des lecteurs de flux Web auto-hébergés et des services de synchronisation en utilisant des composants Livewire, en exploitant Laravel et VueJs pour une interactivité robuste, et en utilisant Alpine.js pour un comportement de composant dynamique, avec des fonctionnalités comme des directives wire: pour une synchronisation de données sans problème.","de":"Ermächtigt Agenten, selbstgehostete Web-Feed-Reader und Synchronisierungsdienste zu erstellen, indem Livewire-Komponenten verwendet werden, Laravel und VueJs für robuste Interaktivität nutzen und Alpine.js für dynamisches Komponentenverhalten verwenden, mit Funktionen wie wire:-Direktiven für eine nahtlose Datensynchronisation.","pt":"Habilita os agentes a criar leitores de feeds da web autossuficientes e serviços de sincronização usando componentes Livewire, aproveitando Laravel e VueJs para interatividade robusta, e utilizando Alpine.js para comportamento dinâmico de componentes, com recursos como diretivas wire: para sincronização de dados sem interrupções.","ru":"Наделяет агентов возможностью создавать самообслуживаемые веб-фид-ридеры и синхронизационные сервисы с использованием компонентов Livewire, используя Laravel и VueJs для надежной интерактивности, и используя Alpine.js для динамического поведения компонентов, с функциями, такими как директивы wire: для бесперебойной синхронизации данных.","ar":"تمكين الوكلاء من إنشاء قراء تلقائيين لمصادر الويب وخدمات التزامن باستخدام مكونات Livewire ، واستخدام Laravel و VueJs للتفاعل القوي ، واستخدام Alpine.js لسلوك المكونات الديناميكي ، مع ميزات مثل توجيهات wire: لتزامن البيانات دون انقطاع."},"useCases":{"en":["Creating new Livewire components with Laravel","Debugging reactivity or lifecycle issues in VueJs","Adding Alpine.js interactivity to existing components","Writing Livewire component tests for validation"],"zh":["使用Laravel创建新的Livewire组件","调试VueJs中的反应性或生命周期问题","将Alpine.js交互性添加到现有组件","编写Livewire组件测试以进行验证"],"ja":["Laravelを使用して新しいLivewireコンポーネントを作成する","VueJsの反応性またはライフサイクル問題をデバッグする","Alpine.jsのインタラクティブ性を既存のコンポーネントに追加する","バリデーションのためにLivewireコンポーネントテストを記述する"],"ko":["Laravel을 사용하여 새로운 Livewire 컴포넌트를 생성하는 것","VueJs의 반응성 또는 수명주기 문제를 디버깅하는 것","기존 컴포넌트에 Alpine.js 상호 작용을 추가하는 것","검증을 위해 Livewire 컴포넌트 테스트를 작성하는 것"],"es":["Creación de nuevos componentes Livewire con Laravel","Depuración de problemas de reactividad o ciclo de vida en VueJs","Agregar interactividad Alpine.js a componentes existentes","Escritura de pruebas de componentes Livewire para validación"],"fr":["Création de nouveaux composants Livewire avec Laravel","Débogage des problèmes de réactivité ou de cycle de vie dans VueJs","Ajout d''interactivité Alpine.js à des composants existants","Écriture de tests de composants Livewire pour validation"],"de":["Erstellung neuer Livewire-Komponenten mit Laravel","Fehlerbehebung bei Reaktivitäts- oder Lebenszyklusproblemen in VueJs","Hinzufügen von Alpine.js-Interaktivität zu bestehenden Komponenten","Schreiben von Livewire-Komponententests für Validierung"],"pt":["Criar novos componentes Livewire com Laravel","Depurar reatividade ou problemas de ciclo de vida em VueJs","Adicionar interatividade Alpine.js a componentes existentes","Escrever testes de componentes Livewire para validação"],"ru":["Создание новых компонентов Livewire с использованием Laravel","Отладка реактивности или проблем жизненного цикла в VueJs","Добавление интерактивности Alpine.js к существующим компонентам","Написание тестов для компонентов Livewire для валидации"],"ar":["إنشاء مكونات Livewire جديدة مع Laravel","تصحيح الأخطاء في التفاعل أو مشاكل الدورة الحياتية في VueJs","إضافة تفاعلية Alpine.js إلى المكونات الحالية","كتابة اختبارات للمكونات Livewire للتحقق"]},"limitations":{"en":["Requires Laravel and VueJs setup","Limited to Livewire 3 patterns and documentation","Needs PHP artisan for component creation"],"zh":["需要Laravel和VueJs设置","仅限Livewire 3模式和文档","需要PHP artisan进行组件创建"],"ja":["LaravelとVueJsの設定が必要","Livewire 3パターンとドキュメントのみ","コンポーネントの作成にはPHP artisanが必要"],"ko":["Laravel 및 VueJs 설정이 필요합니다.","Livewire 3 패턴 및 문서만 해당합니다.","컴포넌트 생성을 위해 PHP artisan이 필요합니다."],"es":["Requiere configuración de Laravel y VueJs","Limitado a patrones y documentación de Livewire 3","Necesita PHP artisan para la creación de componentes"],"fr":["Nécessite une configuration de Laravel et VueJs","Limité aux modèles et à la documentation de Livewire 3","Nécessite PHP artisan pour la création de composants"],"de":["Benötigt Laravel- und VueJs-Konfiguration","Begrenzt auf Livewire-3-Muster und -Dokumentation","Benötigt PHP-Artisan für die Erstellung von Komponenten"],"pt":["Requer configuração do Laravel e VueJs","Limitado a padrões e documentação do Livewire 3","Necessita do PHP artisan para criação de componentes"],"ru":["Требует настройки Laravel и VueJs","Ограничен шаблонами и документацией Livewire 3","Требует PHP artisan для создания компонентов"],"ar":["يتطلب إعداد Laravel و VueJs","محدود بنماذج ووثائق Livewire 3","يحتاج إلى PHP artisan لإنشاء المكونات"]},"version":4},"contentHash":"67f18b250f9b57e2e4b30f45f05f8ccb2f8e67a11e98b57bff9a01467dff54df","qualityScore":31}');
