INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aboustayyef/InfraRead/livewire-development', 'livewire-development', 'aboustayyef', 'InfraRead', 'community', 'livewire-development aboustayyef InfraRead community bulma laravel minimal rss-reader unread vuejs webapp Livewire development is a skill for creating self-hosted web feed readers and sync services using Laravel and VueJs. It benefits developers working with Livewire components. Livewire 是一个基于 Laravel 和 VueJs 的自托管 Web Feed Reader 和 Sync Service Livewire は、Laravel と VueJs を基盤とするセルフホステッド Web Feed Reader と Sync サービス Livewire는 Laravel과 VueJs 기반의 셀프 호스팅 웹 피드 리더 및 동기화 서비스입니다 Livewire Development es un conjunto de herramientas para crear componentes web reactivos con Laravel y VueJs Livewire Development est un ensemble d''outils pour créer des composants web réactifs avec Laravel et VueJs Livewire Development ist eine Sammlung von Tools zur Erstellung reaktiver Webkomponenten mit Laravel und VueJs O Livewire Development é uma ferramenta para criar componentes web interativos com Laravel e VueJs. Livewire Development - это инструмент для создания интерактивных веб-компонентов с помощью Laravel и VueJs. Livewire Development هو أداة لإنشاء مكونات ويب تفاعلية باستخدام Laravel و VueJs. how to use livewire-development livewire-development setup guide livewire-development alternative livewire-development vs Laravel livewire-development install what is livewire-development livewire-development tutorial livewire-development best practices livewire-development and VueJs Livewire 开发 Laravel VueJs Web Feed Reader Sync Service AIエージェント Livewire 组件 调试和测试 Creates new Livewire components using `php artisan make:livewire` command Modifies existing component state or behavior Debugs reactivity or lifecycle issues Writes Livewire component tests Adds Alpine.js interactivity to components Works with wire: directives Livewire-development is a set of techniques for building reactive web applications using Laravel and VueJs, with features like component creation and debugging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('libondev/pxd/vue-best-practices', 'community', 'libondev', 'pxd', 'libondev/pxd', 'vue-best-practices', 18, 3, 31, '2026-02-27T10:09:45Z', '2026-03-07T01:51:07.926Z', '924f1e06b330b5251e393fcf2c79955abb59475c1bb38ab7fcde764b68c7afa9', '{"id":"libondev/pxd/vue-best-practices","name":"vue-best-practices","description":{"en":"vue-best-practices is a universal UI component library for Vue2.7+ and Vue3.2+, providing a set of rules for efficient development. It benefits Vue developers by ensuring strict template standards.","zh":"Vue 最佳实践是一套适用于 Vue2.7+ 和 Vue3.2+ 的 UI 组件库，提供了 vue-tsc-strict-templates 规则","ja":"Vue ベストプラクティスは、Vue2.7+ と Vue3.2+ 用の UI コンポーネントライブラリで、vue-tsc-strict-templates ルールを提供します","ko":"Vue 베스트 프랙티스는 Vue2.7+ 및 Vue3.2+를 위한 UI 컴포넌트 라이브러리로서 vue-tsc-strict-templates 규칙을 제공합니다","es":"Vue Best Practices es una biblioteca de componentes UI universal para Vue2.7+ y Vue3.2+, que proporciona reglas de capacidad para una mejor implementación","fr":"Vue Best Practices est une bibliothèque de composants UI universelle pour Vue2.7+ et Vue3.2+, qui offre des règles de capacité pour une meilleure mise en œuvre","de":"Vue Best Practices ist eine universelle UI-Komponentenbibliothek für Vue2.7+ und Vue3.2+, die Fähigkeitsregeln für eine bessere Implementierung bereitstellt","pt":"O Vue Best Practices é uma biblioteca de componentes UI universais para Vue2.7+ e Vue3.2+, projetada para melhorar a eficiência do código","ru":"Vue Best Practices - это универсальная библиотека UI-компонентов для Vue2.7+ и Vue3.2+, предназначенная для повышения эффективности кода с помощью ИИ Агентов","ar":"أفضل الممارسات لفيو هي مكتبة مكونات واجهة المستخدم الشاملة لفيو 2.7+ و 3.2+، مصممة لتحسين كفاءة الكود"},"seo":{"title":{"en":"vue-best-practices: Universal UI Component Library Setup ...","zh":"Vue 最佳实践设置指南 - UI 组件库","ja":"Vue ベストプラクティス設定ガイド - UI コンポーネントライブラリ","ko":"Vue 베스트 프랙티스 설정 가이드 - UI 컴포넌트 라이브러리","es":"Guía de configuración de Vue Best Practices para bibliote...","fr":"Guide de configuration de Vue Best Practices pour les bib...","de":"Einrichtungsleitfaden für Vue Best Practices zur Erstellu...","pt":"Guia de Configuração do Vue Best Practices para Desenvolv...","ru":"Настройка Vue Best Practices: Руководство для Разработчик...","ar":"دليل إعداد أفضل الممارسات لفيو لمراقبة أداء الإيمان"},"description":{"en":"Unlock efficient Vue development with vue-best-practices. Discover how to implement strict template rules and optimize your UI components. Get started now!","zh":"了解 Vue 最佳实践的技术细节，包括 Vue2.7+ 和 Vue3.2+ 的 UI 组件库","ja":"Vue ベストプラクティスの技術的詳細を学び、Vue2.7+ と Vue3.2+ の UI コンポーネントライブラリを活用する","ko":"Vue 베스트 프랙티스의 기술적 세부 정보를 배우고 Vue2.7+ 및 Vue3.2+의 UI 컴포넌트 라이브러리를 활용하세요","es":"Aprende a implementar Vue Best Practices en tus proyectos de bibliotecas de componentes UI para Vue2.7+ y Vue3.2+","fr":"Découvrez comment mettre en œuvre les meilleures pratiques de Vue pour vos projets de bibliothèques de composants UI pour Vue2.7+ et Vue3.2+","de":"Erfahren Sie, wie Sie Vue Best Practices in Ihren Projekten für UI-Komponentenbibliotheken für Vue2.7+ und Vue3.2+ implementieren","pt":"Aprenda a configurar o Vue Best Practices, uma biblioteca de componentes UI universais para Vue2.7+ e Vue3.2+, e melhore a eficiência do seu código","ru":"Узнайте, как настроить Vue Best Practices, универсальную библиотеку UI-компонентов для Vue2.7+ и Vue3.2+, и повысьте эффективность вашего кода с помощью ИИ А...","ar":"تعرف على كيفية إعداد أفضل الممارسات لفيو، مكتبة مكونات واجهة المستخدم الشاملة لفيو 2.7+ و 3.2+، وتحسين كفاءة كودك"},"definition":{"en":"vue-best-practices is a UI component library for Vue, enforcing strict template rules and providing a standardized approach to component development.","zh":"Vue 最佳实践是指使用 Vue 进行 UI 组件开发的最佳实践和技术细节","ja":"Vue ベストプラクティスとは、Vue を使用した UI コンポーネント開発のベストプラクティスと技術的詳細です","ko":"Vue 베스트 프랙티스는 Vue를 사용한 UI 컴포넌트 개발의最佳实践 및 기술적 세부 사항입니다","es":"Vue Best Practices es una biblioteca de componentes UI que proporciona reglas y patrones para una mejor implementación en proyectos Vue","fr":"Vue Best Practices est une bibliothèque de composants UI qui offre des règles et des modèles pour une meilleure mise en œuvre dans les projets Vue","de":"Vue Best Practices ist eine UI-Komponentenbibliothek, die Regeln und Muster für eine bessere Implementierung in Vue-Projekten bereitstellt","pt":"O que é Vue Best Practices? É uma biblioteca de componentes UI universais para Vue","ru":"Что такое Vue Best Practices? Это универсальная библиотека UI-компонентов для Vue","ar":"ما هي أفضل الممارسات لفيو؟ هي مكتبة مكونات واجهة المستخدم الشاملة لفيو"},"features":{"en":["Enforces strict template rules using vue-tsc-strict-templates","Supports Vue2.7+ and Vue3.2+ for flexible development","Provides a universal UI component library for standardized development","Ensures undefined components are handled properly","Optimizes template rendering for improved performance"],"zh":["支持 Vue2.7+ 和 Vue3.2+","提供 vue-tsc-strict-templates 规则","UI 组件库","适用于大型应用开发","提高代码质量和可维护性"],"ja":["Vue2.7+ と Vue3.2+ をサポート","vue-tsc-strict-templates ルールを提供","UI コンポーネントライブラリ","大規模アプリケーション開発に適している","コード品質とメンテナンス性を向上させる"],"ko":["Vue2.7+ 및 Vue3.2+ 지원","vue-tsc-strict-templates 규칙 제공","UI 컴포넌트 라이브러리","대규모 애플리케이션 개발에 적합","코드 품질 및 유지 보수성을 향상"],"es":["Soporte para Vue2.7+ y Vue3.2+","Reglas de capacidad para una mejor implementación","Compatibilidad con bibliotecas de componentes UI","Implementación de componentes UI personalizados","Integración con herramientas de desarrollo de Vue"],"fr":["Prise en charge de Vue2.7+ et Vue3.2+","Règles de capacité pour une meilleure mise en œuvre","Compatibilité avec les bibliothèques de composants UI","Mise en œuvre de composants UI personnalisés","Intégration avec les outils de développement de Vue"],"de":["Unterstützung für Vue2.7+ und Vue3.2+","Fähigkeitsregeln für eine bessere Implementierung","Kompatibilität mit UI-Komponentenbibliotheken","Implementierung von benutzerdefinierten UI-Komponenten","Integration mit Vue-Entwicklungstools"],"pt":["Suporte a Vue2.7+ e Vue3.2+","Biblioteca de componentes UI universais","Regras de capacidade para melhorar a eficiência do código","Compatibilidade com vue-tsc-strict-templates","Melhoria da experiência do usuário com componentes personalizados"],"ru":["Поддержка Vue2.7+ и Vue3.2+","Универсальная библиотека UI-компонентов","Правила возможностей для повышения эффективности кода","Совместимость с vue-tsc-strict-templates","Улучшение пользовательского опыта с помощью настраиваемых компонентов и ИИ Агентов"],"ar":["دعم فيو 2.7+ و 3.2+","مكتبة مكونات واجهة المستخدم الشاملة","قواعد القدرات لتحسين كفاءة الكود","التوافق مع vue-tsc-strict-templates","تحسين تجربة المستخدم مع مكونات مخصصة"]},"keywords":{"en":["how to use vue-best-practices","vue-best-practices setup guide","vue-best-practices alternative","vue-best-practices vs Vuetify","vue-best-practices install","what is vue-best-practices","vue-best-practices documentation","vue-best-practices tutorial"],"zh":["Vue 最佳实践","Vue UI 组件库","Vue2.7+","Vue3.2+","vue-tsc-strict-templates","前端开发","UI 组件开发"],"ja":["Vue ベストプラクティス","Vue UI コンポーネントライブラリ","Vue2.7+","Vue3.2+","vue-tsc-strict-templates","フロントエンド開発","UI コンポーネント開発"],"ko":["Vue 베스트 프랙티스","Vue UI 컴포넌트 라이브러리","Vue2.7+","Vue3.2+","vue-tsc-strict-templates","프론트엔드 개발","UI 컴포넌트 개발"],"es":["vue best practices","bibliotecas de componentes ui","vue2.7+","vue3.2+","reglas de capacidad","desarrollo de vue","herramientas de desarrollo de vue","componentes ui personalizados"],"fr":["vue best practices","bibliothèques de composants ui","vue2.7+","vue3.2+","règles de capacité","développement de vue","outils de développement de vue","composants ui personnalisés"],"de":["vue best practices","ui-komponentenbibliotheken","vue2.7+","vue3.2+","fähigkeitsregeln","vue-entwicklung","vue-entwicklungstools","benutzerdefinierte ui-komponenten"],"pt":["vue best practices","biblioteca de componentes ui","vue2.7+","vue3.2+","desenvolvimento de software","eficiência do código","componentes personalizados"],"ru":["vue best practices","универсальная библиотека ui-компонентов","vue2.7+","vue3.2+","разработка программного обеспечения","эффективность кода","настраиваемые компоненты","ИИ Агенты"],"ar":["أفضل الممارسات لفيو","مكتبة مكونات واجهة المستخدم","فيو 2.7+","فيو 3.2+","تطوير البرمجيات","كفاءة الكود","مكونات مخصصة","أدوات الذكاء الاصطناعي"]}},"owner":"libondev","repo":"pxd","repoPath":"libondev/pxd","stars":18,"forks":3,"updatedAt":"2026-02-27T10:09:45Z","topics":["component-library","ui","vue","vue-components","vue2","vue3"],"category":"community","skillMd":{"name":"vue-best-practices","description":"Vue 3 TypeScript, vue-tsc, Volar, Vite, component props, testing, composition API.","version":"7.0.0","bodyPreview":"# Vue Best Practices\n\n## Capability Rules\n\n| Rule                                                                      | Keywords                                             | Description                             |\n| ------------------------------------------------------------------------- | ---------------------------------------------------- | --------------------------------------- |\n| [vue-tsc-strict-templates](rules/vue-tsc-strict-templates.md)             | undefined component, template","body":"# Vue Best Practices\n\n## Capability Rules\n\n| Rule                                                                      | Keywords                                             | Description                             |\n| ------------------------------------------------------------------------- | ---------------------------------------------------- | --------------------------------------- |\n| [vue-tsc-strict-templates](rules/vue-tsc-strict-templates.md)             | undefined component, template error, strictTemplates | Catch undefined components in templates |\n| [fallthrough-attributes](rules/fallthrough-attributes.md)                 | fallthrough, $attrs, wrapper component               | Type-check fallthrough attributes       |\n| [strict-css-modules](rules/strict-css-modules.md)                         | css modules, $style, typo                            | Catch CSS module class typos            |\n| [data-attributes-config](rules/data-attributes-config.md)                 | data-\\*, strictTemplates, attribute                  | Allow data-\\* attributes                |\n| [volar-3-breaking-changes](rules/volar-3-breaking-changes.md)             | volar, vue-language-server, editor                   | Fix Volar 3.0 upgrade issues            |\n| [module-resolution-bundler](rules/module-resolution-bundler.md)           | cannot find module, @vue/tsconfig, moduleResolution  | Fix module resolution errors            |\n| [unplugin-auto-import-conflicts](rules/unplugin-auto-import-conflicts.md) | unplugin, auto-import, types any                     | Fix unplugin type conflicts             |\n| [codeactions-save-performance](rules/codeactions-save-performance.md)     | slow save, vscode, performance                       | Fix slow save in large projects         |\n| [duplicate-plugin-detection](rules/duplicate-plugin-detection.md)         | duplicate plugin, vite, vue plugin                   | Detect duplicate plugins                |\n| [define-model-update-event](rules/define-model-update-event.md)           | defineModel, update event, undefined                 | Fix model update errors                 |\n| [with-defaults-union-types](rules/with-defaults-union-types.md)           | withDefaults, union type, default                    | Fix union type defaults                 |\n| [deep-watch-numeric](rules/deep-watch-numeric.md)                         | watch, deep, array, Vue 3.5                          | Efficient array watching                |\n| [vue-directive-comments](rules/vue-directive-comments.md)                 | @vue-ignore, @vue-skip, template                     | Control template type checking          |\n| [script-setup-jsdoc](rules/script-setup-jsdoc.md)                         | jsdoc, script setup, documentation                   | Add JSDoc to script setup               |\n| [vue-router-typed-params](rules/vue-router-typed-params.md)               | route params, typed router, unplugin                 | Fix route params typing                 |\n\n## Efficiency Rules\n\n| Rule                                                | Keywords                   | Description         |\n| --------------------------------------------------- | -------------------------- | ------------------- |\n| [hmr-vue-ssr](rules/hmr-vue-ssr.md)                 | hmr, ssr, hot reload       | Fix HMR in SSR apps |\n| [pinia-store-mocking](rules/pinia-store-mocking.md) | pinia, mock, vitest, store | Mock Pinia stores   |\n\n## Reference\n\n- [Vue Language Tools](https://github.com/vuejs/language-tools)\n- [Vue 3 Documentation](https://vuejs.org/)\n"},"lastSynced":"2026-03-07T01:51:07.926Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient Vue development with strict template standards.","zh":"非常适合需要高效Vue开发和严格模板标准的前端代理。","ja":"Vue開発で効率的な開発と厳格なテンプレート規格が必要なフロントエンドエージェントに最適です。","ko":"효율적인 Vue 개발과 엄격한 템플릿 표준이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan un desarrollo eficiente de Vue con estándares de plantilla estrictos.","fr":"Parfait pour les agents Frontend qui ont besoin d''un développement de Vue efficace avec des normes de modèle strictes.","de":"Perfekt für Frontend-Agents, die eine effiziente Vue-Entwicklung mit strengen Vorlagenstandards benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desenvolvimento Vue eficiente com padrões de modelo estritos.","ru":"Идеально для агентов Frontend, которым необходим эффективный разработка Vue с жесткими стандартами шаблонов.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى تطوير Vue فعال مع معايير قوالب صارمة."},"recommendation":{"en":"Empowers agents to enforce strict template rules for Vue2.7+ and Vue3.2+ using vue-tsc-strict-templates, ensuring efficient development with standardized UI components.","zh":"赋予代理人员使用vue-tsc-strict-templates强制执行Vue2.7+和Vue3.2+的严格模板规则的能力，确保使用标准化的UI组件进行高效的开发。","ja":"vue-tsc-strict-templatesを使用してVue2.7+およびVue3.2+の厳格なテンプレート規則を適用し、標準化されたUIコンポーネントを使用した効率的な開発を可能にします。","ko":"vue-tsc-strict-templates를 사용하여 Vue2.7+ 및 Vue3.2+에 대한 엄격한 템플릿 규칙을 적용하여 표준화된 UI 컴포넌트를 사용한 효율적인 개발을 가능하게 합니다.","es":"Habilita a los agentes a aplicar reglas de plantilla estrictas para Vue2.7+ y Vue3.2+ utilizando vue-tsc-strict-templates, garantizando un desarrollo eficiente con componentes de interfaz de usuario estandarizados.","fr":"Permet aux agents d''appliquer des règles de modèle strictes pour Vue2.7+ et Vue3.2+ en utilisant vue-tsc-strict-templates, garantissant un développement efficace avec des composants d''interface utilisateur standardisés.","de":"Ermächtigt die Agents, strenge Vorlagenregeln für Vue2.7+ und Vue3.2+ mithilfe von vue-tsc-strict-templates durchzusetzen, um so eine effiziente Entwicklung mit standardisierten Benutzeroberflächenkomponenten sicherzustellen.","pt":"Permite que os agentes apliquem regras de modelo estritas para Vue2.7+ e Vue3.2+ usando vue-tsc-strict-templates, garantindo desenvolvimento eficiente com componentes de UI padronizados.","ru":"Позволяет агентам обеспечить соблюдение жестких правил шаблонов для Vue2.7+ и Vue3.2+ с помощью vue-tsc-strict-templates, обеспечивая эффективное развитие с стандартизированными компонентами UI.","ar":"تمكن الوكلاء من فرض قواعد قوالب صارمة ل Vue2.7+ و Vue3.2+ باستخدام vue-tsc-strict-templates، مما يضمن التطوير الفعال مع مكونات واجهة المستخدم المعيارية."},"useCases":{"en":["Enforcing template standards for Vue components","Validating undefined components in Vue templates","Optimizing Vue development workflow with best practices"],"zh":["强制执行Vue组件的模板标准","验证Vue模板中的未定义组件","使用最佳实践优化Vue开发工作流"],"ja":["Vueコンポーネントのテンプレート規格の適用","Vueテンプレート内の未定義コンポーネントの検証","ベストプラクティスを使用したVue開発ワークフローの最適化"],"ko":["Vue 컴포넌트의 템플릿 표준 적용","Vue 템플릿 내의 정의되지 않은 컴포넌트의 검증","베스트 프랙티스를 사용한 Vue 개발 워크플로우 최적화"],"es":["Aplicar estándares de plantilla para componentes de Vue","Validar componentes no definidos en plantillas de Vue","Optimizar el flujo de trabajo de desarrollo de Vue con las mejores prácticas"],"fr":["Mettre en œuvre des normes de modèle pour les composants Vue","Valider les composants non définis dans les modèles Vue","Optimiser le flux de travail de développement de Vue avec les meilleures pratiques"],"de":["Vorlagenstandards für Vue-Komponenten durchsetzen","Nicht definierte Komponenten in Vue-Vorlagen validieren","Vue-Entwicklungsworkflow mit Best Practices optimieren"],"pt":["Aplicar padrões de modelo para componentes Vue","Validar componentes não definidos em modelos Vue","Otimizar o fluxo de trabalho de desenvolvimento Vue com as melhores práticas"],"ru":["Применение стандартов шаблонов для компонентов Vue","Проверка неопределенных компонентов в шаблонах Vue","Оптимизация рабочего процесса разработки Vue с использованием最佳 практик"],"ar":["تطبيق معايير قوالب على مكونات Vue","تحقق من المكونات غير المعرفة في قوالب Vue","تحسين تدفق عمل تطوير Vue مع أفضل الممارسات"]},"limitations":{"en":["Requires Vue2.7+ or Vue3.2+","Limited to Vue ecosystem"],"zh":["需要Vue2.7+或Vue3.2+","仅限Vue生态系统"],"ja":["Vue2.7+またはVue3.2+が必要","Vueエコシステムのみ"],"ko":["Vue2.7+ 또는 Vue3.2+가 필요","Vue 생태계만"],"es":["Requiere Vue2.7+ o Vue3.2+","Limitado al ecosistema de Vue"],"fr":["Nécessite Vue2.7+ ou Vue3.2+","Limité à l''écosystème Vue"],"de":["Benötigt Vue2.7+ oder Vue3.2+","Begrenzt auf das Vue-Ökosystem"],"pt":["Requer Vue2.7+ ou Vue3.2+","Limitado ao ecossistema Vue"],"ru":["Требуется Vue2.7+ или Vue3.2+","Ограничен экосистемой Vue"],"ar":["يتطلب Vue2.7+ أو Vue3.2+","محدود إلى نظام Vue البيئي"]},"version":4},"contentHash":"924f1e06b330b5251e393fcf2c79955abb59475c1bb38ab7fcde764b68c7afa9","qualityScore":31}');
