INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('libondev/pxd/vue-best-practices', 'vue-best-practices', 'libondev', 'pxd', 'community', 'vue-best-practices libondev pxd community component-library ui vue vue-components vue2 vue3 vue-best-practices is a universal UI component library for Vue2.7+ and Vue3.2+, providing a set of rules for efficient development. It benefits Vue developers by ensuring strict template standards. Vue 最佳实践是一套适用于 Vue2.7+ 和 Vue3.2+ 的 UI 组件库，提供了 vue-tsc-strict-templates 规则 Vue ベストプラクティスは、Vue2.7+ と Vue3.2+ 用の UI コンポーネントライブラリで、vue-tsc-strict-templates ルールを提供します Vue 베스트 프랙티스는 Vue2.7+ 및 Vue3.2+를 위한 UI 컴포넌트 라이브러리로서 vue-tsc-strict-templates 규칙을 제공합니다 Vue Best Practices es una biblioteca de componentes UI universal para Vue2.7+ y Vue3.2+, que proporciona reglas de capacidad para una mejor implementación Vue Best Practices est une bibliothèque de composants UI universelle pour Vue2.7+ et Vue3.2+, qui offre des règles de capacité pour une meilleure mise en œuvre Vue Best Practices ist eine universelle UI-Komponentenbibliothek für Vue2.7+ und Vue3.2+, die Fähigkeitsregeln für eine bessere Implementierung bereitstellt O Vue Best Practices é uma biblioteca de componentes UI universais para Vue2.7+ e Vue3.2+, projetada para melhorar a eficiência do código Vue Best Practices - это универсальная библиотека UI-компонентов для Vue2.7+ и Vue3.2+, предназначенная для повышения эффективности кода с помощью ИИ Агентов أفضل الممارسات لفيو هي مكتبة مكونات واجهة المستخدم الشاملة لفيو 2.7+ و 3.2+، مصممة لتحسين كفاءة الكود how to use vue-best-practices vue-best-practices setup guide vue-best-practices alternative vue-best-practices vs Vuetify vue-best-practices install what is vue-best-practices vue-best-practices documentation vue-best-practices tutorial Vue 最佳实践 Vue UI 组件库 Vue2.7+ Vue3.2+ vue-tsc-strict-templates 前端开发 UI 组件开发 Enforces strict template rules using vue-tsc-strict-templates Supports Vue2.7+ and Vue3.2+ for flexible development Provides a universal UI component library for standardized development Ensures undefined components are handled properly Optimizes template rendering for improved performance vue-best-practices is a UI component library for Vue, enforcing strict template rules and providing a standardized approach to component development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DanielShuguang/tool-box/vitest', 'community', 'DanielShuguang', 'tool-box', 'DanielShuguang/tool-box', 'vitest', 0, 0, 31, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:22.217Z', '87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07', '{"id":"DanielShuguang/tool-box/vitest","name":"vitest","description":{"en":"Vitest is a testing framework powered by Vite, providing a Jest-compatible API with native ESM, TypeScript, and JSX support. It benefits developers seeking fast and efficient testing solutions.","zh":"Vitest 是一个小工具箱，提供 Jest 兼容的 API 和原生 ESM、TypeScript 和 JSX 支持。它使用 Vite 的转换管道实现快速的 HMR-like 测试更新","ja":"Vitest は小さなツールボックスで、Jest 互換の API とネイティブの ESM、TypeScript、JSX をサポート。Vite の変換パイプラインを使用して高速な HMR のようなテスト更新を実現","ko":"Vitest는 작은 도구 상자로 Jest와 호환되는 API 및 네이티브 ESM, TypeScript, JSX를 지원합니다. Vite의 변환 파이프라인을 사용하여 빠른 HMR와 같은 테스트 업데이트를 구현합니다","es":"Vitest es un framework de pruebas de próxima generación que ofrece una API compatible con Jest y soporte nativo para ESM, TypeScript y JSX. Está diseñado para funcionar con Vite y ofrece una serie de características avanzadas para mejorar la eficiencia de las pruebas.","fr":"Vitest est un framework de test de nouvelle génération qui offre une API compatible avec Jest et un support natif pour ESM, TypeScript et JSX. Il est conçu pour fonctionner avec Vite et propose une série de fonctionnalités avancées pour améliorer l''efficacité des tests.","de":"Vitest ist ein Framework für Tests der nächsten Generation, das eine API kompatibel mit Jest und nativen Support für ESM, TypeScript und JSX bietet. Es ist für die Verwendung mit Vite konzipiert und bietet eine Reihe von erweiterten Funktionen, um die Effizienz der Tests zu verbessern.","pt":"O Vitest é um framework de teste de próxima geração, construído sobre o Vite, que oferece suporte nativo a ESM, TypeScript e JSX. Ele fornece uma API compatível com o Jest e recursos como atualizações de teste rápidas e inteligentes","ru":"Vitest - это фреймворк для тестирования следующего поколения, построенный на основе Vite, который обеспечивает родную поддержку ESM, TypeScript и JSX. Он предлагает API, совместимый с Jest, и функции, такие как быстрые и умные обновления тестов","ar":"Vitest هو إطار اختبار من الجيل التالي، مبني على Vite، الذي يقدم دعمًا أصليًا ل ESM و TypeScript و JSX. يقدم واجهة برمجة تطبيقات متوافقة مع Jest وميزات مثل تحديثات الاختبار السريعة والذكية"},"seo":{"title":{"en":"Vitest: Next-Gen Testing Framework Setup Guide | AI Agent...","zh":"Vitest_SETUP GUIDE：下一代测试框架","ja":"Vitest_BEST PRACTICES：次世代テストフレームワーク","ko":"Vitest_가이드：次世代 테스트 프레임워크","es":"Guía de configuración de Vitest para desarrolladores","fr":"Guide de mise en place de Vitest pour les développeurs","de":"Vitest-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Vitest: Melhores Práticas para De...","ru":"ИИ Агент Vitest: Руководство по Настройке и Лучшим Практикам","ar":"دليل إعداد Vitest: أفضل الممارسات للاختبارات السريعة"},"description":{"en":"Unlock fast and efficient testing with Vitest. Learn how to setup and leverage its Jest-compatible API and native ESM support. Get started now!","zh":"Vitest 是一个由 Vite 提供支持的下一代 AIエージェント 测试框架，提供 Jest 兼容的 API 和原生 ESM、TypeScript 和 JSX 支持","ja":"Vitest は Vite によって提供される次世代の AIエージェント テストフレームワークで、Jest 互換の API とネイティブの ESM、TypeScript、JSX をサポート","ko":"Vitest는 Vite에 의해 제공되는 차세대 AI Tools 테스트 프레임워크로 Jest와 호환되는 API 및 네이티브 ESM, TypeScript, JSX를 지원합니다","es":"Descubre cómo Vitest, un framework de pruebas de próxima generación, puede mejorar la eficiencia de tus pruebas con su API compatible con Jest y soporte nati...","fr":"Découvrez comment Vitest, un framework de test de nouvelle génération, peut améliorer l''efficacité de vos tests avec son API compatible avec Jest et son supp...","de":"Erfahren Sie, wie Vitest, ein Framework für Tests der nächsten Generation, die Effizienz Ihrer Tests mit seiner Jest-kompatiblen API und nativem Support für ...","pt":"Aprenda a configurar o Vitest, um framework de teste de próxima geração, e descubra como melhorar a eficiência dos seus testes com recursos como ESM, TypeScr...","ru":"Узнайте, как настроить Vitest, современный фреймворк для тестирования, и откройте для себя возможности быстрого тестирования с поддержкой ESM, TypeScript и JSX","ar":"تعرف على كيفية إعداد Vitest، إطار الاختبار من الجيل التالي، واكتشف كيف تحسن كفاءة الاختبارات الخاصة بك باستخدام ميزات مثل ESM و TypeScript و JSX"},"definition":{"en":"Vitest is a next-generation testing framework powered by Vite, offering native ESM, TypeScript, and JSX support out of the box.","zh":"Vitest 是一个由 Vite 提供支持的下一代测试框架","ja":"Vitest は Vite によって提供される次世代のテストフレームワーク","ko":"Vitest는 Vite에 의해 제공되는 차세대 테스트 프레임워크","es":"Vitest es un framework de pruebas de código abierto que utiliza la tubería de transformación de Vite para ofrecer actualizaciones de pruebas rápidas y eficientes","fr":"Vitest est un framework de test open source qui utilise la pipeline de transformation de Vite pour offrir des mises à jour de tests rapides et efficaces","de":"Vitest ist ein Open-Source-Testframework, das die Transformationspipeline von Vite verwendet, um schnelle und effiziente Testaktualisierungen zu bieten","pt":"O Vitest é um framework de teste de código aberto que fornece suporte nativo a ESM, TypeScript e JSX, permitindo testes rápidos e eficientes","ru":"Vitest - это открытый фреймворк для тестирования, который обеспечивает родную поддержку ESM, TypeScript и JSX, позволяя выполнять быстрые и эффективные тесты","ar":"Vitest هو إطار اختبار مفتوح المصدر يقدم دعمًا أصليًا ل ESM و TypeScript و JSX، مما يسمح بإجراء اختبارات سريعة وفعالة"},"features":{"en":["Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates","Jest-compatible: Drop-in replacement for most Jest test suites","Smart watch mode: Only reruns affected tests based on module graph","Native ESM support: Enables fast and efficient testing with ES modules","TypeScript support: Allows for seamless testing with TypeScript projects","JSX support: Enables testing of JSX components out of the box"],"zh":["Vite 原生支持","Jest 兼容的 API","智能监控模式","原生 ESM、TypeScript 和 JSX 支持"],"ja":["Vite ネイティブサポート","Jest 互換の API","スマートウォッチモード","ネイティブの ESM、TypeScript、JSX サポート"],"ko":["Vite 네이티브 지원","Jest와 호환되는 API","스마트 감시 모드","네이티브 ESM, TypeScript, JSX 지원"],"es":["Compatibilidad con Jest","Soporte nativo para ESM","Soporte nativo para TypeScript","Soporte nativo para JSX","Actualizaciones de pruebas rápidas con Vite","Modo de vigilancia inteligente para rerun de pruebas afectadas"],"fr":["Compatibilité avec Jest","Support natif pour ESM","Support natif pour TypeScript","Support natif pour JSX","Mises à jour de tests rapides avec Vite","Mode de surveillance intelligente pour rerun de tests affectés"],"de":["Kompatibilität mit Jest","Nativer Support für ESM","Nativer Support für TypeScript","Nativer Support für JSX","Schnelle Testaktualisierungen mit Vite","Intelligenter Überwachungsmodus für Neuausführung betroffener Tests"],"pt":["Suporte nativo a ESM, TypeScript e JSX","API compatível com o Jest","Atualizações de teste rápidas e inteligentes","Integração com o pipeline de transformação do Vite","Suporte a plugins e resolvers do Vite"],"ru":["Родная поддержка ESM, TypeScript и JSX","API, совместимый с Jest","Быстрые и умные обновления тестов","Интеграция с pipeline трансформации Vite","Поддержка плагинов и ресолверов Vite"],"ar":["دعم أصلي ل ESM و TypeScript و JSX","واجهة برمجة تطبيقات متوافقة مع Jest","تحديثات اختبار سريعة وذكية","التكامل مع خط أنابيب تحويل Vite","دعم المكونات الإضافية والمنحلات من Vite"]},"keywords":{"en":["how to use vitest","vitest setup guide","vitest vs jest","vitest install","what is vitest","vitest alternative","vitest testing framework","vitest and vite","vitest for developers","vitest tutorial"],"zh":["Vitest","Vite","Jest","ESM","TypeScript","JSX","AIエージェント","测试框架","下一代测试框架"],"ja":["Vitest","Vite","Jest","ESM","TypeScript","JSX","AIエージェント","テストフレームワーク","次世代テストフレームワーク"],"ko":["Vitest","Vite","Jest","ESM","TypeScript","JSX","AI Tools","테스트 프레임워크","차세대 테스트 프레임워크"],"es":["Vitest","framework de pruebas","Jest","ESM","TypeScript","JSX","Vite","pruebas de código","desarrollo de software","herramientas de desarrollo"],"fr":["Vitest","framework de test","Jest","ESM","TypeScript","JSX","Vite","tests de code","développement de logiciels","outils de développement"],"de":["Vitest","Testframework","Jest","ESM","TypeScript","JSX","Vite","Code-Tests","Software-Entwicklung","Entwicklungstools"],"pt":["vitest","framework de teste","ESM","TypeScript","JSX","Jest","Vite","testes rápidos","desenvolvimento de software"],"ru":["vitest","фреймворк для тестирования","ESM","TypeScript","JSX","Jest","Vite","быстрые тесты","разработка программного обеспечения"],"ar":["vitest","إطار اختبار","ESM","TypeScript","JSX","Jest","Vite","اختبارات سريعة","تطوير البرمجيات"]}},"owner":"DanielShuguang","repo":"tool-box","repoPath":"DanielShuguang/tool-box","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"vitest","description":"Vitest fast unit testing framework powered by Vite with Jest-compatible API. Use when writing tests, mocking, configuring coverage, or working with test filtering and fixtures.","version":"2026.1.28","bodyPreview":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeS","body":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeScript, JSX support without configuration\n- Multi-threaded workers for parallel test execution\n- Built-in coverage via V8 or Istanbul\n- Snapshot testing, mocking, and spy utilities\n\n> The skill is based on Vitest 3.x, generated at 2026-01-28.\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | Vitest and Vite config integration, defineConfig usage | [core-config](references/core-config.md) |\n| CLI | Command line interface, commands and options | [core-cli](references/core-cli.md) |\n| Test API | test/it function, modifiers like skip, only, concurrent | [core-test-api](references/core-test-api.md) |\n| Describe API | describe/suite for grouping tests and nested suites | [core-describe](references/core-describe.md) |\n| Expect API | Assertions with toBe, toEqual, matchers and asymmetric matchers | [core-expect](references/core-expect.md) |\n| Hooks | beforeEach, afterEach, beforeAll, afterAll, aroundEach | [core-hooks](references/core-hooks.md) |\n\n## Features\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Mocking | Mock functions, modules, timers, dates with vi utilities | [features-mocking](references/features-mocking.md) |\n| Snapshots | Snapshot testing with toMatchSnapshot and inline snapshots | [features-snapshots](references/features-snapshots.md) |\n| Coverage | Code coverage with V8 or Istanbul providers | [features-coverage](references/features-coverage.md) |\n| Test Context | Test fixtures, context.expect, test.extend for custom fixtures | [features-context](references/features-context.md) |\n| Concurrency | Concurrent tests, parallel execution, sharding | [features-concurrency](references/features-concurrency.md) |\n| Filtering | Filter tests by name, file patterns, tags | [features-filtering](references/features-filtering.md) |\n\n## Advanced\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Vi Utilities | vi helper: mock, spyOn, fake timers, hoisted, waitFor | [advanced-vi](references/advanced-vi.md) |\n| Environments | Test environments: node, jsdom, happy-dom, custom | [advanced-environments](references/advanced-environments.md) |\n| Type Testing | Type-level testing with expectTypeOf and assertType | [advanced-type-testing](references/advanced-type-testing.md) |\n| Projects | Multi-project workspaces, different configs per project | [advanced-projects](references/advanced-projects.md) |\n"},"lastSynced":"2026-03-08T02:03:22.217Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript Agents seeking fast and efficient testing solutions with native ESM, TypeScript, and JSX support.","zh":"适用于寻求快速高效测试解决方案的JavaScript Agents，支持原生ESM、TypeScript和JSX。","ja":"JavaScriptエージェントが高速で効率的なテストソリューションを求める場合に適しています。ネイティブESM、TypeScript、JSXをサポートしています。","ko":"빠르고 효율적인 테스트 솔루션을 찾는 JavaScript 에이전트에게 적합합니다. 네이티브 ESM, TypeScript, JSX를 지원합니다.","es":"Ideal para agentes de JavaScript que buscan soluciones de prueba rápidas y eficientes con soporte nativo para ESM, TypeScript y JSX.","fr":"Idéal pour les agents JavaScript qui recherchent des solutions de test rapides et efficaces avec un support natif pour ESM, TypeScript et JSX.","de":"Ideal für JavaScript-Agents, die nach schnellen und effizienten Testlösungen mit nativem ESM-, TypeScript- und JSX-Unterstützung suchen.","pt":"Ideal para Agentes JavaScript que buscam soluções de teste rápidas e eficientes com suporte nativo a ESM, TypeScript e JSX.","ru":"Идеально для агентов JavaScript, ищущих быстрые и эффективные решения для тестирования с родной поддержкой ESM, TypeScript и JSX.","ar":"مثالي لعميل جافا سكريبت الذين يبحثون عن حلول اختبار سريعة وفعالة مع دعم أصلي لـ ESM و TypeScript و JSX."},"recommendation":{"en":"Empowers agents to leverage Vite''s transformation pipeline for fast HMR-like test updates, utilizing Jest-compatible APIs and smart watch modes that only rerun affected tests based on module graphs, all while supporting native ESM, TypeScript, and JSX.","zh":"赋予代理人使用Vite的转换管道来实现快速的HMR样式测试更新的能力，利用Jest兼容的API和智能监视模式，只根据模块图重新运行受影响的测试，同时支持原生ESM、TypeScript和JSX。","ja":"Viteの変換パイプラインを使用して、Jest互換のAPIとスマートなウォッチモードを利用し、モジュールグラフに基づいて影響を受けるテストのみを再実行することで、高速なHMRのようなテスト更新を実現する能力をエージェントに与えます。ネイティブESM、TypeScript、JSXをサポートしています。","ko":"Vite의 변환 파이프라인을 사용하여 Jest와 호환되는 API 및 스마트 감시 모드를 활용하여 모듈 그래프에 따라 영향을 받는 테스트만 다시 실행하여 빠른 HMR와 같은 테스트 업데이트를 가능하게 하는 기능을 에이전트에게 부여합니다. 네이티브 ESM, TypeScript, JSX를 지원합니다.","es":"Permite a los agentes aprovechar la pipeline de transformación de Vite para actualizaciones de pruebas rápidas tipo HMR, utilizando APIs compatibles con Jest y modos de vigilancia inteligentes que solo vuelven a ejecutar las pruebas afectadas en función de los gráficos de módulos, todo esto mientras se mantiene el soporte nativo para ESM, TypeScript y JSX.","fr":"Permet aux agents d''exploiter la pipeline de transformation de Vite pour des mises à jour de tests rapides de type HMR, en utilisant des API compatibles avec Jest et des modes de surveillance intelligents qui ne réexécutent que les tests affectés en fonction des graphiques de modules, le tout en maintenant un support natif pour ESM, TypeScript et JSX.","de":"Ermöglicht es den Agents, Vites Transformation-Pipeline für schnelle HMR-ähnliche Test-Updates zu nutzen, wobei Jest-kompatible APIs und intelligente Wachmodi verwendet werden, die nur betroffene Tests basierend auf Modul-Graphen neu ausführen, während die native Unterstützung für ESM, TypeScript und JSX beibehalten wird.","pt":"Habilita os agentes a aproveitar o pipeline de transformação do Vite para atualizações de teste rápidas tipo HMR, utilizando APIs compatíveis com Jest e modos de visualização inteligentes que apenas reexecutam os testes afetados com base em gráficos de módulos, tudo isso enquanto suporta ESM nativo, TypeScript e JSX.","ru":"Наделяет агентов возможностью использовать конвейер преобразования Vite для быстрых обновлений тестов типа HMR, используя API, совместимые с Jest, и умные режимы просмотра, которые только повторно выполняют затронутые тесты на основе графиков модулей, все это при поддержке родного ESM, TypeScript и JSX.","ar":"يمنح العميل القدرة على استخدام خط أنابيب تحويل Vite للحصول على تحديثات اختبار سريعة مثل HMR، باستخدام واجهات برمجة تطبيقات متوافقة مع Jest ووضع مراقبة ذكي يعيد تشغيل الاختبارات المتأثرة فقط بناءً على رسومات الوحدات، مع دعم أصلي لـ ESM و TypeScript و JSX."},"useCases":{"en":["Automating testing for Vite applications with Jest-compatible test suites","Debugging JavaScript applications using Vitest''s smart watch mode","Optimizing test suites for faster execution with Vitest''s native ESM support"],"zh":["使用Jest兼容的测试套件自动化Vite应用程序的测试","使用Vitest的智能监视模式调试JavaScript应用程序","使用Vitest的原生ESM支持优化测试套件以实现更快的执行"],"ja":["Jest互換のテストスイートを使用してViteアプリケーションのテストを自動化する","Vitestのスマートなウォッチモードを使用してJavaScriptアプリケーションをデバッグする","VitestのネイティブESMサポートを使用してテストスイートを最適化し、実行を高速化する"],"ko":["Jest와 호환되는 테스트 스위트를 사용하여 Vite 애플리케이션의 테스트를 자동화합니다","Vitest의 스마트 감시 모드를 사용하여 JavaScript 애플리케이션을 디버깅합니다","Vitest의 네이티브 ESM 지원을 사용하여 테스트 스위트를 최적화하여 실행을 더 빠르게 합니다"],"es":["Automatizar pruebas para aplicaciones Vite con suites de pruebas compatibles con Jest","Depurar aplicaciones JavaScript utilizando el modo de vigilancia inteligente de Vitest","Optimizar suites de pruebas para una ejecución más rápida con el soporte nativo de ESM de Vitest"],"fr":["Automatiser les tests pour les applications Vite avec des suites de tests compatibles avec Jest","Déboguer les applications JavaScript en utilisant le mode de surveillance intelligent de Vitest","Optimiser les suites de tests pour une exécution plus rapide avec le support natif ESM de Vitest"],"de":["Automatisieren von Tests für Vite-Anwendungen mit Jest-kompatiblen Test-Suiten","Debuggen von JavaScript-Anwendungen unter Verwendung des intelligenten Wachmodus von Vitest","Optimieren von Test-Suiten für eine schnellere Ausführung mit der nativen ESM-Unterstützung von Vitest"],"pt":["Automatizar testes para aplicações Vite com conjuntos de testes compatíveis com Jest","Depurar aplicações JavaScript usando o modo de visualização inteligente do Vitest","Otimizar conjuntos de testes para execução mais rápida com suporte nativo do Vitest a ESM"],"ru":["Автоматизировать тестирование для приложений Vite с наборами тестов, совместимыми с Jest","Отлаживать приложения JavaScript с помощью умного режима просмотра Vitest","Оптимизировать наборы тестов для более быстрого выполнения с родной поддержкой Vitest ESM"],"ar":["تحسين الاختبار التلقائي لتطبيقات Vite مع مجموعات اختبار متوافقة مع Jest","تصحيح أخطاء تطبيقات جافا سكريبت باستخدام وضع المراقبة الذكي في Vitest","تحسين مجموعات الاختبار لتنفيذ أسرع مع دعم Vitest الأصلي لـ ESM"]},"limitations":{"en":["Requires Vite configuration and setup","Limited to JavaScript and TypeScript projects"],"zh":["需要Vite配置和设置","仅限于JavaScript和TypeScript项目"],"ja":["Viteの設定とセットアップが必要","JavaScriptとTypeScriptプロジェクトのみに限定される"],"ko":["Vite 구성 및 설정이 필요합니다","JavaScript 및 TypeScript 프로젝트만 해당됩니다"],"es":["Requiere configuración y configuración de Vite","Limitado a proyectos de JavaScript y TypeScript"],"fr":["Nécessite une configuration et une installation de Vite","Limité aux projets JavaScript et TypeScript"],"de":["Benötigt Vite-Konfiguration und -Einrichtung","Begrenzt auf JavaScript- und TypeScript-Projekte"],"pt":["Exige configuração e instalação do Vite","Limitado a projetos JavaScript e TypeScript"],"ru":["Требует настройки и установки Vite","Ограничен проектами JavaScript и TypeScript"],"ar":["يتطلب تكوينًا وإعدادًا لـ Vite","محدود بمشاريع جافا سكريبت و TypeScript"]},"version":4},"contentHash":"87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07","qualityScore":31}');
