INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DanielShuguang/tool-box/vitest', 'vitest', 'DanielShuguang', 'tool-box', 'community', 'vitest DanielShuguang tool-box community Vitest is a testing framework powered by Vite, providing a Jest-compatible API with native ESM, TypeScript, and JSX support. It benefits developers seeking fast and efficient testing solutions. Vitest 是一个小工具箱，提供 Jest 兼容的 API 和原生 ESM、TypeScript 和 JSX 支持。它使用 Vite 的转换管道实现快速的 HMR-like 测试更新 Vitest は小さなツールボックスで、Jest 互換の API とネイティブの ESM、TypeScript、JSX をサポート。Vite の変換パイプラインを使用して高速な HMR のようなテスト更新を実現 Vitest는 작은 도구 상자로 Jest와 호환되는 API 및 네이티브 ESM, TypeScript, JSX를 지원합니다. Vite의 변환 파이프라인을 사용하여 빠른 HMR와 같은 테스트 업데이트를 구현합니다 Vitest es un framework de pruebas de próxima generación que ofrece una API compatible con Jest y soporte nativo para ESM, TypeScript y JSX. Está diseñado para funcionar con Vite y ofrece una serie de características avanzadas para mejorar la eficiencia de las pruebas. Vitest est un framework de test de nouvelle génération qui offre une API compatible avec Jest et un support natif pour ESM, TypeScript et JSX. Il est conçu pour fonctionner avec Vite et propose une série de fonctionnalités avancées pour améliorer l''efficacité des tests. Vitest ist ein Framework für Tests der nächsten Generation, das eine API kompatibel mit Jest und nativen Support für ESM, TypeScript und JSX bietet. Es ist für die Verwendung mit Vite konzipiert und bietet eine Reihe von erweiterten Funktionen, um die Effizienz der Tests zu verbessern. O Vitest é um framework de teste de próxima geração, construído sobre o Vite, que oferece suporte nativo a ESM, TypeScript e JSX. Ele fornece uma API compatível com o Jest e recursos como atualizações de teste rápidas e inteligentes Vitest - это фреймворк для тестирования следующего поколения, построенный на основе Vite, который обеспечивает родную поддержку ESM, TypeScript и JSX. Он предлагает API, совместимый с Jest, и функции, такие как быстрые и умные обновления тестов Vitest هو إطار اختبار من الجيل التالي، مبني على Vite، الذي يقدم دعمًا أصليًا ل ESM و TypeScript و JSX. يقدم واجهة برمجة تطبيقات متوافقة مع Jest وميزات مثل تحديثات الاختبار السريعة والذكية how to use vitest vitest setup guide vitest vs jest vitest install what is vitest vitest alternative vitest testing framework vitest and vite vitest for developers vitest tutorial Vitest Vite Jest ESM TypeScript JSX AIエージェント 测试框架 下一代测试框架 Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates Jest-compatible: Drop-in replacement for most Jest test suites Smart watch mode: Only reruns affected tests based on module graph Native ESM support: Enables fast and efficient testing with ES modules TypeScript support: Allows for seamless testing with TypeScript projects JSX support: Enables testing of JSX components out of the box Vitest is a next-generation testing framework powered by Vite, offering native ESM, TypeScript, and JSX support out of the box.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('reggiechan74/vp-real-estate/injurious-affection-assessment', 'community', 'reggiechan74', 'vp-real-estate', 'reggiechan74/vp-real-estate', 'injurious-affection-assessment', 0, 0, 31, '2026-03-08T01:57:15.359Z', '2026-03-08T02:04:07.694Z', '4332e210a77d514e5030ca02d289dafa340c2a729a4e2096fcd8b354c7177e2a', '{"id":"reggiechan74/vp-real-estate/injurious-affection-assessment","name":"injurious-affection-assessment","description":{"en":"The injurious-affection-assessment skill provides detailed technical methodology for assessing damages from construction activities and permanent proximity impacts. It benefits experts in quantifying damages from infrastructure projects.","zh":"injurious-affection-assessment是一种量化施工活动和永久接近影响的损害的技术方法，使用Claude Code进行租赁管理","ja":"injurious-affection-assessmentは、建設活動と永久接近影響による損害を評価するための技術方法です。Claude Codeを使用したリース管理も含みます","ko":"injurious-affection-assessment는 건설 활동과 영구 근접 영향에 따른 손해를 평가하는 기술 방법입니다. Claude Code를 사용한 임대 관리도 포함됩니다","es":"Evaluación de afección injuriosa para proyectos de construcción y infraestructura, utilizando Claude Code para medir y valorar daños específicos.","fr":"Évaluation de l''affection injurieuse pour les projets de construction et d''infrastructure, utilisant Claude Code pour mesurer et évaluer des dommages spécifiques.","de":"Bewertung von schädlicher Beeinträchtigung für Bauprojekte und Infrastrukturprojekte, unter Verwendung von Claude Code zur Messung und Bewertung spezifischer Schäden.","pt":"Avalie danos de construção e impactos de proximidade com nossa ferramenta de avaliação de afeto lesivo, utilizando Claude Code","ru":"Оцените вредное воздействие строительных hoạtностей и постоянных близких воздействий с помощью нашего инструмента оценки вредного воздействия, основанного на Claude Code","ar":"قيم الأضرار الناجمة عن الأنشطة الإنشائية والتأثيرات القريبة باستخدام أداة تقييم العواطف الضارة، مع تطبيق Claude Code"},"seo":{"title":{"en":"injurious-affection-assessment: Technical Guide for Quant...","zh":"injurious-affection-assessment Setup Guide - 量化施工活动损害","ja":"injurious-affection-assessment ベストプラクティス - AIエージェントによる損害評価","ko":"injurious-affection-assessment 기술 가이드 - 건설 활동 손해 평가","es":"Guía de configuración para evaluación de afección injurio...","fr":"Configurer l''évaluation de l''affection injurieuse avec Cl...","de":"Einrichtungsleitfaden für die Bewertung von schädlicher B...","pt":"Guia de Configuração para Avaliação de Afeto Lesivo com C...","ru":"Руководство по настройке оценки вредного воздействия с по...","ar":"دليل إعداد لتقييم العواطف الضارة باستخدام Claude Code ووك..."},"description":{"en":"Learn how to assess noise, dust, vibration, and business loss claims with injurious-affection-assessment. Get started with our expert guide and optimize your...","zh":"了解injurious-affection-assessment的技术细节，量化施工活动和永久接近影响的损害","ja":"injurious-affection-assessmentを使用して、建設活動と永久接近影響による損害を評価する方法を学びます","ko":"injurious-affection-assessment를 사용하여 건설 활동과 영구 근접 영향에 따른 손해를 평가하는 방법에 대해 알아보세요","es":"Aprenda a evaluar daños de actividades de construcción y proyectos de infraestructura con nuestra guía de evaluación de afección injuriosa","fr":"Découvrez comment évaluer les dommages causés par les activités de construction et les projets d''infrastructure avec notre guide d''évaluation de l''affection ...","de":"Erfahren Sie, wie Sie Schäden von Bauprojekten und Infrastrukturprojekten mit unserem Leitfaden zur Bewertung von schädlicher Beeinträchtigung bewerten können","pt":"Aprenda a quantificar danos de atividades de construção e impactos de proximidade com nossa ferramenta de avaliação de afeto lesivo","ru":"Оцените вредное воздействие строительных hoạtностей и постоянных близких воздействий с помощью нашего инструмента оценки вредного воздействия","ar":"تعلم كيفية تحديد الأضرار الناجمة عن الأنشطة الإنشائية والتأثيرات القريبة باستخدام أداة تقييم العواطف الضارة"},"definition":{"en":"injurious-affection-assessment is a technical methodology for quantifying damages from construction activities and permanent proximity impacts, including noise, dust, vibration, traffic, visual, and business loss claims","zh":"injurious-affection-assessment是一种评估施工活动和永久接近影响的损害的技术方法","ja":"injurious-affection-assessmentは、建設活動と永久接近影響による損害を評価するための技術方法です","ko":"injurious-affection-assessment는 건설 활동과 영구 근접 영향에 따른 손해를 평가하는 기술 방법입니다","es":"La evaluación de afección injuriosa es un proceso técnico para medir y valorar daños causados por actividades de construcción y proyectos de infraestructura.","fr":"L''évaluation de l''affection injurieuse est un processus technique pour mesurer et évaluer les dommages causés par les activités de construction et les projets d''infrastructure.","de":"Die Bewertung von schädlicher Beeinträchtigung ist ein technischer Prozess zur Messung und Bewertung von Schäden, die durch Bauprojekte und Infrastrukturprojekte verursacht werden.","pt":"Avaliação de afeto lesivo é a quantificação de danos causados por atividades de construção e impactos de proximidade","ru":"Оценка вредного воздействия - это количественная оценка вреда, причиненного строительными hoạtностями и постоянными близкими воздействиями","ar":"تقييم العواطف الضارة هو تحديد كمي للأضرار الناجمة عن الأنشطة الإنشائية والتأثيرات القريبة"},"features":{"en":["Provides technical depth on measuring and valuing specific types of injurious affection","Assesses noise, dust, vibration, traffic, visual, and business loss claims","Quantifies damages from construction and proximity impacts","Offers detailed technical methodology for lease management using Claude Code","Supports analysis of partial taking and infrastructure projects","Enables experts to provide detailed damage assessments"],"zh":["量化施工活动的噪音、灰尘、振动、交通、视觉和商业损失","评估永久接近影响的损害","使用Claude Code进行租赁管理","提供详细的技术方法论","评估噪音、灰尘、振动、交通、视觉和商业损失的损害"],"ja":["建設活動によるノイズ、ダスト、振動、交通、視覚および事業損失の評価","永久接近影響による損害の評価","Claude Codeを使用したリース管理","詳細な技術方法論の提供","ノイズ、ダスト、振動、交通、視覚および事業損失の損害の評価"],"ko":["건설 활동에 따른 소음, 미세먼지, 진동, 교통, 시각 및 사업 손실 평가","영구 근접 영향에 따른 손해 평가","Claude Code를 사용한 임대 관리","상세한 기술 방법론 제공","소음, 미세먼지, 진동, 교통, 시각 및 사업 손실의 손해 평가"],"es":["Medición de daños por ruido","Evaluación de daños por polvo y vibraciones","Análisis de impactos visuales y de tráfico","Cálculo de pérdidas comerciales","Uso de Claude Code para la evaluación","Aplicación de metodologías técnicas para la cuantificación de daños"],"fr":["Mesure des dommages causés par le bruit","Évaluation des dommages causés par la poussière et les vibrations","Analyse des impacts visuels et de la circulation","Calcul des pertes commerciales","Utilisation de Claude Code pour l''évaluation","Application de méthodologies techniques pour la quantification des dommages"],"de":["Messung von Schäden durch Lärm","Bewertung von Schäden durch Staub und Vibrationen","Analyse von visuellen und Verkehrsauswirkungen","Berechnung von Geschäftsverlusten","Verwendung von Claude Code für die Bewertung","Anwendung von technischen Methoden zur Quantifizierung von Schäden"],"pt":["Quantificação de danos de ruído","Avaliação de impactos de poeira","Análise de vibrações","Avaliação de impactos de tráfego","Análise de perdas comerciais","Utilização de Claude Code para lease management"],"ru":["Оценка вредного воздействия шума","Оценка воздействия пыли","Анализ вибраций","Оценка воздействия транспорта","Анализ коммерческих потерь","Применение Claude Code для управления арендой"],"ar":["تحديد الأضرار الناجمة عن الضوضاء","تقييم التأثيرات الناجمة عن الغبار","تحليل الاهتزازات","تقييم التأثيرات الناجمة عن حركة المرور","تحليل الخسائر التجارية","تطبيق Claude Code لإدارة الإيجار"]},"keywords":{"en":["how to use injurious-affection-assessment","injurious-affection-assessment alternative","what is injurious-affection-assessment","injurious-affection-assessment setup guide","quantifying damages from construction activities","lease management using Claude Code","injurious affection assessment methodology","assessing business loss claims","infrastructure project damage assessment"],"zh":["injurious-affection-assessment","量化施工活动损害","永久接近影响评估","Claude Code租赁管理","技术方法论","噪音损害评估","灰尘损害评估","振动损害评估","交通损害评估"],"ja":["injurious-affection-assessment","建設活動による損害評価","永久接近影響評価","Claude Codeリース管理","技術方法論","ノイズ損害評価","ダスト損害評価","振動損害評価","交通損害評価"],"ko":["injurious-affection-assessment","건설 활동 손해 평가","영구 근접 영향 평가","Claude Code 임대 관리","기술 방법론","소음 손해 평가","미세먼지 손해 평가","진동 손해 평가","교통 손해 평가"],"es":["evaluación de afección injuriosa","Claude Code","proyectos de construcción","proyectos de infraestructura","medición de daños","cuantificación de daños","análisis de impactos","pérdidas comerciales","metodologías técnicas"],"fr":["évaluation de l''affection injurieuse","Claude Code","projets de construction","projets d''infrastructure","mesure des dommages","quantification des dommages","analyse des impacts","pertes commerciales","méthodologies techniques"],"de":["Bewertung von schädlicher Beeinträchtigung","Claude Code","Bauprojekte","Infrastrukturprojekte","Messung von Schäden","Quantifizierung von Schäden","Analyse von Auswirkungen","Geschäftsverluste","technische Methoden"],"pt":["avaliação de afeto lesivo","quantificação de danos","construção","impactos de proximidade","Claude Code","lease management","análise de ruído","avaliação de poeira","análise de vibrações"],"ru":["оценка вредного воздействия","количественная оценка вреда","строительные hoạtности","постоянные близкие воздействия","ИИ Агенты","Claude Code","управление арендой","оценка шума","оценка пыли","анализ вибраций"],"ar":["تقييم العواطف الضارة","تحديد كمي للأضرار","أنشطة الإنشائية","التأثيرات القريبة","وكلاء الذكاء الاصطناعي","Claude Code","إدارة الإيجار","تقييم الضوضاء","تقييم الغبار","تحليل الاهتزازات"]}},"owner":"reggiechan74","repo":"vp-real-estate","repoPath":"reggiechan74/vp-real-estate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.359Z","topics":[],"category":"community","skillMd":{"name":"injurious-affection-assessment","description":"Expert in quantifying damages from construction and proximity impacts including noise, dust, vibration, traffic disruption, visual impairment, and business losses. Use when assessing temporary construction impacts, permanent proximity damages, business loss claims, or quantifying injurious affection beyond general principles. Key terms include injurious affection, construction impacts, noise modeling, vibration damage, traffic disruption, visual impairment, business losses","tags":["injurious-affection","construction-impacts","noise-assessment","vibration-damage","business-losses","proximity-impacts"],"bodyPreview":"You are an expert in quantifying damages from construction activities and permanent proximity impacts resulting from infrastructure projects, providing detailed technical methodology for assessing noise, dust, vibration, traffic, visual, and business loss claims.\n\n## Granular Focus\n\nQuantifying damages from construction and proximity (subset of partial taking). This skill provides technical depth on measuring and valuing specific types of injurious affection - NOT general legal principles of com","body":"You are an expert in quantifying damages from construction activities and permanent proximity impacts resulting from infrastructure projects, providing detailed technical methodology for assessing noise, dust, vibration, traffic, visual, and business loss claims.\n\n## Granular Focus\n\nQuantifying damages from construction and proximity (subset of partial taking). This skill provides technical depth on measuring and valuing specific types of injurious affection - NOT general legal principles of compensability.\n\n## Construction Period Impacts (Temporary)\n\nTemporary damages during construction period, typically quantified as percentage rent reduction or lump-sum business loss.\n\n### Noise Impact Modeling (dBA Levels, Duration, Receptor Sensitivity)\n\n**Methodology**: Measure noise levels in dBA, assess duration and timing, evaluate receptor sensitivity.\n\n**Sound level measurements**:\n- **dBA scale**: A-weighted decibels (approximates human hearing sensitivity)\n- **Background noise**: Typical urban 50-60 dBA, suburban 40-50 dBA, rural 30-40 dBA\n- **Construction noise**: Typically 70-95 dBA at 15 meters from equipment\n\n**Construction equipment noise levels** (at 15 meters):\n- **Impact pile driver**: 95-105 dBA\n- **Jackhammer**: 85-95 dBA\n- **Heavy trucks**: 80-90 dBA\n- **Excavator**: 75-85 dBA\n- **Concrete mixer**: 75-85 dBA\n- **Generator**: 70-80 dBA\n\n**Distance attenuation**:\n- Sound decreases approximately **6 dBA per doubling of distance**\n- Example: Pile driver at 95 dBA at 15m → 89 dBA at 30m → 83 dBA at 60m → 77 dBA at 120m\n\n**Impact assessment by receptor**:\n\n**Residential**:\n- **Moderate impact**: 65-75 dBA daytime, <60 dBA nighttime (sleep disturbance threshold)\n- **Severe impact**: >75 dBA daytime, >60 dBA nighttime\n- **Quantification**:\n  - Moderate: 5-10% rent reduction during construction\n  - Severe: 15-25% rent reduction, potential temporary relocation costs\n\n**Commercial (office)**:\n- **Moderate impact**: 70-80 dBA (interferes with phone calls, concentration)\n- **Severe impact**: >80 dBA (disrupts normal business operations)\n- **Quantification**:\n  - Moderate: 3-8% rent reduction\n  - Severe: 10-15% rent reduction\n\n**Industrial**:\n- **Minimal impact**: <85 dBA (typical industrial background)\n- **Quantification**: Generally no compensation unless >85 dBA sustained\n\n**Example calculation**:\n- **Property**: 3-storey apartment building, 12 units, $1,800/month/unit rent\n- **Construction**: Pile driving 40 meters away for 3 months\n- **Noise level**: 95 dBA at 15m → 89 dBA at 30m → 86 dBA at 40m (interpolated)\n- **Impact**: Severe (>75 dBA residential)\n- **Duration**: 3 months\n- **Rent reduction**: 20% × $1,800/unit × 12 units × 3 months = **$12,960**\n\n### Dust and Air Quality (PM2.5/PM10 Levels, Health Impacts)\n\n**Methodology**: Measure particulate matter concentrations, assess health impacts, quantify cleaning costs and health risks.\n\n**Particulate matter standards**:\n- **PM10** (particles <10 micrometers): Ontario 24-hour standard 50 μg/m³\n- **PM2.5** (particles <2.5 micrometers): Ontario 24-hour standard 27 μg/m³\n- **Background levels**: Urban 15-25 μg/m³ (PM2.5), rural 5-10 μg/m³\n\n**Construction dust sources**:\n- **Excavation/grading**: PM10 dominant (coarse dust)\n- **Concrete cutting/grinding**: PM10 + PM2.5 (respirable dust)\n- **Vehicle traffic on unpaved roads**: PM10 (road dust re-suspension)\n- **Diesel exhaust**: PM2.5 + ultrafine particles (<0.1 μm)\n\n**Impact zones by distance**:\n- **High impact** (0-50m): Visible dust deposition, frequent cleaning required\n- **Moderate impact** (50-150m): Occasional dust deposition, periodic cleaning\n- **Low impact** (150-300m): Elevated PM levels but minimal deposition\n\n**Quantification approaches**:\n\n1. **Cleaning costs**:\n   - **Residential**: $150-$300 per cleaning × frequency (weekly for high impact)\n   - **Commercial**: $500-$2,000 per cleaning × frequency\n   - **Example**: House 30m from construction, 6-month project, weekly cleaning\n     - Cost: $200/cleaning × 26 weeks = **$5,200**\n\n2. **Health impacts (severe cases)**:\n   - Respiratory issues requiring medical attention\n   - Documented medical costs + loss of enjoyment\n   - Example: Elderly resident, pre-existing COPD, 3 hospitalizations attributed to dust\n     - Medical costs: $8,000 + suffering: $15,000 = **$23,000**\n\n3. **Rent reduction** (residential/commercial tenants vacate or withhold rent):\n   - Moderate dust: 5-10% rent reduction\n   - Severe dust: 15-25% rent reduction\n   - Example: Office building, severe dust, 4-month impact, $25,000/month rent\n     - Compensation: 18% × $25,000 × 4 months = **$18,000**\n\n### Vibration Damage (Structural, Cosmetic, Annoyance Thresholds)\n\n**Methodology**: Measure peak particle velocity (PPV) in mm/s, assess damage risk, document pre-construction condition.\n\n**Vibration thresholds (PPV in mm/s)**:\n\n**Structural damage**:\n- **Historic buildings** (unreinforced masonry): 5 mm/s (cosmetic), 12 mm/s (minor structural)\n- **Residential buildings** (modern construction): 12 mm/s (cosmetic), 20 mm/s (minor structural), 50 mm/s (major structural)\n- **Commercial/industrial**: 20 mm/s (cosmetic), 50 mm/s (structural)\n\n**Cosmetic damage** (cracks in plaster, drywall):\n- **Threshold**: 5-12 mm/s depending on building age and condition\n- **Repair cost**: $500-$5,000 per location (plaster repair, repainting)\n\n**Annoyance thresholds** (human perception):\n- **Barely perceptible**: 0.15-0.3 mm/s\n- **Distinctly perceptible**: 0.3-1.0 mm/s\n- **Annoying**: 1.0-10 mm/s\n- **Very annoying**: >10 mm/s\n\n**Vibration sources and typical PPV** (at 10 meters):\n- **Impact pile driver**: 20-80 mm/s (high damage risk)\n- **Vibratory pile driver**: 5-20 mm/s (moderate damage risk)\n- **Hydraulic hammer**: 5-15 mm/s\n- **Compactor/roller**: 2-10 mm/s\n- **Loaded truck**: 0.2-0.6 mm/s\n\n**Distance attenuation**:\n- PPV decreases with distance approximately: PPV = PPV₀ × (D₀ / D)^1.5\n- Example: Impact pile driver 40 mm/s at 10m → 14 mm/s at 25m → 7 mm/s at 50m\n\n**Compensation approaches**:\n\n1. **Pre-construction condition survey**:\n   - Document all existing cracks, defects with photos, measurements\n   - Post-construction comparison to prove causation\n\n2. **Cosmetic damage repair**:\n   - Itemized repair costs (plaster, drywall, paint, flooring)\n   - Example: 8 new cracks in century home from pile driving 20m away (PPV 15 mm/s)\n     - Repair: 8 locations × $1,200/location = **$9,600**\n\n3. **Structural damage** (rare, typically from non-compliance with vibration limits):\n   - Engineering assessment + repair costs\n   - Example: Foundation crack in historic building, pile driving exceeded limits\n     - Engineering: $8,000, foundation repair: $45,000 = **$53,000**\n\n4. **Annoyance compensation** (no physical damage):\n   - Rent reduction for duration of severe vibration\n   - Example: Residential, 3 months of daily pile driving (PPV 8 mm/s), very annoying\n     - Rent reduction: 10% × $2,500/month × 3 months = **$750**\n\n### Traffic Disruption (Delay Costs, Business Access Impairment)\n\n**Methodology**: Quantify increased travel time, assess business access impacts, calculate economic costs.\n\n**Delay cost calculation**:\n- **Value of time**: $25-$50/hour for commercial/industrial users, $15-$25/hour for personal travel\n- **Vehicle operating cost**: $0.50-$0.80/km additional distance\n\n**Example (commercial property)**:\n- **Before**: Direct access to arterial road, 5-minute travel to customers\n- **During construction**: Road closure requires 8 km detour, 20-minute travel\n- **Impact**: +15 minutes, +6 km per trip\n- **Business trips**: 40 trips/day × 250 days over 6-month construction\n- **Annual delay cost**: 10,000 trips × 15 min × (1/60 hr/min) × $40/hr = $100,000\n- **Vehicle cost**: 10,000 trips × 6 km × $0.60/km = $36,000\n- **Total traffic disruption**: **$136,000**\n\n**Business access impairment**:\n- **Lost sales** from customer inability to access business\n- **Example**: Retail store, construction blocks parking lot entrance for 4 months\n  - Historic sales: $120,000/month\n  - Sales during construction: $85,000/month (29% reduction)\n  - **Lost revenue**: ($120K - $85K) × 4 months = **$140,000**\n  - **Less avoided variable costs** (30%): $140K × 70% = **$98,000 net loss**\n\n**Parking loss**:\n- **Residential**: Inconvenience, no compensation unless severe (e.g., disabled resident)\n- **Commercial**: Lost customer parking = lost sales\n- **Example**: Restaurant loses 15 of 40 parking spaces for 3 months\n  - Estimated impact: 20% reduction in dinner sales\n  - Dinner sales: $80,000/month × 20% = $16,000/month\n  - **Lost profit**: $16,000 × 40% margin × 3 months = **$19,200**\n\n## Permanent Proximity Impacts\n\nOngoing impacts from completed infrastructure, capitalized to reflect permanent value loss.\n\n### Visual Impact (View Obstruction, Aesthetic Degradation)\n\n**Methodology**: Quantify view loss or aesthetic degradation using market evidence (paired sales, hedonic regression).\n\n**View premium loss**:\n\n**Residential**:\n- **Water view**: 15-40% premium (lakefront, ocean view)\n- **City skyline view**: 10-25% premium\n- **Green space/park view**: 5-15% premium\n- **Mountain view**: 10-30% premium\n\n**Example**:\n- **Before**: House with unobstructed lake view, value $800,000 (includes 25% view premium)\n- **After**: New highway overpass blocks 60% of lake view\n- **Adjusted view premium**: 25% × 40% remaining view = 10% premium\n- **After value**: $800,000 ÷ 1.25 × 1.10 = $704,000\n- **Injurious affection**: $800,000 - $704,000 = **$96,000** (12% loss)\n\n**Aesthetic degradation** (industrial facilities, transmission towers, sound walls):\n- Quantified using paired sales of properties with/without visual exposure to infrastructure\n- Typical range: 5-15% reduction for significant visual impact\n\n**Paired sales example**:\n\n**Sale 1** (no visual impact):\n- House, suburban neighborhood, no infrastructure view\n- Sale price: $650,000\n\n**Sale 2** (visual impact):\n- Comparable house, same neighborhood, backs onto new transmission corridor with towers\n- Sale price: $580,000\n- Time/condition adjusted: $590,000\n\n**Visual impact discount**: ($650K - $590K) ÷ $650K = **9.2% reduction**\n\n**Application to subject**:\n- Property adjacent to new transmission corridor\n- Comparable market evidence: 8-10% reduction\n- Property value before: $720,000\n- **Injurious affection**: $720,000 × 9% = **$64,800**\n\n### Noise from Operations (HVAC, Traffic, Industrial Processes)\n\n**Methodology**: Measure operational noise increase, compare to background, apply market evidence of noise impact on value.\n\n**Operational noise sources**:\n- **Highway traffic**: 65-80 dBA at 30m from highway (depending on volume, speed, trucks)\n- **Railway operations**: 70-90 dBA during train passage (at 50m)\n- **HVAC equipment**: 55-75 dBA at property line\n- **Industrial facilities**: 60-80 dBA at property line (depending on zoning limits)\n\n**Residential noise impact on value**:\n- **Moderate increase** (+10 dBA over background): 5-10% value reduction\n- **Significant increase** (+15-20 dBA): 10-20% value reduction\n- **Severe increase** (+25 dBA or >70 dBA continuous): 20-30% value reduction\n\n**Example**:\n- **Before**: Residential property, background noise 45 dBA (quiet suburban)\n- **After**: New highway 80m away, noise level increases to 68 dBA\n- **Increase**: 68 - 45 = 23 dBA (severe increase)\n- **Market evidence**: Comparable sales show 18% reduction for similar highway proximity\n- **Property value before**: $550,000\n- **Injurious affection**: $550,000 × 18% = **$99,000**\n\n**Commercial/industrial**:\n- Generally minimal impact unless noise interferes with business operations\n- Example: Recording studio, noise-sensitive use, new rail line increases noise\n  - Impact: Business no longer viable at location (requires soundproofing or relocation)\n  - **Compensation**: Soundproofing cost $120,000 or relocation cost $200,000 → adopt lower (**$120,000**)\n\n### Safety Perception (Property Value Discounts Near Hazards)\n\n**Methodology**: Market evidence of stigma/safety perception impacts on value near hazardous infrastructure.\n\n**Hazard types and typical market discounts**:\n- **High-voltage transmission lines** (230kV+): 5-15% discount (EMF perception, visual impact)\n- **Petroleum pipelines**: 5-10% discount (explosion risk perception)\n- **Rail corridors** (freight, hazmat): 8-15% discount (derailment risk, noise)\n- **Highways**: 5-12% discount (noise, air quality, safety)\n- **Cell towers**: 3-8% discount (health perception, visual)\n\n**Example (transmission line)**:\n- **Before**: Rural residential property, $420,000\n- **After**: New 500kV transmission line 150m from house (within easement corridor on adjacent land)\n- **Market evidence**: Sales of homes near transmission lines show 10-12% discount\n- **Injurious affection**: $420,000 × 11% = **$46,200**\n\n**Burden of proof**:\n- Claimant must provide market evidence (paired sales, expert appraisal)\n- Mere fear/perception insufficient without market validation\n- Courts generally accept 5-15% range if credible market evidence provided\n\n### Market Evidence (Paired Sales Analysis, Hedonic Regression)\n\n**Paired sales analysis**:\n- Identify comparable properties with/without proximity to subject infrastructure\n- Adjust for differences in size, age, condition, location\n- Extract percentage discount attributable to infrastructure proximity\n- Apply to subject property\n\n**Example dataset** (residential near highways):\n\n| Sale | Distance to Highway | Sale Price | Adjusted Price | Discount |\n|------|---------------------|------------|----------------|----------|\n| 1 | >500m (no impact) | $620,000 | $620,000 | 0% (baseline) |\n| 2 | 150m | $565,000 | $580,000 | 6.5% |\n| 3 | 80m | $540,000 | $555,000 | 10.5% |\n| 4 | 50m | $515,000 | $530,000 | 14.5% |\n\n**Regression equation**: Discount = 0.002 × (500 - Distance)\n- At 100m: Discount = 0.002 × 400 = 8%\n- At 200m: Discount = 0.002 × 300 = 6%\n\n**Hedonic regression** (multiple variables):\n- Model: Price = β₀ + β₁(Size) + β₂(Age) + β₃(Distance to Highway) + β₄(Noise Level) + ε\n- Isolates infrastructure impact controlling for other variables\n- More robust than paired sales (larger sample, statistical significance testing)\n\n**Example output**:\n- β₃ (Distance to Highway) = +$1,200 per meter (price increases $1,200 for each meter farther from highway)\n- At 100m distance vs. 500m: Price difference = $1,200 × 400m = $480,000\n- Base price $600,000 → **Discount at 100m = 8%**\n\n## Business Losses During Construction\n\nRevenue losses and cost increases during construction period, requiring careful documentation and causation analysis.\n\n### Revenue Loss Documentation (Comparative Sales Analysis)\n\n**Methodology**: Compare actual revenue during construction to baseline revenue (prior years, comparable periods, industry benchmarks).\n\n**Baseline establishment**:\n- **Historical comparison**: Same period prior years (adjusted for growth trends)\n- **Control location**: Comparable business unaffected by construction\n- **Industry benchmarks**: Verify revenue expectations are reasonable\n\n**Example (restaurant)**:\n- **Baseline**: Average monthly sales $95,000 (3-year average for construction months, adjusted +3% annual growth)\n- **Construction period**: 6 months\n- **Actual sales during construction**:\n  - Month 1: $88,000 (7% drop)\n  - Month 2: $75,000 (21% drop)\n  - Month 3: $68,000 (28% drop)\n  - Month 4: $72,000 (24% drop)\n  - Month 5: $80,000 (16% drop)\n  - Month 6: $87,000 (8% drop)\n- **Total revenue loss**: [($95K × 6) - ($88K + $75K + $68K + $72K + $80K + $87K)] = $570K - $470K = **$100,000**\n\n**Causation analysis** (critical):\n- Correlation with construction activity (worst months = peak construction)\n- Control for other factors (weather, competition, economic conditions)\n- Comparable business performance (if control location sales stable, strengthens claim)\n\n### Customer Access Impairment (Parking Loss, Signage Obstruction)\n\n**Parking loss quantification**:\n- **Retail**: Typically $50-$150 sales per parking space per day\n- **Restaurant**: $100-$300 sales per space per day (higher turnover)\n- **Office**: Minimal loss (employees use transit or park farther)\n\n**Example (retail)**:\n- **Before**: 30 parking spaces, average 3 turns/day, $80 sales/turn = $7,200/day\n- **During construction**: 15 spaces lost for 4 months\n- **Revenue loss**: 15 spaces × 3 turns × $80 × 120 days = **$432,000**\n- **Less avoided variable costs** (40%): $432K × 60% = **$259,200 net loss**\n\n**Signage obstruction**:\n- Construction hoarding, equipment blocks business signage from street\n- Quantified as percentage revenue reduction from lost visibility\n- Example: Restaurant, signage blocked for 5 months\n  - Estimated 15% of customers are drive-by traffic attracted by signage\n  - Monthly sales: $100,000 × 15% = $15,000/month\n  - **Loss**: $15,000 × 5 months × 60% (net of variable costs) = **$45,000**\n\n### Operating Cost Increases (Deliveries, Employee Commute)\n\n**Delivery complications**:\n- Increased distance, time for delivery vehicles\n- Example: Loading dock blocked, requires 200m detour for all deliveries\n  - 10 deliveries/day × 200m × 2 (round trip) × $0.80/km × 0.1 km = $3.20/day\n  - 180-day construction period: $3.20 × 180 = **$576** (minimal)\n\n**Employee commute costs** (if employer compensates):\n- Parking lot closed, employees must park 500m away\n- Employer provides shuttle or parking reimbursement\n- Example: 25 employees × $10/day parking × 120 days = **$30,000**\n\n**Increased security** (theft/vandalism risk):\n- Example: Retail store, construction creates access vulnerabilities\n  - Hires security guard for 4 months: 8 hours/day × $25/hr × 120 days = **$24,000**\n\n### Mitigation Costs (Temporary Relocation, Marketing Campaigns)\n\n**Temporary relocation**:\n- Business relocates during construction to avoid severe impacts\n- **Costs**: Moving (×2), temporary rent premium, dual occupancy period, customer notification\n- Example: Dental office, building uninhabitable during renovation for 6 months\n  - Moving costs: $15,000 × 2 = $30,000\n  - Temporary space premium: ($8,000 - $5,000) × 6 months = $18,000\n  - Dual occupancy (overlap): $8,000 × 1 month = $8,000\n  - Patient notification (mail, signage): $3,000\n  - **Total relocation cost**: **$59,000**\n\n**Marketing campaigns** (to offset customer loss):\n- Additional advertising to inform customers of construction impacts, maintain loyalty\n- Example: Restaurant launches social media campaign, special promotions during construction\n  - Advertising: $12,000\n  - Promotion costs (discounts): $8,000\n  - **Total**: **$20,000**\n  - **Net benefit**: Revenue loss reduced from $100K to $70K → **campaign saved $30K**, net cost effectively $0 (or claim $70K loss + $20K mitigation costs = $90K)\n\n---\n\n**This skill activates when you**:\n- Assess temporary construction impacts (noise, dust, vibration, traffic disruption)\n- Quantify permanent proximity impacts (visual, noise, safety perception)\n- Document business losses during construction with revenue analysis\n- Measure noise levels (dBA), particulate matter (PM2.5/PM10), or vibration (PPV)\n- Apply paired sales analysis or hedonic regression for injurious affection valuation\n- Evaluate causation between construction/infrastructure and claimed damages\n- Calculate mitigation costs or cost-to-cure for injurious affection\n"},"lastSynced":"2026-03-08T02:04:07.694Z","agentAnalysis":{"suitability":{"en":"Ideal for Construction Analysis Agents requiring advanced methodology for assessing damages from infrastructure projects","zh":"适用于需要高级方法评估基础设施项目损害的建筑分析代理","ja":"建設分析エージェントに適しています。インフラストラクチャプロジェクトの損害を評価するための高度な方法論を必要とする","ko":"건설 분석 에이전트에 적합합니다. 인프라 프로젝트의 손실을 평가하기 위한 고급 방법론이 필요한 경우","es":"Ideal para Agentes de Análisis de Construcción que requieren una metodología avanzada para evaluar daños de proyectos de infraestructura","fr":"Idéal pour les Agents d''Analyse de Construction nécessitant une méthodologie avancée pour évaluer les dommages des projets d''infrastructure","de":"Ideal für Construction Analysis Agents, die eine fortschrittliche Methodik zur Bewertung von Schäden aus Infrastrukturprojekten erfordern","pt":"Ideal para Agentes de Análise de Construção que exigem metodologia avançada para avaliar danos de projetos de infraestrutura","ru":"Идеально для Агентов Анализа Строительства, требующих передовой методологии для оценки ущерба от проектов инфраструктуры","ar":"مثالية للوكلاء تحليل البناء التي تتطلب منهجية متقدمة لتقييم الأضرار من مشاريع البنية التحتية"},"recommendation":{"en":"Empowers agents to quantify damages from construction activities and permanent proximity impacts, utilizing technical methodologies for measuring and valuing noise, dust, vibration, traffic, visual, and business loss claims, and providing detailed assessments of injurious affection","zh":"赋予代理评估建筑活动和永久接近影响造成的损害的能力，利用技术方法评估和量化噪音、灰尘、振动、交通、视觉和业务损失索赔，并提供对损害影响的详细评估","ja":"エージェントは、建設活動および永久接近影響による損害を技術的方法論を用いて評価および量化することができ、ノイズ、ダスト、振動、交通、視覚および事業損失請求に対する詳細な評価を提供する","ko":"에이전트가 건설 활동 및 영구 근접 영향으로 인한 손실을 기술적 방법론을 사용하여 평가 및 정량화할 수 있도록 해줍니다. 소음, 먼지, 진동, 교통, 시각 및 사업 손실 청구에 대한 자세한 평가를 제공합니다","es":"Habilita a los agentes a cuantificar daños de las actividades de construcción y los impactos de proximidad permanente, utilizando metodologías técnicas para medir y valorar ruido, polvo, vibración, tráfico, impactos visuales y reclamaciones de pérdida de negocio, y proporcionando evaluaciones detalladas de afectación perjudicial","fr":"Permet aux agents de quantifier les dommages des activités de construction et les impacts de proximité permanente, en utilisant des méthodologies techniques pour mesurer et évaluer les nuisances sonores, la poussière, les vibrations, la circulation, les impacts visuels et les réclamations de perte d''activité, et en fournissant des évaluations détaillées de l''affection nuisible","de":"Ermächtigt die Agenten, Schäden von Baustellen und dauerhaften Näheeffekten zu quantifizieren und technische Methoden zur Messung und Bewertung von Lärm, Staub, Vibration, Verkehr, visuellen Auswirkungen und Geschäftsverlustansprüchen anzuwenden, und detaillierte Bewertungen von schädlichen Auswirkungen bereitzustellen","pt":"Habilita os agentes a quantificar danos das atividades de construção e impactos de proximidade permanente, utilizando metodologias técnicas para medir e avaliar ruído, poeira, vibração, tráfego, impactos visuais e reclamações de perda de negócios, e fornecendo avaliações detalhadas de afecção lesiva","ru":"Наделяет агентов возможностью количественно оценить ущерб от строительных hoạtностей и постоянных близких воздействий, используя технические методологии для измерения и оценки шума, пыли, вибрации, движения транспорта, визуальных и деловых потерь, и предоставляя подробные оценки вредного воздействия","ar":"تمكين الوكلاء من تقدير الأضرار من الأنشطة الإنشائية والتأثيرات القريبة الدائمة، باستخدام منهجيات تقنية لقياس وتقييم الضوضاء والغبار والاهتزاز والمرور والأثر البصري وادعاءات خسارة الأعمال، وتقديم تقييمات مفصلة للتأثير الضار"},"useCases":{"en":["Assessing noise pollution impacts from construction sites","Quantifying business loss claims due to permanent proximity effects","Evaluating visual impacts of infrastructure projects on surrounding environments"],"zh":["评估建筑工地的噪音污染影响","量化永久接近效果对业务损失的索赔","评估基础设施项目对周围环境的视觉影响"],"ja":["建設現場からのノイズ汚染の影響を評価する","永久接近効果による事業損失請求を量化する","インフラストラクチャプロジェクトが周囲の環境に与える視覚的影響を評価する"],"ko":["건설 현장의 소음 오염 영향 평가","영구 근접 효과에 따른 사업 손실 청구 정량화","인프라 프로젝트가 주변 환경에 미치는 시각적 영향 평가"],"es":["Evaluación de los impactos de la contaminación acústica de los sitios de construcción","Cuantificación de las reclamaciones de pérdida de negocio debido a efectos de proximidad permanente","Evaluación de los impactos visuales de los proyectos de infraestructura en los entornos circundantes"],"fr":["Évaluation des impacts de la pollution sonore des chantiers de construction","Quantification des réclamations de perte d''activité due aux effets de proximité permanente","Évaluation des impacts visuels des projets d''infrastructure sur les environnements avoisinants"],"de":["Bewertung der Auswirkungen von Lärmbelästigung von Baustellen","Quantifizierung von Geschäftsverlustansprüchen aufgrund dauerhafter Näheeffekte","Bewertung der visuellen Auswirkungen von Infrastrukturprojekten auf die umliegenden Umgebungen"],"pt":["Avaliando os impactos da poluição sonora de sites de construção","Quantificando reclamações de perda de negócios devido a efeitos de proximidade permanente","Avaliando os impactos visuais de projetos de infraestrutura em ambientes circundantes"],"ru":["Оценка воздействия шумового загрязнения от строительных объектов","Количественная оценка деловых потерь из-за постоянных близких воздействий","Оценка визуальных воздействий инфраструктурных проектов на окружающую среду"],"ar":["تقييم تأثيرات تلوث الضوضاء من مواقع البناء","تقدير ادعاءات خسارة الأعمال بسبب التأثيرات القريبة الدائمة","تقييم التأثيرات البصرية لمشاريع البنية التحتية على البيئة المحيطة"]},"limitations":{"en":["Requires expertise in construction and infrastructure project assessment","Focused on technical methodology, not general legal principles","Limited to quantifying damages from construction and proximity impacts"],"zh":["需要建筑和基础设施项目评估方面的专业知识","专注于技术方法论，而不是一般法律原则","仅限于量化建筑和接近影响造成的损害"],"ja":["建設およびインフラストラクチャプロジェクト評価における専門知識が必要","技術的方法論に焦点を当てており、一般的な法的原則ではない","建設および接近影響による損害の量化のみに限定"],"ko":["건설 및 인프라 프로젝트 평가에 대한 전문 지식 필요","기술적 방법론에 초점을 맞추고 일반적인 법적 원칙은 아님","건설 및 근접 영향에 의한 손실의 정량화에만 제한"],"es":["Requiere experiencia en evaluación de proyectos de construcción e infraestructura","Se centra en la metodología técnica, no en los principios legales generales","Limitado a la cuantificación de daños de la construcción y los impactos de proximidad"],"fr":["Nécessite une expertise dans l''évaluation des projets de construction et d''infrastructure","Se concentre sur la méthodologie technique, et non sur les principes juridiques généraux","Limité à la quantification des dommages des activités de construction et des impacts de proximité"],"de":["Erfordert Erfahrung in der Bewertung von Bauprojekten und Infrastrukturprojekten","Konzentriert sich auf die technische Methodik, nicht auf allgemeine Rechtsgrundsätze","Begrenzt auf die Quantifizierung von Schäden aus Bau- und Näheeffekten"],"pt":["Exige especialização em avaliação de projetos de construção e infraestrutura","Focado em metodologia técnica, não em princípios legais gerais","Limitado a quantificar danos de construção e impactos de proximidade"],"ru":["Требует экспертизы в области оценки строительных и инфраструктурных проектов","Сосредоточен на технической методологии, а не на общих юридических принципах","Ограничен количественной оценкой ущерба от строительства и близких воздействий"],"ar":["يتطلب خبرة في تقييم مشاريع البناء والبنية التحتية","يركز على المنهجية التقنية، وليس على المبادئ القانونية العامة","محدود بتقدير الأضرار من البناء والتأثيرات القريبة"]},"version":4},"contentHash":"4332e210a77d514e5030ca02d289dafa340c2a729a4e2096fcd8b354c7177e2a","qualityScore":31}');
