INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ledzepp1109/SYSopGPTWSL/sysop-kernel', 'sysop-kernel', 'ledzepp1109', 'SYSopGPTWSL', 'community', 'sysop-kernel ledzepp1109 SYSopGPTWSL community sysop-kernel is a plan-first operator kernel that enables efficient task management for AI agents. It benefits developers by providing a structured approach to defining operator goals and tracking progress. Sysop-Kernel是一种运营商内核，提供计划模式、工作树和验证功能，帮助开发者高效地开发AI工具 Sysop-Kernelは、AIエージェントの開発を効率化するためのオペレーターカーネルです。プランモード、ワークツリー、検証機能を提供します Sysop-Kernel은 AI 도구 개발을 효율화하는 운영자 커널로, 계획 모드, 작업 트리 및 검증 기능을 제공합니다 Sysop-kernel es un núcleo de operador que sigue el plan de trabajo definido en AGENTS.md, permitiendo la ejecución paralela de tareas y la verificación de resultados Sysop-kernel est un noyau d''opérateur qui suit le plan de travail défini dans AGENTS.md, permettant l''exécution parallèle de tâches et la vérification des résultats Sysop-kernel ist ein Betreiber-Kernel, der dem in AGENTS.md definierten Arbeitsplan folgt, wodurch die parallele Ausführung von Aufgaben und die Überprüfung von Ergebnissen ermöglicht wird O sysop-kernel é um operador que segue o plano-first e trabalha com worktrees por tarefa em paralelo, com verificação e anotações auditáveis. sysop-kernel - это оператор, который следует план-first и работает с worktrees по задаче в параллели, с проверкой и аудиторскими заметками. sysop-kernel هو مشغل يتبع الخطة الأولى ويعمل مع worktrees لكل مهمة بالتوازي، مع التحقق والملاحظات القابلة للتدقيق. how to use sysop-kernel sysop-kernel setup guide sysop-kernel alternative sysop-kernel vs other kernels plan-first workflow management automated verification processes sysop-kernel install sysop-kernel documentation AI agent task management worktrees per task Sysop-Kernel AI工具开发 运营商内核 计划模式 工作树 验证功能 可审计的笔记 AI开发最佳实践 Executes `sysop/run.sh` for automated workflows Generates fresh artifacts under `sysop/out/` directory Appends new entries to `learn/LEDGER.md` for tracking Supports plan mode with no writes for initial setup Defines ''done means'' criteria for task completion Utilizes `AGENTS.md` and `sysop/README_INDEX.md` for documentation sysop-kernel is a technical framework that follows a plan-first approach, utilizing worktrees per task for parallel execution and requiring verification for auditable notes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('venikman/fpf-foundry/workflow/respond-to-approval', 'community', 'venikman', 'fpf-foundry', 'venikman/fpf-foundry', 'workflow/respond-to-approval', 0, 0, 31, '2026-03-08T01:57:15.389Z', '2026-03-08T02:06:00.653Z', 'c5b06aa0681ed051cc82bde1247eaa3f5f9832d771ae9c46ef863e7990ba623b', '{"id":"venikman/fpf-foundry/workflow/respond-to-approval","name":"workflow/respond-to-approval","description":{"en":"The workflow/respond-to-approval skill records approval decisions linked to prior approval requests, benefiting developers and auditors by providing a clear record of decisions. It supports inputs like context, session_id, and approval_id.","zh":"workflow/respond-to-approval AI工具允许开发者记录审批决策，实现审计和审批请求的跟踪","ja":"AIエージェントを使用して、承認決定を記録し、監査性とゲートを実現することができます","ko":"AI 에이전트를 사용하여 승인 결정을 기록하고 감사 및 게이트를 thực現할 수 있습니다","es":"El skill de aprobación registra decisiones de aprobación para auditoría y control de flujos de trabajo, utilizando parámetros como context, session_id, approval_id y decision.","fr":"Le skill d''approbation enregistre les décisions d''approbation pour l''audit et le contrôle des flux de travail, en utilisant des paramètres tels que context, session_id, approval_id et decision.","de":"Das Approval-Skill protokolliert Entscheidungen zu Genehmigungen für die Prüfbarkeit und die Steuerung von Workflows, unter Verwendung von Parametern wie context, session_id, approval_id und decision.","pt":"O fluxo de trabalho de resposta a aprovação registra decisões de aprovação para auditoria e portais. Requer contexto, ID de sessão, ID de aprovação e decisão.","ru":"Рабочий процесс ответа на одобрение регистрирует решения об одобрении для аудита и шлюзов. Требует контекста, идентификатора сеанса, идентификатора одобрения и решения.","ar":"سير عمل الاستجابة للموافقة يسجل قرارات الموافقة من أجل التدقيق والبوابات. يتطلب س